class Robot:
    HEADINGS = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    NAMES = ("north", "east", "south", "west")

    def __init__(self):
        self.x = 0
        self.y = 0
        self.heading = 0

    def turn_left(self):
        self.heading = (self.heading - 1) % len(self.HEADINGS)

    def turn_right(self):
        self.heading = (self.heading + 1) % len(self.HEADINGS)

    def move(self, distance):
        dx, dy = self.HEADINGS[self.heading]
        self.x += dx * distance
        self.y += dy * distance

    def position(self):
        return (self.x, self.y)

    def facing(self):
        return self.NAMES[self.heading]


class CommandInterpreter:
    def __init__(self, robot):
        self.robot = robot
        self.actions = {
            "left": lambda amount: self.robot.turn_left(),
            "right": lambda amount: self.robot.turn_right(),
            "move": lambda amount: self.robot.move(amount),
        }
        self.log = []

    def parse(self, command):
        try:
            action, amount = command
        except (TypeError, ValueError):
            raise ValueError("each command must be an (action, amount) pair")
        if action not in self.actions:
            raise ValueError("unknown action: {!r}".format(action))
        if not isinstance(amount, int) or isinstance(amount, bool):
            raise ValueError("amount must be an integer, got {!r}".format(amount))
        return action, amount

    def execute(self, command):
        action, amount = self.parse(command)
        self.actions[action](amount)
        self.log.append((action, amount, self.robot.position(), self.robot.facing()))

    def run(self, commands):
        for command in commands:
            self.execute(command)
        return self.robot.position()

    def report(self):
        lines = []
        for action, amount, position, facing in self.log:
            lines.append("{:<5} {:>3} -> {} facing {}".format(action, amount, position, facing))
        lines.append("final position: {}".format(self.robot.position()))
        return "\n".join(lines)


def navigate(commands):
    interpreter = CommandInterpreter(Robot())
    return interpreter.run(commands)


def main():
    interpreter = CommandInterpreter(Robot())
    interpreter.run([("move", 3), ("right", 0), ("move", 4)])
    print(interpreter.report())
    print(navigate([("move", 5), ("left", 0), ("move", 2), ("left", 0), ("move", 1)]))


if __name__ == "__main__":
    main()

