class Ledger:
    """Blueprint of a ledger that tracks a running balance and its operations."""

    FEE_BASE = 2

    def __init__(self):
        self.balance = 0
        self.operations = 0
        self.history = []

    def _log(self, action, amount):
        self.history.append((action, amount, self.balance))

    def add(self, amount):
        self.balance += amount
        self.operations += 1
        self._log("add", amount)
        return self.balance

    def remove(self, amount):
        self.balance -= amount
        self.operations += 1
        self._log("remove", amount)
        return self.balance

    def fee(self, _amount=0):
        self.operations += 1
        charge = self.FEE_BASE + self.operations
        self.balance -= charge
        self._log("fee", charge)
        return self.balance

    def final_balance(self):
        return self.balance


class TransactionParser:
    """Turns raw input pairs into (action, value) items the ledger understands."""

    def __init__(self, allowed_actions):
        self.allowed_actions = set(allowed_actions)

    def parse_one(self, entry):
        action, value = entry
        key = str(action).strip().lower()
        if key not in self.allowed_actions:
            raise ValueError("unknown ledger action: {!r}".format(action))
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("value for {!r} must be numeric".format(key))
        return key, value

    def parse_all(self, transactions):
        return [self.parse_one(entry) for entry in transactions]


class LedgerReport:
    """Renders the ledger history as readable lines."""

    def __init__(self, ledger):
        self.ledger = ledger

    def lines(self):
        rows = ["{:>2}. {:<7} {:>8} -> {}".format(index, action, amount, balance)
                for index, (action, amount, balance) in enumerate(self.ledger.history, 1)]
        rows.append("final balance after {} operations: {}".format(
            self.ledger.operations, self.ledger.final_balance()))
        return rows

    def render(self):
        return "\n".join(self.lines())


def process(transactions):
    ledger = Ledger()
    parser = TransactionParser(("add", "remove", "fee"))
    handlers = {"add": ledger.add, "remove": ledger.remove, "fee": ledger.fee}
    for action, value in parser.parse_all(transactions):
        handlers[action](value)
    return ledger.final_balance()


def main():
    sample = [("add", 100), ("remove", 20), ("fee", 0)]
    print(process(sample))
    ledger = Ledger()
    for action, value in TransactionParser(("add", "remove", "fee")).parse_all(sample):
        getattr(ledger, action)(value)
    print(LedgerReport(ledger).render())


if __name__ == "__main__":
    main()

