class Creature:
    def __init__(self, name="Pixel"):
        self.name = name
        self.energy = 10
        self.hunger = 0

    def feed(self):
        self.hunger = self._clamp_hunger(self.hunger - 3)

    def sleep(self):
        self.energy = self._clamp_energy(self.energy + 5)

    def play(self):
        self.energy = self._clamp_energy(self.energy - 4)
        self.hunger = self._clamp_hunger(self.hunger + 2)

    def _clamp_energy(self, value):
        return 0 if value < 0 else value

    def _clamp_hunger(self, value):
        return 10 if value > 10 else max(0, value)

    def report(self):
        return "{0}: energy={1}, hunger={2}".format(self.name, self.energy, self.hunger)

    def stats(self):
        return (self.energy, self.hunger)


class CreatureKeeper:
    def __init__(self, creature):
        self.creature = creature
        self.log = []
        self.handlers = {
            "feed": creature.feed,
            "sleep": creature.sleep,
            "play": creature.play,
            "report": self._record_report,
        }

    def _record_report(self):
        self.log.append(self.creature.report())

    def apply(self, action):
        handler = self.handlers.get(action)
        if handler is None:
            raise ValueError("unknown action: {0!r}".format(action))
        handler()

    def run(self, actions):
        for action in actions:
            self.apply(action)
        return self.creature.stats()

    def summary(self):
        lines = list(self.log)
        lines.append("final " + self.creature.report())
        return "\n".join(lines)


def simulate(actions):
    keeper = CreatureKeeper(Creature())
    return keeper.run(actions)


def main():
    plan = ["play", "play", "feed", "sleep"]
    keeper = CreatureKeeper(Creature("Blip"))
    keeper.run(plan + ["report", "play", "report"])
    print(keeper.summary())
    print("simulate result:", simulate(plan))


if __name__ == "__main__":
    main()

