class CoinSlot:
    """Holds the coins a customer has inserted but not yet spent."""

    def __init__(self):
        self.inserted = 0

    def insert(self, amount):
        if amount <= 0:
            raise ValueError("a coin must have a positive value, got %r" % (amount,))
        self.inserted += amount
        return self.inserted

    def take(self, amount):
        if self.inserted < amount:
            return False
        self.inserted -= amount
        return True

    def flush(self):
        change = self.inserted
        self.inserted = 0
        return change


class Dispenser:
    """A one-product dispenser whose single article costs fifty cents."""

    PRICE = 50

    def __init__(self):
        self.slot = CoinSlot()
        self.revenue = 0
        self.change_returned = 0

    def insert_coin(self, amount):
        return self.slot.insert(amount)

    def request_product(self):
        if not self.slot.take(self.PRICE):
            return False
        self.revenue += self.PRICE
        self.change_returned += self.slot.flush()
        return True

    def cancel(self):
        self.change_returned += self.slot.flush()

    def total_revenue(self):
        return self.revenue

    def describe(self):
        return "revenue=%d change returned=%d still inserted=%d" % (
            self.revenue,
            self.change_returned,
            self.slot.inserted,
        )


class VendingSession:
    """Replays a command stream against a dispenser and keeps statistics."""

    def __init__(self, machine):
        self.machine = machine
        self.sold = 0
        self.declined = 0

    def execute(self, command, amount):
        if command == "insert":
            self.machine.insert_coin(amount)
        elif command == "request":
            if self.machine.request_product():
                self.sold += 1
            else:
                self.declined += 1
        elif command == "cancel":
            self.machine.cancel()
        else:
            raise ValueError("unknown command %r" % (command,))

    def run(self, requests):
        for command, amount in requests:
            self.execute(command, amount)
        return self.machine.total_revenue()

    def summary(self):
        return "sold=%d declined=%d %s" % (
            self.sold,
            self.declined,
            self.machine.describe(),
        )


def vend(requests):
    return VendingSession(Dispenser()).run(requests)


if __name__ == "__main__":
    script = [("insert", 25), ("insert", 25), ("request", 0), ("insert", 10), ("cancel", 0)]
    session = VendingSession(Dispenser())
    print(session.run(script))
    print(session.summary())

