class RewardAccount:
    """Accumulates points and promotes the customer one tier per full threshold."""

    def __init__(self, threshold=1000):
        self.points = 0
        self.tier = 0
        self.threshold = threshold

    def earn(self, amount):
        self.points += amount
        self._update_tier()

    def spend(self, amount):
        if amount > self.points:
            return False
        self.points -= amount
        return True

    def _update_tier(self):
        promotions = self.points // self.threshold
        if promotions:
            self.tier += promotions
            self.points -= promotions * self.threshold

    def summary(self):
        return (self.tier, self.points)


class EventProcessor:
    """Validates loyalty events and applies them to a reward account."""

    def __init__(self, account=None):
        self.account = account if account is not None else RewardAccount()
        self.actions = ("earn", "spend")
        self.rejected = []

    def _validate(self, event):
        if not isinstance(event, tuple) or len(event) != 2:
            raise ValueError("each event must be a (action, amount) tuple")
        action, amount = event
        if action not in self.actions:
            raise ValueError("unknown action: {!r}".format(action))
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError("amount must be a non-negative integer")
        return action, amount

    def apply(self, action, amount):
        if action == "earn":
            self.account.earn(amount)
        elif not self.account.spend(amount):
            self.rejected.append(amount)

    def run(self, events):
        for event in events:
            action, amount = self._validate(event)
            self.apply(action, amount)
        return self.account.summary()


class ReportFormatter:
    """Turns a processed account into a short human readable summary."""

    def __init__(self, processor):
        self.processor = processor

    def lines(self):
        tier, points = self.processor.account.summary()
        report = ["Tier reached: {}".format(tier), "Points left: {}".format(points)]
        for amount in self.processor.rejected:
            report.append("Declined spend of {} (insufficient balance)".format(amount))
        return report

    def render(self):
        return "\n".join(self.lines())


def reward(events):
    return EventProcessor().run(events)


def main():
    processor = EventProcessor()
    processor.run([("earn", 1500), ("spend", 200), ("earn", 800), ("spend", 5000)])
    print(ReportFormatter(processor).render())
    print(reward([("earn", 1500), ("spend", 200), ("earn", 800)]))


if __name__ == "__main__":
    main()

