class HeaterLog:
    """Keeps a human readable trace of every controller event."""

    def __init__(self):
        self.entries = []

    def note_target(self, degrees):
        self.entries.append("target set to {}F".format(degrees))

    def record(self, reading, target, heater_on):
        state = "ON" if heater_on else "off"
        self.entries.append(
            "reading {}F (target {}F) -> heater {}".format(reading, target, state)
        )

    def summary(self):
        numbered = []
        for index, entry in enumerate(self.entries, start=1):
            numbered.append("{:>2}. {}".format(index, entry))
        return "\n".join(numbered)


class ClimateController:
    """Thermostat that counts the minutes its heater spends running."""

    def __init__(self, log=None):
        self.target = 70
        self.heater_on = False
        self.active_minutes = 0
        self.log = log

    def adjust_target(self, degrees):
        self.target = degrees
        if self.log is not None:
