class Library:
    def __init__(self):
        self.available = []
        self.loaned = []

    def donate(self, title):
        self.available.append(title)
        return True

    def borrow(self, title):
        if title not in self.available:
            return False
        self.available.remove(title)
        self.loaned.append(title)
        return True

    def give_back(self, title):
        if title not in self.loaned:
            return False
        self.loaned.remove(title)
        self.available.append(title)
        return True

    def count_available(self):
        return len(self.available)

    def summary(self):
        return "available=%d loaned=%d" % (self.count_available(), len(self.loaned))


class InventoryManager:
    def __init__(self, library):
        self.library = library
        self.actions = {
            "donate": library.donate,
            "borrow": library.borrow,
            "return": library.give_back,
        }
        self.rejected = []

    def normalize(self, event):
        action, title = event
        return action.strip().lower(), title.strip().lower()

    def apply(self, event):
        action, title = self.normalize(event)
        handler = self.actions.get(action)
        if handler is None or not title:
            self.rejected.append((action, title))
            return False
        if not handler(title):
            self.rejected.append((action, title))
            return False
        return True

    def run(self, events):
        for event in events:
            self.apply(event)
        return self.library.count_available()

    def report(self):
        lines = [self.library.summary()]
        for action, title in self.rejected:
            lines.append("skipped %s of %r" % (action, title))
        return "\n".join(lines)


def manage(events):
    manager = InventoryManager(Library())
    total = manager.run(events)
    print(manager.report())
    return total


