class WorkoutEntry:
    VALID_TYPES = ("cardio", "weights", "end")

    def __init__(self, raw):
        kind, minutes = raw
        self.kind = str(kind).strip().lower()
        self.minutes = minutes
        self.validate()

    def validate(self):
        if self.kind not in self.VALID_TYPES:
            raise ValueError("unknown exercise type: {!r}".format(self.kind))
        if not isinstance(self.minutes, int) or self.minutes < 0:
            raise ValueError("duration must be a non-negative whole number of minutes")

    def is_end(self):
        return self.kind == "end"

    def describe(self):
        if self.is_end():
            return "end of day"
        return "{} for {} min".format(self.kind, self.minutes)


class FitnessProfile:
    CARDIO_RATE = 10
    WEIGHT_RATE = 5

    def __init__(self, base_rate=1200):
        self.base_rate = base_rate
        self.daily_calories = 0
        self.weekly_total = 0
        self.days_logged = 0

    def log_cardio(self, minutes):
        self.daily_calories += self.CARDIO_RATE * minutes
        return self.daily_calories

    def log_weights(self, minutes):
        self.daily_calories += self.WEIGHT_RATE * minutes
        return self.daily_calories

    def end_day(self):
        self.daily_calories += self.base_rate
        self.weekly_total += self.daily_calories
        self.days_logged += 1
        self.daily_calories = 0
        return self.weekly_total

    def report_week(self):
        return self.weekly_total

    def daily_average(self):
        if self.days_logged == 0:
            return 0.0
        return self.report_week() / self.days_logged


class WeekTracker:
    def __init__(self, profile):
        self.profile = profile
        self.history = []

    def apply(self, entry):
        if entry.is_end():
            self.profile.end_day()
        elif entry.kind == "cardio":
            self.profile.log_cardio(entry.minutes)
        else:
            self.profile.log_weights(entry.minutes)
        self.history.append(entry.describe())

    def run(self, workouts):
        for raw in workouts:
            self.apply(WorkoutEntry(raw))
        return self.profile.report_week()

    def summary(self):
        activity = "; ".join(self.history)
        total = self.profile.report_week()
        average = self.profile.daily_average()
        return "Activity: {}\nWeekly total: {} cal\nDaily average: {:.1f} cal".format(
            activity, total, average)


def track(workouts):
    return WeekTracker(FitnessProfile()).run(workouts)


def main():
    week = [("cardio", 30), ("weights", 20), ("end", 0),
            ("cardio", 45), ("end", 0)]
    tracker = WeekTracker(FitnessProfile())
    tracker.run(week)
    print(tracker.summary())
    print("Single day check:", track([("cardio", 30), ("weights", 20), ("end", 0)]))


if __name__ == "__main__":
    main()

