class ParkingFacility:
    def __init__(self, capacity=50):
        self.capacity = capacity
        self.count = 0
        self.peak = 0

    def admit(self):
        if self.count >= self.capacity:
            return False
        self.count += 1
        if self.count > self.peak:
            self.peak = self.count
        return True

    def release(self):
        if self.count <= 0:
            return False
        self.count -= 1
        return True

    def peak_occupancy(self):
        return self.peak

    def free_spaces(self):
        return self.capacity - self.count


class GateController:
    def __init__(self, facility):
        self.facility = facility
        self.rejected = 0
        self.history = []

    def dispatch(self, action):
        if action == "admit":
            accepted = self.facility.admit()
        elif action == "release":
            accepted = self.facility.release()
        else:
            raise ValueError("unknown action: {!r}".format(action))
        if not accepted:
            self.rejected += 1
        self.history.append((action, self.facility.count))
        return accepted

    def run(self, actions):
        for action in actions:
            self.dispatch(action)
        return self.facility.peak_occupancy()


class FacilityReport:
    def __init__(self, controller):
        self.controller = controller

    def lines(self):
        rendered = []
        for step, (action, occupancy) in enumerate(self.controller.history, 1):
            rendered.append("{:>3}. {:<8} -> {} vehicle(s)".format(step, action, occupancy))
        return rendered

    def render(self):
        facility = self.controller.facility
        body = self.lines()
        body.append("peak occupancy: {}".format(facility.peak_occupancy()))
        body.append("free spaces now: {}".format(facility.free_spaces()))
        body.append("refused actions: {}".format(self.controller.rejected))
        return "\n".join(body)


def operate(arrivals):
    controller = GateController(ParkingFacility())
    return controller.run(arrivals)


def main():
    sequence = ["admit", "admit", "release", "admit", "admit"]
    controller = GateController(ParkingFacility())
    peak = controller.run(sequence)
    print(FacilityReport(controller).render())
    print("operate() returns:", operate(sequence), "==", peak)


if __name__ == "__main__":
    main()

