class Job:
    def __init__(self, name):
        self.name = name
        self.done = False

    def mark_done(self):
        self.done = True
        return self

    def label(self):
        if self.done:
            return "[x] " + self.name
        return "[ ] " + self.name


class JobList:
    def __init__(self):
        self.pending = []
        self.completed = []

    def add(self, name):
        job = Job(name)
        self.pending.append(job)
        return job

    def find_pending(self, name):
        for job in self.pending:
            if job.name == name:
                return job
        return None

    def complete(self, name):
        job = self.find_pending(name)
        if job is None:
            return None
        self.pending.remove(job)
        self.completed.append(job.mark_done())
        return job

    def clear_completed(self):
        removed = len(self.completed)
        self.completed = []
        return removed

    def count_pending(self):
        return len(self.pending)

    def report(self):
        lines = [job.label() for job in self.pending]
        lines.extend(job.label() for job in self.completed)
        lines.append("pending: %d" % self.count_pending())
        return "\n".join(lines)


class Scheduler:
    def __init__(self, commands):
        self.commands = commands
        self.jobs = JobList()
        self.errors = []

    def dispatch(self, command, name):
        if command == "add":
            self.jobs.add(name)
        elif command == "complete":
            if self.jobs.complete(name) is None:
                self.errors.append("cannot complete missing job: " + name)
        elif command == "clear":
            self.jobs.clear_completed()
        else:
            self.errors.append("unknown command: " + str(command))

    def run(self):
        for command, name in self.commands:
            self.dispatch(command, name)
        return self.jobs.count_pending()

    def summary(self):
        parts = [self.jobs.report()]
        parts.extend(self.errors)
        return "\n".join(parts)


def schedule(commands):
    runner = Scheduler(commands)
    remaining = runner.run()
    print(runner.summary())
    return remaining


if __name__ == "__main__":
    print(schedule([("add", "sweep"), ("add", "wash"), ("complete", "sweep")]))

