class Cart:
    def __init__(self):
        self.total = 0.0
        self.discount = False

    def add_item(self, price):
        self.total += price
        return self.total

    def remove_item(self, price):
        if price > self.total:
            raise ValueError("cannot remove %s from a total of %s" % (price, self.total))
        self.total -= price
        return self.total

    def apply_coupon(self):
        self.discount = True
        return self.discount

    def discount_applies(self):
        return self.total > 100

    def finalize(self):
        if self.discount:
            if self.discount_applies():
                self.total *= 0.9
        return self.total

    def final_cost(self):
        rounded = round(self.total, 2)
        if rounded == int(rounded):
            return int(rounded)
        return rounded


class CheckoutProcessor:
    def __init__(self, cart=None):
        self.cart = cart if cart is not None else Cart()
        self.handlers = {
            "add": self.handle_add,
            "remove": self.handle_remove,
            "coupon": self.handle_coupon,
            "finalize": self.handle_finalize,
        }

    def handle_add(self, value):
        price = self.validate_price(value)
        self.cart.add_item(price)

    def handle_remove(self, value):
        price = self.validate_price(value)
        self.cart.remove_item(price)

    def handle_coupon(self, value):
        self.cart.apply_coupon()

    def handle_finalize(self, value):
        self.cart.finalize()

    def validate_price(self, value):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("price must be numeric, got %r" % (value,))
        if value < 0:
            raise ValueError("price must not be negative: %r" % (value,))
        return float(value)

    def run(self, items):
        for action, value in items:
            handler = self.handlers.get(action)
            if handler is None:
                raise ValueError("unknown action: %r" % (action,))
            handler(value)
