class Cart:
    def __init__(this):
        this.total = 0.0
        this.discount = False

    def add_item(this, price):
        this.total += price
        return this.total

    def remove_item(this, price):
        if price > this.total:
            raise ValueError("cannot remove %s from a total of %s" % (price, this.total))
        this.total -= price
        return this.total

    def apply_coupon(this):
        this.discount = True
        return this.discount

    def discount_applies(this):
        return this.total > 100

    def finalize(this):
        if this.discount:
            if this.discount_applies():
                this.total *= 0.9
        return this.total

    def final_cost(this):
        rounded = round(this.total, 2)
        if rounded == int(rounded):
            return int(rounded)
        return rounded


class CheckoutProcessor:
    def __init__(this, cart=None):
        this.cart = cart if cart is not None else Cart()
        this.handlers = {
            "add": this.handle_add,
            "remove": this.handle_remove,
            "coupon": this.handle_coupon,
            "finalize": this.handle_finalize,
        }

    def handle_add(this, value):
        price = this.validate_price(value)
        this.cart.add_item(price)

    def handle_remove(this, value):
        price = this.validate_price(value)
        this.cart.remove_item(price)

    def handle_coupon(this, value):
        this.cart.apply_coupon()

    def handle_finalize(this, value):
        this.cart.finalize()

    def validate_price(this, value):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("price must be numeric, got %r" % (value,))
        if value < 0:
            raise ValueError("price must not be negative: %r" % (value,))
        return float(value)

    def run(this, items):
        for action, value in items:
            handler = this.handlers.get(action)
            if handler is None:
                raise ValueError("unknown action: %r" % (action,))
            handler(value)
        return this.cart.final_cost()

    def report(this):
        state = "with coupon" if this.cart.discount else "no coupon"
        return "cart total %s (%s)" % (this.cart.final_cost(), state)


