class PlantContainer:
    """A single potted plant tracking its moisture and its health."""

    MOISTURE_FLOOR = 10
    MOISTURE_CEILING = 50
    WATER_AMOUNT = 15
    DAILY_LOSS = 5
    HEALTH_PENALTY = 10

    def __init__(self, moisture=20, health=100):
        self.moisture = moisture
        self.health = health

    def water(self):
        self.moisture += self.WATER_AMOUNT
        return self.moisture

    def pass_day(self):
        self.moisture -= self.DAILY_LOSS
        if self.is_stressed():
            self.health -= self.HEALTH_PENALTY
        return self.moisture

    def is_stressed(self):
        return self.moisture < self.MOISTURE_FLOOR or self.moisture > self.MOISTURE_CEILING

    def report_health(self):
        return self.health

    def status(self):
        return "moisture={0}, health={1}".format(self.moisture, self.report_health())


class LogParser:
    """Turns free-form log words into container method names."""

    def __init__(self):
        self.actions = {"water": "water", "wait": "pass_day"}

    def parse(self, logs):
        if isinstance(logs, str):
            raise TypeError("logs must be a sequence of strings, not a single string")
        return [self.resolve(self.clean(entry)) for entry in logs]

    def clean(self, entry):
        return str(entry).strip().lower()

    def resolve(self, token):
        if token not in self.actions:
            known = ", ".join(sorted(self.actions))
            raise ValueError("unknown garden action {0!r}; expected one of {1}".format(token, known))
        return self.actions[token]


class Gardener:
    """Applies a parsed log to a container and reports the outcome."""

    def __init__(self, plant=None):
        self.plant = plant if plant is not None else PlantContainer()
        self.parser = LogParser()

    def follow(self, logs):
        for method_name in self.parser.parse(logs):
            getattr(self.plant, method_name)()
        return self.plant.report_health()

    def describe(self):
        return "garden {0}".format(self.plant.status())


def hydrate(logs):
    gardener = Gardener()
    score = gardener.follow(logs)
    print(gardener.describe())
    return score


