class Hero:
    MAX_HEALTH = 50
    LOOT_AMOUNT = 10

    def __init__(self):
        self.health = self.MAX_HEALTH
        self.gold = 0
        self.armor = 5

    def is_alive(self):
        return self.health > 0

    def take_damage(self, amount):
        net = amount - self.armor
        if net > 0:
            self.health = max(0, self.health - net)
            return net
        return 0

    def heal(self):
        before = self.health
        self.health = self.MAX_HEALTH
        return self.health - before

    def loot(self):
        self.gold += self.LOOT_AMOUNT
        return self.gold

    def report(self):
        return "health {0}/{1}, gold {2}".format(self.health, self.MAX_HEALTH, self.gold)

    def status(self):
        return (self.health, self.gold)


class AdventureLog:
    def __init__(self):
        self.entries = []

    def record(self, action, detail):
        self.entries.append("{0}: {1}".format(action, detail))

    def skip(self, action):
        self.entries.append("{0}: ignored (hero is dead)".format(action))

    def summary(self):
        return "\n".join(self.entries)


class Adventure:
    ACTIONS = ("damage", "heal", "loot", "report")

    def __init__(self, events):
        self.events = list(events)
        self.hero = Hero()
        self.log = AdventureLog()

    def validate(self):
        for event in self.events:
            if len(event) != 2:
                raise ValueError("each event must be an (action, value) pair: {0!r}".format(event))
            action, value = event
            if action not in self.ACTIONS:
                raise ValueError("unknown action: {0!r}".format(action))
            if not isinstance(value, int):
                raise ValueError("value for {0} must be an int".format(action))

    def apply(self, action, value):
        if action == "damage":
            return "lost {0} health".format(self.hero.take_damage(value))
        if action == "heal":
            return "regained {0} health".format(self.hero.heal())
        if action == "loot":
            return "gold is now {0}".format(self.hero.loot())
        return self.hero.report()

    def run(self):
        self.validate()
        for action, value in self.events:
            if not self.hero.is_alive():
                self.log.skip(action)
                continue
            self.log.record(action, self.apply(action, value))
        return self.hero.status()


def adventure(events):
    return Adventure(events).run()


def main():
    run = Adventure([("loot", 0), ("damage", 30), ("heal", 0), ("damage", 40)])
    result = run.run()
    print(run.log.summary())
    print("final:", result)


if __name__ == "__main__":
    main()

