class Recipe:
    def __init__(self, name, water, beans):
        self.name = name
        self.water = water
        self.beans = beans

    def is_available(self, water_level, beans_level):
        return water_level >= self.water and beans_level >= self.beans

    def describe(self):
        return f"{self.name}: {self.water} units water + {self.beans} units beans per cup"


class BeverageMachine:
    def __init__(self, recipe):
        self.recipe = recipe
        self.water = 0
        self.beans = 0
        self.cups = 0

    def add_water(self, amount):
        self.water += amount
        return self.water

    def add_beans(self, amount):
        self.beans += amount
        return self.beans

    def make_coffee(self):
        if not self.recipe.is_available(self.water, self.beans):
            return False
        self.water -= self.recipe.water
        self.beans -= self.recipe.beans
        self.cups += 1
        return True

    def total_cups(self):
        return self.cups

    def status(self):
        return f"water={self.water} beans={self.beans} cups={self.cups}"


class InstructionProcessor:
    ACTIONS = ("water", "beans", "make", "cups")

    def __init__(self, machine):
        self.machine = machine
        self.refused = 0
        self.reports = []

    def validate(self, step):
        if not isinstance(step, tuple) or len(step) != 2:
            raise ValueError(f"instruction must be an (action, amount) pair: {step!r}")
        action, amount = step
        if action not in self.ACTIONS:
            raise ValueError(f"unknown action {action!r}, expected one of {self.ACTIONS}")
        if not isinstance(amount, int) or amount < 0:
            raise ValueError(f"amount for {action!r} must be a non-negative integer")
        return action, amount

    def apply(self, step):
        action, amount = self.validate(step)
        if action == "water":
            self.machine.add_water(amount)
        elif action == "beans":
            self.machine.add_beans(amount)
        elif action == "make":
            if not self.machine.make_coffee():
                self.refused += 1
        else:
            self.reports.append(self.machine.total_cups())

    def run(self, steps):
        for step in steps:
            self.apply(step)
        return self.machine.total_cups()

    def summary(self):
        return f"{self.machine.status()} refused={self.refused} reported={self.reports}"


def brew(steps):
    machine = BeverageMachine(Recipe("coffee", 20, 10))
    return InstructionProcessor(machine).run(steps)


