class MediaPlayer:
    """A tiny media player holding a queue of tracks and a playback cursor."""

    def __init__(self):
        self.tracks = []
        self.index = 0
        self.repeating = False

    def queue(self, name):
        self.tracks.append(name)
        return len(self.tracks)

    def skip(self):
        if not self.tracks:
            return self.current()
        last = len(self.tracks) - 1
        if self.index >= last:
            self.index = 0 if self.repeating else last
        else:
            self.index += 1
        return self.current()

    def toggle(self):
        self.repeating = not self.repeating
        return self.repeating

    def current(self):
        if not self.tracks:
            return ""
        return self.tracks[self.index]


class ActionDispatcher:
    """Applies (action, track) tuples to a player and records what happened."""

    def __init__(self, player):
        self.player = player
        self.history = []

    def parse(self, item):
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError("each action must be a (action, name) tuple: %r" % (item,))
        action, name = item
        return action.strip().lower(), name

    def apply(self, action, name):
        if action == "queue":
            if not name:
                raise ValueError("queueing a track requires a name")
            self.player.queue(name)
        elif action == "skip":
            self.player.skip()
        elif action == "toggle":
            self.player.toggle()
        elif action != "report":
            raise ValueError("unknown action: %r" % (action,))
        return self.player.current()

    def run(self, actions):
        for item in actions:
            action, name = self.parse(item)
            active = self.apply(action, name)
            self.history.append((action, active, self.player.repeating))
        return self.player.current()


class PlaybackReport:
    """Formats the dispatcher history into readable lines."""

    def __init__(self, history):
        self.history = history

    def lines(self):
        rendered = []
        for step, (action, active, repeating) in enumerate(self.history, start=1):
            mode = "repeat" if repeating else "once"
            rendered.append("%d. %-7s -> %-8s [%s]" % (step, action, active or "-", mode))
        return rendered

    def __str__(self):
        return "\n".join(self.lines())


def play(actions):
    dispatcher = ActionDispatcher(MediaPlayer())
    return dispatcher.run(actions)


def main():
    script = [("queue", "intro"), ("queue", "chorus"), ("skip", ""), ("toggle", ""), ("skip", "")]
    dispatcher = ActionDispatcher(MediaPlayer())
    active = dispatcher.run(script)
    print(PlaybackReport(dispatcher.history))
    print("active track:", active)
    print("play() result:", play(script))


if __name__ == "__main__":
    main()

