        self.current_floor = 0
        self.total_distance = 0
        self.doors = Doors()

    def call_to(self, floor):
        if self.doors.is_open:
            self.doors.close_doors()
        distance = abs(self.current_floor - floor)
        self.total_distance += distance
        self.current_floor = floor
        self.doors.open_doors()
        return distance

    def report(self):
        return self.total_distance

    def position(self):
        return self.current_floor


class Dispatcher:
    def __init__(self, lift):
        self.lift = lift
        self.trips = []

    def validate(self, request):
        if isinstance(request, bool) or not isinstance(request, int):
            raise TypeError("floor requests must be integers, got %r" % (request,))
        return request

    def run(self, requests):
        for request in requests:
            floor = self.validate(request)
            distance = self.lift.call_to(floor)
            self.trips.append((floor, distance))
        return self.lift.report()

    def summary(self):
        lines = []
        for floor, distance in self.trips:
            lines.append("-> floor %d (%d floor(s) travelled)" % (floor, distance))
        lines.append("final floor: %d" % self.lift.position())
        lines.append("total distance: %d" % self.lift.report())
        return "\n".join(lines)


def transport(requests):
    dispatcher = Dispatcher(Lift())
    return dispatcher.run(requests)


def main():
    dispatcher = Dispatcher(Lift())
    total = dispatcher.run([5, 2, 8])
    print(dispatcher.summary())
    print("transport([5, 2, 8]) =", total)
    print("transport([]) =", transport([]))
    print("transport([0, 0, 3]) =", transport([0, 0, 3]))


if __name__ == "__main__":
    main()

