class Battery:
    def __init__(self, capacity=100):
        self.capacity = capacity
        self.charge_level = capacity
        self.power_saving = False

    def charge(self, percent):
        self.charge_level = min(self.capacity, self.charge_level + percent)
        return self.charge_level

    def drain(self, percent):
        effective = percent / 2 if self.power_saving else percent
        self.charge_level = max(0, self.charge_level - effective)
        return self.charge_level

    def enable_power_saving(self):
        self.power_saving = True
        return self.charge_level

    def report(self):
        mode = "power saving" if self.power_saving else "normal"
        return "charge {0:g}/{1:g} ({2})".format(
            self.charge_level, self.capacity, mode)


class BatteryController:
    def __init__(self, battery):
        self.battery = battery
        self.history = []

    def validate(self, command, amount):
        if command not in ("charge", "drain", "save", "report"):
            raise ValueError("unknown command: {0!r}".format(command))
        if not isinstance(amount, (int, float)):
            raise TypeError("amount must be numeric, got {0!r}".format(amount))
        if amount < 0:
            raise ValueError("amount must not be negative: {0}".format(amount))
        return command

    def execute(self, command, amount):
        self.validate(command, amount)
        if command == "charge":
            level = self.battery.charge(amount)
        elif command == "drain":
            level = self.battery.drain(amount)
        elif command == "save":
            level = self.battery.enable_power_saving()
        else:
            level = self.battery.charge_level
            self.history.append(self.battery.report())
            return level
        self.history.append("{0} {1:g} -> {2:g}".format(command, amount, level))
        return level

    def run(self, usage):
        for command, amount in usage:
            self.execute(command, amount)
        return self.battery.charge_level

    def summary(self):
        lines = list(self.history)
        lines.append("final " + self.battery.report())
        return "\n".join(lines)


def power(usage):
    controller = BatteryController(Battery())
    final = controller.run(usage)
    print(controller.summary())
    return final


if __name__ == "__main__":
    plan = [("drain", 40), ("save", 0), ("drain", 20), ("charge", 10)]
    print("result:", power(plan))

