class Printer:
    """A single printer with finite ink and paper."""

    def __init__(self):
        self.ink = 100
        self.paper = 50
        self.total_pages = 0

    def supply_paper(self, amount):
        if amount < 0:
            raise ValueError("cannot supply a negative amount of paper")
        self.paper += amount
        return self.paper

    def print_document(self, pages):
        if pages < 0:
            raise ValueError("a document cannot have a negative page count")
        if pages > self.ink or pages > self.paper:
            return 0
        self.ink -= pages
        self.paper -= pages
        self.total_pages += pages
        return pages

    def report(self):
        return self.total_pages

    def status(self):
        return "ink={0}, paper={1}, printed={2}".format(
            self.ink, self.paper, self.total_pages)


class SpoolReport:
    """Collects what happened to every queued job."""

    def __init__(self):
        self.entries = []
        self.halted_at = None

    def record(self, index, requested, produced):
        self.entries.append((index, requested, produced))

    def halt(self, index, requested):
        self.halted_at = (index, requested)

    def total(self):
        return sum(produced for _, _, produced in self.entries)

    def lines(self):
        out = ["job {0}: {1} page(s) printed".format(i, produced)
               for i, _, produced in self.entries]
        if self.halted_at is not None:
            index, requested = self.halted_at
            out.append("job {0}: refused ({1} page(s) requested) - queue stopped"
                       .format(index, requested))
        out.append("total pages: {0}".format(self.total()))
        return out


class Spooler:
    """Feeds documents to a printer until one of them cannot be produced."""

    def __init__(self, printer):
        self.printer = printer
        self.report = SpoolReport()

    def run(self, jobs):
        for index, pages in enumerate(jobs, start=1):
            if not isinstance(pages, int) or isinstance(pages, bool):
                raise TypeError("job {0} is not an integer page count".format(index))
            produced = self.printer.print_document(pages)
            if produced == 0 and pages > 0:
                self.report.halt(index, pages)
                break
            self.report.record(index, pages, produced)
        return self.report.total()


def spool(jobs):
    printer = Printer()
    spooler = Spooler(printer)
    spooler.run(jobs)
    return printer.report()


def main():
    queue = [30, 25, 10]
    printer = Printer()
    spooler = Spooler(printer)
    spooler.run(queue)
    for line in spooler.report.lines():
        print(line)
    print(printer.status())
    print("spool({0}) = {1}".format(queue, spool(queue)))


if __name__ == "__main__":
    main()

