class Vessel:
    def __init__(self, fuel=100, distance=0):
        self.fuel = fuel
        self.distance = distance

    def can_spend(self, amount):
        return self.fuel >= amount

    def thrust(self):
        if not self.can_spend(10):
            return False
        self.fuel -= 10
        self.distance += 20
        return True

    def cruise(self):
        if not self.can_spend(5):
            return False
        self.fuel -= 5
        self.distance += 10
        return True

    def harvest(self):
        self.fuel += 15
        return True

    def verify(self):
        return self.distance >= 100

    def status(self):
        return "fuel={} distance={}".format(self.fuel, self.distance)


class FlightController:
    def __init__(self, vessel):
        self.vessel = vessel
        self.actions = {
            "thrust": vessel.thrust,
            "cruise": vessel.cruise,
            "harvest": vessel.harvest,
            "verify": vessel.verify,
        }
        self.log = []

    def execute(self, maneuver):
        action = self.actions.get(maneuver)
        if action is None:
            raise ValueError("unknown maneuver: {!r}".format(maneuver))
        outcome = action()
        self.log.append((maneuver, outcome, self.vessel.status()))
        return outcome

    def run(self, maneuvers):
        for maneuver in maneuvers:
            self.execute(maneuver)
        return self.vessel.verify()

    def report(self):
        lines = []
        for index, (maneuver, outcome, status) in enumerate(self.log, 1):
            mark = "ok" if outcome else "skipped"
            lines.append("{:>2}. {:<8} {:<8} {}".format(index, maneuver, mark, status))
        lines.append("arrived: {}".format(self.vessel.verify()))
        return "\n".join(lines)


def fly(maneuvers):
    controller = FlightController(Vessel())
    return controller.run(maneuvers)


def main():
    plans = [
        ["thrust", "thrust", "harvest", "cruise", "thrust"],
        ["thrust", "thrust", "thrust", "thrust", "thrust", "verify"],
        ["cruise", "cruise", "harvest", "thrust", "thrust", "thrust", "thrust"],
    ]
    for plan in plans:
        controller = FlightController(Vessel())
        controller.run(plan)
        print(controller.report())
        print("fly({}) -> {}\n".format(plan, fly(plan)))


if __name__ == "__main__":
    main()

