class Oven:
    def __init__(self, heat=300):
        self.heat = heat
        self.readings = []

    def increase(self, amount):
        self.heat += amount
        return self.heat

    def decrease(self, amount):
        self.heat -= amount
        return self.heat

    def record(self, _amount=0):
        self.readings.append(self.heat)
        return self.heat

    def average(self):
        if not self.readings:
            return self.heat
        return int(sum(self.readings) / len(self.readings))

    def summary(self):
        return "heat={} readings={} average={}".format(
            self.heat, self.readings, self.average()
        )


class AdjustmentProcessor:
    def __init__(self, oven):
        self.oven = oven
        self.actions = {
            "up": oven.increase,
            "down": oven.decrease,
            "record": oven.record,
        }

    def validate(self, step):
        if not isinstance(step, (tuple, list)) or len(step) != 2:
            raise ValueError("each adjustment must be an (action, value) pair")
        action, value = step
        if action not in self.actions:
            raise ValueError("unknown action: {!r}".format(action))
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError("value must be numeric, got {!r}".format(value))
        return action, value

    def apply(self, step):
        action, value = self.validate(step)
        return self.actions[action](value)

    def run(self, adjustments):
        for step in adjustments:
            self.apply(step)
        return self.oven.average()


def bake(adjustments):
    processor = AdjustmentProcessor(Oven())
    return processor.run(adjustments)


def main():
    programs = [
        [("up", 50), ("record", 0), ("down", 100), ("record", 0)],
        [("record", 0), ("up", 120), ("record", 0), ("up", 30), ("record", 0)],
        [("down", 75), ("record", 0)],
    ]
    for program in programs:
        oven = Oven()
        AdjustmentProcessor(oven).run(program)
        print(oven.summary())
    print("bake(example) =", bake(programs[0]))


if __name__ == "__main__":
    main()

