class TrafficSignal:
    """An intersection signal that tracks its color and the cars it let through."""

    ORDER = ("red", "green", "yellow")

    def __init__(self):
        self.color = "red"
        self.passed = 0

    def cycle(self, cars=0):
        index = self.ORDER.index(self.color)
        self.color = self.ORDER[(index + 1) % len(self.ORDER)]
        return self.color

    def approach(self, cars):
        if cars < 0:
            raise ValueError("car count cannot be negative: %d" % cars)
        if self.color == "green":
            allowed = cars
        elif self.color == "yellow":
            allowed = min(1, cars)
        else:
            allowed = 0
        self.passed += allowed
        return allowed

    def report(self, cars=0):
        return self.passed


class SignalController:
    """Applies a sequence of (action, car count) instructions to a signal."""

    def __init__(self, signal):
        self.signal = signal
        self.log = []

    def actions(self):
        return {
            "cycle": self.signal.cycle,
            "approach": self.signal.approach,
            "report": self.signal.report,
        }

    def step(self, action, cars):
        handler = self.actions().get(action)
        if handler is None:
            raise ValueError("unknown action: %r" % (action,))
        result = handler(cars)
        self.log.append((action, cars, self.signal.color, result))
        return result

    def run(self, ticks):
        for action, cars in ticks:
            self.step(action, cars)
        return self.signal.report()

    def summary(self):
        lines = ["%-8s cars=%d color=%-6s -> %s" % entry for entry in self.log]
        lines.append("total passed: %d" % self.signal.passed)
        return "\n".join(lines)


def traffic(ticks):
    controller = SignalController(TrafficSignal())
    return controller.run(ticks)


def main():
    ticks = [("approach", 5), ("cycle", 0), ("approach", 5),
             ("cycle", 0), ("approach", 2), ("report", 0)]
    controller = SignalController(TrafficSignal())
    total = controller.run(ticks)
    print(controller.summary())
    print("traffic() ->", traffic(ticks[:-1]), "| controller ->", total)


if __name__ == "__main__":
    main()

