    def __init__(this):
        this.color = "red"
        this.passed = 0

    def cycle(this, cars=0):
        index = this.ORDER.index(this.color)
        this.color = this.ORDER[(index + 1) % len(this.ORDER)]
        return this.color

    def approach(this, cars):
        if cars < 0:
            raise ValueError("car count cannot be negative: %d" % cars)
        if this.color == "green":
            allowed = cars
        elif this.color == "yellow":
            allowed = min(1, cars)
        else:
            allowed = 0
        this.passed += allowed
        return allowed

    def report(this, cars=0):
        return this.passed


class SignalController:
    """Applies a sequence of (action, car count) instructions to a signal."""

    def __init__(this, signal):
        this.signal = signal
        this.log = []

    def actions(this):
        return {
            "cycle": this.signal.cycle,
            "approach": this.signal.approach,
            "report": this.signal.report,
        }

    def step(this, action, cars):
        handler = this.actions().get(action)
        if handler is None:
            raise ValueError("unknown action: %r" % (action,))
        result = handler(cars)
        this.log.append((action, cars, this.signal.color, result))
        return result

    def run(this, ticks):
        for action, cars in ticks:
            this.step(action, cars)
        return this.signal.report()

    def summary(this):
        lines = ["%-8s cars=%d color=%-6s -> %s" % entry for entry in this.log]
        lines.append("total passed: %d" % this.signal.passed)
        return "\n".join(lines)


def traffic(ticks):
    controller = SignalController(TrafficSignal())
    return controller.run(ticks)


def main():
    ticks = [("approach", 5), ("cycle", 0), ("approach", 5),
             ("cycle", 0), ("approach", 2), ("report", 0)]
    controller = SignalController(TrafficSignal())
    total = controller.run(ticks)
    print(controller.summary())
    print("traffic() ->", traffic(ticks[:-1]), "| controller ->", total)


if __name__ == "__main__":
    main()

