class Inventory:
    """Physical stock count plus a moving average unit cost."""

    def __init__(self):
        self.count = 0
        self.unit_cost = 0.0

    def receive(self, quantity, cost):
        if quantity <= 0:
            raise ValueError("received quantity must be positive")
        if cost < 0:
            raise ValueError("received cost cannot be negative")
        pooled_cost = self.total_value() + cost
        self.count += quantity
        self.unit_cost = pooled_cost / self.count

    def ship(self, quantity):
        if quantity <= 0:
            raise ValueError("shipped quantity must be positive")
        if quantity > self.count:
            raise ValueError("cannot ship %d of %d units" % (quantity, self.count))
        self.count -= quantity

    def total_value(self):
        return self.count * self.unit_cost

    def describe(self):
        return "%d units @ %.2f = %.2f" % (self.count, self.unit_cost, self.total_value())


class InventoryLedger:
    """Applies a sequence of stock movements and keeps a readable trail."""

    def __init__(self, inventory):
        self.inventory = inventory
        self.history = []

    def apply(self, action, quantity, cost):
        if action == "receive":
            self.inventory.receive(quantity, cost)
        elif action == "ship":
            self.inventory.ship(quantity)
        else:
            raise ValueError("unknown action: %r" % (action,))
        self.history.append((action, quantity, self.inventory.total_value()))

    def process(self, changes):
        for entry in changes:
            action, quantity, cost = self.unpack(entry)
            self.apply(action, quantity, cost)
        return self.inventory.total_value()

    def unpack(self, entry):
        if len(entry) == 2:
            action, quantity = entry
            return action, quantity, 0
        if len(entry) != 3:
            raise ValueError("change entry needs an action, quantity and cost")
        return entry

    def report(self):
        lines = ["%-8s %4d -> value %.2f" % row for row in self.history]
        lines.append("final: " + self.inventory.describe())
        return "\n".join(lines)


def stock(changes):
    ledger = InventoryLedger(Inventory())
    return ledger.process(changes)


if __name__ == "__main__":
    movements = [("receive", 10, 100), ("ship", 4, 0), ("receive", 4, 80)]
    audit = InventoryLedger(Inventory())
    print(audit.process(movements))
    print(audit.report())
    print(stock(movements))

