class SalesLog:
    def __init__(self):
        self.sales = []
        self.refunds = []
        self.rejected = 0

    def record_sale(self, kind, price):
        self.sales.append((kind, price))

    def record_refund(self, amount):
        self.refunds.append(amount)

    def record_rejected(self):
        self.rejected += 1

    def tickets_sold(self):
        return len(self.sales)

    def refunded_total(self):
        return sum(self.refunds)

    def summary_lines(self):
        lines = ["tickets sold: %d" % self.tickets_sold()]
        for kind, price in self.sales:
            lines.append("  %s ticket: $%d" % (kind, price))
        lines.append("refunded: $%d" % self.refunded_total())
        lines.append("ignored sales (sold out): %d" % self.rejected)
        return lines


class Theater:
    PRICES = {"standard": 10, "premium": 15}

    def __init__(self, total_seats=40):
        self.total_seats = total_seats
        self.seats_sold = 0
        self.revenue = 0
        self.log = SalesLog()

    def seats_available(self):
        return self.total_seats - self.seats_sold

    def sell(self, kind):
        price = self.PRICES[kind]
        if self.seats_available() <= 0:
            self.log.record_rejected()
            return False
        self.seats_sold += 1
        self.revenue += price
        self.log.record_sale(kind, price)
        return True

    def refund(self, amount):
        self.revenue -= amount
        self.log.record_refund(amount)
        return True

    def final_revenue(self):
        return self.revenue


class BoxOffice:
    def __init__(self, theater):
        self.theater = theater

    def apply(self, action, amount):
        if action == "refund":
            return self.theater.refund(amount)
        if action in self.theater.PRICES:
            return self.theater.sell(action)
        raise ValueError("unknown action: %r" % (action,))

    def run(self, patrons):
        for action, amount in patrons:
            self.apply(action, amount)
        return self.theater.final_revenue()

    def report(self):
        lines = self.theater.log.summary_lines()
        lines.append("seats left: %d" % self.theater.seats_available())
        lines.append("final revenue: $%d" % self.theater.final_revenue())
        return "\n".join(lines)


def screen(patrons):
    return BoxOffice(Theater()).run(patrons)


def main():
    patrons = [("standard", 0), ("premium", 0), ("refund", 10), ("standard", 0)]
    office = BoxOffice(Theater())
    print(office.run(patrons))
    print(office.report())


if __name__ == "__main__":
    main()

