class Factory:
    """Tracks raw materials, finished goods and defective build attempts."""

    MATERIALS_PER_UNIT = 3

    def __init__(self):
        self.materials = 0
        self.finished = 0
        self.defects = 0

    def restock(self, amount):
        self.materials += amount
        return self.materials

    def build(self):
        if self.materials < self.MATERIALS_PER_UNIT:
            self.defects += 1
            return False
        self.materials -= self.MATERIALS_PER_UNIT
        self.finished += 1
        return True

    def audit(self):
        return self.finished, self.defects


class AssemblyLine:
    """Applies a sequence of (action, amount) operations to a factory."""

    def __init__(self, factory=None):
        self.factory = factory if factory is not None else Factory()
        self.history = []

    def parse(self, operation):
        action, amount = operation
        if action not in ("restock", "build"):
            raise ValueError("unknown action: {!r}".format(action))
        if not isinstance(amount, int) or isinstance(amount, bool):
            raise ValueError("amount must be an integer, got {!r}".format(amount))
        if amount < 0:
            raise ValueError("amount must not be negative: {}".format(amount))
        return action, amount

    def apply(self, operation):
        action, amount = self.parse(operation)
        if action == "restock":
            outcome = "materials={}".format(self.factory.restock(amount))
        else:
            outcome = "built" if self.factory.build() else "defect"
        self.history.append((action, amount, outcome))
        return outcome

    def run(self, operations):
        for operation in operations:
            self.apply(operation)
        return self.audit()

    def audit(self):
        return self.factory.audit()


class Report:
    """Renders a human readable summary of a finished production run."""

    def __init__(self, line, title="Production report"):
        self.line = line
        self.title = title

    def body(self):
        return ["  {:>2}. {:<8} {:>3} -> {}".format(index, action, amount, outcome)
                for index, (action, amount, outcome) in enumerate(self.line.history, 1)]

    def render(self):
        finished, defects = self.line.audit()
        rows = [self.title] + self.body()
        rows.append("  finished={} defects={}".format(finished, defects))
        return "\n".join(rows)


def assemble(operations):
    return AssemblyLine().run(operations)


def main():
    schedule = [("restock", 5), ("build", 0), ("build", 0), ("restock", 2), ("build", 0)]
    line = AssemblyLine()
    line.run(schedule)
    print(Report(line).render())
    print("assemble ->", assemble(schedule))


if __name__ == "__main__":
    main()

