class VehicleTariff:
    def __init__(self, rates):
        self.rates = dict(rates)

    def covers(self, kind):
        return kind in self.rates

    def fee(self, kind):
        if not self.covers(kind):
            raise ValueError("unknown vehicle type: {}".format(kind))
        return self.rates[kind]

    def vehicle_types(self):
        return sorted(self.rates)


class Shift:
    def __init__(self, number, vehicle_types):
        self.number = number
        self.counts = {kind: 0 for kind in vehicle_types}

    def record(self, kind):
        self.counts[kind] += 1
        return self.counts[kind]

    def processed(self):
        return sum(self.counts.values())

    def breakdown(self):
        return ", ".join("{}: {}".format(k, self.counts[k]) for k in sorted(self.counts))

    def describe(self):
        return "shift {} -> {} vehicles ({})".format(self.number, self.processed(), self.breakdown())


class TollPlaza:
    def __init__(self, tariff):
        self.tariff = tariff
        self.revenue = 0
        self.shift = Shift(1, self.tariff.vehicle_types())
        self.closed_shifts = []

    def handle(self, event):
        name = event.strip().lower()
        if name == "shift":
            self.rotate_shift()
        elif self.tariff.covers(name):
            self.admit(name)
        else:
            raise ValueError("unrecognized event: {}".format(event))

    def admit(self, kind):
        self.revenue += self.tariff.fee(kind)
        self.shift.record(kind)

    def rotate_shift(self):
        self.closed_shifts.append(self.shift)
        self.shift = Shift(self.shift.number + 1, self.tariff.vehicle_types())

    def run(self, events):
        for event in events:
            self.handle(event)
        return self.summary()

    def summary(self):
        return [self.revenue, self.shift.processed()]

    def report(self):
        lines = ["total revenue: ${}".format(self.revenue)]
        for past in self.closed_shifts:
            lines.append(past.describe())
        lines.append(self.shift.describe() + " (active)")
        return "\n".join(lines)


def toll(events):
    plaza = TollPlaza(VehicleTariff({"car": 2, "truck": 5}))
    return plaza.run(events)


def main():
    sample = ["car", "truck", "shift", "car"]
    plaza = TollPlaza(VehicleTariff({"car": 2, "truck": 5}))
    print(plaza.run(sample))
    print(plaza.report())
    print(toll(["truck", "truck", "car", "shift", "shift", "truck"]))


if __name__ == "__main__":
    main()

