class CoolingFan:
    def __init__(self, threshold=30, relief=5):
        self.threshold = threshold
        self.relief = relief

    def is_triggered(self, temperature):
        return temperature > self.threshold

    def correct(self, temperature):
        if self.is_triggered(temperature):
            return temperature - self.relief
        return temperature


class Sprinkler:
    def __init__(self, floor=30, boost=10):
        self.floor = floor
        self.boost = boost

    def is_triggered(self, moisture):
        return moisture < self.floor

    def correct(self, moisture):
        if self.is_triggered(moisture):
            return moisture + self.boost
        return moisture


class Greenhouse:
    def __init__(self, temperature=20, moisture=50):
        self.temperature = temperature
        self.moisture = moisture
        self.fan = CoolingFan()
        self.sprinkler = Sprinkler()
        self.history = []

    def validated(self, readings):
        for reading in readings:
            if not isinstance(reading, int) or isinstance(reading, bool):
                raise TypeError("readings must be integers, got %r" % (reading,))
            yield reading

    def apply_reading(self, reading):
        self.temperature += reading
        self.moisture -= reading
        self.temperature = self.fan.correct(self.temperature)
        self.moisture = self.sprinkler.correct(self.moisture)
        self.history.append((reading, self.temperature, self.moisture))

    def state(self):
        return [self.temperature, self.moisture]

    def run(self, readings):
        for reading in self.validated(readings):
            self.apply_reading(reading)
        return self.state()


class ClimateReport:
    def __init__(self, house):
        self.house = house
        self.width = max([len(str(row[0])) for row in house.history] + [7])

    def format_row(self, reading, temperature, moisture):
        return "{:>{w}} | {:>4} | {:>8}".format(reading, temperature, moisture, w=self.width)

    def lines(self):
        rows = [self.format_row("reading", "temp", "moist")]
        for reading, temperature, moisture in self.house.history:
            rows.append(self.format_row(reading, temperature, moisture))
        rows.append("final: " + ", ".join(str(value) for value in self.house.state()))
        return rows

    def render(self):
        return "\n".join(self.lines())


def greenhouse(readings):
    return Greenhouse().run(readings)


def main():
    samples = [10, 5, -10]
    house = Greenhouse()
    house.run(samples)
    print(ClimateReport(house).render())
    print("greenhouse(%r) -> %r" % (samples, greenhouse(samples)))
