class CoolingFan:
    def __init__(this, threshold=30, relief=5):
        this.threshold = threshold
        this.relief = relief

    def is_triggered(this, temperature):
        return temperature > this.threshold

    def correct(this, temperature):
        if this.is_triggered(temperature):
            return temperature - this.relief
        return temperature


class Sprinkler:
    def __init__(this, floor=30, boost=10):
        this.floor = floor
        this.boost = boost

    def is_triggered(this, moisture):
        return moisture < this.floor

    def correct(this, moisture):
        if this.is_triggered(moisture):
            return moisture + this.boost
        return moisture


class Greenhouse:
    def __init__(this, temperature=20, moisture=50):
        this.temperature = temperature
        this.moisture = moisture
        this.fan = CoolingFan()
        this.sprinkler = Sprinkler()
        this.history = []

    def validated(this, readings):
        for reading in readings:
            if not isinstance(reading, int) or isinstance(reading, bool):
                raise TypeError("readings must be integers, got %r" % (reading,))
            yield reading

    def apply_reading(this, reading):
        this.temperature += reading
        this.moisture -= reading
        this.temperature = this.fan.correct(this.temperature)
        this.moisture = this.sprinkler.correct(this.moisture)
        this.history.append((reading, this.temperature, this.moisture))

    def state(this):
        return [this.temperature, this.moisture]

    def run(this, readings):
        for reading in this.validated(readings):
            this.apply_reading(reading)
        return this.state()


class ClimateReport:
    def __init__(this, house):
        this.house = house
        this.width = max([len(str(row[0])) for row in house.history] + [7])

    def format_row(this, reading, temperature, moisture):
        return "{:>{w}} | {:>4} | {:>8}".format(reading, temperature, moisture, w=this.width)

    def lines(this):
        rows = [this.format_row("reading", "temp", "moist")]
        for reading, temperature, moisture in this.house.history:
            rows.append(this.format_row(reading, temperature, moisture))
        rows.append("final: " + ", ".join(str(value) for value in this.house.state()))
        return rows

    def render(this):
        return "\n".join(this.lines())


def greenhouse(readings):
    return Greenhouse().run(readings)


def main():
    samples = [10, 5, -10]
    house = Greenhouse()
    house.run(samples)
    print(ClimateReport(house).render())
    print("greenhouse(%r) -> %r" % (samples, greenhouse(samples)))
    print("greenhouse([25, 25]) -> %r" % (greenhouse([25, 25]),))


if __name__ == "__main__":
    main()

