class Farm:
    SEEDS_PER_PLANTING = 10
    FOOD_PER_SEED = 2
    DAYS_TO_MATURITY = 3

    def __init__(self):
        self.storage = 0
        self.seeds = 0
        self.growth_days = 0

    def plant(self):
        self.seeds += self.SEEDS_PER_PLANTING
        self.growth_days = 0
        return self.seeds

    def wait(self):
        self.growth_days += 1
        return self.growth_days

    def is_mature(self):
        return self.growth_days >= self.DAYS_TO_MATURITY

    def reap(self):
        yielded = 0
        if self.is_mature():
            yielded = self.seeds * self.FOOD_PER_SEED
            self.storage += yielded
        self.seeds = 0
        self.growth_days = 0
        return yielded


class FarmJournal:
    def __init__(self, farm):
        self.farm = farm
        self.entries = []
        self.actions = {
            "plant": self.record_plant,
            "wait": self.record_wait,
            "reap": self.record_reap,
        }

    def run(self, command):
        action = self.actions.get(command)
        if action is None:
            raise ValueError("unknown farm command: {!r}".format(command))
        action()

    def record_plant(self):
        seeds = self.farm.plant()
        self.entries.append("planted, {} seeds in the ground".format(seeds))

    def record_wait(self):
        days = self.farm.wait()
        self.entries.append("waited, crops now {} day(s) old".format(days))

    def record_reap(self):
        gained = self.farm.reap()
        if gained:
            self.entries.append("reaped {} food (total {})".format(gained, self.farm.storage))
        else:
            self.entries.append("reaped too early, ground cleared")

    def report(self):
        lines = list(self.entries)
        lines.append("final storage: {} food".format(self.farm.storage))
        return "\n".join(lines)


def harvest(cycles):
    journal = FarmJournal(Farm())
    for command in cycles:
        journal.run(command.strip().lower())
    return journal.farm.storage


def main():
    season = ["plant", "wait", "wait", "wait", "reap", "plant", "wait", "reap"]
    journal = FarmJournal(Farm())
    for command in season:
        journal.run(command)
    print(journal.report())
    print("harvest() returns:", harvest(season))


if __name__ == "__main__":
    main()

