class TicketInspector:
    """Keeps a running tally of tickets checked, fines issued and removals."""

    NO_TICKET_FINE = 50
    FORGED_TICKET_FINE = 100

    def __init__(self):
        self.valid_tickets = 0
        self.fines_issued = 0
        self.fine_revenue = 0
        self.forged_tickets = 0
        self.removed_seats = []

    def reset(self):
        self.valid_tickets = 0
        self.fines_issued = 0
        self.fine_revenue = 0
        self.forged_tickets = 0
        self.removed_seats = []

    def accept_ticket(self):
        self.valid_tickets += 1

    def issue_fine(self, amount):
        self.fines_issued += 1
        self.fine_revenue += amount

    def remove_passenger(self, seat):
        self.forged_tickets += 1
        self.removed_seats.append(seat)

    def check(self, seat, status):
        if status == 1:
            self.accept_ticket()
        elif status == 0:
            self.issue_fine(self.NO_TICKET_FINE)
        elif status == -1:
            self.issue_fine(self.FORGED_TICKET_FINE)
            self.remove_passenger(seat)
        else:
            raise ValueError("unknown ticket status at seat %d: %r" % (seat, status))

    def totals(self):
        return [self.valid_tickets, self.fine_revenue, self.forged_tickets]

    def inspect(self, passengers):
        self.reset()
        for seat, status in enumerate(passengers, start=1):
            self.check(seat, status)
        return self.totals()


class InspectionReport:
    """Turns an inspector's tallies into human readable output."""

    def __init__(self, inspector):
        self.inspector = inspector

    def average_fine(self):
        if self.inspector.fines_issued == 0:
            return 0.0
        return self.inspector.fine_revenue / self.inspector.fines_issued

    def lines(self):
        report = ["Valid tickets: %d" % self.inspector.valid_tickets,
                  "Fines issued: %d" % self.inspector.fines_issued,
                  "Fine revenue: %d" % self.inspector.fine_revenue,
                  "Average fine: %.2f" % self.average_fine(),
                  "Forged tickets: %d" % self.inspector.forged_tickets]
        if self.inspector.removed_seats:
            seats = ", ".join(str(s) for s in self.inspector.removed_seats)
            report.append("Removed from seats: " + seats)
        return report

    def __str__(self):
        return "\n".join(self.lines())


def inspect(passengers):
    return TicketInspector().inspect(passengers)


def main():
    inspector = TicketInspector()
    print(inspector.inspect([1, 0, -1, 1]))
    print(InspectionReport(inspector))
    print(inspect([0, 0, -1, -1, 1]))


if __name__ == "__main__":
    main()

