class Party:
    """A group of guests either arriving at or leaving the restaurant."""

    def __init__(self, size):
        if not isinstance(size, int):
            raise TypeError("party size must be an integer")
        if size == 0:
            raise ValueError("party size must be non-zero")
        self.size = size

    def is_arrival(self):
        return self.size > 0

    def guests(self):
        return abs(self.size)

    def describe(self):
        direction = "arrives" if self.is_arrival() else "leaves"
        return "a party of {0} {1}".format(self.guests(), direction)


class ServiceLog:
    """Keeps the chronological record of what happened to every party."""

    def __init__(self):
        self.entries = []

    def record(self, message):
        self.entries.append(message)

    def formatted(self):
        return ["{0}. {1}".format(number, text)
                for number, text in enumerate(self.entries, 1)]


class Restaurant:
    TOTAL_TABLES = 10

    def __init__(self):
        self.available_tables = self.TOTAL_TABLES
        self.seated_guests = 0
        self.total_served = 0
        self.log = ServiceLog()

    def has_free_table(self):
        return self.available_tables > 0

    def seat(self, party):
        self.available_tables -= 1
        self.seated_guests += party.guests()
        self.log.record("{0} and is seated".format(party.describe()))

    def release(self, party):
        self.available_tables += 1
        self.seated_guests -= party.guests()
        self.total_served += party.guests()
        self.log.record("{0} after being served".format(party.describe()))

    def process(self, party):
        if not party.is_arrival():
            self.release(party)
        elif self.has_free_table():
            self.seat(party)
        else:
            self.log.record("{0} but finds no table".format(party.describe()))

    def run(self, parties):
        for size in parties:
            self.process(Party(size))
        return self.summary()

    def summary(self):
        return [self.total_served, self.available_tables]

    def report(self):
        header = "served {0} guests, {1} tables free, {2} guests still seated".format(
            self.total_served, self.available_tables, self.seated_guests)
        return "\n".join([header] + self.log.formatted())


def restaurant(parties):
    house = Restaurant()
    return house.run(parties)


if __name__ == "__main__":
    print(restaurant([4, 2, -4]))
    evening = Restaurant()
    print(evening.run([2, 3, 1, 1, 2, 4, 2, 1, 3, 2, 5, -3, -1]))
    print(evening.report())

