class WindMonitor:
    STRONG_SPEED = 50
    CALM_SPEED = 10
    SAFE_LIMIT = 40

    def __init__(self):
        self.speed = 0

    def gust(self):
        self.speed = self.STRONG_SPEED
        return self.speed

    def calm(self):
        self.speed = self.CALM_SPEED
        return self.speed

    def is_safe(self):
        return self.speed < self.SAFE_LIMIT

    def describe(self):
        state = "open" if self.is_safe() else "closed"
        return f"wind {self.speed} km/h ({state})"


class Chairlift:
    CAPACITY = 4

    def __init__(self):
        self.wind = WindMonitor()
        self.trips = 0
        self.skiers = 0

    def carry(self, group):
        if not self.wind.is_safe():
            return 0
        trips = -(-group // self.CAPACITY)
        self.trips += trips
        self.skiers += group
        return trips

    def handle(self, event):
        if event == -1:
            return f"strong wind, {self.wind.gust()} km/h"
        if event == -2:
            return f"calm wind, {self.wind.calm()} km/h"
        if event <= 0:
            raise ValueError(f"unknown event code: {event}")
        trips = self.carry(event)
        if trips:
            return f"group of {event} carried in {trips} trip(s)"
        return f"group of {event} turned away"

    def totals(self):
        return self.trips, self.skiers

    def summary(self):
        return f"totals: {self.trips} trip(s), {self.skiers} skier(s), {self.wind.describe()}"


class DayReport:
    def __init__(self, label):
        self.label = label
        self.lift = Chairlift()
        self.entries = []

    def run(self, events):
        for event in events:
            self.entries.append(self.lift.handle(event))
        return self.lift.totals()

    def render(self):
        lines = [f"== {self.label} =="]
        lines.extend(f"  {n}. {text}" for n, text in enumerate(self.entries, 1))
        lines.append("  " + self.lift.summary())
        return "\n".join(lines)


def skilift(skiers):
    lift = Chairlift()
    for event in skiers:
        if not isinstance(event, int) or isinstance(event, bool):
            raise TypeError(f"events must be integers, got {event!r}")
        lift.handle(event)
    return lift.totals()


def main():
    report = DayReport("Saturday")
    report.run([-2, 5, -1, 3, -2, 9, 12])
    print(report.render())
    print(skilift([-2, 5, -1, 3]))


if __name__ == "__main__":
    main()

