class ManifestValidator:
    """Checks that an incoming manifest really contains usable container weights."""

    def __init__(self, source_name):
        self.source_name = source_name
        self.inspected = 0

    def validate(self, containers):
        if not isinstance(containers, (list, tuple)):
            raise TypeError("%s must be a list or tuple of weights" % self.source_name)
        return [self.validate_one(index, weight) for index, weight in enumerate(containers)]

    def validate_one(self, index, weight):
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise TypeError("%s[%d] is not a numeric weight" % (self.source_name, index))
        if weight <= 0:
            raise ValueError("%s[%d] must be a positive weight" % (self.source_name, index))
        self.inspected += 1
        return weight


class CargoShip:
    """A ship that loads containers while respecting a hard weight limit."""

    MAX_WEIGHT = 1000
    REST_INTERVAL = 5
    REST_COST = 20

    def __init__(self):
        self.current_weight = 0
        self.loaded = 0
        self.rejected = 0
        self.rest_breaks = 0

    def can_load(self, weight):
        return self.current_weight + weight <= self.MAX_WEIGHT

    def capacity_left(self):
        return self.MAX_WEIGHT - self.current_weight

    def take_rest_break(self):
        self.rest_breaks += 1
        self.current_weight = max(0, self.current_weight - self.REST_COST)

    def load(self, weight):
