class ManifestValidator:
    """Checks that an incoming manifest really contains usable container weights."""

    def __init__(this, source_name):
        this.source_name = source_name
        this.inspected = 0

    def validate(this, containers):
        if not isinstance(containers, (list, tuple)):
            raise TypeError("%s must be a list or tuple of weights" % this.source_name)
        return [this.validate_one(index, weight) for index, weight in enumerate(containers)]

    def validate_one(this, index, weight):
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise TypeError("%s[%d] is not a numeric weight" % (this.source_name, index))
        if weight <= 0:
            raise ValueError("%s[%d] must be a positive weight" % (this.source_name, index))
        this.inspected += 1
        return weight


class CargoShip:
    """A ship that loads containers while respecting a hard weight limit."""

    MAX_WEIGHT = 1000
    REST_INTERVAL = 5
    REST_COST = 20

    def __init__(this):
        this.current_weight = 0
        this.loaded = 0
        this.rejected = 0
        this.rest_breaks = 0

    def can_load(this, weight):
        return this.current_weight + weight <= this.MAX_WEIGHT

    def capacity_left(this):
        return this.MAX_WEIGHT - this.current_weight

    def take_rest_break(this):
        this.rest_breaks += 1
        this.current_weight = max(0, this.current_weight - this.REST_COST)

    def load(this, weight):
        if not this.can_load(weight):
            this.rejected += 1
            return False
        this.current_weight += weight
        this.loaded += 1
        if this.loaded % this.REST_INTERVAL == 0:
            this.take_rest_break()
        return True

    def process(this, weights):
        for weight in weights:
            this.load(weight)
        return this.summary()

    def summary(this):
        return [this.loaded, this.current_weight, this.rejected]


