def normalize(amount):
    """Return whole money values as ints so that 35.0 prints as 35."""
    rounded = round(amount, 2)
    if rounded == int(rounded):
        return int(rounded)
    return rounded


class DeliveryLog:
    """Keeps a per-delivery history of a shift."""

    def __init__(self):
        self.entries = []

    def record(self, distance, tip, miles, refueled):
        self.entries.append(
            {"distance": distance, "tip": tip, "miles": miles, "refueled": refueled}
        )

    def total_tips(self):
        return sum(entry["tip"] for entry in self.entries)

    def refuel_stops(self):
        return sum(1 for entry in self.entries if entry["refueled"])


class Driver:
    """A pizza delivery driver tracking cash, miles and completed deliveries."""

    STARTING_FLOAT = 20
    REFUEL_THRESHOLD = 50
    REFUEL_COST = 15

    def __init__(self, name):
        self.name = name
        self.cash = self.STARTING_FLOAT
        self.miles_driven = 0
        self.deliveries_completed = 0
        self.log = DeliveryLog()

    def validated(self, orders):
        clean = []
        for distance in orders:
            if isinstance(distance, bool) or not isinstance(distance, int):
                raise TypeError(f"{self.name}: distances must be integers, got {distance!r}")
            if distance < 0:
                raise ValueError(f"{self.name}: distance cannot be negative ({distance})")
            clean.append(distance)
        return clean

    def drive(self, distance):
        self.miles_driven += distance

    def collect_tip(self, distance):
        tip = distance / 2
        self.cash += tip
        return tip

    def refuel(self):
        self.cash -= self.REFUEL_COST
        self.miles_driven = 0

    def run_shift(self, orders):
        for distance in self.validated(orders):
            self.drive(distance)
            tip = self.collect_tip(distance)
            self.deliveries_completed += 1
            refueled = self.miles_driven >= self.REFUEL_THRESHOLD
            if refueled:
                self.refuel()
            self.log.record(distance, tip, self.miles_driven, refueled)
        return [normalize(self.cash), self.deliveries_completed]


class ShiftReport:
    """Formats the outcome of a driver's shift."""

    def __init__(self, driver):
        self.driver = driver

    def lines(self):
        report = [f"Shift report for {self.driver.name}"]
        for number, entry in enumerate(self.driver.log.entries, start=1):
            note = " (refuelled)" if entry["refueled"] else ""
            report.append(
                f"  #{number}: {entry['distance']} mi, tip {normalize(entry['tip'])}, "
                f"odometer {entry['miles']}{note}"
            )
        report.append(f"  tips collected: {normalize(self.driver.log.total_tips())}")
        report.append(f"  refuel stops: {self.driver.log.refuel_stops()}")
        report.append(f"  cash on hand: {normalize(self.driver.cash)}")
        return report

    def render(self):
        return "\n".join(self.lines())


def delivery(orders):
    return Driver("Sam").run_shift(orders)


def main():
    driver = Driver("Sam")
    result = driver.run_shift([10, 20, 30])
    print(ShiftReport(driver).render())
    print(f"Result: {result}")


if __name__ == "__main__":
    main()

