START_MANA = 100
XP_PER_CAST = 10
EXHAUSTION_COST = 5
XP_PER_LEVEL = 50


def validate_cost(cost):
    if not isinstance(cost, int) or isinstance(cost, bool):
        raise TypeError("spell cost must be an integer, got %r" % (cost,))
    if cost < 0:
        raise ValueError("spell cost must not be negative: %d" % cost)


class Wizard:
    def __init__(self):
        self.mana = START_MANA
        self.experience = 0
        self.level = 1

    def can_cast(self, cost):
        return self.mana >= cost

    def cast(self, cost):
        if not self.can_cast(cost):
            self.mana -= EXHAUSTION_COST
            return False
        self.mana -= cost
        self.experience += XP_PER_CAST
        self.check_level_up()
        return True

    def check_level_up(self):
        earned = self.experience // XP_PER_LEVEL + 1
        if earned > self.level:
            self.level = earned
            self.mana = START_MANA

    def status(self):
        mana = self.mana
        return [mana, self.experience]


class SpellBook:
    def __init__(self):
        self.wizard = Wizard()
        self.log = []

    def attempt(self, cost):
        validate_cost(cost)
        success = self.wizard.cast(cost)
        entry = (cost, success) + tuple(self.wizard.status())
        self.log.append(entry)
        return success

    def run(self, casts):
        for cost in casts:
            self.attempt(cost)
        return self.wizard.status()

    def successes(self):
        return sum(1 for entry in self.log if entry[1])

    def failures(self):
        attempted = len(self.log)
        return attempted - self.successes()


class Report:
    def __init__(self, book):
        self.book = book

    def rows(self):
        lines = ["cost  result  mana   xp"]
        for cost, success, mana, experience in self.book.log:
            outcome = "cast" if success else "fail"
            lines.append("%4d  %6s  %4d  %3d" % (cost, outcome, mana, experience))
        return lines

    def summary(self):
        book = self.book
        wizard = book.wizard
        return "level %d, %d cast, %d failed, final %s" % (
            wizard.level, book.successes(), book.failures(), wizard.status())

    def render(self):
        lines = self.rows()
        lines.append(self.summary())
        return "\n".join(lines)


def spellbook(casts):
    return SpellBook().run(casts)


def main():
    casts = [40, 30, 10, 10, 10, 30, 30, 20, 10, 10, 120]
    book = SpellBook()
    book.run(casts)
    print(Report(book).render())
    print("spellbook(%r) -> %r" % (casts, spellbook(casts)))


if __name__ == "__main__":
    main()

