def _as_int(item):
    if isinstance(item, bool) or not isinstance(item, int):
        raise TypeError("carousel items must be integers, got {!r}".format(item))
    return item


class BaggageCarousel:
    """A carousel of fixed capacity that overflows into unclaimed storage."""

    def __init__(self, capacity=20):
        self.capacity = capacity
        self.on_carousel = 0
        self.total_processed = 0
        self.unclaimed_removed = 0

    def load(self, bags):
        self.total_processed += bags
        space = self.capacity - self.on_carousel
        if bags > space:
            self.unclaimed_removed += bags - space
            self.on_carousel = self.capacity
        else:
            self.on_carousel += bags
        return self.on_carousel

    def claim(self, bags):
        self.on_carousel = max(0, self.on_carousel - bags)
        return self.on_carousel

    def handle(self, item):
        if item >= 0:
            return self.load(item)
        return self.claim(-item)

    def process(self, items):
        for item in items:
            self.handle(_as_int(item))
        return self.status()

    def status(self):
        return self.on_carousel, self.unclaimed_removed


class CarouselReport:
    """Runs a sequence through a carousel and describes every movement."""

    def __init__(self, carousel):
        self.carousel = carousel
        self.lines = []

    def run(self, items):
        for item in items:
            remaining = self.carousel.handle(_as_int(item))
            self.lines.append(self.describe(item, remaining))
        return self.carousel.status()

    def describe(self, item, remaining):
        action = "arrived" if item >= 0 else "claimed"
        return "{:>3} bags {}: {:>2} on carousel, {} unclaimed".format(
            abs(item), action, remaining, self.carousel.unclaimed_removed)

    def summary(self):
        remaining, unclaimed = self.carousel.status()
        head = "Carousel capacity {}".format(self.carousel.capacity)
        tail = "{} bags arrived in total".format(self.carousel.total_processed)
        final = "final: {} on carousel, {} unclaimed".format(remaining, unclaimed)
        return "\n".join([head] + self.lines + [tail, final])


def baggage(items):
    return BaggageCarousel().process(items)


def main():
    print(baggage([15, 10, -5]))
    report = CarouselReport(BaggageCarousel())
    print(report.run([8, 14, -3, 6, -25, 2]))
    print(report.summary())


if __name__ == "__main__":
    main()

