class AlarmPanel:
    DISARMED = "disarmed"
    ARMED_AWAY = "armed away"
    ARMED_STAY = "armed stay"

    def __init__(self):
        self.state = self.DISARMED
        self.trigger_count = 0
        self.alarming = False

    def arm(self, mode):
        self.state = mode
        self.alarming = False
        return self.state

    def disarm(self):
        self.state = self.DISARMED
        self.alarming = False
        return self.state

    def trigger(self):
        self.alarming = True
        self.trigger_count += 1
        return self.trigger_count

    def handle_motion(self):
        if self.state == self.ARMED_AWAY:
            self.trigger()
            return True
        return False

    def handle_door(self):
        if self.state in (self.ARMED_AWAY, self.ARMED_STAY):
            self.trigger()
            return True
        return False

    def summary(self):
        return [self.state, self.trigger_count]


class SecurityController:
    def __init__(self, panel=None):
        self.panel = panel or AlarmPanel()
        self.history = []

    def normalize(self, event):
        return " ".join(str(event).lower().split())

    def dispatch(self, event):
        name = self.normalize(event)
        if name == "arm away":
            self.panel.arm(AlarmPanel.ARMED_AWAY)
        elif name == "arm stay":
            self.panel.arm(AlarmPanel.ARMED_STAY)
        elif name == "disarm":
            self.panel.disarm()
        elif name == "motion":
            self.panel.handle_motion()
        elif name == "door":
            self.panel.handle_door()
        else:
            raise ValueError("unknown event: {!r}".format(event))
        self.history.append((name, self.panel.state, self.panel.alarming))
        return self.panel.state

    def run(self, events):
        for event in events:
            self.dispatch(event)
        return self.panel.summary()

    def report(self):
        lines = ["{} -> {}{}".format(name, state, " [ALARM]" if ringing else "")
                 for name, state, ringing in self.history]
        lines.append("final: {} after {} trigger(s)".format(*self.panel.summary()))
        return "\n".join(lines)


def security(events):
    return SecurityController().run(events)


def main():
    controller = SecurityController()
    print(controller.run(["arm stay", "motion", "door", "disarm"]))
    print(controller.report())
    print(security(["arm away", "motion", "door", "arm stay", "motion"]))


if __name__ == "__main__":
    main()

