    def dispatch(this, event):
        name = this.normalize(event)
        if name == "arm away":
            this.panel.arm(AlarmPanel.ARMED_AWAY)
        elif name == "arm stay":
            this.panel.arm(AlarmPanel.ARMED_STAY)
        elif name == "disarm":
            this.panel.disarm()
        elif name == "motion":
            this.panel.handle_motion()
        elif name == "door":
            this.panel.handle_door()
        else:
            raise ValueError("unknown event: {!r}".format(event))
        this.history.append((name, this.panel.state, this.panel.alarming))
        return this.panel.state

    def run(this, events):
        for event in events:
            this.dispatch(event)
        return this.panel.summary()

    def report(this):
        lines = ["{} -> {}{}".format(name, state, " [ALARM]" if ringing else "")
                 for name, state, ringing in this.history]
        lines.append("final: {} after {} trigger(s)".format(*this.panel.summary()))
        return "\n".join(lines)


def security(events):
    return SecurityController().run(events)


def main():
    controller = SecurityController()
    print(controller.run(["arm stay", "motion", "door", "disarm"]))
    print(controller.report())
    print(security(["arm away", "motion", "door", "arm stay", "motion"]))


if __name__ == "__main__":
    main()

