from collections import deque


class Kitchen:
    """Tracks chefs, revenue and pending room-service orders."""

    def __init__(self, chefs=3):
        self.total_chefs = chefs
        self.available_chefs = chefs
        self.revenue = 0
        self.pending = deque()

    def assign(self, price):
        self.available_chefs -= 1
        self.revenue += price

    def receive_order(self, price):
        if self.available_chefs > 0:
            self.assign(price)
        else:
            self.pending.append(price)

    def finish_order(self):
        if self.available_chefs < self.total_chefs:
            self.available_chefs += 1
        if self.pending:
            self.assign(self.pending.popleft())

    def handle(self, request):
        if request == 0:
            self.finish_order()
        else:
            self.receive_order(request)

    def busy_chefs(self):
        return self.total_chefs - self.available_chefs

    def summary(self):
        return self.revenue, len(self.pending)


class ServiceReport:
    """Turns a kitchen's state into human-readable lines."""

    def __init__(self, kitchen):
        self.kitchen = kitchen

    def revenue_line(self):
        revenue, _ = self.kitchen.summary()
        return "Revenue collected: {}".format(revenue)

    def queue_line(self):
        _, waiting = self.kitchen.summary()
        if waiting == 0:
            return "No orders waiting in the queue"
        return "Orders still pending: {} (prices {})".format(
            waiting, ", ".join(str(p) for p in self.kitchen.pending)
        )

    def staff_line(self):
        return "Chefs busy: {} of {}".format(
            self.kitchen.busy_chefs(), self.kitchen.total_chefs
        )

    def render(self):
        return "\n".join([self.staff_line(), self.revenue_line(), self.queue_line()])


def roomservice(requests):
    kitchen = Kitchen()
    for request in requests:
        if not isinstance(request, int) or isinstance(request, bool):
            raise TypeError("requests must contain integers, got {!r}".format(request))
        if request < 0:
            raise ValueError("request prices cannot be negative: {}".format(request))
        kitchen.handle(request)
    return kitchen.summary()


def main():
    shift = [20, 30, 15, 40, 0, 0, 25, 0, 50, 10]
    kitchen = Kitchen()
    for request in shift:
        kitchen.handle(request)
    print(ServiceReport(kitchen).render())
    print("roomservice([20, 30, 15, 40]) ->", roomservice([20, 30, 15, 40]))
    print("roomservice(shift) ->", roomservice(shift))


if __name__ == "__main__":
    main()

