class Train:
    def __init__(self, capacity=8):
        self.capacity = capacity
        self.riders = 0

    def seats_left(self):
        return self.capacity - self.riders

    def fits(self, group):
        return group <= self.seats_left()

    def board(self, group):
        self.riders += group

    def is_empty(self):
        return self.riders == 0

    def dispatch(self):
        leaving = self.riders
        self.riders = 0
        return leaving


class DispatchSystem:
    def __init__(self, capacity=8):
        self.train = Train(capacity)
        self.dispatches = 0
        self.total_riders = 0

    def validate(self, group):
        if not isinstance(group, int) or isinstance(group, bool):
            raise TypeError("group sizes must be integers, got %r" % (group,))
        if group < 1:
            raise ValueError("group sizes must be positive, got %d" % group)
        if group > self.train.capacity:
            raise ValueError("group of %d cannot fit a train of %d"
                             % (group, self.train.capacity))

    def accept(self, group):
        self.validate(group)
        if not self.train.fits(group):
            self.send_train()
        self.train.board(group)

    def send_train(self):
        self.total_riders += self.train.dispatch()
        self.dispatches += 1

    def close(self):
        if not self.train.is_empty():
            self.send_train()
        return [self.dispatches, self.total_riders]

    def report(self):
        average = self.total_riders / self.dispatches if self.dispatches else 0.0
        return ("%d dispatches carried %d riders (%.2f per train)"
                % (self.dispatches, self.total_riders, average))


def themepark(groups):
    system = DispatchSystem()
    for group in groups:
        system.accept(group)
    return system.close()


def main():
    queues = [[4, 3, 5], [8, 8, 1], [2, 2, 2, 2], [1]]
    for queue in queues:
        dispatches, riders = themepark(queue)
        print("%-16s -> %s" % (queue, [dispatches, riders]))
    busy_day = DispatchSystem()
    for group in [6, 3, 3, 2, 7, 1]:
        busy_day.accept(group)
    busy_day.close()
    print(busy_day.report())


if __name__ == "__main__":
    main()

