class AuctionLedger:
    """Chronological record of everything that happens at the rostrum."""

    def __init__(self):
        self.events = []

    def record_accepted(self, bid, highest):
        self.events.append(("accepted", bid, highest))

    def record_rejected(self, bid, highest):
        self.events.append(("rejected", bid, highest))

    def record_premium(self, highest):
        self.events.append(("premium", None, highest))

    def describe(self, event):
        kind, bid, highest = event
        if kind == "accepted":
            return "Bid of {} accepted, highest is now {}".format(bid, highest)
        if kind == "rejected":
            return "Bid of {} rejected, highest stays {}".format(bid, highest)
        return "Crowd goes wild: ten percent premium lifts the bid to {}".format(highest)

    def lines(self):
        return [self.describe(event) for event in self.events]


class Auction:
    """A running auction for a single painting."""

    def __init__(self, base_price=100):
        self.base_price = base_price
        self.highest_bid = base_price
        self.bid_count = 0
        self.ledger = AuctionLedger()

    def validate(self, bids):
        for bid in bids:
            if isinstance(bid, bool) or not isinstance(bid, int):
                raise TypeError("bids must be integers, got {!r}".format(bid))

    def is_valid(self, bid):
        return bid > self.highest_bid

    def doubles_current(self, bid):
        return bid == self.highest_bid * 2

    def apply_premium(self):
        raised = self.highest_bid * 11
        self.highest_bid = raised // 10 if raised % 10 == 0 else raised / 10
        self.ledger.record_premium(self.highest_bid)

    def place(self, bid):
        if not self.is_valid(bid):
            self.ledger.record_rejected(bid, self.highest_bid)
            return False
        wild = self.doubles_current(bid)
        self.highest_bid = bid
        self.bid_count += 1
        self.ledger.record_accepted(bid, self.highest_bid)
        if wild:
            self.apply_premium()
        return True

    def run(self, bids):
        self.validate(bids)
        for bid in bids:
            self.place(bid)
        return self.result()

    def result(self):
        return [self.highest_bid, self.bid_count]


class AuctionReporter:
    def __init__(self, sale):
        self.sale = sale

    def headline(self):
        return "Painting opens at {}".format(self.sale.base_price)

    def footer(self):
        highest, count = self.sale.result()
        return "Hammer price {} after {} valid bid(s)".format(highest, count)

    def report(self):
        body = self.sale.ledger.lines()
        return "\n".join([self.headline()] + body + [self.footer()])


def auction(bids):
    return Auction().run(bids)


def main():
    incoming = [150, 140, 300]
    sale = Auction()
    sale.run(incoming)
    print(AuctionReporter(sale).report())
    print(auction(incoming))


if __name__ == "__main__":
    main()

