class RollValidator:
    def __init__(self, max_pins=10):
        self.max_pins = max_pins

    def validate(self, rolls):
        checked = []
        for index, pins in enumerate(rolls):
            checked.append(self.check_one(index, pins))
        return checked

    def check_one(self, index, pins):
        if not isinstance(pins, int) or isinstance(pins, bool):
            raise TypeError("roll %d is not an integer: %r" % (index + 1, pins))
        if pins < 0:
            raise ValueError("roll %d knocks down a negative count" % (index + 1))
        if pins > self.max_pins:
            raise ValueError(
                "roll %d exceeds %d pins" % (index + 1, self.max_pins))
        return pins


class BowlingLane:
    def __init__(self, full_rack=10, clear_bonus=5, rolls_per_frame=2):
        self.full_rack = full_rack
        self.clear_bonus = clear_bonus
        self.rolls_per_frame = rolls_per_frame
        self.score = 0
        self.standing = full_rack
        self.rolls_in_frame = 0
        self.log = []

    def roll(self, pins):
        self.score += pins
        self.standing -= pins
        self.rolls_in_frame += 1
        if self.standing <= 0:
            self.score += self.clear_bonus
            self.rack_up()
            cleared = True
        else:
            cleared = False
            if self.rolls_in_frame >= self.rolls_per_frame:
                self.rack_up()
        self.log.append((pins, self.score, self.standing, cleared))
        return self.score

    def rack_up(self):
        self.standing = self.full_rack
        self.rolls_in_frame = 0

    def play(self, rolls):
        for pins in rolls:
            self.roll(pins)
        return self.score


class LaneReport:
    def __init__(self, lane):
        self.lane = lane

    def lines(self):
        rendered = ["roll  pins  score  standing"]
        for number, entry in enumerate(self.lane.log, start=1):
            rendered.append(self.format_entry(number, entry))
        rendered.append("final score: %d" % self.lane.score)
        return rendered

    def format_entry(self, number, entry):
        pins, score, standing, cleared = entry
        mark = " *cleared*" if cleared else ""
        return "%4d  %4d  %5d  %8d%s" % (number, pins, score, standing, mark)

    def render(self):
        return "\n".join(self.lines())


def bowling(rolls):
    checked = RollValidator().validate(rolls)
    return BowlingLane().play(checked)


def main():
    rolls = [5, 5, 3, 4]
    lane = BowlingLane()
    lane.play(RollValidator().validate(rolls))
    print(LaneReport(lane).render())
    print("bowling(%r) = %d" % (rolls, bowling(rolls)))


if __name__ == "__main__":
    main()

