class FlightPlan:
    """Validates and exposes the one-way distances of a delivery run."""

    def __init__(self, flights):
        self.flights = list(flights)

    def describe(self):
        return "plan of {} flight(s)".format(len(self.flights))

    def check(self, index, distance):
        if isinstance(distance, bool) or not isinstance(distance, int):
            raise TypeError("flight {} of the {} is not an integer".format(index, self.describe()))
        if distance < 0:
            raise ValueError("flight {} of the {} is negative".format(index, self.describe()))
        return distance

    def validated(self):
        return [self.check(index, distance) for index, distance in enumerate(self.flights)]


class Drone:
    """A drone that delivers while it has charge and recharges when it cannot."""

    def __init__(self, capacity=100):
        self.capacity = capacity
        self.battery = capacity
        self.delivered = 0

    def round_trip_cost(self, distance):
        return 2 * distance

    def can_deliver(self, distance):
        return self.round_trip_cost(distance) <= self.battery

    def deliver(self, distance):
        self.battery -= self.round_trip_cost(distance)
        self.delivered += 1

    def recharge(self):
        self.battery = self.capacity

    def attempt(self, distance):
        if self.can_deliver(distance):
            self.deliver(distance)
            return "delivered"
        self.recharge()
        return "skipped, recharged"

    def status(self):
        return self.delivered, self.battery


class Mission:
    """Runs a flight plan with a drone and keeps a log for reporting."""

    def __init__(self, flights):
        self.plan = FlightPlan(flights)
        self.drone = Drone()
        self.log = []

    def run(self):
        for distance in self.plan.validated():
            outcome = self.drone.attempt(distance)
            self.log.append((distance, outcome, self.drone.battery))
        return self.drone.status()

    def summary(self):
        delivered, battery = self.drone.status()
        return "{} package(s) delivered, battery at {}%".format(delivered, battery)

    def report_lines(self):
        lines = [self.plan.describe()]
        for distance, outcome, battery in self.log:
            lines.append("{:>4} km one way -> {} (battery {}%)".format(distance, outcome, battery))
        lines.append(self.summary())
        return lines


def drone(flights):
    return Mission(flights).run()


def main():
    flights = [20, 30, 10]
    print(drone(flights))
    mission = Mission(flights)
    mission.run()
    for line in mission.report_lines():
        print(line)


if __name__ == "__main__":
    main()

