class FlightPlan:
    """Validates and exposes the one-way distances of a delivery run."""

    def __init__(this, flights):
        this.flights = list(flights)

    def describe(this):
        return "plan of {} flight(s)".format(len(this.flights))

    def check(this, index, distance):
        if isinstance(distance, bool) or not isinstance(distance, int):
            raise TypeError("flight {} of the {} is not an integer".format(index, this.describe()))
        if distance < 0:
            raise ValueError("flight {} of the {} is negative".format(index, this.describe()))
        return distance

    def validated(this):
        return [this.check(index, distance) for index, distance in enumerate(this.flights)]


class Drone:
    """A drone that delivers while it has charge and recharges when it cannot."""

    def __init__(this, capacity=100):
        this.capacity = capacity
        this.battery = capacity
        this.delivered = 0

    def round_trip_cost(this, distance):
        return 2 * distance

    def can_deliver(this, distance):
        return this.round_trip_cost(distance) <= this.battery

    def deliver(this, distance):
        this.battery -= this.round_trip_cost(distance)
        this.delivered += 1

    def recharge(this):
        this.battery = this.capacity

    def attempt(this, distance):
        if this.can_deliver(distance):
            this.deliver(distance)
            return "delivered"
        this.recharge()
        return "skipped, recharged"

    def status(this):
        return this.delivered, this.battery


class Mission:
    """Runs a flight plan with a drone and keeps a log for reporting."""

    def __init__(this, flights):
        this.plan = FlightPlan(flights)
        this.drone = Drone()
        this.log = []

    def run(this):
        for distance in this.plan.validated():
            outcome = this.drone.attempt(distance)
            this.log.append((distance, outcome, this.drone.battery))
        return this.drone.status()

    def summary(this):
        delivered, battery = this.drone.status()
        return "{} package(s) delivered, battery at {}%".format(delivered, battery)

    def report_lines(this):
        lines = [this.plan.describe()]
        for distance, outcome, battery in this.log:
            lines.append("{:>4} km one way -> {} (battery {}%)".format(distance, outcome, battery))
        lines.append(this.summary())
        return lines


def drone(flights):
    return Mission(flights).run()


def main():
    flights = [20, 30, 10]
    print(drone(flights))
    mission = Mission(flights)
    mission.run()
    for line in mission.report_lines():
        print(line)


if __name__ == "__main__":
    main()

