class BatchValidator:
    """Checks that a batch schedule is a sequence of non-negative whole numbers."""

    def __init__(self, batches):
        self.batches = batches

    def validated(self):
        if not isinstance(self.batches, (list, tuple)):
            raise TypeError("batches must be a list of integers")
        return [self.check_size(position, size) for position, size in enumerate(self.batches)]

    def check_size(self, position, size):
        if isinstance(size, bool) or not isinstance(size, int):
            raise TypeError("batch %d is not an integer: %r" % (position, size))
        if size < 0:
            raise ValueError("batch %d is negative: %d" % (position, size))
        return size


class OilVat:
    """Holds the frying oil and tracks how cooking cools it down."""

    def __init__(self, base_temperature=300, cooling=10, reheat_trigger=280):
        self.base_temperature = base_temperature
        self.cooling = cooling
        self.reheat_trigger = reheat_trigger
        self.temperature = base_temperature

    def cook(self):
        self.temperature -= self.cooling
        return self.temperature

    def needs_reheat(self):
        return self.temperature <= self.reheat_trigger

    def reheat(self):
        self.temperature = self.base_temperature
        return self.temperature


class BatchLog:
    """Keeps a per-batch history so the shop can print a production report."""

    def __init__(self):
        self.entries = []

    def record(self, size, total, temperature, reheated):
        self.entries.append((len(self.entries) + 1, size, total, temperature, reheated))

    def format_entry(self, entry):
        index, size, total, temperature, reheated = entry
        return "%5d %5d %6d %6d  %s" % (index, size, total, temperature, "yes" if reheated else "no")

    def report(self):
        lines = ["batch  size  total   temp  reheated"]
        lines.extend(self.format_entry(entry) for entry in self.entries)
        return "\n".join(lines)


class Fryer:
    """Fries batches of donuts, reheating the oil (and losing a taste test) when it cools."""

    def __init__(self, vat=None, log=None):
        self.vat = vat if vat is not None else OilVat()
        self.log = log if log is not None else BatchLog()
        self.total_fried = 0

    def fry_batch(self, size):
        self.total_fried += size
        temperature = self.vat.cook()
        reheated = self.vat.needs_reheat()
        if reheated:
            temperature = self.vat.reheat()
            self.taste_test()
        self.log.record(size, self.total_fried, temperature, reheated)
        return self.total_fried

    def taste_test(self):
        if self.total_fried > 0:
            self.total_fried -= 1

    def run(self, batches):
        for size in BatchValidator(batches).validated():
            self.fry_batch(size)
        return [self.total_fried, self.vat.temperature]


def fryer(batches):
    return Fryer().run(batches)


def main():
    shop = Fryer()
    print(shop.run([10, 10, 10]))
    print(shop.log.report())
    print(fryer([5, 5, 5, 5, 5, 5]))


if __name__ == "__main__":
    main()

