class Movement:
    SHOTS = {0: 0, 1: 1, 2: 3}

    def __init__(self, size):
        if not isinstance(size, int) or isinstance(size, bool):
            raise TypeError("movement size must be an integer: %r" % (size,))
        if size not in self.SHOTS:
            raise ValueError("unknown movement size: %d" % size)
        self.size = size

    def shots(self):
        return self.SHOTS[self.size]

    def label(self):
        if self.size == 0:
            return "wind"
        return "small animal" if self.size == 1 else "large animal"


class WildlifeCamera:
    def __init__(self, memory=50, battery=100):
        self.memory = memory
        self.battery = battery
        self.photos = 0

    def is_operational(self):
        return self.memory > 0 and self.battery > 0

    def activate(self, movement):
        self.battery -= 1
        taken = min(movement.shots(), self.memory)
        self.memory -= taken
        self.photos += taken
        return taken

    def run(self, movements):
        for movement in movements:
            if not self.is_operational():
                break
            self.activate(movement)
        return [self.photos, self.battery]

    def status(self):
        state = "online" if self.is_operational() else "shut down"
        return "%s: %d photos, %d memory, %d battery" % (
            state, self.photos, self.memory, self.battery)


class ActivityReport:
    def __init__(self, camera):
        self.camera = camera
        self.entries = []

    def record(self, movement, taken):
        self.entries.append((movement.label(), taken))

    def observe(self, movements):
        for movement in movements:
            if not self.camera.is_operational():
                break
            self.record(movement, self.camera.activate(movement))
        return self

    def lines(self):
        numbered = ["%2d. %-13s -> %d photo(s)" % (index, label, taken)
                    for index, (label, taken) in enumerate(self.entries, 1)]
        numbered.append(self.camera.status())
        numbered.append("ignored movements: %d" % self.ignored_count)
        return numbered

    def observe_all(self, movements):
        parsed = [Movement(size) for size in movements]
        self.observe(parsed)
        self.ignored_count = len(parsed) - len(self.entries)
        return self


def cameratrap(movements):
    return WildlifeCamera().run(Movement(size) for size in movements)


def main():
    sequences = [[1, 2, 0, 2], [2] * 20, [1] * 60, [0] * 120]
    for sequence in sequences:
        print(sequence[:6], "->", cameratrap(sequence))
    report = ActivityReport(WildlifeCamera()).observe_all([1, 2, 0, 2, 1])
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

