"""Automated car wash bay simulation."""

REFILL_AMOUNT = 50
REFILL_COST = 5


class VehicleType:
    """A kind of vehicle the bay knows how to wash."""

    def __init__(self, code, name, soap_cost, price):
        self.code = code
        self.name = name
        self.soap_cost = soap_cost
        self.price = price

    def label(self):
        return "{} (type {})".format(self.name, self.code)

    def margin_per_wash(self):
        return self.price - self.soap_cost


class CarWashBay:
    """Tracks soap level and revenue while washing vehicles."""

    def __init__(self, soap=15, revenue=0):
        self.soap = soap
        self.revenue = revenue
        self.refills = 0
        self.log = []

    def catalog_lookup(self, code):
        if code not in CATALOG:
            raise ValueError("unknown vehicle type: {!r}".format(code))
        return CATALOG[code]

    def needs_refill(self, spec):
        return self.soap < spec.soap_cost

    def refill(self):
        self.soap += REFILL_AMOUNT
        self.revenue -= REFILL_COST
        self.refills += 1
        self.log.append("refill -> soap {}, revenue {}".format(self.soap, self.revenue))

    def wash(self, code):
        spec = self.catalog_lookup(code)
        if self.needs_refill(spec):
            self.refill()
        self.soap -= spec.soap_cost
        self.revenue += spec.price
        self.log.append("washed {} -> soap {}, revenue {}".format(
            spec.label(), self.soap, self.revenue))

    def process(self, vehicles):
        for code in vehicles:
            self.wash(code)
        return self.state()

    def state(self):
        return [self.soap, self.revenue]


class WashReport:
    """Formats the history of a finished shift."""

    def __init__(self, bay):
        self.bay = bay

    def header(self):
        return "Refills used: {}".format(self.bay.refills)

    def body(self):
        return ["  " + entry for entry in self.bay.log]

    def footer(self):
        soap, revenue = self.bay.state()
        return "Final soap: {}  Final revenue: {}".format(soap, revenue)

    def render(self):
        return "\n".join([self.header()] + self.body() + [self.footer()])


CATALOG = {
    1: VehicleType(1, "sedan", 5, 10),
    2: VehicleType(2, "truck", 10, 15),
}


def carwash(vehicles):
    bay = CarWashBay()
    return bay.process(vehicles)


def main():
    queue = [2, 2, 2, 2, 2, 2]
    bay = CarWashBay()
    bay.process(queue)
    print(WashReport(bay).render())
    print("carwash({}) = {}".format(queue, carwash(queue)))
    print("carwash([1, 1, 1, 2]) = {}".format(carwash([1, 1, 1, 2])))
    for spec in CATALOG.values():
        print("{} margin per wash: {}".format(spec.label(), spec.margin_per_wash()))


if __name__ == "__main__":
    main()

