class Turbine:
    """A single pitch-regulated wind turbine with a mechanical brake."""

    def __init__(self, name, capacity=2000.0):
        self.name = name
        self.capacity = capacity
        self.pitch = 90.0
        self.rotor_speed = 0.0
        self.braked = False
        self.cut_in = 3.0
        self.rated_wind = 12.0
        self.cut_out = 20.0
        self.rated_rotor = 18.0

    def adjust_pitch(self, wind_speed):
        if wind_speed < self.cut_in:
            self.pitch = 90.0
        elif wind_speed <= self.rated_wind:
            self.pitch = 0.0
        else:
            self.pitch = min(35.0, (wind_speed - self.rated_wind) * 3.0)
        return self.pitch

    def apply_brake(self):
        self.braked = True
        self.pitch = 90.0
        self.rotor_speed = 0.0

    def release_brake(self):
        self.braked = False

    def check_brakes(self, wind_speed):
        if wind_speed > self.cut_out:
            self.apply_brake()
        else:
            self.release_brake()
        return self.braked

    def spin(self, wind_speed):
        if self.braked or wind_speed < self.cut_in:
            self.rotor_speed = 0.0
        else:
            free = min(wind_speed, self.rated_wind) / self.rated_wind * self.rated_rotor
            self.rotor_speed = free * (1.0 - self.pitch / 90.0)
        return self.rotor_speed

    def power_output(self):
        if self.braked or self.rotor_speed <= 0.0:
            return 0.0
        ratio = self.rotor_speed / self.rated_rotor
        return min(self.capacity, self.capacity * ratio ** 3)

    def update(self, wind_speed):
        self.check_brakes(wind_speed)
        self.adjust_pitch(wind_speed)
        self.spin(wind_speed)
        return self.power_output()

    def status(self):
        state = "braked" if self.braked else "running"
        return "{0}: {1}, pitch {2:.1f}deg, rotor {3:.1f}rpm, {4:.1f}kW".format(
            self.name, state, self.pitch, self.rotor_speed, self.power_output())


class WindFarm:
    """A farm that drives several turbines from the same wind conditions."""

    def __init__(self, names, capacity=2000.0):
        self.turbines = [Turbine(name, capacity) for name in names]

    def add_turbine(self, turbine):
        self.turbines.append(turbine)
        return len(self.turbines)

    def total_power(self):
        return sum(turbine.power_output() for turbine in self.turbines)

    def update(self, wind_speed):
        for turbine in self.turbines:
            turbine.update(wind_speed)
        return self.total_power()

    def emergency_stop(self):
        for turbine in self.turbines:
            turbine.apply_brake()
        return self.total_power()

    def report(self, wind_speed):
        header = "wind {0:.1f} m/s -> farm {1:.1f} kW".format(wind_speed, self.total_power())
        return "\n".join([header] + ["  " + t.status() for t in self.turbines])


def evaluate(conditions):
    farm = WindFarm(["T1", "T2", "T3"])
    outputs = []
    for wind_speed in conditions:
        outputs.append(round(farm.update(wind_speed), 2))
    return outputs


def main():
    conditions = [10.0, 25.0, 5.0]
    farm = WindFarm(["T1", "T2", "T3"])
    for wind_speed in conditions:
        farm.update(wind_speed)
        print(farm.report(wind_speed))
    print("shutdown total:", farm.emergency_stop())
    print("evaluate:", evaluate(conditions))


if __name__ == "__main__":
    main()

