        return this.rotor_speed

    def power_output(this):
        if this.braked or this.rotor_speed <= 0.0:
            return 0.0
        ratio = this.rotor_speed / this.rated_rotor
        return min(this.capacity, this.capacity * ratio ** 3)

    def update(this, wind_speed):
        this.check_brakes(wind_speed)
        this.adjust_pitch(wind_speed)
        this.spin(wind_speed)
        return this.power_output()

    def status(this):
        state = "braked" if this.braked else "running"
        return "{0}: {1}, pitch {2:.1f}deg, rotor {3:.1f}rpm, {4:.1f}kW".format(
            this.name, state, this.pitch, this.rotor_speed, this.power_output())


class WindFarm:
    """A farm that drives several turbines from the same wind conditions."""

    def __init__(this, names, capacity=2000.0):
        this.turbines = [Turbine(name, capacity) for name in names]

    def add_turbine(this, turbine):
        this.turbines.append(turbine)
        return len(this.turbines)

    def total_power(this):
        return sum(turbine.power_output() for turbine in this.turbines)

    def update(this, wind_speed):
        for turbine in this.turbines:
            turbine.update(wind_speed)
        return this.total_power()

    def emergency_stop(this):
        for turbine in this.turbines:
            turbine.apply_brake()
        return this.total_power()

    def report(this, wind_speed):
        header = "wind {0:.1f} m/s -> farm {1:.1f} kW".format(wind_speed, this.total_power())
        return "\n".join([header] + ["  " + t.status() for t in this.turbines])


def evaluate(conditions):
    farm = WindFarm(["T1", "T2", "T3"])
    outputs = []
    for wind_speed in conditions:
        outputs.append(round(farm.update(wind_speed), 2))
    return outputs


