DELAY_LIMIT = 10
DELAY_PENALTY = 8
STARTING_SECONDS = 20


class PlayerClock:
    def __init__(self, name, seconds):
        self.name = name
        self.seconds_remaining = seconds

    def spend(self, seconds):
        self.seconds_remaining -= seconds
        return self.seconds_remaining

    def has_flagged(self):
        return self.seconds_remaining <= 0

    def label(self):
        return "{}: {}s".format(self.name, max(self.seconds_remaining, 0))


class DualTimer:
    def __init__(self, starting_seconds=STARTING_SECONDS,
                 delay_limit=DELAY_LIMIT, delay_penalty=DELAY_PENALTY):
        self.clocks = [PlayerClock("white", starting_seconds),
                       PlayerClock("black", starting_seconds)]
        self.delay_limit = delay_limit
        self.delay_penalty = delay_penalty
        self.active = 0
        self.turn_open = False

    def active_clock(self):
        return self.clocks[self.active]

    def start_turn(self):
        if self.turn_open:
            raise RuntimeError("a turn is already running")
        self.turn_open = True
        return self.active_clock()

    def end_turn(self, elapsed):
        if not self.turn_open:
            raise RuntimeError("no turn is running")
        if elapsed < 0:
            raise ValueError("a turn cannot last a negative number of seconds")
        clock = self.active_clock()
        charge = elapsed
        if elapsed > self.delay_limit:
            charge += self.delay_penalty
        clock.spend(charge)
        self.turn_open = False
        self.active = 1 - self.active
        return clock, charge

    def flag_fall(self):
        for clock in self.clocks:
            if clock.has_flagged():
                return clock.name
        return None

    def opponent_of(self, name):
        return next(c.name for c in self.clocks if c.name != name)


class MatchReport:
    def __init__(self, timer):
        self.timer = timer
        self.lines = []

    def record(self, clock, elapsed, charge):
        self.lines.append("{} used {}s (charged {}s), left {}s".format(
            clock.name, elapsed, charge, max(clock.seconds_remaining, 0)))

    def verdict(self):
        flagged = self.timer.flag_fall()
        if flagged is None:
            return "ongoing"
        return self.timer.opponent_of(flagged) + " wins"

    def summary(self):
        standings = " | ".join(c.label() for c in self.timer.clocks)
        return "\n".join(self.lines + [standings, self.verdict()])


def time(moves):
    timer = DualTimer()
    report = MatchReport(timer)
    for elapsed in moves:
        timer.start_turn()
        clock, charge = timer.end_turn(elapsed)
        report.record(clock, elapsed, charge)
        if timer.flag_fall() is not None:
            break
    return report.verdict()


if __name__ == "__main__":
    print(time([5, 12, 8]))
    print(time([3, 4, 5, 6]))

