class NitrogenModel:
    """Tracks the diver's accumulated nitrogen load in arbitrary units."""

    def __init__(self, warning_threshold=100.0):
        self.level = 0.0
        self.warning_threshold = warning_threshold
        self.warning_triggered = False

    def depth_multiplier(self, depth):
        return 1.0 + depth / 10.0

    def absorb(self, depth):
        self.level += self.depth_multiplier(depth) * 2.0

    def offgas(self, rate):
        self.level = max(0.0, self.level - rate)

    def check_warning(self):
        if self.level > self.warning_threshold:
            self.warning_triggered = True
        return self.warning_triggered


class SafetyStopController:
    """Enforces a three minute stop after any ascent from deep water."""

    DEEP_LIMIT = 20.0
    STOP_ZONE = 6.0
    DURATION = 3

    def __init__(self):
        self.remaining = 0
        self.violations = 0

    def note_ascent(self, previous, depth):
        if previous is not None and previous >= self.DEEP_LIMIT and depth < previous:
            self.remaining = self.DURATION

    def tick(self, depth):
        if self.remaining > 0:
            if depth <= self.STOP_ZONE:
                self.remaining -= 1
            else:
                self.violations += 1
        return self.remaining


class DiveComputer:
    SURFACE_ZONE = 5.0
    OFFGAS_RATE = 3.0

    def __init__(self):
        self.nitrogen = NitrogenModel()
        self.stop = SafetyStopController()
        self.minutes = 0
        self.previous = None
        self.log = []

    def validate(self, depth):
        if not isinstance(depth, (int, float)) or depth < 0:
            raise ValueError("depth must be a non-negative number, got %r" % (depth,))
        return float(depth)

    def step(self, depth):
        depth = self.validate(depth)
        self.stop.note_ascent(self.previous, depth)
        if depth <= self.SURFACE_ZONE:
            self.nitrogen.offgas(self.OFFGAS_RATE)
        else:
            self.nitrogen.absorb(depth)
        pending = self.stop.tick(depth)
        self.nitrogen.check_warning()
        self.minutes += 1
        self.previous = depth
        self.log.append((self.minutes, depth, round(self.nitrogen.level, 2), pending))

    def run(self, depths):
        for depth in depths:
            self.step(depth)
        return round(self.nitrogen.level, 2), self.nitrogen.warning_triggered

    def report(self):
        lines = ["min  depth  nitrogen  stop"]
        for minute, depth, level, pending in self.log:
            lines.append("%3d %6.1f %9.2f %5d" % (minute, depth, level, pending))
        lines.append("total %d min, warning=%s, stop violations=%d"
                     % (self.minutes, self.nitrogen.warning_triggered, self.stop.violations))
        return "\n".join(lines)


def monitor(depths):
    return DiveComputer().run(depths)


def main():
    profile = [0, 12, 25, 30, 30, 30, 28, 22, 18, 5, 5, 5, 3, 0]
    computer = DiveComputer()
    print(computer.run(profile))
    print(computer.report())
    print(monitor([40] * 30))


if __name__ == "__main__":
    main()

