class Pouch:
    def __init__(self):
        self.items = []

    def store(self, density):
        self.items.append(density)
        return len(self.items)

    def count(self):
        return len(self.items)

    def heaviest(self):
        if not self.items:
            return 0.0
        return max(self.items)

    def summary(self):
        return "{0} item(s), best density {1:.2f}".format(self.count(), self.heaviest())


class MetalDetector:
    DRAIN_PER_PLOT = 4.0

    def __init__(self, sensitivity=1.0):
        self.sensitivity = self.validate(sensitivity)
        self.battery = 100.0
        self.pouch = Pouch()
        self.beeps = 0

    def validate(self, sensitivity):
        if not isinstance(sensitivity, (int, float)):
            raise TypeError("sensitivity must be numeric")
        if sensitivity <= 0 or sensitivity > 1:
            raise ValueError("sensitivity must be in (0, 1]")
        return float(sensitivity)

    def threshold(self):
        return 1.0 / self.sensitivity

    def adjust(self, sensitivity):
        self.sensitivity = self.validate(sensitivity)
        return self.threshold()

    def has_power(self):
        return self.battery >= self.DRAIN_PER_PLOT

    def recharge(self):
        self.battery = 100.0
        return self.battery

    def search(self, density):
        if not self.has_power():
            return False
        self.battery -= self.DRAIN_PER_PLOT
        if density > self.threshold():
            self.pouch.store(density)
            self.beeps += 1
            return True
        return False

    def report(self):
        return "battery {0:.1f}%, {1} beep(s), pouch: {2}".format(
            self.battery, self.beeps, self.pouch.summary())


def sweep(terrain):
    detector = MetalDetector(sensitivity=0.5)
    for density in terrain:
        if not detector.has_power():
            detector.recharge()
        detector.search(density)
    return detector.pouch.count(), detector.battery


def main():
    plots = [0.4, 3.1, 1.8, 7.5, 0.9, 2.05, 12.0]
    found, battery = sweep(plots)
    print("swept {0} plots -> found {1}, battery {2:.1f}%".format(len(plots), found, battery))

    detector = MetalDetector()
    print("sensitive threshold:", detector.adjust(0.9))
    for density in plots:
        detector.search(density)
    print(detector.report())
    detector.recharge()
    print("after recharge:", detector.report())


if __name__ == "__main__":
    main()

