import random

MOVES = {
    "left": (-1, 0),
    "right": (1, 0),
    "forward": (0, 1),
    "back": (0, -1),
}


class Claw:
    def __init__(self, strength, grid_size=10, max_level=3):
        self.x = 0
        self.y = 0
        self.level = 0
        self.strength = strength
        self.grid_size = grid_size
        self.max_level = max_level

    def move(self, dx, dy):
        self.x = min(self.grid_size - 1, max(0, self.x + dx))
        self.y = min(self.grid_size - 1, max(0, self.y + dy))

    def position(self):
        return (self.x, self.y)

    def lower(self):
        self.level = self.max_level

    def retract(self):
        self.level = 0

    def grip_holds(self, rng):
        return rng.random() < self.strength


class PrizeField:
    def __init__(self, prizes):
        self.prizes = dict(prizes)

    def has_prize(self, position):
        return position in self.prizes

    def take(self, position):
        return self.prizes.pop(position)

    def remaining(self):
        return len(self.prizes)


class ClawMachine:
    def __init__(self, prizes, strength=0.6, seed=None):
        self.field = PrizeField(prizes)
        self.claw = Claw(strength)
        self.rng = random.Random(seed)
        self.won = []
        self.attempts = 0

    def step(self, command):
        key = command.strip().lower()
        if key in MOVES:
            dx, dy = MOVES[key]
            self.claw.move(dx, dy)
            return None
        if key != "drop":
            raise ValueError("unknown command: %r" % command)
        return self.attempt_drop()

    def attempt_drop(self):
        self.attempts += 1
        self.claw.lower()
        spot = self.claw.position()
        prize = None
        if self.field.has_prize(spot) and self.claw.grip_holds(self.rng):
            prize = self.field.take(spot)
            self.won.append(prize)
        self.claw.retract()
        return prize

    def run(self, inputs):
        for command in inputs:
            self.step(command)
        return len(self.won)

    def report(self):
        haul = ", ".join(self.won) if self.won else "nothing"
        return "drops=%d won=%d (%s) left=%d claw at %s level %d" % (
            self.attempts, len(self.won), haul,
            self.field.remaining(), self.claw.position(), self.claw.level,
        )


def play(inputs):
    prizes = {(0, 0): "bear", (2, 1): "robot", (2, 3): "duck", (5, 5): "dragon"}
    return ClawMachine(prizes, strength=0.7, seed=2026).run(inputs)


if __name__ == "__main__":
    script = ["drop", "right", "right", "forward", "drop", "drop",
              "forward", "forward", "drop", "left", "back", "drop"]
    print("prizes won:", play(script))
    machine = ClawMachine({(1, 1): "panda", (4, 2): "alien"}, strength=0.5, seed=7)
    machine.run(["right", "forward", "drop", "right", "right", "right",
                 "forward", "drop", "drop"])
    print(machine.report())

