DIRECTIONS = {"up": (0, 1), "down": (0, -1), "left": (-1, 0), "right": (1, 0)}


class Pouch:
    def __init__(self):
        self.contents = []

    def add(self, location):
        self.contents.append(location)

    def count(self):
        return len(self.contents)

    def describe(self):
        if not self.contents:
            return "empty"
        return ", ".join(str(location) for location in self.contents)


class Maze:
    def __init__(self, seed_locations):
        self.seeds = {tuple(location) for location in seed_locations}

    def take_seed(self, position):
        if position in self.seeds:
            self.seeds.discard(position)
            return True
        return False

    def remaining(self):
        return len(self.seeds)


class Hamster:
    def __init__(self, stamina=10):
        self.x = 0
        self.y = 0
        self.stamina = stamina
        self.pouch = Pouch()

    def position(self):
        return (self.x, self.y)

    def is_awake(self):
        return self.stamina > 0

    def step(self, direction, maze):
        if not self.is_awake():
            return False
        dx, dy = DIRECTIONS[direction]
        self.x += dx
        self.y += dy
        self.stamina -= 1
        if maze.take_seed(self.position()):
            self.pouch.add(self.position())
            self.stamina += 5
        return True


class Expedition:
    def __init__(self, path, seeds):
        self.path = [str(direction).lower() for direction in path]
        for direction in self.path:
            if direction not in DIRECTIONS:
                raise ValueError("unknown direction: " + direction)
        self.maze = Maze(seeds)
        self.hamster = Hamster()
        self.log = []

    def run(self):
        for direction in self.path:
            if self.hamster.step(direction, self.maze):
                self.log.append("%s -> %s (stamina %d)" % (direction, self.hamster.position(), self.hamster.stamina))
            else:
                self.log.append("%s ignored, asleep" % direction)
        return self.hamster.position(), self.hamster.pouch.count()

    def report(self):
        lines = list(self.log)
        lines.append("final position: %s" % (self.hamster.position(),))
        lines.append("collected: %s" % self.hamster.pouch.describe())
        lines.append("seeds left in maze: %d" % self.maze.remaining())
        lines.append("awake" if self.hamster.is_awake() else "asleep")
        return "\n".join(lines)


