class Lamp:
    BURNOUT_ROTATIONS = 50

    def __init__(self):
        self.lit = False
        self.rotations_lit = 0
        self.burned_out = False

    def turn_on(self):
        if not self.burned_out:
            self.lit = True

    def turn_off(self):
        self.lit = False

    def register_rotation(self):
        if self.lit:
            self.rotations_lit += 1
            if self.rotations_lit >= self.BURNOUT_ROTATIONS:
                self.burned_out = True
                self.lit = False

    def replace(self):
        self.rotations_lit = 0
        self.burned_out = False
        self.turn_on()

    def intensity(self):
        if not self.lit:
            return 0
        remaining = self.BURNOUT_ROTATIONS - self.rotations_lit
        return int(100 * remaining / self.BURNOUT_ROTATIONS)


class FogHorn:
    def __init__(self):
        self.enabled = False
        self.blasts = 0

    def enable(self):
        self.enabled = True

    def disable(self):
        self.enabled = False

    def sound_if_enabled(self):
        if self.enabled:
            self.blasts += 1


class Lighthouse:
    NIGHT_SPEED = 6
    DAY_SPEED = 2

    def __init__(self):
        self.lamp = Lamp()
        self.horn = FogHorn()
        self.night = False
        self.foggy = False
        self.rotation_speed = self.DAY_SPEED

    def set_daytime(self):
        self.night = False
        self.rotation_speed = self.DAY_SPEED
        self.lamp.turn_off()
        self.horn.disable()

    def set_nighttime(self):
        self.night = True
        self.rotation_speed = self.NIGHT_SPEED
        self.lamp.turn_on()
        if self.foggy:
            self.horn.enable()

    def set_fog(self, foggy):
        self.foggy = foggy
        if foggy and self.night:
            self.horn.enable()
        else:
            self.horn.disable()

    def rotate(self):
        self.lamp.register_rotation()
        self.horn.sound_if_enabled()

    def replace_lamp(self):
        self.lamp.replace()
        if not self.night:
            self.lamp.turn_off()

    def status(self):
        return "speed=%d rpm, intensity=%d%%, horn=%s, blasts=%d" % (
            self.rotation_speed,
            self.lamp.intensity(),
            "on" if self.horn.enabled else "off",
            self.horn.blasts,
        )

    def apply(self, event):
        actions = {
            "day": self.set_daytime,
            "night": self.set_nighttime,
            "fog": lambda: self.set_fog(True),
            "clear": lambda: self.set_fog(False),
            "rotate": self.rotate,
            "replace lamp": self.replace_lamp,
        }
        if event not in actions:
            raise ValueError("unknown event: %r" % (event,))
        actions[event]()


def operate(events):
    tower = Lighthouse()
    for event in events:
        tower.apply(event)
    return tower.horn.blasts, tower.lamp.burned_out


if __name__ == "__main__":
    script = ["night", "fog"] + ["rotate"] * 55 + ["clear", "day"]
    blasts, needs_lamp = operate(script)
    print("horn blasts: %d" % blasts)
    print("lamp needs replacement: %s" % needs_lamp)

    tower = Lighthouse()
    for event in ["night", "fog"] + ["rotate"] * 50 + ["replace lamp", "rotate"]:
        tower.apply(event)
    print(tower.status())

