class Stirrer:
    def __init__(self, evaporation_rate=0.10, low_rate=1.0, high_rate=2.5):
        self.evaporation_rate = evaporation_rate
        self.low_rate = low_rate
        self.high_rate = high_rate

    def blend_rate(self, speed):
        if speed == "low":
            return self.low_rate
        if speed == "high":
            return self.high_rate
        raise ValueError("unknown stirrer speed: %r" % (speed,))

    def homogeneity_gain(self, speed, minutes):
        return self.blend_rate(speed) * minutes

    def surviving_alcohol(self, alcohol, speed, minutes):
        if speed == "high":
            return alcohol * (1.0 - self.evaporation_rate) ** minutes
        self.blend_rate(speed)
        return alcohol


class RatioChecker:
    def __init__(self, base=3.0, top=1.0, alcohol=6.0, tolerance=0.02):
        self.targets = {"base": base, "top": top, "alcohol": alcohol}
        self.tolerance = tolerance

    def target_fractions(self):
        total = sum(self.targets.values())
        return dict((name, share / total) for name, share in self.targets.items())

    def deviations(self, volumes):
        total = sum(volumes.values())
        if total <= 0:
            return dict((name, 1.0) for name in self.targets)
        wanted = self.target_fractions()
        return dict((name, abs(volumes[name] / total - wanted[name])) for name in wanted)

    def matches(self, volumes):
        return all(gap <= self.tolerance for gap in self.deviations(volumes).values())


class Vat:
    def __init__(self, stirrer, checker, min_homogeneity=5.0):
        self.stirrer = stirrer
        self.checker = checker
        self.min_homogeneity = min_homogeneity
        self.volumes = {"base": 0.0, "top": 0.0, "alcohol": 0.0}
        self.homogeneity = 0.0

    def add(self, ingredient, amount):
        if ingredient not in self.volumes:
            raise ValueError("unknown ingredient: %r" % (ingredient,))
        if amount < 0:
            raise ValueError("cannot add a negative volume")
        self.volumes[ingredient] += float(amount)

    def stir(self, speed, minutes):
        if minutes < 0:
            raise ValueError("cannot stir for a negative time")
        alcohol = self.volumes["alcohol"]
        self.volumes["alcohol"] = self.stirrer.surviving_alcohol(alcohol, speed, minutes)
        self.homogeneity += self.stirrer.homogeneity_gain(speed, minutes)

    def is_ideal(self):
        return self.homogeneity >= self.min_homogeneity and self.checker.matches(self.volumes)

    def apply(self, drop):
        action, kind, value = drop
        if action == "add":
            self.add(kind, value)
        elif action == "stir":
            self.stir(kind, value)
        else:
            raise ValueError("unknown action: %r" % (action,))

    def result(self):
        volumes = dict((name, round(v, 4)) for name, v in self.volumes.items())
        return volumes, self.is_ideal()

    def report(self):
        volumes, ideal = self.result()
        lines = ["%-8s %8.3f ml" % (name, volumes[name]) for name in sorted(volumes)]
        lines.append("homogeneity %.2f (needs %.2f)" % (self.homogeneity, self.min_homogeneity))
        gaps = self.checker.deviations(self.volumes)
        lines.append("worst ratio gap %.4f" % max(gaps.values()))
        lines.append("ideal perfume: %s" % ("yes" if ideal else "no"))
        return "\n".join(lines)


def blend(drops):
    vat = Vat(Stirrer(), RatioChecker())
    for drop in drops:
        vat.apply(drop)
    return vat.result()


def main():
    recipe = [("add", "base", 30), ("add", "top", 10), ("add", "alcohol", 66.7),
              ("stir", "low", 4), ("stir", "high", 1)]
    vat = Vat(Stirrer(), RatioChecker())
    for drop in recipe:
        vat.apply(drop)
    print(vat.report())
    print(blend([("add", "base", 10), ("stir", "high", 2)]))


if __name__ == "__main__":
    main()

