class BelayDevice:
    """Tracks rope slack and whether the friction mode is engaged."""

    def __init__(self):
        self.slack = 0.0
        self.friction_engaged = True

    def pay_out(self, meters):
        self.slack += meters
        return self.slack

    def take_in(self, meters):
        pulled = min(meters, self.slack)
        self.slack -= pulled
        return pulled

    def set_friction(self, engaged):
        self.friction_engaged = bool(engaged)

    def catch_distance(self):
        drop = 2.0 * self.slack
        if not self.friction_engaged:
            drop += 5.0
        return drop

    def arrest(self):
        drop = self.catch_distance()
        self.slack = 0.0
        return drop


class Climber:
    """A climber whose height and accumulated fall distance are tracked."""

    def __init__(self, height=0.0):
        self.height = height
        self.total_fallen = 0.0

    def ascend(self, meters, device):
        self.height += meters
        device.pay_out(meters)
        return self.height

    def take_fall(self, device):
        drop = min(device.arrest(), self.height)
        self.height -= drop
        self.total_fallen += drop
        return drop


class ClimbSession:
    """Applies a sequence of movements to a climber on a belay device."""

    def __init__(self):
        self.device = BelayDevice()
        self.climber = Climber()
        self.log = []

    def normalize(self, movement):
        if isinstance(movement, str):
            return movement.lower(), 0.0
        kind = str(movement[0]).lower()
        value = movement[1] if len(movement) > 1 else 0.0
        if kind == "friction" and isinstance(value, str):
            value = value.lower() in ("on", "engaged", "true")
        return kind, value

    def apply(self, movement):
        kind, value = self.normalize(movement)
        if kind == "up":
            self.log.append("climbed %.1fm to %.1fm" % (value, self.climber.ascend(value, self.device)))
        elif kind in ("pull", "take"):
            self.log.append("belayer pulled in %.1fm" % self.device.take_in(value))
        elif kind == "friction":
            self.device.set_friction(value)
            self.log.append("friction %s" % ("engaged" if self.device.friction_engaged else "disengaged"))
        elif kind == "fall":
            self.log.append("fell %.1fm" % self.climber.take_fall(self.device))
        else:
            raise ValueError("unknown movement: %r" % (movement,))

    def run(self, movements):
        for movement in movements:
            self.apply(movement)
        return self.climber.height, self.climber.total_fallen

    def report(self):
        lines = ["%2d. %s" % (i + 1, entry) for i, entry in enumerate(self.log)]
        lines.append("height %.1fm, slack %.1fm, fallen %.1fm"
                     % (self.climber.height, self.device.slack, self.climber.total_fallen))
        return "\n".join(lines)


def climb(movements):
    return ClimbSession().run(movements)


def main():
    route = [("up", 10), ("pull", 4), ("up", 6), ("friction", "off"),
             ("fall",), ("up", 3), ("friction", "on"), ("fall",)]
    session = ClimbSession()
    height, fallen = session.run(route)
    print(session.report())
