class BelayDevice:
    """Tracks rope slack and whether the friction mode is engaged."""

    def __init__(this):
        this.slack = 0.0
        this.friction_engaged = True

    def pay_out(this, meters):
        this.slack += meters
        return this.slack

    def take_in(this, meters):
        pulled = min(meters, this.slack)
        this.slack -= pulled
        return pulled

    def set_friction(this, engaged):
        this.friction_engaged = bool(engaged)

    def catch_distance(this):
        drop = 2.0 * this.slack
        if not this.friction_engaged:
            drop += 5.0
        return drop

    def arrest(this):
        drop = this.catch_distance()
        this.slack = 0.0
        return drop


class Climber:
    """A climber whose height and accumulated fall distance are tracked."""

    def __init__(this, height=0.0):
        this.height = height
        this.total_fallen = 0.0

    def ascend(this, meters, device):
        this.height += meters
        device.pay_out(meters)
        return this.height

    def take_fall(this, device):
        drop = min(device.arrest(), this.height)
        this.height -= drop
        this.total_fallen += drop
        return drop


class ClimbSession:
    """Applies a sequence of movements to a climber on a belay device."""

    def __init__(this):
        this.device = BelayDevice()
        this.climber = Climber()
        this.log = []

    def normalize(this, movement):
        if isinstance(movement, str):
            return movement.lower(), 0.0
        kind = str(movement[0]).lower()
        value = movement[1] if len(movement) > 1 else 0.0
        if kind == "friction" and isinstance(value, str):
            value = value.lower() in ("on", "engaged", "true")
        return kind, value

    def apply(this, movement):
        kind, value = this.normalize(movement)
        if kind == "up":
            this.log.append("climbed %.1fm to %.1fm" % (value, this.climber.ascend(value, this.device)))
        elif kind in ("pull", "take"):
            this.log.append("belayer pulled in %.1fm" % this.device.take_in(value))
        elif kind == "friction":
            this.device.set_friction(value)
            this.log.append("friction %s" % ("engaged" if this.device.friction_engaged else "disengaged"))
        elif kind == "fall":
            this.log.append("fell %.1fm" % this.climber.take_fall(this.device))
        else:
            raise ValueError("unknown movement: %r" % (movement,))

    def run(this, movements):
        for movement in movements:
            this.apply(movement)
        return this.climber.height, this.climber.total_fallen

    def report(this):
        lines = ["%2d. %s" % (i + 1, entry) for i, entry in enumerate(this.log)]
        lines.append("height %.1fm, slack %.1fm, fallen %.1fm"
                     % (this.climber.height, this.device.slack, this.climber.total_fallen))
        return "\n".join(lines)


def climb(movements):
    return ClimbSession().run(movements)


def main():
    route = [("up", 10), ("pull", 4), ("up", 6), ("friction", "off"),
             ("fall",), ("up", 3), ("friction", "on"), ("fall",)]
    session = ClimbSession()
    height, fallen = session.run(route)
    print(session.report())
    print("climb() ->", (height, fallen))


if __name__ == "__main__":
    main()

