import math


class CoolingSensor:
    """Sensor whose temperature decays exponentially toward a cold floor."""

    def __init__(self, ambient=20.0, floor=-45.0, tau=120.0):
        self.temperature = float(ambient)
        self.floor = float(floor)
        self.tau = float(tau)

    def cool(self, seconds):
        if seconds < 0:
            raise ValueError("cooling time must not be negative")
        span = self.temperature - self.floor
        self.temperature = self.floor + span * math.exp(-seconds / self.tau)
        return self.temperature

    def dark_rate(self):
        return 0.6 * 2.0 ** ((self.temperature - self.floor) / 10.0)


class Spectrometer:
    def __init__(self, channels, sensor):
        self.sensor = sensor
        self.counts = [0.0] * channels
        self.dark_frame = [0.0] * channels
        self.exposure_time = 1.0
        self.pending_frames = 0

    def cool(self, seconds):
        return self.sensor.cool(seconds)

    def set_exposure(self, seconds):
        if seconds <= 0:
            raise ValueError("exposure time must be positive")
        self.exposure_time = float(seconds)

    def dark_counts(self):
        noise = self.sensor.dark_rate() * self.exposure_time
        return [noise] * len(self.counts)

    def calibrate(self):
        dark = self.dark_counts()
        for index, level in enumerate(dark):
            self.counts[index] -= level * self.pending_frames
        self.dark_frame = dark
        self.pending_frames = 0

    def observe(self, flux):
        if len(flux) != len(self.counts):
            raise ValueError("flux vector does not match channel count")
        noise = self.sensor.dark_rate() * self.exposure_time
        for index, signal in enumerate(flux):
            self.counts[index] += signal * self.exposure_time + noise
        self.pending_frames += 1

    def cleaned_counts(self):
        return [max(0.0, raw - dark * self.pending_frames)
                for raw, dark in zip(self.counts, self.dark_frame)]

    def brightest_pixel(self):
        cleaned = self.cleaned_counts()
        index = max(range(len(cleaned)), key=cleaned.__getitem__)
        return index, cleaned[index]

    def report(self):
        index, total = self.brightest_pixel()
        return "T={0:.2f}C exposure={1:.1f}s brightest=ch{2} total={3:.2f}".format(
            self.sensor.temperature, self.exposure_time, index, total)


class ExposureRunner:
    def __init__(self, spectrometer):
        self.spectrometer = spectrometer
        self.handlers = {
            "wait": self.spectrometer.cool,
            "exposure": self.spectrometer.set_exposure,
            "calibrate": self.spectrometer.calibrate,
            "observe": self.spectrometer.observe,
        }

    def run(self, exposures):
        for step in exposures:
            self.execute(step)
        return self.spectrometer

    def execute(self, step):
        operation, arguments = step[0], step[1:]
        if operation not in self.handlers:
            raise ValueError("unknown exposure step: %r" % (operation,))
        self.handlers[operation](*arguments)


def analyze(exposures):
    channels = max((len(step[1]) for step in exposures if step[0] == "observe"), default=1)
    spectrometer = Spectrometer(channels, CoolingSensor())
    ExposureRunner(spectrometer).run(exposures)
    return spectrometer.brightest_pixel()[1]


def main():
    plan = [
        ("exposure", 10.0),
        ("observe", [3.0, 12.0, 5.0]),
        ("wait", 300.0),
        ("calibrate",),
        ("observe", [3.0, 12.0, 5.0]),
        ("observe", [2.5, 11.0, 4.5]),
        ("wait", 120.0),
        ("exposure", 20.0),
        ("calibrate",),
        ("observe", [3.0, 12.0, 5.0]),
    ]
    scope = Spectrometer(3, CoolingSensor())
    ExposureRunner(scope).run(plan)
    print(scope.report())
    print("analyze -> {0:.2f}".format(analyze(plan)))


if __name__ == "__main__":
    main()

