class Wax:
    def __init__(self, snow_type):
        self.snow_type = snow_type
        if snow_type == "cold":
            self.name = "blue hard wax"
            self.melting_point = 145
        elif snow_type == "warm":
            self.name = "red soft wax"
            self.melting_point = 120
        else:
            raise ValueError("unknown snow type: %s" % snow_type)
        self.tolerance = 5

    def is_too_cold(self, temperature):
        return temperature < self.melting_point - self.tolerance

    def is_burning(self, temperature):
        return temperature > self.melting_point + self.tolerance

    def describe(self):
        return "%s (melts at %d C)" % (self.name, self.melting_point)


class Iron:
    def __init__(self, ambient=20):
        self.temperature = ambient
        self.powered = False

    def heat_to(self, target):
        self.powered = True
        self.temperature = target
        return self.temperature

    def cool_down(self):
        self.powered = False
        self.temperature = 20


class TuningBench:
    def __init__(self, wax, iron):
        self.wax = wax
        self.iron = iron
        self.wax_applied = False
        self.scraping_passes = 0
        self.burned = False

    def heat_iron(self, target):
        self.iron.heat_to(target)
        return self.iron.temperature

    def apply_wax(self):
        temperature = self.iron.temperature
        if self.wax.is_too_cold(temperature):
            return "iron too cold at %d C, wax will not melt" % temperature
        if self.wax.is_burning(temperature):
            self.burned = True
            return "iron too hot at %d C, the base is burned" % temperature
        self.wax_applied = True
        return "applied %s at %d C" % (self.wax.name, temperature)

    def scrape(self, passes):
        if not self.wax_applied:
            return "nothing to scrape"
        self.scraping_passes += passes
        return "scraped %d time(s)" % self.scraping_passes

    def finish_quality(self):
        if self.burned:
            return "Base burned with %s: ski ruined." % self.wax.describe()
        if not self.wax_applied:
            return "No wax bonded: base left dry and slow."
        if self.scraping_passes < 3:
            return "Excess %s left after %d pass(es): base sticky." % (
                self.wax.name, self.scraping_passes)
        if self.scraping_passes > 3:
            return "Over-scraped %s: base clean but under-waxed." % self.wax.name
        self.iron.cool_down()
        return "Perfect finish with %s: base fast and glossy." % self.wax.name


def prepare(conditions):
    wax = Wax(conditions.get("snow", "cold"))
    bench = TuningBench(wax, Iron())
    bench.heat_iron(conditions.get("iron_temperature", wax.melting_point))
    bench.apply_wax()
    bench.scrape(conditions.get("scraping_passes", 3))
    return bench.finish_quality()


def main():
    runs = [
        {"snow": "cold", "iron_temperature": 145, "scraping_passes": 3},
        {"snow": "warm", "iron_temperature": 145, "scraping_passes": 3},
        {"snow": "cold", "iron_temperature": 110, "scraping_passes": 2},
        {"snow": "warm", "iron_temperature": 118, "scraping_passes": 1},
    ]
    for conditions in runs:
        print(prepare(conditions))


if __name__ == "__main__":
    main()

