class Dough:
    def __init__(self, volume=1.0):
        self.volume = volume
        self.crusted = False

    def double(self):
        self.volume *= 2
        return self.volume

    def form_crust(self):
        self.crusted = True

    def can_grow(self):
        return not self.crusted


class ProofingBox:
    IDEAL_RANGE = (70, 80)
    HIGH_HUMIDITY = 70

    def __init__(self, temperature=75, humidity=85, evaporation=8):
        self.temperature = temperature
        self.humidity = humidity
        self.evaporation = evaporation
        self.dough = Dough()
        self.log = []

    def add_steam(self, amount=20):
        self.humidity = min(100, self.humidity + amount)

    def set_thermostat(self, degrees):
        self.temperature = degrees

    def apply(self, adjustment):
        if "steam" in adjustment:
            self.add_steam(adjustment["steam"])
        if "thermostat" in adjustment:
            self.set_thermostat(adjustment["thermostat"])

    def humid_enough(self):
        return self.humidity >= self.HIGH_HUMIDITY

    def warm_enough(self):
        low, high = self.IDEAL_RANGE
        return low <= self.temperature <= high

    def tick(self):
        if not self.humid_enough():
            self.dough.form_crust()
        elif self.warm_enough() and self.dough.can_grow():
            self.dough.double()
        self.humidity = max(0, self.humidity - self.evaporation)
        self.log.append(self.snapshot())

    def snapshot(self):
        return {
            "temperature": self.temperature,
            "humidity": self.humidity,
            "volume": self.dough.volume,
            "crusted": self.dough.crusted,
        }

    def run(self, hours):
        for adjustment in hours:
            self.apply(adjustment)
            self.tick()
        return {"volume_multiplier": self.dough.volume, "crusted": self.dough.crusted}

    def report(self):
        lines = ["hour  temp  humidity  volume  crust"]
        for hour, state in enumerate(self.log, start=1):
            lines.append("{:>4}  {:>4}  {:>8}  {:>6.1f}  {}".format(
                hour, state["temperature"], state["humidity"],
                state["volume"], "yes" if state["crusted"] else "no"))
        return "\n".join(lines)


def proof(environment):
    box = ProofingBox()
    result = box.run(environment)
    print(box.report())
    return result


if __name__ == "__main__":
    schedule = [{}, {"steam": 15}, {"thermostat": 68}, {"steam": 25, "thermostat": 76}, {}]
    outcome = proof(schedule)
    print("final multiplier: {:.1f}x, crust: {}".format(
        outcome["volume_multiplier"], "formed" if outcome["crusted"] else "none"))

