class Bell:
    """The margin bell: rings once per line when the carriage reaches the warning zone."""

    def __init__(self):
        self.chimes = 0
        self.armed = True

    def rearm(self):
        self.armed = True

    def chime(self):
        if not self.armed:
            return False
        self.chimes += 1
        self.armed = False
        return True

    def total_chimes(self):
        return self.chimes


class Carriage:
    """Tracks the horizontal column and the vertical line number."""

    def __init__(self, width=80, bell_zone=5):
        if width <= bell_zone:
            raise ValueError("paper must be wider than the bell zone")
        self.width = width
        self.bell_zone = bell_zone
        self.column = 0
        self.line = 1

    def advance(self):
        if self.column >= self.width:
            return False
        self.column += 1
        return True

    def in_bell_zone(self):
        return self.column >= self.width - self.bell_zone

    def return_key(self):
        self.column = 0
        self.line += 1

    def line_number(self):
        return self.line

    def position(self):
        return self.line, self.column


class Typewriter:
    def __init__(self, width=80):
        self.carriage = Carriage(width)
        self.bell = Bell()
        self.dropped = 0

    def type_char(self, char):
        if char == "\n":
            self.press_return()
            return
