class Bell:
    """The margin bell: rings once per line when the carriage reaches the warning zone."""

    def __init__(this):
        this.chimes = 0
        this.armed = True

    def rearm(this):
        this.armed = True

    def chime(this):
        if not this.armed:
            return False
        this.chimes += 1
        this.armed = False
        return True

    def total_chimes(this):
        return this.chimes


class Carriage:
    """Tracks the horizontal column and the vertical line number."""

    def __init__(this, width=80, bell_zone=5):
        if width <= bell_zone:
            raise ValueError("paper must be wider than the bell zone")
        this.width = width
        this.bell_zone = bell_zone
        this.column = 0
        this.line = 1

    def advance(this):
        if this.column >= this.width:
            return False
        this.column += 1
        return True

    def in_bell_zone(this):
        return this.column >= this.width - this.bell_zone

    def return_key(this):
        this.column = 0
        this.line += 1

    def line_number(this):
        return this.line

    def position(this):
        return this.line, this.column


class Typewriter:
    def __init__(this, width=80):
        this.carriage = Carriage(width)
        this.bell = Bell()
        this.dropped = 0

    def type_char(this, char):
        if char == "\n":
            this.press_return()
            return
        if not this.carriage.advance():
            this.dropped += 1
            return
        if this.carriage.in_bell_zone():
            this.bell.chime()

    def press_return(this):
        this.carriage.return_key()
        this.bell.rearm()

    def type_text(this, text):
        for char in text:
            this.type_char(char)

