class YoYo:
    """A single yo-yo with string tension, spin velocity and a mount state."""

    def __init__(self, name):
        self.name = name
        self.velocity = 0.0
        self.tension = 0.0
        self.mount = None
        self.spinning = False
        self.in_hand = True

    def throw(self):
        self.velocity = 100.0
        self.tension = 0.0
        self.mount = "sleeper"
        self.spinning = True
        self.in_hand = False
        return True

    def drain(self, amount):
        self.velocity -= amount
        if self.velocity < 10.0:
            self.die()
        return self.velocity

    def die(self):
        self.velocity = 0.0
        self.spinning = False
        self.mount = "dead"

    def mount_to(self, mount):
        if not self.spinning:
            return False
        self.mount = mount
        self.tension += 1.5
        self.drain(5.0)
        return self.spinning

    def perform(self, trick):
        if not self.spinning:
            return False
        self.tension += 2.0
        self.mount = trick
        self.drain(8.0 + self.tension * 1.5)
        return self.spinning

    def bind(self):
        if not self.spinning or self.velocity < 20.0:
            return False
        self.velocity = 0.0
        self.tension = 0.0
        self.mount = None
        self.spinning = False
        self.in_hand = True
        return True

    def status(self):
        place = "hand" if self.in_hand else str(self.mount)
        return "%s: velocity=%.1f tension=%.1f at %s" % (self.name, self.velocity, self.tension, place)


class Routine:
    MOUNTS = ("trapeze", "breakaway", "wrist", "undermount")

    def __init__(self, yoyo):
        self.yoyo = yoyo
        self.log = []
        self.caught = False

    def apply(self, move):
        name = move.strip().lower()
        if name == "throw":
            self.caught = False
            done = self.yoyo.throw()
        elif name == "bind":
            done = self.yoyo.bind()
            self.caught = done
        elif name in self.MOUNTS:
            done = self.yoyo.mount_to(name)
        else:
            done = self.yoyo.perform(name)
        self.log.append((name, done, round(self.yoyo.velocity, 1)))
        return done

    def run(self, moves):
        for move in moves:
            self.apply(move)
        return self.caught and self.yoyo.in_hand

    def report(self):
        lines = ["%-12s %-7s v=%s" % (name, "ok" if done else "FAIL", vel) for name, done, vel in self.log]
        lines.append(self.yoyo.status())
        return "\n".join(lines)


