SEASONS = ("spring", "summer", "autumn", "winter")


class BonsaiTree:
    CRITICAL_STRESS = 10.0

    def __init__(self, branches=8, leaf_density=40.0):
        self.branches = branches
        self.leaf_density = leaf_density
        self.stress = 0.0

    def water(self, season):
        if season == "spring":
            self.branches += 1
            self.leaf_density += 5.0
        else:
            self.leaf_density += 1.0
        return self.relieve_stress(0.5)

    def fertilize(self, season):
        if season == "spring":
            self.branches += 2
            self.leaf_density += 8.0
        else:
            self.leaf_density += 2.0
            return self.add_stress(1.5)
        return self.settle()

    def prune(self, season):
        removed = max(1, self.branches // 5)
        self.branches = max(1, self.branches - removed)
        self.leaf_density = max(0.0, self.leaf_density - 2.0 * removed)
        if season == "winter":
            return self.relieve_stress(3.0)
        if season == "summer":
            return self.add_stress(4.0)
        return self.add_stress(1.0)

    def endure(self, weather):
        if weather == "drought":
            self.leaf_density = max(0.0, self.leaf_density - 6.0)
            return self.add_stress(3.0)
        if weather == "storm":
            self.branches = max(1, self.branches - 1)
            return self.add_stress(2.0)
        self.leaf_density += 3.0
        return self.relieve_stress(1.0)

    def add_stress(self, amount):
        self.stress += amount
        return self.settle()

    def relieve_stress(self, amount):
        self.stress = max(0.0, self.stress - amount)
        return self.settle()

    def settle(self):
        if self.stress < self.CRITICAL_STRESS:
            return False
        self.leaf_density /= 2.0
        self.stress = 0.0
        return True

    def report(self):
        return "branches=%d leaves=%.1f stress=%.1f" % (
            self.branches, self.leaf_density, self.stress)


class Gardener:
    ACTIONS = ("water", "fertilize", "prune")
    WEATHER = ("drought", "storm", "rain")

    def __init__(self, tree):
        self.tree = tree
        self.journal = []

    def apply(self, season, event):
        if season not in SEASONS:
            raise ValueError("unknown season: %r" % (season,))
        if event in self.ACTIONS:
            dropped = getattr(self.tree, event)(season)
        elif event in self.WEATHER:
            dropped = self.tree.endure(event)
        else:
            raise ValueError("unknown event: %r" % (event,))
        self.journal.append((season, event, dropped, self.tree.report()))
        return dropped

    def run(self, seasons):
        for season, event in seasons:
            self.apply(season, event)
        return self.tree.branches, self.tree.leaf_density

    def summary(self):
        lines = ["%-7s %-10s %s%s" % (s, e, state, "  <leaf drop>" if d else "")
                 for s, e, d, state in self.journal]
        lines.append("drops: %d" % sum(1 for entry in self.journal if entry[2]))
        return "\n".join(lines)


def cultivate(seasons):
    gardener = Gardener(BonsaiTree())
    return gardener.run(seasons)


def main():
    schedule = [("spring", "water"), ("spring", "fertilize"), ("summer", "drought"),
                ("summer", "prune"), ("summer", "storm"), ("autumn", "rain"),
                ("winter", "prune"), ("spring", "fertilize")]
    gardener = Gardener(BonsaiTree())
    branches, leaves = gardener.run(schedule)
    print(gardener.summary())
    print("final: %d branches, %.1f leaf density" % (branches, leaves))
    print("entry function: %r" % (cultivate(schedule),))


if __name__ == "__main__":
    main()

