class AirPurifier:
    """An air purifier tracking fan speed, filter health and air quality."""

    MIN_HEALTH = 0
    FULL_HEALTH = 100

    def __init__(self):
        self.fan_speed = 1
        self.filter_health = self.FULL_HEALTH
        self.air_quality = 0

    def detect(self, index):
        self.air_quality = index
        if index < 20:
            self.fan_speed = 1
        elif index <= 50:
            self.fan_speed = 2
        else:
            self.fan_speed = 3
        return self.fan_speed

    def run(self, hours):
        wear = self.fan_speed * hours
        self.filter_health = max(self.MIN_HEALTH, self.filter_health - wear)
        return self.filter_health

    def replace(self):
        self.filter_health = self.FULL_HEALTH
        return self.filter_health

    def state(self):
        return (self.filter_health, self.fan_speed)

    def describe(self):
        return "AQI {0} | fan {1} | filter {2}%".format(
            self.air_quality, self.fan_speed, self.filter_health)


class PurifierController:
    """Validates and applies a sequence of (action, value) commands."""

    VALUED_ACTIONS = ("detect", "run")
    BARE_ACTIONS = ("replace",)

    def __init__(self, purifier=None):
        self.purifier = purifier or AirPurifier()
        self.history = []

    def apply(self, action, value=0):
        name = str(action).lower()
        if name in self.VALUED_ACTIONS:
            getattr(self.purifier, name)(int(value))
        elif name in self.BARE_ACTIONS:
            self.purifier.replace()
        else:
            raise ValueError("unknown action: {0!r}".format(action))
        self.history.append((name, self.purifier.describe()))
        return self.purifier.state()

    def apply_all(self, actions):
        for command in actions:
            self.apply(*command[:2]) if len(command) > 1 else self.apply(command[0])
        return self.purifier.state()

    def report(self):
        lines = ["step {0}: {1} -> {2}".format(i + 1, name, text)
                 for i, (name, text) in enumerate(self.history)]
        lines.append("final: health={0} speed={1}".format(*self.purifier.state()))
        return "\n".join(lines)


def simulate(actions):
    return PurifierController().apply_all(actions)


def main():
    controller = PurifierController()
    controller.apply_all([("detect", 60), ("run", 5), ("replace", 0), ("detect", 10)])
    print(controller.report())
    print(simulate([("detect", 60), ("run", 5)]))


if __name__ == "__main__":
    main()

