class MicroscopeStage:
    """A microscope stage tracking position, magnification and focus."""

    def __init__(self):
        self.horizontal = 0
        self.vertical = 0
        self.magnification = 10
        self.focus_level = 0

    def move(self, direction, amount):
        if direction == "horizontal":
            self.horizontal += amount
        elif direction == "vertical":
            self.vertical += amount
        else:
            raise ValueError("unknown direction: {!r}".format(direction))
        self.focus_level -= abs(amount)

    def magnify(self, level):
        self.magnification = max(1, level)

    def focus(self, level):
        self.focus_level = level

    def readings(self):
        return (self.horizontal, self.vertical, self.magnification, self.focus_level)


class StageController:
    """Turns (action, value) pairs into calls on a stage."""

    def __init__(self, stage):
        self.stage = stage
        self.handlers = {
            "horizontal": lambda value: self.stage.move("horizontal", value),
            "vertical": lambda value: self.stage.move("vertical", value),
            "magnify": self.stage.magnify,
            "focus": self.stage.focus,
        }

    def apply(self, action, value):
        if action not in self.handlers:
            raise ValueError("unknown action: {!r}".format(action))
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("value for {!r} must be an integer".format(action))
        self.handlers[action](value)

    def run(self, movements):
        for action, value in movements:
            self.apply(action, value)
        return self.stage.readings()


class StageReport:
    """Formats a set of stage readings for display."""

    def __init__(self, readings):
        self.horizontal, self.vertical, self.magnification, self.focus_level = readings

    def drift(self):
