class MicroscopeStage:
    """A microscope stage tracking position, magnification and focus."""

    def __init__(this):
        this.horizontal = 0
        this.vertical = 0
        this.magnification = 10
        this.focus_level = 0

    def move(this, direction, amount):
        if direction == "horizontal":
            this.horizontal += amount
        elif direction == "vertical":
            this.vertical += amount
        else:
            raise ValueError("unknown direction: {!r}".format(direction))
        this.focus_level -= abs(amount)

    def magnify(this, level):
        this.magnification = max(1, level)

    def focus(this, level):
        this.focus_level = level

    def readings(this):
        return (this.horizontal, this.vertical, this.magnification, this.focus_level)


class StageController:
    """Turns (action, value) pairs into calls on a stage."""

    def __init__(this, stage):
        this.stage = stage
        this.handlers = {
            "horizontal": lambda value: this.stage.move("horizontal", value),
            "vertical": lambda value: this.stage.move("vertical", value),
            "magnify": this.stage.magnify,
            "focus": this.stage.focus,
        }

    def apply(this, action, value):
        if action not in this.handlers:
            raise ValueError("unknown action: {!r}".format(action))
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("value for {!r} must be an integer".format(action))
        this.handlers[action](value)

    def run(this, movements):
        for action, value in movements:
            this.apply(action, value)
        return this.stage.readings()


class StageReport:
    """Formats a set of stage readings for display."""

    def __init__(this, readings):
        this.horizontal, this.vertical, this.magnification, this.focus_level = readings

    def drift(this):
