    def lines(this):
        yield "position: ({}, {})".format(this.horizontal, this.vertical)
        yield "magnification: {}x".format(this.magnification)
        yield "focus: {}".format(this.focus_level)
        yield "total travel from origin: {}".format(this.drift())

    def render(this):
        return "\n".join(this.lines())


