class CashDrawer:
    """Holds the cash and the net number of sales."""

    def __init__(self):
        self.cash = 50
        self.sales = 0

    def sale(self, amount):
        self.cash += amount
        self.sales += 1
        return True

    def refund(self, amount):
        if amount > self.cash:
            return False
        self.cash -= amount
        self.sales -= 1
        return True

    def deposit(self, amount):
        self.cash += amount
        return True

    def totals(self):
        return (self.cash, self.sales)


class TransactionLog:
    """Keeps the outcome of every attempted transaction."""

    def __init__(self):
        self.entries = []

    def record(self, operation, amount, accepted):
        self.entries.append((operation, amount, accepted))

    def rejected(self):
        return [entry for entry in self.entries if not entry[2]]

    def report(self):
        lines = []
        for operation, amount, accepted in self.entries:
            lines.append("{:<8}{:>5}  {}".format(
                operation, amount, "accepted" if accepted else "REJECTED"))
        lines.append("{} of {} transactions rejected".format(
            len(self.rejected()), len(self.entries)))
        return "\n".join(lines)


class Register:
    """Dispatches operation tuples onto a drawer and logs them."""

    def __init__(self):
        self.drawer = CashDrawer()
        self.log = TransactionLog()
        self.handlers = {
            "sale": self.drawer.sale,
            "refund": self.drawer.refund,
            "deposit": self.drawer.deposit,
        }

    def validate(self, operation, amount):
        if operation not in self.handlers:
            raise ValueError("unknown operation: {!r}".format(operation))
        if not isinstance(amount, int) or isinstance(amount, bool):
            raise TypeError("amount must be an integer, got {!r}".format(amount))
        if amount < 0:
            raise ValueError("amount must not be negative: {}".format(amount))

    def apply(self, operation, amount):
        self.validate(operation, amount)
        accepted = self.handlers[operation](amount)
        self.log.record(operation, amount, accepted)
        return accepted

    def run(self, operations):
        for operation, amount in operations:
            self.apply(operation, amount)
        return self.drawer.totals()


def transact(operations):
    return Register().run(operations)


def main():
    register = Register()
    cash, sales = register.run([("sale", 20), ("refund", 80), ("deposit", 15),
                                ("sale", 40), ("refund", 25)])
    print(register.log.report())
    print("balance={} count={}".format(cash, sales))
    print(transact([("sale", 20), ("refund", 80)]))


if __name__ == "__main__":
    main()

