class Amplifier:
    MIN_SETTING = 0
    MAX_SETTING = 10

    def __init__(self):
        self.volume_level = 5
        self.treble_level = 5
        self.bass_level = 5
        self.overdrive_on = False
        self.wear = 0

    def _bound(self, target):
        if target < self.MIN_SETTING:
            return self.MIN_SETTING
        if target > self.MAX_SETTING:
            return self.MAX_SETTING
        return target

    def _register_use(self):
        self.wear += 1

    def volume(self, target):
        self.volume_level = self._bound(target)
        self._register_use()

    def treble(self, target):
        self.treble_level = self._bound(target)
        self._register_use()

    def bass(self, target):
        self.bass_level = self._bound(target)
        self._register_use()

    def overdrive(self, target):
        self.overdrive_on = target == 1
        self._register_use()

    def state(self):
        return (self.volume_level, self.treble_level, self.bass_level,
                self.overdrive_on, self.wear)


class ControlPanel:
    def __init__(self, amplifier):
        self.amplifier = amplifier
        self.routes = {
            "volume": amplifier.volume,
            "treble": amplifier.treble,
            "bass": amplifier.bass,
            "overdrive": amplifier.overdrive,
        }

    def apply(self, control, target):
        if control not in self.routes:
            raise ValueError("unknown control: %r" % (control,))
        if not isinstance(target, int) or isinstance(target, bool):
            raise TypeError("target for %s must be an int" % control)
        self.routes[control](target)

    def apply_all(self, adjustments):
        for control, target in adjustments:
            self.apply(control, target)
        return self.amplifier.state()


class SessionReport:
    def __init__(self, state):
        self.volume, self.treble, self.bass, self.overdrive, self.wear = state

    def tone_line(self):
        return "volume=%d treble=%d bass=%d" % (self.volume, self.treble, self.bass)

    def drive_line(self):
        return "overdrive=%s" % ("on" if self.overdrive else "off")

    def render(self):
        return "%s | %s | wear=%d" % (self.tone_line(), self.drive_line(), self.wear)


def play(adjustments):
    amplifier = Amplifier()
    panel = ControlPanel(amplifier)
    return panel.apply_all(adjustments)


def main():
    session = [("volume", 11), ("bass", -3), ("overdrive", 1),
               ("treble", 7), ("overdrive", 0)]
    print(SessionReport(play(session)).render())


if __name__ == "__main__":
    main()

