class LoomError(ValueError):
    """Raised when a loom command cannot be interpreted."""


class PowerLoom:
    def __init__(self):
        self.thread_count = 1000
        self.pattern_index = 0
        self.cloth_length = 0

    def thread(self, amount):
        self.thread_count += amount
        return self.thread_count

    def pattern(self, index):
        self.pattern_index = index
        return self.pattern_index

    def thread_per_row(self):
        return self.pattern_index + 1

    def weave(self, rows):
        cost = self.thread_per_row()
        woven = 0
        for _ in range(rows):
            if self.thread_count < cost:
                break
            self.thread_count -= cost
            self.cloth_length += 1
            woven += 1
        return woven

    def state(self):
        return (self.cloth_length, self.thread_count)


class LoomController:
    COMMANDS = ("thread", "pattern", "weave")

    def __init__(self, loom):
        self.loom = loom
        self.history = []

    def validate(self, action):
        if len(action) != 2:
            raise LoomError("each action needs a command and an integer: %r" % (action,))
        command, value = action
        if command not in self.COMMANDS:
            raise LoomError("unknown loom command: %r" % (command,))
        if not isinstance(value, int) or isinstance(value, bool):
            raise LoomError("command %s needs an integer value" % command)
        return command, value

    def dispatch(self, action):
        command, value = self.validate(action)
        if command == "thread":
            note = "thread now %d" % self.loom.thread(value)
        elif command == "pattern":
            note = "row cost now %d" % (self.loom.pattern(value) + 1)
        else:
            note = "%d of %d rows woven" % (self.loom.weave(value), value)
        self.history.append((command, value, note))
        return note

    def run(self, actions):
        for action in actions:
            self.dispatch(action)
        return self.loom.state()

    def report(self):
        lines = ["%s %d -> %s" % entry for entry in self.history]
        cloth, thread = self.loom.state()
        lines.append("final cloth %d, thread %d" % (cloth, thread))
        return "\n".join(lines)


def weave(actions):
    return LoomController(PowerLoom()).run(actions)


def main():
    controller = LoomController(PowerLoom())
    result = controller.run([("thread", 100), ("pattern", 3), ("weave", 50),
                             ("pattern", 0), ("weave", 1000), ("weave", 5)])
    print(controller.report())
    print("weave() returned %r" % (result,))


if __name__ == "__main__":
    main()

