class BookPress:
    """A book press with adjustable pressure and glue temperature."""

    MIN_PRESSURE = 40
    MIN_TEMPERATURE = 90

    def __init__(self, pressure=50, temperature=100, books_bound=0):
        self.pressure = pressure
        self.temperature = temperature
        self.books_bound = books_bound

    def set_pressure(self, value):
        self.pressure = value

    def set_temperature(self, value):
        self.temperature = value

    def is_ready(self):
        return self.pressure > self.MIN_PRESSURE and self.temperature > self.MIN_TEMPERATURE

    def press(self, batch_size):
        if not self.is_ready():
            return False
        self.books_bound += batch_size
        self.pressure -= batch_size
        return True

    def totals(self):
        return self.books_bound, self.pressure


class CommandValidator:
    """Checks that each batch entry is a known command paired with an integer."""

    def __init__(self, allowed):
        self.allowed = set(allowed)

    def known_commands(self):
        return ", ".join(sorted(self.allowed))

    def validate(self, entry):
        try:
            name, value = entry
        except (TypeError, ValueError):
            raise ValueError("each batch entry must be a (command, value) pair: %r" % (entry,))
        if name not in self.allowed:
            raise ValueError("unknown command %r; expected one of %s" % (name, self.known_commands()))
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("command %r needs an integer value, got %r" % (name, value))
        return name, value


class PressController:
    """Turns a sequence of commands into operations on a BookPress."""

    def __init__(self, press=None):
        self.press = press if press is not None else BookPress()
        self.actions = {
            "pressure": self.press.set_pressure,
            "temperature": self.press.set_temperature,
            "press": self.press.press,
        }
        self.validator = CommandValidator(self.actions)

    def apply(self, entry):
        name, value = self.validator.validate(entry)
        return self.actions[name](value)

    def run(self, batches):
        for entry in batches:
            self.apply(entry)
        return self.press.totals()


def bind(batches):
    return PressController().run(batches)

