class SolarPanel:
    MIN_ANGLE = -90
    MAX_ANGLE = 90

    def __init__(self):
        self.angle = 0
        self.dirt = 0
        self.energy = 0

    def tilt(self, amount):
        target = self.angle + amount
        self.angle = max(self.MIN_ANGLE, min(self.MAX_ANGLE, target))

    def dust(self, amount):
        self.dirt += amount

    def _raw_output(self, intensity):
        magnitude = abs(self.angle)
        if magnitude == 0:
            return intensity
        if magnitude <= 45:
            return intensity // 2
        return intensity // 4

    def sun(self, intensity):
        gain = self._raw_output(intensity) - self.dirt
        if gain > 0:
            self.energy += gain

    def clean(self):
        self.dirt = 0


class EventProcessor:
    ACTIONS = ("tilt", "dust", "sun", "clean")

    def __init__(self, panel):
        self.panel = panel

    def validate(self, events):
        checked = []
        for event in events:
            if len(event) != 2:
                raise ValueError("each event needs an action and an integer")
            action, value = event
            if action not in self.ACTIONS:
                raise ValueError("unknown action: {}".format(action))
            checked.append((action, int(value)))
        return checked

    def apply(self, action, value):
        if action == "tilt":
            self.panel.tilt(value)
        elif action == "dust":
            self.panel.dust(value)
        elif action == "sun":
            self.panel.sun(value)
        else:
            self.panel.clean()

    def run(self, events):
        for action, value in self.validate(events):
            self.apply(action, value)
        return self.panel.energy


def generate(events):
    return EventProcessor(SolarPanel()).run(events)


class ScenarioRunner:
    def __init__(self, scenarios):
        self.scenarios = scenarios

    def results(self):
        return [(name, generate(events)) for name, events in self.scenarios]

    def report(self):
