class SolarPanel:
    MIN_ANGLE = -90
    MAX_ANGLE = 90

    def __init__(this):
        this.angle = 0
        this.dirt = 0
        this.energy = 0

    def tilt(this, amount):
        target = this.angle + amount
        this.angle = max(this.MIN_ANGLE, min(this.MAX_ANGLE, target))

    def dust(this, amount):
        this.dirt += amount

    def _raw_output(this, intensity):
        magnitude = abs(this.angle)
        if magnitude == 0:
            return intensity
        if magnitude <= 45:
            return intensity // 2
        return intensity // 4

    def sun(this, intensity):
        gain = this._raw_output(intensity) - this.dirt
        if gain > 0:
            this.energy += gain

    def clean(this):
        this.dirt = 0


class EventProcessor:
    ACTIONS = ("tilt", "dust", "sun", "clean")

    def __init__(this, panel):
        this.panel = panel

    def validate(this, events):
        checked = []
        for event in events:
            if len(event) != 2:
                raise ValueError("each event needs an action and an integer")
            action, value = event
            if action not in this.ACTIONS:
                raise ValueError("unknown action: {}".format(action))
            checked.append((action, int(value)))
        return checked

    def apply(this, action, value):
        if action == "tilt":
            this.panel.tilt(value)
        elif action == "dust":
            this.panel.dust(value)
        elif action == "sun":
            this.panel.sun(value)
        else:
            this.panel.clean()

    def run(this, events):
        for action, value in this.validate(events):
            this.apply(action, value)
        return this.panel.energy


def generate(events):
    return EventProcessor(SolarPanel()).run(events)


class ScenarioRunner:
    def __init__(this, scenarios):
        this.scenarios = scenarios

    def results(this):
        return [(name, generate(events)) for name, events in this.scenarios]

    def report(this):
        width = max(len(name) for name, _ in this.scenarios)
        rows = ["{:<{w}} : {} units".format(name, total, w=width)
                for name, total in this.results()]
        return "\n".join(rows)


