class Bumper:
    """A pinball bumper with a score multiplier, an active state and a running total."""

    def __init__(self):
        self.multiplier = 1
        self.active = False
        self.score = 0

    def activate(self):
        self.active = True

    def deactivate(self):
        self.active = False

    def upgrade(self):
        self.multiplier += 1

    def hit(self):
        if self.active:
            gained = 10 * self.multiplier
        else:
            gained = 1
        self.score += gained
        return gained

    def state_label(self):
        return "active" if self.active else "idle"


class BumperController:
    """Applies named commands to a bumper and records what each one did."""

    COMMANDS = ("hit", "activate", "deactivate", "upgrade")

    def __init__(self, bumper):
        self.bumper = bumper
        self.log = []

    def apply(self, command):
        name = command.strip().lower()
        if name not in self.COMMANDS:
            raise ValueError("unknown bumper command: %r" % command)
        gained = self.bumper.hit() if name == "hit" else 0
        if name == "activate":
            self.bumper.activate()
        elif name == "deactivate":
            self.bumper.deactivate()
        elif name == "upgrade":
            self.bumper.upgrade()
        self.log.append((name, gained, self.bumper.score))
        return gained

    def run(self, commands):
        for command in commands:
            self.apply(command)
        return self.bumper.score

    def report(self):
        lines = []
        for step, (name, gained, total) in enumerate(self.log, start=1):
            lines.append("%2d. %-10s +%-3d total=%d" % (step, name, gained, total))
        lines.append("final: %d points (%s, x%d)" % (
            self.bumper.score, self.bumper.state_label(), self.bumper.multiplier))
        return "\n".join(lines)


def bounce(hits):
    controller = BumperController(Bumper())
    return controller.run(hits)


