class Scooter:
    PIN = 1234
    MAX_BATTERY = 100

    def __init__(self):
        self.battery = self.MAX_BATTERY
        self.locked = True
        self.distance_travelled = 0

    def unlock(self, pin):
        if pin == self.PIN:
            self.locked = False
        return not self.locked

    def lock(self):
        self.locked = True

    def charge(self, amount):
        self.battery = min(self.MAX_BATTERY, self.battery + amount)
        return self.battery

    def drive(self, requested):
        if self.locked:
            return 0
        travelled = min(requested, self.battery)
        self.battery -= travelled
        self.distance_travelled += travelled
        return travelled

    def state(self):
        return self.distance_travelled, self.battery


class RideController:
    def __init__(self, scooter):
        self.scooter = scooter
        self.log = []

    def apply(self, action, value):
        if action == "unlock":
            opened = self.scooter.unlock(value)
            self.log.append("unlock accepted" if opened else "unlock rejected")
        elif action == "lock":
            self.scooter.lock()
            self.log.append("locked")
        elif action == "charge":
            self.log.append("charged to %d" % self.scooter.charge(value))
        elif action == "drive":
            self.log.append("drove %d of %d" % (self.scooter.drive(value), value))
        else:
            raise ValueError("unknown action: %r" % (action,))

    def run(self, actions):
        for action, value in actions:
            self.apply(action, value)
        return self.scooter.state()

    def report(self):
        distance, battery = self.scooter.state()
        lines = ["%2d. %s" % (i + 1, entry) for i, entry in enumerate(self.log)]
        lines.append("total distance %d, battery %d%%" % (distance, battery))
        return "\n".join(lines)


def ride(actions):
    return RideController(Scooter()).run(actions)


def main():
    actions = [
        ("unlock", 1111),
        ("drive", 10),
        ("unlock", 1234),
        ("drive", 40),
        ("charge", 30),
        ("drive", 100),
        ("lock", 0),
        ("drive", 5),
    ]
    controller = RideController(Scooter())
    controller.run(actions)
    print(controller.report())
    print(ride(actions))


if __name__ == "__main__":
    main()

