class FireworksLauncher:
    """A launcher with a safety lock, a fuse delay and a launch tally."""

    def __init__(self):
        self.safety_lock = True
        self.fuse_delay = 5
        self.launched_count = 0

    def unlock(self):
        self.safety_lock = False

    def lock(self):
        self.safety_lock = True

    def delay(self, seconds):
        if not isinstance(seconds, int) or isinstance(seconds, bool):
            raise TypeError("fuse delay must be an integer")
        self.fuse_delay = seconds

    def fire(self, quantity):
        if self.safety_lock:
            return []
        self.launched_count += quantity
        return ["boom"] * quantity

    def is_armed(self):
        return not self.safety_lock


class LaunchSequence:
    """Applies a list of (action, value) pairs to a launcher."""

    def __init__(self, sequence):
        self.launcher = FireworksLauncher()
        self.steps = [self._validate(step) for step in sequence]
        self.booms = []

    def _validate(self, step):
        if len(step) != 2:
            raise ValueError("each step needs an action and an integer")
        action, value = step
        if action not in ("unlock", "lock", "delay", "fire"):
            raise ValueError("unknown action: %r" % (action,))
        return action, value

    def run(self):
        for action, value in self.steps:
            self.apply(action, value)
        return self.launcher.launched_count, self.booms

    def apply(self, action, value):
        if action == "unlock":
            self.launcher.unlock()
        elif action == "lock":
            self.launcher.lock()
        elif action == "delay":
            self.launcher.delay(value)
        else:
            self.booms.extend(self.launcher.fire(value))


class ShowReport:
    """Renders the outcome of a finished launch sequence."""

    def __init__(self, launcher, total, booms):
        self.launcher = launcher
        self.total = total
        self.booms = booms

    def lines(self):
        state = "armed" if self.launcher.is_armed() else "locked"
        return [
            "fireworks launched: %d" % self.total,
            "fuse delay: %ds" % self.launcher.fuse_delay,
            "launcher state: %s" % state,
            "soundtrack: %s" % (" ".join(self.booms) or "(silence)"),
        ]

    def render(self):
        return "\n".join(self.lines())


def launch(sequence):
    runner = LaunchSequence(sequence)
    total, booms = runner.run()
    return total, booms


def main():
    show = [("fire", 3), ("unlock", 0), ("delay", 2), ("fire", 2), ("lock", 0), ("fire", 5)]
    runner = LaunchSequence(show)
    total, booms = runner.run()
    print(ShowReport(runner.launcher, total, booms).render())
    print(launch([("unlock", 0), ("fire", 1)]))


if __name__ == "__main__":
    main()

