class CuckooClock:
    """A mechanical cuckoo clock driven by elapsed minutes."""

    MINUTES_PER_CHIME = 60

    def __init__(self):
        self.total_minutes = 0
        self.bird_visible = False
        self.chime_count = 0

    def calculated_chimes(self):
        return self.total_minutes // self.MINUTES_PER_CHIME

    def advance(self, minutes):
        before = self.calculated_chimes()
        self.total_minutes += minutes
        after = self.calculated_chimes()
        if after > before:
            self.bird_visible = True
            self.chime_count = after
        return self.bird_visible

    def reset(self):
        self.bird_visible = False

    def state(self):
        return (self.chime_count, self.bird_visible)

    def describe(self):
        position = "out" if self.bird_visible else "inside"
        return "{0} min, {1} chimes, bird {2}".format(
            self.total_minutes, self.chime_count, position
        )


class ClockSimulator:
    """Applies a sequence of minute events to a clock and records a log."""

    RESET_EVENT = -1

    def __init__(self, clock=None):
        self.clock = clock if clock is not None else CuckooClock()
        self.log = []

    def apply(self, event):
        if not isinstance(event, int) or isinstance(event, bool):
            raise TypeError("events must be integers, got {0!r}".format(event))
        if event == self.RESET_EVENT:
            self.clock.reset()
            action = "reset"
        elif event < 0:
            raise ValueError("negative events other than -1 are invalid")
        else:
            self.clock.advance(event)
            action = "advance {0}".format(event)
        self.log.append("{0} -> {1}".format(action, self.clock.describe()))
        return self.clock.state()

    def run(self, events):
        for event in events:
            self.apply(event)
        return self.clock.state()

    def report(self):
        lines = ["step {0}: {1}".format(i + 1, entry)
                 for i, entry in enumerate(self.log)]
        chimes, visible = self.clock.state()
        lines.append("final: {0} chimes, visible={1}".format(chimes, visible))
        return "\n".join(lines)


def tick(events):
    simulator = ClockSimulator()
    return simulator.run(events)


def main():
    simulator = ClockSimulator()
    simulator.run([30, 45, 10, -1, 120, 5])
    print(simulator.report())
    print("tick result:", tick([59, 1, -1, 60]))


if __name__ == "__main__":
    main()

