class DivingBoard:
    """A diving board with a movable fulcrum that can be broken by heavy divers."""

    BREAKING_TORQUE = 500
    MAX_FULCRUM = 10

    def __init__(self):
        self.fulcrum = 0
        self.bounces = 0
        self.broken = False

    def adjust(self, delta):
        if self.broken:
            return False
        target = self.fulcrum + delta
        self.fulcrum = max(0, min(self.MAX_FULCRUM, target))
        return True

    def jump(self, weight):
        if self.broken:
            return False
        if weight * self.fulcrum > self.BREAKING_TORQUE:
            self.broken = True
        else:
            self.bounces += 1
        return True

    def result(self):
        return (self.bounces, self.broken)


class DiveLog:
    """Keeps a trace of every attempted action for the final report."""

    def __init__(self):
        self.entries = []

    def record(self, action, value, board, applied):
        self.entries.append((action, value, board.fulcrum, board.bounces, applied))

    def report(self):
        lines = ["action  value  fulcrum  bounces  applied"]
        for action, value, fulcrum, bounces, applied in self.entries:
            lines.append("%-6s %6d %8d %8d  %s" % (action, value, fulcrum, bounces, applied))
        return "\n".join(lines)


class DiveSimulator:
    """Runs a sequence of (action, value) pairs against a single board."""

    def __init__(self, jumps):
        self.jumps = jumps
        self.board = DivingBoard()
        self.log = DiveLog()

    def _dispatch(self, action, value):
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("value must be an integer, got %r" % (value,))
        if action == "adjust":
            return self.board.adjust(value)
        if action == "jump":
            return self.board.jump(value)
        raise ValueError("unknown action %r" % (action,))

    def run(self):
        for action, value in self.jumps:
            applied = self._dispatch(action, value)
            self.log.record(action, value, self.board, applied)
        return self.board.result()

    def trace(self):
        return self.log.report()


def dive(jumps):
    return DiveSimulator(jumps).run()


if __name__ == "__main__":
