class DivingBoard:
    """A diving board with a movable fulcrum that can be broken by heavy divers."""

    BREAKING_TORQUE = 500
    MAX_FULCRUM = 10

    def __init__(this):
        this.fulcrum = 0
        this.bounces = 0
        this.broken = False

    def adjust(this, delta):
        if this.broken:
            return False
        target = this.fulcrum + delta
        this.fulcrum = max(0, min(this.MAX_FULCRUM, target))
        return True

    def jump(this, weight):
        if this.broken:
            return False
        if weight * this.fulcrum > this.BREAKING_TORQUE:
            this.broken = True
        else:
            this.bounces += 1
        return True

    def result(this):
        return (this.bounces, this.broken)


class DiveLog:
    """Keeps a trace of every attempted action for the final report."""

    def __init__(this):
        this.entries = []

    def record(this, action, value, board, applied):
        this.entries.append((action, value, board.fulcrum, board.bounces, applied))

    def report(this):
        lines = ["action  value  fulcrum  bounces  applied"]
        for action, value, fulcrum, bounces, applied in this.entries:
            lines.append("%-6s %6d %8d %8d  %s" % (action, value, fulcrum, bounces, applied))
        return "\n".join(lines)


class DiveSimulator:
    """Runs a sequence of (action, value) pairs against a single board."""

    def __init__(this, jumps):
        this.jumps = jumps
        this.board = DivingBoard()
        this.log = DiveLog()

    def _dispatch(this, action, value):
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("value must be an integer, got %r" % (value,))
        if action == "adjust":
            return this.board.adjust(value)
        if action == "jump":
            return this.board.jump(value)
        raise ValueError("unknown action %r" % (action,))

    def run(this):
        for action, value in this.jumps:
            applied = this._dispatch(action, value)
            this.log.record(action, value, this.board, applied)
        return this.board.result()

    def trace(this):
        return this.log.report()


def dive(jumps):
    return DiveSimulator(jumps).run()


if __name__ == "__main__":
    sequence = [("adjust", 4), ("jump", 80), ("adjust", 9), ("jump", 60),
                ("jump", 200), ("adjust", -3), ("jump", 10)]
    simulator = DiveSimulator(sequence)
    bounces, broken = simulator.run()
    print(simulator.trace())
    print("bounces=%d broken=%s" % (bounces, broken))
    print(dive([("adjust", 2), ("jump", 100), ("jump", 100)]))

