class RotorSystem:
    MAX_PITCH = 10
    MAX_SPEED = 100
    SAFE_TEMP = 100

    def __init__(self):
        self.blade_pitch = 0
        self.speed = 0
        self.temperature = 50
        self.shutoffs = 0

    def pitch(self, value):
        self.blade_pitch = min(max(value, 0), self.MAX_PITCH)

    def throttle(self, value):
        self.speed = min(self.speed + value, self.MAX_SPEED)

    def run(self, minutes):
        self.temperature += self.speed * self.blade_pitch * minutes // 100
        if self.temperature > self.SAFE_TEMP:
            self.speed = 0
            self.shutoffs += 1

    def state(self):
        return (self.speed, self.temperature)


class FlightController:
    def __init__(self):
        self.rotor = RotorSystem()
        self.handlers = {
            "pitch": self.rotor.pitch,
            "throttle": self.rotor.throttle,
            "run": self.rotor.run,
        }
        self.history = []

    def dispatch(self, action, value):
        handler = self.handlers.get(action)
        if handler is None:
            raise ValueError("unknown rotor action: %r" % (action,))
        handler(int(value))
        self.history.append((action, int(value)) + self.rotor.state())

    def execute(self, inputs):
        for action, value in inputs:
            self.dispatch(action, value)
        return self.rotor.state()


class FlightReport:
    def __init__(self, controller):
        self.controller = controller
        self.width = max([len(action) for action, _, _, _ in controller.history] + [6])

    def header(self):
        return "%-*s %6s %6s %6s" % (self.width, "action", "value", "speed", "temp")

    def lines(self):
        return ["%-*s %6d %6d %6d" % (self.width, action, value, speed, temp)
                for action, value, speed, temp in self.controller.history]

    def summary(self):
        rotor = self.controller.rotor
        return "final speed=%d temp=%d pitch=%d shutoffs=%d" % (
            rotor.speed, rotor.temperature, rotor.blade_pitch, rotor.shutoffs)

    def render(self):
        return "\n".join([self.header()] + self.lines() + [self.summary()])


def fly(inputs):
    controller = FlightController()
    return controller.execute(inputs)


def main():
    commands = [("pitch", 7), ("throttle", 60), ("run", 20),
                ("throttle", 80), ("run", 30), ("run", 5)]
    controller = FlightController()
    result = controller.execute(commands)
    print(FlightReport(controller).render())
    print("fly() ->", fly(commands), "matches:", result == fly(commands))


if __name__ == "__main__":
    main()

