class IceCreamMachine:
    MIN_TEMPERATURE = -10
    FREEZING_POINT = 0

    def __init__(self):
        self.mix_level = 100
        self.temperature = 20
        self.total_servings = 0

    def cool(self, minutes):
        target = self.temperature - 2 * minutes
        self.temperature = max(target, self.MIN_TEMPERATURE)
        return self.temperature

    def refill(self, amount):
        self.mix_level += amount
        return self.mix_level

    def is_frozen(self):
        return self.temperature < self.FREEZING_POINT

    def serve(self, portion):
        if self.is_frozen() and self.mix_level >= portion:
            self.mix_level -= portion
            self.total_servings += 1
            return True
        return False

    def summary(self):
        return (self.total_servings, self.mix_level)

    def status(self):
        state = "frozen" if self.is_frozen() else "too warm"
        return "temp={0}C mix={1} servings={2} ({3})".format(
            self.temperature, self.mix_level, self.total_servings, state)


class OrderProcessor:
    def __init__(self, machine):
        self.machine = machine
        self.log = []

    def apply(self, action, amount):
        if action == "cool":
            self.machine.cool(amount)
            outcome = "cooled"
        elif action == "refill":
            self.machine.refill(amount)
            outcome = "refilled"
        elif action == "serve":
            outcome = "served" if self.machine.serve(amount) else "refused"
        else:
            raise ValueError("unknown action: {0}".format(action))
        self.log.append((action, amount, outcome))
        return outcome

    def run(self, orders):
        for action, amount in orders:
            self.apply(action, amount)
        return self.machine.summary()

    def report(self):
        lines = ["{0} {1} -> {2}".format(*entry) for entry in self.log]
        lines.append(self.machine.status())
        refused = sum(1 for entry in self.log if entry[2] == "refused")
        lines.append("{0} orders, {1} refused".format(len(self.log), refused))
        return "\n".join(lines)


def dispense(orders):
    processor = OrderProcessor(IceCreamMachine())
    return processor.run(orders)


def main():
    orders = [("serve", 10), ("cool", 15), ("serve", 30), ("refill", 20),
              ("serve", 50), ("serve", 100)]
    processor = OrderProcessor(IceCreamMachine())
    processor.run(orders)
    print(processor.report())
    print("dispense ->", dispense(orders))


if __name__ == "__main__":
    main()

