class Balloon:
    def __init__(self):
        self.fuel = 50
        self.altitude = 0
        self.distance = 0

    def burn(self, amount):
        consumed = min(amount, self.fuel)
        self.fuel -= consumed
        self.altitude += consumed * 10
        return consumed

    def cool(self, value):
        self.altitude = max(0, self.altitude - value)
        return self.altitude

    def drift(self, wind_speed):
        self.distance += wind_speed * self.altitude // 100
        return self.distance

    def state(self):
        return self.altitude, self.distance


class FlightLog:
    def __init__(self):
        self.entries = []

    def record(self, action, value, balloon):
        altitude, distance = balloon.state()
        self.entries.append((action, value, altitude, distance, balloon.fuel))

    def report(self):
        lines = ["step  action  value  altitude  distance  fuel"]
        for step, entry in enumerate(self.entries, start=1):
            action, value, altitude, distance, fuel = entry
            lines.append("%4d  %-6s  %5d  %8d  %8d  %4d"
                         % (step, action, value, altitude, distance, fuel))
        return "\n".join(lines)


class Navigator:
    ACTIONS = ("burn", "cool", "drift")

    def __init__(self):
        self.balloon = Balloon()
        self.log = FlightLog()

    def execute(self, action, value):
        if action not in self.ACTIONS:
            raise ValueError("unknown action: %r" % (action,))
        if value < 0:
            raise ValueError("value must be non-negative, got %d" % value)
        if action == "burn":
            self.balloon.burn(value)
        elif action == "cool":
            self.balloon.cool(value)
        else:
            self.balloon.drift(value)
        self.log.record(action, value, self.balloon)

    def run(self, commands):
        for action, value in commands:
            self.execute(action, value)
        return self.balloon.state()

    def summary(self):
        altitude, distance = self.balloon.state()
        return "%s\nfinal altitude %d, horizontal distance %d, fuel left %d" % (
            self.log.report(), altitude, distance, self.balloon.fuel)


def navigate(commands):
    return Navigator().run(commands)


def main():
    flight = [("burn", 20), ("drift", 15), ("cool", 50),
              ("drift", 40), ("burn", 45), ("drift", 10)]
    pilot = Navigator()
    altitude, distance = pilot.run(flight)
    print(pilot.summary())
    print("navigate() returns", (altitude, distance))


if __name__ == "__main__":
    main()

