MAX_PRESSURE = 100
MIN_PRESSURE = 0


class Valve:
    """A heavy duty plumbing valve with pressure, state and throughput."""

    def __init__(self, pressure=50, is_open=False, volume_passed=0):
        self.pressure = pressure
        self.is_open = is_open
        self.volume_passed = volume_passed

    def toggle(self, _value=0):
        self.is_open = not self.is_open
        return self.is_open

    def pressurize(self, amount):
        self.pressure = min(self.pressure + amount, MAX_PRESSURE)
        return self.pressure

    def run(self, duration):
        if self.is_open:
            self.volume_passed += duration * self.pressure
        self.pressure = max(self.pressure - duration, MIN_PRESSURE)
        return self.volume_passed

    def describe(self):
        state = "open" if self.is_open else "closed"
        return "valve {0}, pressure {1}, volume {2}".format(
            state, self.pressure, self.volume_passed
        )


class ValveController:
    """Validates command tuples and applies them to a valve."""

    def __init__(self, valve=None):
        self.valve = valve if valve is not None else Valve()
        self.actions = {
            "toggle": self.valve.toggle,
            "pressurize": self.valve.pressurize,
            "run": self.valve.run,
        }

    def parse(self, command):
        if not isinstance(command, (tuple, list)) or len(command) != 2:
            raise ValueError("command must be a (action, value) pair: %r" % (command,))
        action, value = command
        if action not in self.actions:
            raise ValueError("unknown action: %r" % (action,))
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("value must be an integer: %r" % (value,))
        return action, value

    def execute(self, command):
        action, value = self.parse(command)
        return self.actions[action](value)

    def execute_all(self, commands):
        for command in commands:
            self.execute(command)
        return self.valve.volume_passed

    def report(self):
        return "{0}; total passed {1}".format(self.valve.describe(), self.valve.volume_passed)


def flow(commands):
    return ValveController().execute_all(commands)


def main():
    script = [("pressurize", 30), ("toggle", 0), ("run", 10), ("run", 5), ("toggle", 0)]
    controller = ValveController()
    total = controller.execute_all(script)
    print(controller.report())
    print("flow() ->", flow(script), "matches driver total:", total)


if __name__ == "__main__":
    main()

