class DebateTimer:
    """Tracks per-speaker speaking time and the overrun penalty flag."""

    LIMIT = 100

    def __init__(self):
        self.current_speaker = 1
        self.speaker_one_time = 0
        self.speaker_two_time = 0
        self.penalty = False

    def switch(self):
        self.current_speaker = 2 if self.current_speaker == 1 else 1

    def speak(self, duration):
        if self.current_speaker == 1:
            self.speaker_one_time += duration
        else:
            self.speaker_two_time += duration
        self.update_penalty()

    def update_penalty(self):
        if self.speaker_one_time > self.LIMIT or self.speaker_two_time > self.LIMIT:
            self.penalty = True

    def totals(self):
        return (self.speaker_one_time, self.speaker_two_time, self.penalty)


class TurnRunner:
    """Validates and dispatches (action, value) turns onto a timer."""

    def __init__(self, timer):
        self.timer = timer

    def run(self, turns):
        for turn in turns:
            action, value = turn
            self.apply(action, value)
        return self.timer.totals()

    def apply(self, action, value):
        name = action.strip().lower()
        if name == "switch":
            self.timer.switch()
        elif name == "speak":
            self.timer.speak(self.checked_duration(value))
        else:
            raise ValueError("unknown debate action: {!r}".format(action))

    def checked_duration(self, value):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("speak duration must be an integer, got {!r}".format(value))
        if value < 0:
            raise ValueError("speak duration must not be negative: {}".format(value))
        return value


class DebateReport:
    """Turns a debate result triple into readable lines."""

    def __init__(self, result):
        self.one_time, self.two_time, self.penalty = result

    def leader(self):
