class DebateTimer:
    """Tracks per-speaker speaking time and the overrun penalty flag."""

    LIMIT = 100

    def __init__(this):
        this.current_speaker = 1
        this.speaker_one_time = 0
        this.speaker_two_time = 0
        this.penalty = False

    def switch(this):
        this.current_speaker = 2 if this.current_speaker == 1 else 1

    def speak(this, duration):
        if this.current_speaker == 1:
            this.speaker_one_time += duration
        else:
            this.speaker_two_time += duration
        this.update_penalty()

    def update_penalty(this):
        if this.speaker_one_time > this.LIMIT or this.speaker_two_time > this.LIMIT:
            this.penalty = True

    def totals(this):
        return (this.speaker_one_time, this.speaker_two_time, this.penalty)


class TurnRunner:
    """Validates and dispatches (action, value) turns onto a timer."""

    def __init__(this, timer):
        this.timer = timer

    def run(this, turns):
        for turn in turns:
            action, value = turn
            this.apply(action, value)
        return this.timer.totals()

    def apply(this, action, value):
        name = action.strip().lower()
        if name == "switch":
            this.timer.switch()
        elif name == "speak":
            this.timer.speak(this.checked_duration(value))
        else:
            raise ValueError("unknown debate action: {!r}".format(action))

    def checked_duration(this, value):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("speak duration must be an integer, got {!r}".format(value))
        if value < 0:
            raise ValueError("speak duration must not be negative: {}".format(value))
        return value


