import sys


class CementMixer:
    """A drum mixer that tracks rotation speed, wetness and readiness."""

    WETNESS_MIN = 40
    WETNESS_MAX = 60
    IDLE_SPEED = 10

    def __init__(self):
        self.rotation_speed = 0
        self.wetness = 0
        self.ready = False
        self.elapsed_minutes = 0

    def add_water(self, amount):
        self.wetness += amount
        return self.wetness

    def spin(self, speed):
        self.rotation_speed = int(speed)
        return self.rotation_speed

    def tumble(self, minutes):
        self.elapsed_minutes += minutes
        if self.rotation_speed > self.IDLE_SPEED:
            self.ready = self.WETNESS_MIN <= self.wetness <= self.WETNESS_MAX
        return self.ready

    def apply_stage(self, action, value):
        if action == "water":
            return self.add_water(value)
        if action == "spin":
            return self.spin(value)
        if action == "tumble":
            return self.tumble(value)
        raise ValueError("unknown mixer action: %r" % (action,))

    def status(self):
        return "speed=%d wetness=%d minutes=%d ready=%s" % (
            self.rotation_speed, self.wetness, self.elapsed_minutes, self.ready)


class StageParser:
    """Turns command line tokens such as 'water:50' into mixer stages."""

    ACTIONS = ("water", "spin", "tumble")

    def __init__(self, text):
        self.text = text

    def parse(self):
        return [self.parse_token(token) for token in self.text.split()]

    def parse_token(self, token):
        if ":" not in token:
            raise ValueError("stage %r must look like action:amount" % token)
        action, raw_amount = token.split(":", 1)
        action = action.strip().lower()
        if action not in self.ACTIONS:
            raise ValueError("stage %r uses an unsupported action" % token)
        return (action, self.parse_amount(raw_amount))

    def parse_amount(self, raw_amount):
        try:
            return int(raw_amount.strip())
        except ValueError:
            raise ValueError("amount in %r is not an integer" % self.text)


class MixReport:
    """Human readable summary of a batch of stages and its outcome."""

    def __init__(self, stages, ready):
        self.stages = stages
        self.ready = ready

    def render(self):
        lines = [self.describe(index, stage)
                 for index, stage in enumerate(self.stages)]
        lines.append("verdict: " + self.verdict())
        return "\n".join(lines)

    def describe(self, index, stage):
        action, value = stage
        return "stage %d: %s %s" % (index + 1, action, self.quantity(action, value))

    def quantity(self, action, value):
        if action == "water":
            return "%d litres" % value
        if action == "spin":
            return "%d rpm" % value
        return "%d minutes" % value

    def verdict(self):
        return "ready to pour" if self.ready else "mix not ready"


