class Battery:
    def __init__(self, level=100):
        self.level = level

    def can_supply(self, amount):
        return amount <= self.level

    def consume(self, amount):
        if not self.can_supply(amount):
            return False
        self.level -= amount
        return True

    def recharge(self, amount):
        self.level = min(100, self.level + amount) if amount > 0 else 100
        return self.level


class SampleManifest:
    def __init__(self):
        self.entries = []

    def add(self, weight):
        self.entries.append(weight)
        return self.total()

    def total(self):
        return sum(self.entries)

    def describe(self):
        return "%d samples, %d total weight" % (len(self.entries), self.total())


class Rover:
    HEADINGS = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    GATHER_COST = 5

    def __init__(self):
        self.x = 0
        self.y = 0
        self.facing = 0
        self.battery = Battery()
        self.manifest = SampleManifest()

    def move(self, distance):
        if not self.battery.consume(distance):
            return False
        dx, dy = self.HEADINGS[self.facing]
        self.x += dx * distance
        self.y += dy * distance
        return True

    def turn(self, quarters):
        self.facing = (self.facing + quarters) % len(self.HEADINGS)
        return True

    def gather(self, weight):
        if not self.battery.consume(self.GATHER_COST):
            return False
        self.manifest.add(weight)
        return True

    def execute(self, action, value):
        if action == "move":
            return self.move(value)
        if action == "turn":
            return self.turn(value)
        if action == "gather":
            return self.gather(value)
        if action == "recharge":
            self.battery.recharge(value)
            return True
        raise ValueError("unknown action: %s" % action)

    def state(self):
        return (self.x, self.y, self.manifest.total())


class MissionLog:
    def __init__(self, rover):
        self.rover = rover
        self.steps = []

    def run(self, commands):
        for action, value in commands:
            applied = self.rover.execute(action, value)
            self.steps.append((action, value, applied, self.rover.battery.level))
        return self.rover.state()

    def report(self):
        lines = ["%s %d -> %s (battery %d)" % (a, v, "ok" if ok else "skipped", b)
                 for a, v, ok, b in self.steps]
        lines.append(self.rover.manifest.describe())
        lines.append("final position %d %d" % (self.rover.x, self.rover.y))
        return "\n".join(lines)


def navigate(commands):
    return MissionLog(Rover()).run(commands)


def main():
    commands = [("move", 10), ("gather", 3), ("turn", 1), ("move", 4),
                ("gather", 7), ("recharge", 0), ("turn", -1), ("move", 2)]
    log = MissionLog(Rover())
    result = log.run(commands)
    print(log.report())
    print("navigate ->", navigate(commands), "==", result)


if __name__ == "__main__":
    main()

