class Patient:
    def __init__(self, severity, duration, arrival_order):
        self.severity = severity
        self.remaining = duration
        self.arrival_order = arrival_order

    def priority(self):
        return (self.severity, self.arrival_order)

    def treat(self, minutes):
        used = min(self.remaining, minutes)
        self.remaining -= used
        return minutes - used

    def is_done(self):
        return self.remaining <= 0


class EventParser:
    def __init__(self, min_severity=1, max_severity=5):
        self.min_severity = min_severity
        self.max_severity = max_severity

    def check_severity(self, severity):
        if not self.min_severity <= severity <= self.max_severity:
            raise ValueError("severity must be between %d and %d"
                             % (self.min_severity, self.max_severity))

    def parse(self, event):
        if isinstance(event, int):
            return "advance", (event,)
        if len(event) == 3 and event[0] == "arrive":
            self.check_severity(event[1])
            return "arrive", (event[1], event[2])
        if len(event) == 2 and event[0] == "advance":
            return "advance", (event[1],)
        if len(event) == 2:
            self.check_severity(event[0])
            return "arrive", (event[0], event[1])
        raise ValueError("unrecognised event: %r" % (event,))


class EmergencyRoom:
    def __init__(self, parser=None):
        self.parser = parser or EventParser()
        self.waiting = []
        self.current = None
        self.clock = 0
        self.arrivals_seen = 0

    def admit_next(self):
        if self.waiting:
            self.current = min(self.waiting, key=lambda p: p.priority())
            self.waiting.remove(self.current)
        else:
            self.current = None

    def arrive(self, severity, duration):
        self.arrivals_seen += 1
        self.waiting.append(Patient(severity, duration, self.arrivals_seen))
        if self.current is None:
            self.admit_next()

    def advance(self, minutes):
        self.clock += minutes
        left = minutes
        while left > 0 and self.current is not None:
            left = self.current.treat(left)
            if self.current.is_done():
                self.admit_next()

    def handle(self, event):
        kind, values = self.parser.parse(event)
        if kind == "arrive":
            self.arrive(*values)
        else:
            self.advance(*values)

    def status(self):
        severity = self.current.severity if self.current else 0
        return len(self.waiting), severity

    def summary(self):
        waiting, severity = self.status()
        treated = "severity %d" % severity if severity else "nobody"
        return "t=%d min: treating %s, %d waiting" % (self.clock, treated, waiting)


def triage(arrivals):
    room = EmergencyRoom()
    for event in arrivals:
