class Server:
    def __init__(self, identifier, capacity=10):
        self.identifier = identifier
        self.capacity = capacity
        self.connections = 0

    def is_full(self):
        return self.connections >= self.capacity

    def accept(self):
        if self.is_full():
            return False
        self.connections += 1
        return True

    def release(self):
        if self.connections > 0:
            self.connections -= 1

    def describe(self):
        return "server {0}: {1}/{2}".format(self.identifier, self.connections, self.capacity)


class LoadBalancer:
    def __init__(self, server_count=3, capacity=10):
        self.servers = [Server(i, capacity) for i in range(server_count)]
        self.dropped = 0

    def pick_server(self):
        available = [s for s in self.servers if not s.is_full()]
        if not available:
            return None
        return min(available, key=lambda s: (s.connections, s.identifier))

    def handle_request(self):
        target = self.pick_server()
        if target is None:
            self.dropped += 1
            return None
        target.accept()
        return target.identifier

    def handle_completion(self, identifier):
        if 0 <= identifier < len(self.servers):
            self.servers[identifier].release()

    def snapshot(self):
        return [s.connections for s in self.servers]

    def result(self):
        return (self.dropped, self.snapshot())

    def report(self):
        lines = [s.describe() for s in self.servers]
        lines.append("dropped requests: {0}".format(self.dropped))
        return "\n".join(lines)


class CommandParser:
    REQUEST_WORDS = ("request", "req", "new")
    COMPLETION_WORDS = ("complete", "completion", "done", "finish", "release")

    def parse(self, line):
        tokens = str(line).strip().lower().replace(":", " ").replace(",", " ").split()
        if not tokens:
            return None
        verb = tokens[0]
        if verb in self.REQUEST_WORDS:
            return ("request", None)
