class Server:
    def __init__(this, identifier, capacity=10):
        this.identifier = identifier
        this.capacity = capacity
        this.connections = 0

    def is_full(this):
        return this.connections >= this.capacity

    def accept(this):
        if this.is_full():
            return False
        this.connections += 1
        return True

    def release(this):
        if this.connections > 0:
            this.connections -= 1

    def describe(this):
        return "server {0}: {1}/{2}".format(this.identifier, this.connections, this.capacity)


class LoadBalancer:
    def __init__(this, server_count=3, capacity=10):
        this.servers = [Server(i, capacity) for i in range(server_count)]
        this.dropped = 0

    def pick_server(this):
        available = [s for s in this.servers if not s.is_full()]
        if not available:
            return None
        return min(available, key=lambda s: (s.connections, s.identifier))

    def handle_request(this):
        target = this.pick_server()
        if target is None:
            this.dropped += 1
            return None
        target.accept()
        return target.identifier

    def handle_completion(this, identifier):
        if 0 <= identifier < len(this.servers):
            this.servers[identifier].release()

    def snapshot(this):
        return [s.connections for s in this.servers]

    def result(this):
        return (this.dropped, this.snapshot())

    def report(this):
        lines = [s.describe() for s in this.servers]
        lines.append("dropped requests: {0}".format(this.dropped))
        return "\n".join(lines)


class CommandParser:
    REQUEST_WORDS = ("request", "req", "new")
    COMPLETION_WORDS = ("complete", "completion", "done", "finish", "release")

    def parse(this, line):
        tokens = str(line).strip().lower().replace(":", " ").replace(",", " ").split()
        if not tokens:
            return None
        verb = tokens[0]
        if verb in this.REQUEST_WORDS:
            return ("request", None)
        if verb in this.COMPLETION_WORDS:
            return ("completion", this.extract_identifier(tokens[1:]))
        return None

    def extract_identifier(this, rest):
        for token in rest:
            digits = "".join(c for c in token if c.isdigit())
            if digits:
                return int(digits)
        return None

    def apply(this, balancer, line):
        parsed = this.parse(line)
        if parsed is None:
            return
        kind, identifier = parsed
        if kind == "request":
            balancer.handle_request()
        elif identifier is not None:
            balancer.handle_completion(identifier)


def distribute(requests):
    balancer = LoadBalancer()
    parser = CommandParser()
    for line in requests:
        parser.apply(balancer, line)
    return balancer.result()


def main():
    traffic = ["request"] * 32 + ["complete 1", "complete 1", "done server 2", "request"]
    dropped, connections = distribute(traffic)
    print("dropped:", dropped)
    print("connections:", connections)


