class Cabin:
    def __init__(self, name, capacity, price):
        self.name = name
        self.capacity = capacity
        self.price = price
        self.passengers = set()

    def available(self):
        return self.capacity - len(self.passengers)

    def holds(self, passenger):
        return passenger in self.passengers

    def add(self, passenger):
        if self.holds(passenger) or self.available() == 0:
            return False
        self.passengers.add(passenger)
        return True

    def remove(self, passenger):
        if not self.holds(passenger):
            return False
        self.passengers.remove(passenger)
        return True


class TransactionLog:
    def __init__(self):
        self.entries = []

    def record(self, action, passenger, ticket_type, accepted):
        self.entries.append((action, passenger, ticket_type, accepted))

    def rejected(self):
        return [entry for entry in self.entries if not entry[3]]

    def summary(self):
        lines = ["processed %d transaction(s)" % len(self.entries)]
        for action, passenger, ticket_type, _ in self.rejected():
            lines.append("  rejected: %s %s (%s)" % (action, passenger, ticket_type))
        return "\n".join(lines)


class Flight:
    ECONOMY_PRICE = 200
    FIRST_PRICE = 500
    UPGRADE_FEE = 300

    def __init__(self):
        self.economy = Cabin("economy", 50, self.ECONOMY_PRICE)
        self.first = Cabin("first", 10, self.FIRST_PRICE)
        self.revenue = 0
        self.paid = {}
        self.log = TransactionLog()

    def cabin_for(self, ticket_type):
        if ticket_type == "economy":
            return self.economy
        if ticket_type == "first":
            return self.first
        raise ValueError("unknown ticket type: %r" % (ticket_type,))

    def book_seat(self, passenger, ticket_type):
        cabin = self.cabin_for(ticket_type)
        if not cabin.add(passenger):
            return False
        self.revenue += cabin.price
        self.paid[passenger] = cabin.price
        return True

    def cancel_seat(self, passenger, ticket_type):
        cabin = self.cabin_for(ticket_type)
        if not cabin.remove(passenger):
            return False
        self.revenue -= self.paid.pop(passenger)
        return True

    def upgrade_seat(self, passenger):
        if not self.economy.holds(passenger) or self.first.available() == 0:
            return False
        self.economy.remove(passenger)
        self.first.add(passenger)
        self.revenue += self.UPGRADE_FEE
        self.paid[passenger] += self.UPGRADE_FEE
        return True

    def apply(self, action, passenger, ticket_type):
        if action == "book":
            return self.book_seat(passenger, ticket_type)
        if action == "cancel":
            return self.cancel_seat(passenger, ticket_type)
        if action == "upgrade":
            return self.upgrade_seat(passenger)
        raise ValueError("unknown action: %r" % (action,))

    def process_all(self, transactions):
        for transaction in transactions:
            if len(transaction) != 3:
                raise ValueError("malformed transaction: %r" % (transaction,))
            action, passenger, ticket_type = transaction
            self.log.record(action, passenger, ticket_type,
                            self.apply(action, passenger, ticket_type))
        return self


def book(transactions):
    flight = Flight().process_all(transactions)
    return flight.revenue, flight.economy.available()


def main():
    transactions = [
        ("book", "Ada", "economy"),
        ("book", "Grace", "first"),
        ("book", "Alan", "economy"),
        ("upgrade", "Alan", "economy"),
        ("cancel", "Ada", "economy"),
        ("upgrade", "Ada", "economy"),
    ]
    flight = Flight().process_all(transactions)
    print(flight.log.summary())
    print("revenue: %d, economy seats free: %d" % book(transactions))


if __name__ == "__main__":
    main()

