from collections import deque


class Parcel:
    def __init__(self, zip_code, weight):
        self.zip_code = str(zip_code).zfill(5)
        self.weight = float(weight)
        if len(self.zip_code) != 5 or not self.zip_code.isdigit():
            raise ValueError("zip code must be five digits: %r" % zip_code)
        if self.weight <= 0:
            raise ValueError("parcel weight must be positive: %r" % weight)

    def lead_digit(self):
        return int(self.zip_code[0])

    def __repr__(self):
        return "Parcel(%s, %g)" % (self.zip_code, self.weight)


class RegionalBin:
    def __init__(self, name, digits):
        self.name = name
        self.digits = set(digits)
        self.weight = 0.0
        self.count = 0

    def handles(self, parcel):
        return parcel.lead_digit() in self.digits

    def store(self, parcel):
        self.weight += parcel.weight
        self.count += 1


class SortingCenter:
    DAILY_LIMIT = 50.0

    def __init__(self):
        self.east = RegionalBin("east", range(0, 4))
        self.central = RegionalBin("central", range(4, 7))
        self.west = RegionalBin("west", range(7, 10))
        self.bins = [self.east, self.central, self.west]
        self.daily_weight = 0.0
        self.backlog = deque()

    def bin_for(self, parcel):
        for regional_bin in self.bins:
            if regional_bin.handles(parcel):
                return regional_bin
        raise ValueError("no bin serves %r" % parcel)

    def accept(self, parcel):
        if self.daily_weight + parcel.weight > self.DAILY_LIMIT:
            return False
        self.bin_for(parcel).store(parcel)
        self.daily_weight += parcel.weight
        return True

    def submit(self, parcel):
        if not self.accept(parcel):
            self.backlog.append(parcel)

    def new_day(self):
        self.daily_weight = 0.0
        while self.backlog and self.accept(self.backlog[0]):
            self.backlog.popleft()

    def totals(self):
        return (self.east.weight, self.central.weight, self.west.weight, len(self.backlog))


class ManifestReader:
    def __init__(self, text):
        self.lines = [line.strip() for line in text.strip().splitlines()]

    def parse_line(self, line):
        if line.lower() == "new day":
            return "new day"
        zip_code, weight = line.split()
        return (zip_code, float(weight))

    def entries(self):
        return [self.parse_line(line) for line in self.lines if line]


def process(parcels):
    center = SortingCenter()
    for item in parcels:
        if isinstance(item, tuple):
            center.submit(Parcel(*item))
        elif item is None or str(item).lower() == "new day":
            center.new_day()
        else:
            raise ValueError("unknown manifest entry: %r" % (item,))
    return center.totals()


MANIFEST = """
02134 20
45678 15
91101 18
07030 12
new day
12345 30
64106 25
98101 10
new day
33101 8
"""


def main():
    reader = ManifestReader(MANIFEST)
    east, central, west, held = process(reader.entries())
    print("east=%g central=%g west=%g backlog=%d" % (east, central, west, held))


if __name__ == "__main__":
