class Item:
    def __init__(self, kind, value):
        self.kind = kind
        self.value = int(value or 0)

    def is_equippable(self):
        return self.kind in ("weapon", "armor")

    def describe(self):
        return "%s worth %dg" % (self.kind, self.value)


class Inventory:
    def __init__(self, capacity=20):
        self.capacity = capacity
        self.items = []

    def is_full(self):
        return len(self.items) >= self.capacity

    def store(self, item):
        if self.is_full():
            return False
        self.items.append(item)
        return True

    def take(self, kind, value=None):
        for index, item in enumerate(self.items):
            if item.kind == kind and (value is None or item.value == value):
                return self.items.pop(index)
        return None

    def filled_slots(self):
        return len(self.items)

    def appraise(self):
        return sum(item.value for item in self.items)


class Character:
    def __init__(self, gold=0):
        self.gold = gold
        self.inventory = Inventory()
        self.equipped = {"weapon": None, "armor": None}
        self.discarded = 0

    def acquire(self, kind, value):
        if not self.inventory.store(Item(kind, value)):
            self.discarded += 1

    def sell(self, kind, value):
        item = self.inventory.take(kind, value)
        if item is not None:
            self.gold += item.value

    def drop(self, kind, value):
        self.inventory.take(kind, value)

    def equip(self, kind, value):
        item = self.inventory.take(kind, value)
        if item is None or not item.is_equippable():
            if item is not None:
                self.inventory.store(item)
            return
        previous = self.equipped[item.kind]
        self.equipped[item.kind] = item
        if previous is not None:
            self.inventory.store(previous)

    def perform(self, action, kind, value):
        handlers = {"add": self.acquire, "sell": self.sell,
                    "drop": self.drop, "equip": self.equip}
        handler = handlers.get(action)
        if handler is not None:
            handler(kind, value)

    def report(self):
        gear = [slot.describe() for slot in self.equipped.values() if slot]
        return ("gold=%d slots=%d/%d pack_value=%dg discarded=%d gear=[%s]"
                % (self.gold, self.inventory.filled_slots(), self.inventory.capacity,
                   self.inventory.appraise(), self.discarded, ", ".join(gear)))


def manage(actions):
    hero = Character()
    for action, kind, value in actions:
        hero.perform(action, kind, value)
    return hero.gold, hero.inventory.filled_slots()


def main():
    script = [("add", "weapon", 50), ("add", "armor", 30), ("add", "potion", 5),
              ("equip", "weapon", 50), ("equip", "armor", 30),
              ("add", "weapon", 90), ("equip", "weapon", 90),
              ("sell", "weapon", 50), ("drop", "potion", 5)]
    hero = Character()
    for action, kind, value in script:
        hero.perform(action, kind, value)
        print("%-6s %-7s -> %s" % (action, kind, hero.report()))
    print("manage() result:", manage(script))


if __name__ == "__main__":
    main()

