class Reservoir:
    def __init__(self, level=50.0):
        self.level = float(level)

    def add_rain(self, amount):
        self.level += amount
        return self.level

    def release(self, amount):
        drawn = min(amount, self.level)
        self.level -= drawn
        return drawn

    def above(self, threshold):
        return self.level > threshold

    def below(self, threshold):
        return self.level < threshold


class Spillway:
