    CLOSE_BELOW = 60.0
    DISCHARGE = 5.0

    def __init__(self, reservoir):
        self.reservoir = reservoir
        self.open = False

    def update(self):
        if self.reservoir.above(self.OPEN_ABOVE):
            self.open = True
        elif self.open and self.reservoir.below(self.CLOSE_BELOW):
            self.open = False
        return self.open

    def discharge(self):
        if not self.open:
            return 0.0
        return self.reservoir.release(self.DISCHARGE)


class TurbineHall:
    MIN_LEVEL = 40.0
    WATER_PER_HOUR = 2.0
    OUTPUT_MW = 10.0

    def __init__(self, reservoir):
        self.reservoir = reservoir
        self.total_power = 0.0

    def run_hour(self):
        if not self.reservoir.above(self.MIN_LEVEL):
            return 0.0
        self.reservoir.release(self.WATER_PER_HOUR)
        self.total_power += self.OUTPUT_MW
        return self.OUTPUT_MW


class HydroDam:
    def __init__(self, level=50.0):
        self.reservoir = Reservoir(level)
        self.spillway = Spillway(self.reservoir)
        self.turbines = TurbineHall(self.reservoir)
