class Gondola:
    def __init__(self, index, capacity=4):
        self.index = index
        self.capacity = capacity
        self.occupants = 0

    def free_seats(self):
        return self.capacity - self.occupants

    def board(self, people):
        accepted = min(people, self.free_seats())
        self.occupants += accepted
        return accepted, people - accepted

    def empty(self):
        leaving = self.occupants
        self.occupants = 0
        return leaving

    def describe(self):
        return "G{}[{}/{}]".format(self.index, self.occupants, self.capacity)


class ActionParser:
    def __init__(self):
        self.argument_free = {"rotate", "unload"}
        self.with_argument = {"load"}

    def parse(self, action):
        if isinstance(action, str):
            parts = action.split()
        else:
            parts = list(action)
        name = str(parts[0]).lower()
        if name in self.with_argument:
            return name, int(parts[1])
        if name in self.argument_free:
            return name, 0
        raise ValueError("unknown action: {!r}".format(action))


class FerrisWheel:
    def __init__(self, gondola_count=8, capacity=4):
        self.gondolas = [Gondola(i, capacity) for i in range(gondola_count)]
        self.bottom = 0
        self.revolutions = 0
        self.total_served = 0
        self.rejected = 0
        self.parser = ActionParser()

    def bottom_gondola(self):
        return self.gondolas[self.bottom]

    def load(self, people):
        accepted, turned_away = self.bottom_gondola().board(people)
        self.rejected += turned_away
        return accepted

    def rotate(self):
        self.bottom = (self.bottom + 1) % len(self.gondolas)
        if self.bottom == 0:
            self.revolutions += 1
        return self.bottom

    def unload(self):
        leaving = self.bottom_gondola().empty()
        self.total_served += leaving
        return leaving

    def apply(self, action):
        name, amount = self.parser.parse(action)
        if name == "load":
            return self.load(amount)
        if name == "rotate":
            return self.rotate()
        return self.unload()

    def run_actions(self, actions):
        for action in actions:
            self.apply(action)
        return self.total_served, self.revolutions

    def report(self):
        seats = " ".join(car.describe() for car in self.gondolas)
        return "bottom=G{} revolutions={} served={} rejected={}\n{}".format(
            self.bottom, self.revolutions, self.total_served, self.rejected, seats)


def run(actions):
    wheel = FerrisWheel()
    return wheel.run_actions(actions)


def main():
    script = ["load 6", "rotate", "load 4", "rotate", "load 2"]
    script += ["rotate"] * 6 + ["unload", "rotate", "unload"]
    wheel = FerrisWheel()
    served, revolutions = wheel.run_actions(script)
    print(wheel.report())
    print("run() ->", run(script))
    print("served {} people in {} revolution(s)".format(served, revolutions))


if __name__ == "__main__":
    main()

