class FuelTank:
    """Holds the fuel of the vehicle, in liters."""

    def __init__(self, level=50.0):
        self.level = float(level)

    def draw(self, liters):
        taken = min(liters, self.level)
        self.level -= taken
        return taken

    def is_empty(self):
        return self.level <= 0


class Engine:
    """Turns fuel into motion; shuts itself down when the tank runs dry."""

    def __init__(self, tank):
        self.tank = tank
        self.running = False

    def start(self):
        if not self.tank.is_empty():
            self.running = True

    def stop(self):
        self.running = False

    def burn(self, liters):
        self.tank.draw(liters)
        if self.tank.is_empty():
            self.stop()


class Vehicle:
    """Tracks speed in km/h, cumulative distance in km and fuel in liters."""

    def __init__(self):
        self.tank = FuelTank()
        self.engine = Engine(self.tank)
        self.speed = 0
        self.distance = 0.0
        self.commands = {
            "start": self.engine.start,
            "stop": self.stop,
            "accelerate": self.accelerate,
            "brake": self.brake,
            "cruise": self.cruise,
        }

    def stop(self):
        self.engine.stop()
        self.speed = 0

    def accelerate(self):
        if self.engine.running:
            self.speed += 10
            self.engine.burn(1)
            self.coast_if_stalled()

    def brake(self):
        if self.engine.running:
            self.speed = max(0, self.speed - 10)

    def cruise(self):
        if self.engine.running and self.speed > 0:
            self.distance += self.speed
            self.engine.burn(self.speed / 10)
            self.coast_if_stalled()

    def coast_if_stalled(self):
        if not self.engine.running:
            self.speed = 0

    def execute(self, command):
        action = self.commands.get(command)
        if action is None:
            raise ValueError("unknown dashboard command: {!r}".format(command))
        action()


class Dashboard:
    """Feeds driver commands to a vehicle and reads its instruments."""

    def __init__(self, vehicle):
        self.vehicle = vehicle

    def run(self, inputs):
        for command in inputs:
            self.vehicle.execute(command)
        return self.readout()

    def readout(self):
        return self.vehicle.distance, self.vehicle.tank.level


def drive(inputs):
    return Dashboard(Vehicle()).run(inputs)


def main():
    commands = ["start", "accelerate", "accelerate", "cruise", "cruise",
                "brake", "cruise", "stop"]
    distance, fuel = drive(commands)
    print("Distance travelled: {:.1f} km".format(distance))
    print("Fuel remaining: {:.1f} L".format(fuel))


if __name__ == "__main__":
    main()

