class Driver:
    def __init__(self, identifier, location):
        self.identifier = identifier
        self.location = location
        self.earnings = 0

    def distance_to(self, coordinate):
        return abs(self.location - coordinate)

    def bid(self, start):
        return (self.distance_to(start), self.identifier)

    def serve(self, start, destination):
        fare = abs(destination - start)
        self.location = destination
        self.earnings += fare
        return fare


class Dispatcher:
    def __init__(self, start_locations):
        self.drivers = [Driver(index, location)
                        for index, location in enumerate(start_locations)]
        self.trip_log = []

    def select_driver(self, start):
        return min(self.drivers, key=lambda driver: driver.bid(start))

    def handle(self, request):
        start, destination = self.validate(request)
        driver = self.select_driver(start)
        fare = driver.serve(start, destination)
        self.trip_log.append((driver.identifier, start, destination, fare))
        return driver

    def validate(self, request):
        if len(request) != 2:
            raise ValueError("each request needs a start and a destination")
        start, destination = request
        for coordinate in (start, destination):
            if not isinstance(coordinate, (int, float)):
                raise TypeError("coordinates must be numeric")
        return start, destination

    def run(self, requests):
        for request in requests:
            self.handle(request)
        return self.locations(), self.fares()

    def locations(self):
        return [driver.location for driver in self.drivers]

    def fares(self):
        return [driver.earnings for driver in self.drivers]

    def report(self):
        lines = []
        for identifier, start, destination, fare in self.trip_log:
            lines.append("driver %d: %s -> %s for %s"
                         % (identifier, start, destination, fare))
        for driver in self.drivers:
            lines.append("driver %d ends at %s with %s earned"
                         % (driver.identifier, driver.location, driver.earnings))
        return "\n".join(lines)


def dispatch(requests):
    dispatcher = Dispatcher([0, 10, 20])
    return dispatcher.run(requests)


def main():
    requests = [(5, 15), (12, 2), (25, 30), (0, 8)]
    dispatcher = Dispatcher([0, 10, 20])
    locations, fares = dispatcher.run(requests)
    print(dispatcher.report())
    print("final locations:", locations)
    print("total fares:", fares)


if __name__ == "__main__":
    main()

