class Account:
    TIER_COSTS = {"basic": 10, "premium": 20}
    AUTO_PAUSE_LIMIT = 50

    def __init__(self, tier="basic"):
        if tier not in self.TIER_COSTS:
            raise ValueError("unknown tier: %s" % tier)
        self.tier = tier
        self.status = "active"
        self.balance = 0

    def upgrade(self):
        self.tier = "premium"

    def downgrade(self):
        self.tier = "basic"

    def pause(self):
        self.status = "paused"

    def resume(self):
        self.status = "active"

    def is_active(self):
        return self.status == "active"

    def monthly_cost(self):
        return self.TIER_COSTS[self.tier]

    def pay(self, amount):
        if amount <= 0:
            raise ValueError("payment must be positive")
        self.balance = max(0, self.balance - amount)

    def apply_monthly_charge(self):
        if self.is_active():
            self.balance += self.monthly_cost()
            if self.balance > self.AUTO_PAUSE_LIMIT:
                self.pause()

    def snapshot(self):
        return self.balance, self.status


class EventParser:
    SIMPLE_ACTIONS = ("upgrade", "downgrade", "pause", "resume")

    def parse(self, event):
        if isinstance(event, (tuple, list)):
            action, amount = event[0], event[1] if len(event) > 1 else None
        else:
            parts = str(event).replace(":", " ").split()
            action, amount = parts[0], parts[1] if len(parts) > 1 else None
        action = action.strip().lower()
        return action, self.check(action, amount)

    def check(self, action, amount):
        if action == "pay":
            if amount is None:
                raise ValueError("payment amount missing")
            return float(amount)
        if action not in self.SIMPLE_ACTIONS:
            raise ValueError("unknown action: %s" % action)
        return None


class BillingSimulator:
    def __init__(self):
        self.account = Account()
        self.parser = EventParser()

    def dispatch(self, action, amount):
        if action == "pay":
            self.account.pay(amount)
        else:
            getattr(self.account, action)()

    def run(self, months):
        for events in months:
            for event in events:
                action, amount = self.parser.parse(event)
                self.dispatch(action, amount)
            self.account.apply_monthly_charge()
        return self.account.snapshot()


def bill(months):
    return BillingSimulator().run(months)


def main():
    scenarios = [
        ("steady basic", [[], [], ["pay 10"]]),
        ("upgrade then pay", [["upgrade"], ["pay:20"], []]),
        ("neglected premium", [["upgrade"], [], [], []]),
        ("pause and resume", [[], ["pause"], ["resume", ("pay", 5)]]),
    ]
    for name, months in scenarios:
        balance, status = bill(months)
        print("%-18s balance=%6.2f status=%s" % (name, balance, status))


if __name__ == "__main__":
    main()

