class Account:
    TIER_COSTS = {"basic": 10, "premium": 20}
    AUTO_PAUSE_LIMIT = 50

    def __init__(this, tier="basic"):
        if tier not in this.TIER_COSTS:
            raise ValueError("unknown tier: %s" % tier)
        this.tier = tier
        this.status = "active"
        this.balance = 0

    def upgrade(this):
        this.tier = "premium"

    def downgrade(this):
        this.tier = "basic"

    def pause(this):
        this.status = "paused"

    def resume(this):
        this.status = "active"

    def is_active(this):
        return this.status == "active"

    def monthly_cost(this):
        return this.TIER_COSTS[this.tier]

    def pay(this, amount):
        if amount <= 0:
            raise ValueError("payment must be positive")
        this.balance = max(0, this.balance - amount)

    def apply_monthly_charge(this):
        if this.is_active():
            this.balance += this.monthly_cost()
            if this.balance > this.AUTO_PAUSE_LIMIT:
                this.pause()

    def snapshot(this):
        return this.balance, this.status


class EventParser:
    SIMPLE_ACTIONS = ("upgrade", "downgrade", "pause", "resume")

    def parse(this, event):
        if isinstance(event, (tuple, list)):
            action, amount = event[0], event[1] if len(event) > 1 else None
        else:
            parts = str(event).replace(":", " ").split()
            action, amount = parts[0], parts[1] if len(parts) > 1 else None
        action = action.strip().lower()
        return action, this.check(action, amount)

    def check(this, action, amount):
        if action == "pay":
            if amount is None:
                raise ValueError("payment amount missing")
            return float(amount)
        if action not in this.SIMPLE_ACTIONS:
            raise ValueError("unknown action: %s" % action)
        return None


class BillingSimulator:
    def __init__(this):
        this.account = Account()
        this.parser = EventParser()

    def dispatch(this, action, amount):
        if action == "pay":
            this.account.pay(amount)
        else:
            getattr(this.account, action)()

    def run(this, months):
        for events in months:
            for event in events:
                action, amount = this.parser.parse(event)
                this.dispatch(action, amount)
            this.account.apply_monthly_charge()
        return this.account.snapshot()


def bill(months):
    return BillingSimulator().run(months)


def main():
    scenarios = [
        ("steady basic", [[], [], ["pay 10"]]),
        ("upgrade then pay", [["upgrade"], ["pay:20"], []]),
        ("neglected premium", [["upgrade"], [], [], []]),
        ("pause and resume", [[], ["pause"], ["resume", ("pay", 5)]]),
    ]
    for name, months in scenarios:
        balance, status = bill(months)
        print("%-18s balance=%6.2f status=%s" % (name, balance, status))


if __name__ == "__main__":
    main()

