class Track:
    def __init__(self, object_id, altitude, distance):
        self.object_id = object_id
        self.altitude = altitude
        self.distance = distance
        self.missed_scans = 0

    def update(self, altitude, distance):
        self.altitude = altitude
        self.distance = distance
        self.missed_scans = 0

    def threat_level(self):
        return self.altitude / self.distance

    def is_threatening(self):
        return self.threat_level() > 10

    def mark_missed(self):
        self.missed_scans += 1

    def is_lost(self):
        return self.missed_scans >= 3

    def describe(self):
        return "#{0}: alt={1} dist={2} threat={3:.2f} missed={4}".format(
            self.object_id, self.altitude, self.distance,
            self.threat_level(), self.missed_scans)


class RadarTracker:
    def __init__(self):
        self.tracks = {}
        self.alerts = 0

    def detect(self, object_id, altitude, distance):
        if distance <= 0:
            raise ValueError("distance to object {0} must be positive".format(object_id))
        track = self.tracks.get(object_id)
        if track is None:
            track = Track(object_id, altitude, distance)
            self.tracks[object_id] = track
        else:
            track.update(altitude, distance)
        if track.is_threatening():
            self.alerts += 1
        return track

    def age_unseen(self, seen_ids):
        for object_id, track in list(self.tracks.items()):
            if object_id in seen_ids:
                continue
            track.mark_missed()
            if track.is_lost():
                del self.tracks[object_id]

    def process_scan(self, detections):
        seen_ids = set()
        for object_id, altitude, distance in detections:
            self.detect(object_id, altitude, distance)
            seen_ids.add(object_id)
        self.age_unseen(seen_ids)

    def run(self, signals):
        for detections in signals:
            self.process_scan(detections)
        return self.alerts, len(self.tracks)

    def report(self):
        lines = ["alerts issued: {0}".format(self.alerts),
                 "tracked objects: {0}".format(len(self.tracks))]
        for object_id in sorted(self.tracks):
            lines.append("  " + self.tracks[object_id].describe())
        return "\n".join(lines)


def scan(signals):
    return RadarTracker().run(signals)


def main():
    signals = [
        [(1, 5000, 400), (2, 9000, 300)],
        [(1, 4800, 500), (3, 12000, 200)],
        [(3, 11000, 250)],
        [(3, 10500, 900)],
        [(3, 10000, 1000), (4, 800, 700)],
    ]
    tracker = RadarTracker()
    alerts, tracked = tracker.run(signals)
    print(tracker.report())
    print("scan() ->", (alerts, tracked), scan(signals))


if __name__ == "__main__":
    main()

