PRIMARY = "coin"
FEE = 1


class TransactionError(Exception):
    """Raised when an operation cannot be completed and must be abandoned."""


class Wallet:
    def __init__(self, primary_balance):
        self.primary = primary_balance
        self.tokens = {}

    def token_balance(self, name):
        return self.tokens.get(name, 0)

    def require_fee(self):
        if self.primary < FEE:
            raise TransactionError("primary balance cannot cover the network fee")

    def require_token(self, name, amount):
        held = self.token_balance(name)
        if held < amount:
            raise TransactionError("not enough %s to move %d" % (name, amount))

    def pay_fee(self):
        self.primary -= FEE

    def receive_primary(self, amount):
        self.primary += amount

    def receive_token(self, name, amount):
        held = self.token_balance(name)
        self.tokens[name] = held + amount

    def deduct_token(self, name, amount):
        held = self.token_balance(name)
        self.tokens[name] = held - amount

    def send_primary(self, amount):
        if self.primary < amount + FEE:
            raise TransactionError("primary balance cannot cover amount plus fee")
        self.primary -= amount + FEE

    def send_token(self, name, amount):
        self.require_fee()
        self.require_token(name, amount)
        self.pay_fee()
        self.deduct_token(name, amount)

    def swap_token(self, source, target, amount):
        self.require_fee()
        self.require_token(source, amount)
        self.pay_fee()
        self.deduct_token(source, amount)
        self.receive_token(target, amount)


class TransactionProcessor:
    def __init__(self, wallet):
        self.wallet = wallet
        self.log = []

    def dispatch(self, action, asset, amount, other):
        if action == "receive":
            if asset == PRIMARY:
                self.wallet.receive_primary(amount)
            else:
                self.wallet.receive_token(asset, amount)
        elif action == "send":
            if asset == PRIMARY:
                self.wallet.send_primary(amount)
            else:
                self.wallet.send_token(asset, amount)
        elif action == "swap":
            if other is None:
                raise TransactionError("swap requires a target asset")
            self.wallet.swap_token(asset, other, amount)
        else:
            raise TransactionError("unknown action %r" % (action,))

    def execute(self, operation):
        action, asset, amount = operation[0], operation[1], operation[2]
        other = operation[3] if len(operation) > 3 else None
        try:
            self.dispatch(action, asset, amount, other)
            status = "ok"
        except TransactionError as error:
            status = "failed: %s" % error
        self.log.append((action, asset, amount, other, status))

    def snapshot(self):
        wallet = self.wallet
        return wallet.primary, wallet.token_balance("star")

    def run(self, operations):
        for operation in operations:
            self.execute(operation)
        return self.snapshot()

    def report(self):
        lines = ["%-7s %-6s %4s -> %s" % (a, s, n, status)
                 for a, s, n, _o, status in self.log]
        primary, star = self.snapshot()
        lines.append("primary=%d star=%d" % (primary, star))
        return "\n".join(lines)


def transact(operations):
    initial_balance, steps = operations[0], operations[1:]
    processor = TransactionProcessor(Wallet(initial_balance))
    result = processor.run(steps)
    print(processor.report())
    return result


if __name__ == "__main__":
    print(transact([10,
                    ("receive", "star", 50),
                    ("send", "star", 20),
                    ("receive", "moon", 5),
                    ("swap", "moon", 5, "star"),
                    ("swap", "moon", 99, "star"),
                    ("send", "coin", 3)]))

