class BillInventory:
    DENOMINATIONS = (100, 50, 20)

    def __init__(self, initial_count=10):
        self.counts = {denomination: initial_count for denomination in self.DENOMINATIONS}

    def total_bills(self):
        return sum(self.counts.values())

    def knows(self, denomination):
        return denomination in self.counts

    def plan(self, amount):
        return self._search(amount, 0, {})

    def _search(self, amount, index, chosen):
        if amount == 0:
            return {d: n for d, n in chosen.items() if n}
        if index >= len(self.DENOMINATIONS):
            return None
        denomination = self.DENOMINATIONS[index]
        for take in range(min(self.counts[denomination], amount // denomination), -1, -1):
            chosen[denomination] = take
            found = self._search(amount - take * denomination, index + 1, chosen)
            if found is not None:
                return found
        del chosen[denomination]
        return None

    def take_out(self, plan):
        for denomination, count in plan.items():
            self.counts[denomination] -= count

    def put_in(self, bills):
        for bill in bills:
            self.counts[bill] += 1


class Account:
    def __init__(self, balance):
        self.balance = balance

    def can_cover(self, amount):
        return 0 < amount <= self.balance

    def debit(self, amount):
        self.balance -= amount

    def credit(self, amount):
        self.balance += amount


class CashMachine:
    def __init__(self, balance, inventory=None):
        self.account = Account(balance)
        self.inventory = BillInventory() if inventory is None else inventory
        self.log = []

    def withdraw(self, amount):
        if not self.account.can_cover(amount):
            self.log.append("withdraw %d rejected: insufficient balance" % amount)
            return False
        plan = self.inventory.plan(amount)
        if plan is None:
            self.log.append("withdraw %d rejected: no bill combination" % amount)
            return False
        self.inventory.take_out(plan)
        self.account.debit(amount)
        detail = ", ".join("%dx%d" % (count, d) for d, count in sorted(plan.items(), reverse=True))
        self.log.append("withdraw %d dispensed as %s" % (amount, detail))
        return True

    def deposit(self, bills):
        rejected = [bill for bill in bills if not self.inventory.knows(bill)]
        if rejected:
            self.log.append("deposit rejected: unsupported bills %s" % rejected)
            return False
        self.inventory.put_in(bills)
        self.account.credit(sum(bills))
        self.log.append("deposit accepted: %s" % bills)
        return True

    def perform(self, action, payload):
        if action == "withdraw":
            return self.withdraw(payload)
        if action == "deposit":
            return self.deposit(payload)
        raise ValueError("unknown action: %r" % action)

    def summary(self):
        return self.account.balance, self.inventory.total_bills()

    def report(self):
        return "\n".join(self.log)


def dispense(transactions):
    balance, actions = transactions
    machine = CashMachine(balance)
    for action, payload in actions:
        machine.perform(action, payload)
    print(machine.report())
    return machine.summary()


if __name__ == "__main__":
    print(dispense((1000, [("withdraw", 250), ("deposit", [50, 100, 100]), ("withdraw", 60),
                           ("withdraw", 5000), ("withdraw", 30), ("deposit", [10])])))

