class Deck:
    def __init__(self, cards=None):
        if cards is None:
            cards = range(1, 51)
        self.cards = list(cards)

    def is_empty(self):
        return not self.cards

    def draw(self):
        return self.cards.pop(0)

    def replace(self, cards):
        self.cards = list(cards)

    def remaining(self):
        return len(self.cards)


class DiscardPile:
    def __init__(self):
        self.cards = []

    def add(self, card):
        self.cards.append(card)

    def take_all(self):
        taken = self.cards
        self.cards = []
        return taken


class Hand:
    def __init__(self, capacity=5):
        self.capacity = capacity
        self.cards = []

    def is_full(self):
        return len(self.cards) >= self.capacity

    def is_empty(self):
        return not self.cards

    def add(self, card):
        self.cards.append(card)

    def remove_highest(self):
        highest = max(self.cards)
        self.cards.remove(highest)
        return highest


class Game:
    def __init__(self):
        self.deck = Deck()
        self.hand = Hand()
        self.discard = DiscardPile()
        self.score = 0

    def draw(self):
        if self.deck.is_empty():
            return
        card = self.deck.draw()
        if self.hand.is_full():
            self.discard.add(card)
        else:
            self.hand.add(card)

    def play_card(self):
        if self.hand.is_empty():
            return
        card = self.hand.remove_highest()
        self.score += card
        self.discard.add(card)

    def shuffle(self):
        if self.deck.is_empty():
            self.deck.replace(reversed(self.discard.take_all()))

    def apply(self, move):
        if move == "draw":
            self.draw()
        elif move == "play":
            self.play_card()
        elif move == "shuffle":
            self.shuffle()
        else:
            raise ValueError("unknown move: {!r}".format(move))

    def result(self):
        return self.score, self.deck.remaining()


def play(moves):
    game = Game()
    for move in moves:
        game.apply(move)
    return game.result()


def main():
    moves = ["draw"] * 7 + ["play", "play", "shuffle", "draw", "play"]
    score, remaining = play(moves)
    print("score: {}, cards left in deck: {}".format(score, remaining))


if __name__ == "__main__":
    main()

