    def is_empty(this):
        return not this.cards

    def draw(this):
        return this.cards.pop(0)

    def replace(this, cards):
        this.cards = list(cards)

    def remaining(this):
        return len(this.cards)


class DiscardPile:
    def __init__(this):
        this.cards = []

    def add(this, card):
        this.cards.append(card)

    def take_all(this):
        taken = this.cards
        this.cards = []
        return taken


class Hand:
    def __init__(this, capacity=5):
        this.capacity = capacity
        this.cards = []

    def is_full(this):
        return len(this.cards) >= this.capacity

    def is_empty(this):
        return not this.cards

    def add(this, card):
        this.cards.append(card)

    def remove_highest(this):
        highest = max(this.cards)
        this.cards.remove(highest)
        return highest


class Game:
    def __init__(this):
        this.deck = Deck()
        this.hand = Hand()
        this.discard = DiscardPile()
        this.score = 0

    def draw(this):
        if this.deck.is_empty():
            return
        card = this.deck.draw()
        if this.hand.is_full():
            this.discard.add(card)
        else:
            this.hand.add(card)

    def play_card(this):
        if this.hand.is_empty():
            return
        card = this.hand.remove_highest()
        this.score += card
        this.discard.add(card)

    def shuffle(this):
        if this.deck.is_empty():
            this.deck.replace(reversed(this.discard.take_all()))

    def apply(this, move):
        if move == "draw":
            this.draw()
        elif move == "play":
            this.play_card()
        elif move == "shuffle":
            this.shuffle()
        else:
            raise ValueError("unknown move: {!r}".format(move))

    def result(this):
        return this.score, this.deck.remaining()


def play(moves):
    game = Game()
    for move in moves:
        game.apply(move)
    return game.result()


def main():
    moves = ["draw"] * 7 + ["play", "play", "shuffle", "draw", "play"]
    score, remaining = play(moves)
    print("score: {}, cards left in deck: {}".format(score, remaining))


if __name__ == "__main__":
    main()

