class Compass:
    _ORDER = ("EAST", "SOUTH", "WEST", "NORTH")
    _DELTAS = {"EAST": (1, 0), "SOUTH": (0, -1), "WEST": (-1, 0), "NORTH": (0, 1)}

    def __init__(self, facing="EAST"):
        self._index = self._ORDER.index(facing)

    def facing(self):
        return self._ORDER[self._index]

    def turn_left(self):
        self._index = (self._index - 1) % len(self._ORDER)

    def turn_right(self):
        self._index = (self._index + 1) % len(self._ORDER)

    def delta(self):
        return self._DELTAS[self.facing()]


class Probe:
    def __init__(self, energy=20):
        self.x = 0
        self.y = 0
        self.energy = energy
        self.compass = Compass()
        self.discovered = []
        self.asleep = False

    def sector(self):
        return (self.x, self.y)

    def consume(self, amount):
        self.energy -= amount
        if self.energy <= 0:
            self.energy = 0
            self.asleep = True

    def move_forward(self):
        dx, dy = self.compass.delta()
        self.x += dx
        self.y += dy
        self.energy += 1
        self.consume(2)

    def turn_left(self):
        self.compass.turn_left()
        self.consume(1)

    def turn_right(self):
        self.compass.turn_right()
        self.consume(1)

    def scan(self):
        self.discovered.append(self.sector())
        self.consume(5)

    def wait(self):
        self.energy += 10
        self.asleep = False


class ProbeController:
