class Train:
    def __init__(self, destination, cars):
        if cars <= 0:
            raise ValueError("a train must have at least one car")
        self.destination = destination
        self.cars = cars

    def manifest(self):
        return "{} ({} cars)".format(self.destination, self.cars)


class HoldingTrack:
    def __init__(self, number, capacity):
        self.number = number
        self.capacity = capacity
        self.trains = []

    def occupied(self):
        return sum(train.cars for train in self.trains)

    def remaining_capacity(self):
        return self.capacity - self.occupied()

    def accept(self, train):
        if train.cars > self.remaining_capacity():
            return False
        self.trains.append(train)
        return True

    def dispatch(self):
        departing = self.trains
        self.trains = []
        return departing

    def describe(self):
        held = ", ".join(train.manifest() for train in self.trains) or "empty"
        return "track {} [{} free]: {}".format(self.number, self.remaining_capacity(), held)


class SwitchingYard:
    def __init__(self):
        self.tracks = {1: HoldingTrack(1, 20), 2: HoldingTrack(2, 30), 3: HoldingTrack(3, 10)}
        self.bypassed_cars = 0
        self.log = []

    def holding_track(self, number):
        if number not in self.tracks:
            raise ValueError("no holding track numbered {}".format(number))
        return self.tracks[number]

    def arrive(self, destination, cars, track_number):
        train = Train(destination, cars)
        track = self.holding_track(track_number)
        if track.accept(train):
            self.log.append("routed {} to track {}".format(train.manifest(), track.number))
        else:
            self.bypassed_cars += train.cars
            self.log.append("bypassed {}".format(train.manifest()))

    def dispatch(self, track_number):
        track = self.holding_track(track_number)
        departing = track.dispatch()
        self.log.append("dispatched {} train(s) from track {}".format(len(departing), track.number))

    def execute(self, instruction):
        kind = instruction[0]
        if kind == "arrive":
            self.arrive(instruction[1], instruction[2], instruction[3])
        elif kind == "dispatch":
            self.dispatch(instruction[1])
        else:
            raise ValueError("unknown instruction: {}".format(kind))

    def report(self):
        lines = list(self.log)
        lines.extend(self.holding_track(number).describe() for number in sorted(self.tracks))
        lines.append("bypass total: {} cars".format(self.bypassed_cars))
        return "\n".join(lines)


def route(instructions):
    yard = SwitchingYard()
    for instruction in instructions:
        yard.execute(instruction)
    return yard.bypassed_cars, yard.holding_track(2).remaining_capacity()


def main():
    yard = SwitchingYard()
    schedule = [
        ("arrive", "NORTH", 18, 1),
        ("arrive", "EAST", 25, 2),
        ("arrive", "WEST", 12, 3),
        ("arrive", "SOUTH", 8, 1),
        ("dispatch", 3),
        ("arrive", "SOUTH", 9, 3),
        ("arrive", "NORTH", 7, 2),
    ]
    for instruction in schedule:
        yard.execute(instruction)
    print(yard.report())
    print("route() ->", route(schedule))


if __name__ == "__main__":
    main()

