class Package:
    def __init__(self, destination, weight):
        self.destination = destination
        self.weight = weight

    def is_for(self, destination):
        return self.destination == destination

    def describe(self):
        return "{} ({} kg)".format(self.destination, self.weight)


class Truck:
    CAPACITY_KG = 5000
    TANK_GALLONS = 100

    def __init__(self):
        self.cargo = []
        self.fuel = self.TANK_GALLONS
        self.delivered_weight = 0
        self.left_at_depot = []
        self.towed = False

    def load_weight(self):
        return sum(package.weight for package in self.cargo)

    def can_load(self, weight):
        return self.load_weight() + weight <= self.CAPACITY_KG

    def load(self, package):
        if not self.can_load(package.weight):
            self.left_at_depot.append(package)
            return False
        self.cargo.append(package)
        return True

    def travel_to(self, destination, distance):
        if distance > self.fuel:
            self.towed = True
            return False
        self.fuel -= distance
        self.unload(destination)
        return True

    def unload(self, destination):
        staying = []
        for package in self.cargo:
            if package.is_for(destination):
                self.delivered_weight += package.weight
            else:
                staying.append(package)
        self.cargo = staying


class Dispatcher:
    def __init__(self, manifest):
        self.manifest = manifest
        self.truck = Truck()
        self.events = []

    def run(self):
        for action in self.manifest:
            if self.truck.towed:
                break
            self.handle(action)
        return self.truck.delivered_weight, self.truck.fuel

    def handle(self, action):
        destination = action["destination"]
        if "weight" in action:
            package = Package(destination, action["weight"])
            if self.truck.load(package):
                self.events.append("loaded " + package.describe())
            else:
                self.events.append("left at depot " + package.describe())
        else:
            distance = action["distance"]
            if self.truck.travel_to(destination, distance):
                self.events.append("arrived at {} after {} miles".format(destination, distance))
            else:
                self.events.append("out of fuel before {}; tow called".format(destination))

    def report(self):
        lines = list(self.events)
        lines.append("delivered {} kg, fuel left {} gal".format(
            self.truck.delivered_weight, self.truck.fuel))
        return "\n".join(lines)


def deliver(manifest):
    return Dispatcher(manifest).run()


def main():
    manifest = [
        {"destination": "Reno", "weight": 2000},
        {"destination": "Boise", "weight": 2500},
        {"destination": "Reno", "weight": 900},
        {"destination": "Reno", "distance": 40},
        {"destination": "Boise", "weight": 1500},
        {"destination": "Boise", "distance": 55},
        {"destination": "Fargo", "distance": 30},
    ]
    dispatcher = Dispatcher(manifest)
    weight, fuel = dispatcher.run()
    print(dispatcher.report())
    print("deliver() ->", (weight, fuel))


if __name__ == "__main__":
    main()

