class Room:
    def __init__(self, name, capacity):
        self.name = name
        self.capacity = capacity

    def can_admit(self, group_size):
        return group_size <= self.capacity

    def describe(self):
        if self.capacity is None:
            return "%s (unlimited)" % self.name
        return "%s (max %d)" % (self.name, self.capacity)


class Lobby(Room):
    def __init__(self):
        Room.__init__(self, "lobby", None)

    def can_admit(self, group_size):
        return True


class TourGroup:
    def __init__(self):
        self.size = 0

    def join(self, count):
        if count < 0:
            raise ValueError("cannot join a negative number of visitors")
        self.size += count
        return self.size

    def leave(self, count):
        if count < 0:
            raise ValueError("cannot remove a negative number of visitors")
        if count > self.size:
            raise ValueError("cannot remove more visitors than are present")
        self.size -= count
        return self.size


class TourGuide:
    def __init__(self):
        self.rooms = {room.name: room for room in
                      (Lobby(),
                       Room("ancient history hall", 20),
                       Room("art gallery", 15),
                       Room("science wing", 30))}
        self.group = TourGroup()
        self.current_room = self.rooms["lobby"]
        self.tips = 0
        self.log = []

    def lookup(self, name):
        if name not in self.rooms:
            raise KeyError("unknown room: %s" % name)
        return self.rooms[name]

    def admit_visitors(self, count):
        self.group.join(count)
        self.log.append("%d joined, group is now %d" % (count, self.group.size))

    def release_visitors(self, count):
        self.group.leave(count)
        self.log.append("%d left, group is now %d" % (count, self.group.size))

    def move_to(self, name):
        target = self.lookup(name)
        if not target.can_admit(self.group.size):
            self.log.append("waiting in %s: %d cannot fit in %s"
                            % (self.current_room.name, self.group.size, target.describe()))
            return False
        self.current_room = target
        self.tips += self.group.size
        self.log.append("entered %s, earned $%d (total $%d)"
                        % (target.name, self.group.size, self.tips))
        return True

    def handle(self, event):
        action, value = event
        if action == "join":
            self.admit_visitors(value)
        elif action == "leave":
            self.release_visitors(value)
        elif action == "move":
            self.move_to(value)
        else:
            raise ValueError("unknown event: %s" % action)

    def report(self):
        return "\n".join(self.log)


def tour(events):
    guide = TourGuide()
    for event in events:
        guide.handle(event)
    return guide.tips, guide.current_room.name


def main():
    events = [("join", 10), ("move", "ancient history hall"), ("join", 12),
              ("move", "art gallery"), ("leave", 7), ("move", "art gallery"),
              ("move", "science wing")]
    guide = TourGuide()
    for event in events:
        guide.handle(event)
    print(guide.report())
    print("tour() result: %s" % (tour(events),))


if __name__ == "__main__":
    main()

