        Room.__init__(this, "lobby", None)

    def can_admit(this, group_size):
        return True


class TourGroup:
    def __init__(this):
        this.size = 0

    def join(this, count):
        if count < 0:
            raise ValueError("cannot join a negative number of visitors")
        this.size += count
        return this.size

    def leave(this, count):
        if count < 0:
            raise ValueError("cannot remove a negative number of visitors")
        if count > this.size:
            raise ValueError("cannot remove more visitors than are present")
        this.size -= count
        return this.size


class TourGuide:
    def __init__(this):
        this.rooms = {room.name: room for room in
                      (Lobby(),
                       Room("ancient history hall", 20),
                       Room("art gallery", 15),
                       Room("science wing", 30))}
        this.group = TourGroup()
        this.current_room = this.rooms["lobby"]
        this.tips = 0
        this.log = []

    def lookup(this, name):
        if name not in this.rooms:
            raise KeyError("unknown room: %s" % name)
        return this.rooms[name]

    def admit_visitors(this, count):
        this.group.join(count)
        this.log.append("%d joined, group is now %d" % (count, this.group.size))

    def release_visitors(this, count):
        this.group.leave(count)
        this.log.append("%d left, group is now %d" % (count, this.group.size))

    def move_to(this, name):
        target = this.lookup(name)
        if not target.can_admit(this.group.size):
            this.log.append("waiting in %s: %d cannot fit in %s"
                            % (this.current_room.name, this.group.size, target.describe()))
            return False
        this.current_room = target
        this.tips += this.group.size
        this.log.append("entered %s, earned $%d (total $%d)"
                        % (target.name, this.group.size, this.tips))
        return True

    def handle(this, event):
        action, value = event
        if action == "join":
            this.admit_visitors(value)
        elif action == "leave":
            this.release_visitors(value)
        elif action == "move":
            this.move_to(value)
        else:
            raise ValueError("unknown event: %s" % action)

    def report(this):
        return "\n".join(this.log)


def tour(events):
    guide = TourGuide()
    for event in events:
        guide.handle(event)
    return guide.tips, guide.current_room.name


def main():
    events = [("join", 10), ("move", "ancient history hall"), ("join", 12),
              ("move", "art gallery"), ("leave", 7), ("move", "art gallery"),
              ("move", "science wing")]
    guide = TourGuide()
    for event in events:
        guide.handle(event)
    print(guide.report())
    print("tour() result: %s" % (tour(events),))


if __name__ == "__main__":
    main()

