CAPACITY = 40
TRIP_MINUTES = 15


class Station:
    def __init__(self, name):
        self.name = name
        self.queue = 0

    def arrive(self, people):
        if people < 0:
            raise ValueError("cannot have a negative number of arrivals at " + self.name)
        self.queue += people
        return self.queue

    def board(self, capacity):
        boarded = min(self.queue, capacity)
        self.queue -= boarded
        return boarded

    def waiting(self):
        return self.queue


class CableCar:
    def __init__(self, stations, position, capacity=CAPACITY):
        self.stations = stations
        self.position = position
        self.capacity = capacity
        self.onboard = 0
        self.delivered = 0

    def current_station(self):
        return self.stations[self.position]

    def other_position(self):
        return "summit" if self.position == "base" else "base"

    def dispatch(self):
        self.onboard = self.current_station().board(self.capacity)
        self.position = self.other_position()
        arrived = self.onboard
        self.onboard = 0
        self.delivered += arrived
        return arrived


class CableCarSystem:
    def __init__(self):
        self.stations = {"base": Station("base"), "summit": Station("summit")}
        self.car = CableCar(self.stations, "base")
        self.clock = 0

    def handle(self, event):
        kind = event[0]
        if kind == "arrive":
            station = self.stations.get(event[1])
            if station is None:
                raise ValueError("unknown station: " + str(event[1]))
            station.arrive(event[2])
        elif kind == "dispatch":
            self.car.dispatch()
            self.clock += TRIP_MINUTES
        else:
            raise ValueError("unknown event: " + str(kind))

    def run(self, schedule):
        for event in schedule:
            self.handle(event)
        return self.report()

    def report(self):
        return self.car.delivered, self.stations["base"].waiting()

    def summary(self):
        transported, waiting = self.report()
        return "t={}min car at {}: {} transported, {} waiting at base".format(
            self.clock, self.car.position, transported, waiting)


def transport(schedule):
    return CableCarSystem().run(schedule)


def main():
    system = CableCarSystem()
    system.run([
        ("arrive", "base", 55),
        ("dispatch",),
        ("arrive", "summit", 10),
        ("dispatch",),
        ("dispatch",),
    ])
    print(system.summary())
    print(transport([("arrive", "base", 12), ("dispatch",)]))


if __name__ == "__main__":
    main()

