class Player:
    def __init__(self, color):
        self.color = color
        self.reserve = 10

    def withdraw(self, amount):
        taken = min(amount, self.reserve)
        self.reserve -= taken
        return taken


class Zone:
    def __init__(self, index):
        self.index = index
        self.garrison = {"black": 0, "white": 0}

    def count(self, color):
        return self.garrison[color]

    def add(self, color, amount):
        self.garrison[color] += amount

    def clear(self, color):
        lost = self.garrison[color]
        self.garrison[color] = 0
        return lost

    def resolve_attack(self, attacker, defender):
        force = self.count(attacker)
        held = self.count(defender)
        if force > held:
            self.clear(defender)
            self.garrison[attacker] = force - force // 2
            return True
        self.clear(attacker)
        return False

    def describe(self):
        return "zone {}: black {}, white {}".format(
            self.index, self.count("black"), self.count("white"))


class Game:
    COLORS = ("black", "white")

    def __init__(self, zone_count=5):
        self.players = {color: Player(color) for color in self.COLORS}
        self.zones = [Zone(i) for i in range(zone_count)]
        self.log = []

    def player(self, color):
        if color not in self.players:
            raise ValueError("unknown player colour: {!r}".format(color))
        return self.players[color]

    def zone_at(self, index):
        if not isinstance(index, int) or not 0 <= index < len(self.zones):
            raise ValueError("no such zone: {!r}".format(index))
        return self.zones[index]

    def opponent(self, color):
        self.player(color)
        return self.COLORS[0] if color == self.COLORS[1] else self.COLORS[1]

    def deploy(self, color, index, amount):
        if not isinstance(amount, int) or amount < 0:
            raise ValueError("invalid deploy amount: {!r}".format(amount))
        moved = self.player(color).withdraw(amount)
        self.zone_at(index).add(color, moved)
        self.log.append("{} deployed {} piece(s) to zone {}".format(color, moved, index))
        return moved

    def attack(self, color, index):
        won = self.zone_at(index).resolve_attack(color, self.opponent(color))
        outcome = "overran" if won else "was wiped out in"
        self.log.append("{} {} zone {}".format(color, outcome, index))
        return won

    def apply_turn(self, turn):
        color, action, index, amount = turn
        if action == "deploy":
            return self.deploy(color, index, amount)
        if action == "attack":
            return self.attack(color, index)
        raise ValueError("unknown action: {!r}".format(action))

    def play(self, turns):
        for turn in turns:
            self.apply_turn(turn)
        return self.totals()

    def totals(self):
        return tuple(sum(zone.count(color) for zone in self.zones) for color in self.COLORS)

    def report(self):
        lines = list(self.log)
        lines.extend(zone.describe() for zone in self.zones)
        lines.append("reserves: black {}, white {}".format(
            self.player("black").reserve, self.player("white").reserve))
        lines.append("board totals: black {}, white {}".format(*self.totals()))
        return "\n".join(lines)


def battle(turns):
    return Game().play(turns)


def main():
    turns = [
        ("black", "deploy", 0, 6),
        ("white", "deploy", 0, 4),
        ("black", "attack", 0, 0),
        ("white", "deploy", 2, 5),
        ("black", "deploy", 2, 3),
        ("black", "attack", 2, 0),
        ("white", "deploy", 4, 1),
    ]
    game = Game()
    game.play(turns)
    print(game.report())
    print("battle() ->", battle(turns))


if __name__ == "__main__":
    main()

