class Animal:
    """An animal that eats, moves, and starves after three cycles without food."""

    STARVATION_LIMIT = 3

    def __init__(self, symbol, energy_gain):
        self.symbol = symbol
        self.energy_gain = energy_gain
        self.energy = 0
        self.cycles_since_meal = 0
        self.fed_this_cycle = False

    def eat(self):
        self.energy += self.energy_gain
        self.cycles_since_meal = 0
        self.fed_this_cycle = True

    def grow_hungrier(self):
        if self.fed_this_cycle:
            self.fed_this_cycle = False
            return False
        self.cycles_since_meal += 1
        return self.cycles_since_meal >= self.STARVATION_LIMIT

    def can_eat(self, occupant):
        raise NotImplementedError


class Herbivore(Animal):
    def __init__(self):
        super().__init__('H', 1)

    def can_eat(self, occupant):
        return occupant == 'plant'


class Carnivore(Animal):
    def __init__(self):
        super().__init__('C', 2)

    def can_eat(self, occupant):
        return isinstance(occupant, Herbivore)


class Ecosystem:
    SIZE = 10
    PLANT_INTERVAL = 3

    def __init__(self, placements):
        self.cells = [None] * self.SIZE
        self.cycle = 0
        for index, kind in placements:
            self.place(index, kind)

    def place(self, index, kind):
        if not 0 <= index < self.SIZE:
            raise IndexError("placement %d is outside the grid" % index)
        factories = {'plant': lambda: 'plant', 'herbivore': Herbivore, 'carnivore': Carnivore}
        if kind not in factories:
            raise ValueError("unknown entity type %r" % kind)
        self.cells[index] = factories[kind]()

    def neighbours(self, index):
        return [j for j in (index - 1, index + 1) if 0 <= j < self.SIZE]

    def animal_positions(self):
        return [i for i, cell in enumerate(self.cells) if isinstance(cell, Animal)]

    def act(self, index):
        animal = self.cells[index]
        for target in self.neighbours(index):
            if animal.can_eat(self.cells[target]):
                animal.eat()
                self.cells[target] = animal
                self.cells[index] = None
                return target
        for target in self.neighbours(index):
            if self.cells[target] is None:
                self.cells[target] = animal
                self.cells[index] = None
                return target
        return index

    def remove_starved(self):
        for index in self.animal_positions():
            if self.cells[index].grow_hungrier():
                self.cells[index] = None

    def grow_plants(self):
        for index, cell in enumerate(self.cells):
            if cell is None:
                self.cells[index] = 'plant'

    def run_cycle(self):
        self.cycle += 1
        already_acted = set()
        for index in self.animal_positions():
            if index not in already_acted:
                already_acted.add(self.act(index))
        self.remove_starved()
        if self.cycle % self.PLANT_INTERVAL == 0:
            self.grow_plants()

    def census(self):
        herbivores = sum(1 for cell in self.cells if isinstance(cell, Herbivore))
        carnivores = sum(1 for cell in self.cells if isinstance(cell, Carnivore))
        return {'herbivores': herbivores, 'carnivores': carnivores}

    def render(self):
        return ''.join('.' if cell is None else 'p' if cell == 'plant' else cell.symbol
                       for cell in self.cells)


DEFAULT_PLACEMENTS = [(0, 'plant'), (1, 'herbivore'), (3, 'plant'),
                      (4, 'herbivore'), (6, 'carnivore'), (8, 'plant')]


def simulate(cycles, placements=DEFAULT_PLACEMENTS):
    world = Ecosystem(placements)
    for _ in range(cycles):
        world.run_cycle()
        print("cycle %2d: %s" % (world.cycle, world.render()))
    return world.census()


def main():
    survivors = simulate(9)
    print("survivors: %d herbivores, %d carnivores"
          % (survivors['herbivores'], survivors['carnivores']))


if __name__ == '__main__':
    main()

