class AccessLog:
    """Chronological record of everything that happened at the front desk."""

    def __init__(self):
        self.entries = []

    def record(self, kind, detail):
        self.entries.append((kind, detail))

    def count(self, kind):
        return sum(1 for entry_kind, _ in self.entries if entry_kind == kind)

    def summary(self):
        lines = ["%d. %s: %s" % (i, kind, detail)
                 for i, (kind, detail) in enumerate(self.entries, 1)]
        lines.append("visits=%d denials=%d" % (self.count("visit"), self.count("denied")))
        return "\n".join(lines)


class Member:
    """A single member's access rights, guest passes and outstanding balance."""

    BALANCE_LIMIT = 50
    GUEST_FEE = 20

    def __init__(self, status="active", guest_passes=5, balance=0):
        self.status = status
        self.guest_passes = guest_passes
        self.balance = balance
        self.log = AccessLog()

    def denial_reason(self):
        if self.balance > self.BALANCE_LIMIT:
            return "balance %s over limit" % self.balance
        if self.status != "active":
            return "status is %s" % self.status
        return None

    def check_in(self):
        reason = self.denial_reason()
        if reason is not None:
            self.log.record("denied", reason)
            return False
        self.log.record("visit", "balance %s" % self.balance)
        return True

    def add_charge(self, amount):
        if amount < 0:
            raise ValueError("charge must not be negative")
        self.balance += amount
        self.log.record("charge", "+%s" % amount)

