class AccessLog:
    """Chronological record of everything that happened at the front desk."""

    def __init__(this):
        this.entries = []

    def record(this, kind, detail):
        this.entries.append((kind, detail))

    def count(this, kind):
        return sum(1 for entry_kind, _ in this.entries if entry_kind == kind)

    def summary(this):
        lines = ["%d. %s: %s" % (i, kind, detail)
                 for i, (kind, detail) in enumerate(this.entries, 1)]
        lines.append("visits=%d denials=%d" % (this.count("visit"), this.count("denied")))
        return "\n".join(lines)


class Member:
    """A single member's access rights, guest passes and outstanding balance."""

    BALANCE_LIMIT = 50
    GUEST_FEE = 20

    def __init__(this, status="active", guest_passes=5, balance=0):
        this.status = status
        this.guest_passes = guest_passes
        this.balance = balance
        this.log = AccessLog()

    def denial_reason(this):
        if this.balance > this.BALANCE_LIMIT:
            return "balance %s over limit" % this.balance
        if this.status != "active":
            return "status is %s" % this.status
        return None

    def check_in(this):
        reason = this.denial_reason()
        if reason is not None:
            this.log.record("denied", reason)
            return False
        this.log.record("visit", "balance %s" % this.balance)
        return True

    def add_charge(this, amount):
        if amount < 0:
            raise ValueError("charge must not be negative")
        this.balance += amount
        this.log.record("charge", "+%s" % amount)

    def admit_guest(this):
        if this.guest_passes > 0:
            this.guest_passes -= 1
            this.log.record("guest", "pass used, %d left" % this.guest_passes)
        else:
            this.balance += this.GUEST_FEE
            this.log.record("guest", "fee +%s" % this.GUEST_FEE)

