class CycleProfile:
    """Water temperature and drum speed required by a fabric type."""

    SETTINGS = {
        "delicates": ("cold", 400, 30),
        "synthetics": ("warm", 800, 45),
        "cotton": ("hot", 1200, 60),
    }

    def __init__(self, fabric):
        if fabric not in self.SETTINGS:
            raise ValueError("unknown fabric: {}".format(fabric))
        self.fabric = fabric
        self.temperature, self.speed, self.duration = self.SETTINGS[fabric]

    def runtime(self, minutes):
        if minutes is None:
            return self.duration
        if minutes <= 0:
            raise ValueError("cycle length must be positive")
        return minutes


class Washer:
    MAX_DETERGENT = 30

    def __init__(self):
        self.door_locked = False
        self.water = "off"
        self.detergent = 0
        self.speed = 0
        self.minutes_left = 0

    def state(self):
        return {
            "detergent": self.detergent,
            "door_locked": self.door_locked,
            "water": self.water,
            "speed": self.speed,
            "minutes_left": self.minutes_left,
        }

    def add_detergent(self, ounces):
        if ounces < 0:
            raise ValueError("cannot add negative detergent")
        self.detergent = min(self.MAX_DETERGENT, self.detergent + ounces)
        return self.state()

    def set_cycle(self, fabric, minutes=None):
        profile = CycleProfile(fabric)
        self.door_locked = True
        self.water = profile.temperature
        self.speed = profile.speed
        self.minutes_left = profile.runtime(minutes)
        return self.state()

    def advance_timer(self, minutes):
        self.minutes_left = max(0, self.minutes_left - minutes)
        if self.minutes_left == 0:
            self.speed = 0
            self.water = "off"
            self.door_locked = False
        return self.state()


class WashController:
    def __init__(self):
        self.washer = Washer()
        self.log = []

    def execute(self, instruction):
        action, args = instruction[0], tuple(instruction[1:])
        if action == "detergent":
            state = self.washer.add_detergent(*args)
        elif action == "cycle":
            state = self.washer.set_cycle(*args)
        elif action == "tick":
            state = self.washer.advance_timer(*args)
        else:
            raise ValueError("unknown instruction: {}".format(action))
        self.log.append(state)
        return state

    def run(self, cycles):
        for instruction in cycles:
            self.execute(instruction)
        return self.log


def wash(cycles):
    return WashController().run(cycles)


def main():
    program = [
        ("detergent", 10),
        ("cycle", "synthetics"),
        ("tick", 20),
        ("detergent", 25),
        ("tick", 25),
    ]
    for step, state in zip(program, wash(program)):
        print(step, "->", state)


if __name__ == "__main__":
    main()

