class DamageReport:
    def __init__(self, deposit):
        self.initial_deposit = deposit
        self.forfeited = False
        self.notice = ""

    def forfeit(self, occupant):
        self.forfeited = True
        self.notice = "Eviction notice served to {}".format(occupant)
        return self.initial_deposit

    def remaining_deposit(self):
        if self.forfeited:
            return 0
        return self.initial_deposit

    def status_text(self):
        if self.forfeited:
            return "a forfeited deposit"
        return "a full deposit of ${}".format(self.initial_deposit)


class Campsite:
    def __init__(self, deposit=150):
        self.standard_deposit = deposit
        self.occupant = "nobody"
        self.nights = 0
        self.fire_pit = False
        self.report = DamageReport(deposit)

    def book(self, camper, nights):
        self.occupant = camper
        self.nights = nights
        self.report = DamageReport(self.standard_deposit)
        self.fire_pit = False
        return self.occupant

    def rent_fire_pit(self):
        self.fire_pit = True
        return self.fire_pit

    def extend(self, extra_nights):
        self.nights += extra_nights
        return self.nights

    def flag_damage(self):
        lost = self.report.forfeit(self.occupant)
        self.nights = 0
        return lost

    def summary(self):
        if self.nights == 0 and self.report.forfeited:
            return "Site vacated by {}; {}.".format(self.occupant, self.report.notice)
        if self.nights == 0:
            return "Site is unoccupied with {}.".format(self.report.status_text())
        return "Site is occupied by {} for {} nights with {}.".format(
            self.occupant, self.nights, self.report.status_text())


class RequestRunner:
    def __init__(self, campsite):
        self.campsite = campsite
        self.handlers = {
            "book": self.do_book,
            "firepit": self.do_firepit,
            "extend": self.do_extend,
            "damage": self.do_damage,
        }

    def do_book(self, args):
        return self.campsite.book(args[0], int(args[1]))

    def do_firepit(self, args):
        return self.campsite.rent_fire_pit()

    def do_extend(self, args):
        return self.campsite.extend(int(args[0]))

    def do_damage(self, args):
        return self.campsite.flag_damage()

    def run(self, request):
        parts = request.split()
        if not parts:
            raise ValueError("empty request")
        verb = parts[0].lower()
        if verb not in self.handlers:
            raise ValueError("unknown request: " + verb)
        return self.handlers[verb](parts[1:])

    def run_all(self, requests):
        for request in requests:
            self.run(request)
        return self.campsite.summary()


def manage(requests):
    site = Campsite()
    return RequestRunner(site).run_all(requests)


if __name__ == "__main__":
    print(manage(["book Rowan 3", "firepit", "extend 2"]))
    print(manage(["book Maya 4", "damage"]))

