class MaterialLibrary:
    AMBIENT = 25.0

    def __init__(self):
        self.melting_points = {"PLA": 200.0, "ABS": 230.0, "PETG": 240.0, "TPU": 220.0}
        self.flow_rates = {"PLA": 0.42, "ABS": 0.47, "PETG": 0.51, "TPU": 0.38}

    def is_known(self, material):
        return material in self.melting_points

    def melting_point(self, material):
        if not self.is_known(material):
            raise ValueError("unknown filament material: %r" % (material,))
        return self.melting_points[material]

    def flow_rate(self, material):
        if not self.is_known(material):
            raise ValueError("unknown filament material: %r" % (material,))
        return self.flow_rates[material]


class Nozzle:
    def __init__(self, library, material="PLA"):
        self.library = library
        self.temperature = MaterialLibrary.AMBIENT
        self.material = material
        self.position = 0.0
        self.extruded = 0.0

    def load(self, material):
        if not self.library.is_known(material):
            raise ValueError("cannot load %r" % (material,))
        self.material = material

    def heat(self):
        self.temperature = self.library.melting_point(self.material)

    def cool(self):
        self.temperature = MaterialLibrary.AMBIENT

    def is_molten(self):
        return self.temperature >= self.library.melting_point(self.material)

    def move(self, distance):
        self.position += distance
        if self.is_molten():
            self.extruded += abs(distance) * self.library.flow_rate(self.material)

    def state(self):
        return (self.temperature, self.position, self.extruded)


class PrintJob:
    def __init__(self, commands):
        self.commands = commands
        self.nozzle = Nozzle(MaterialLibrary())

    def apply(self, command):
        action = command[0]
        if action == "material":
            self.nozzle.load(command[1])
        elif action == "heat":
            self.nozzle.heat()
        elif action == "move":
            self.nozzle.move(float(command[1]))
        elif action == "cool":
            self.nozzle.cool()
        else:
            raise ValueError("unsupported command: %r" % (action,))

    def run(self):
        for command in self.commands:
            self.apply(command)
        return self.nozzle.state()

    def report(self):
        temperature, position, extruded = self.run()
        return "%s: %.1fC at x=%.1f, extruded %.2f mm3" % (
            self.nozzle.material, temperature, position, extruded)


def fabricate(commands):
    return PrintJob(commands).run()


def main():
    script = [("material", "PETG"), ("heat",), ("move", 10), ("move", -4), ("cool",), ("move", 3)]
    print(fabricate(script))
    print(PrintJob(script).report())


if __name__ == "__main__":
    main()

