class PlasmaCooler:
    TARGET_TEMPERATURE = -20.0
    TEMPERATURE_LIMIT = -10.0
    DOOR_LIMIT_MINUTES = 5.0

    def __init__(self, temperature=TARGET_TEMPERATURE):
        self.temperature = float(temperature)
        self.inventory = 0
        self.buzzer_active = False
        self.door_open_minutes = 0.0

    def insert(self, bags):
        count = int(bags)
        if count < 0:
            raise ValueError("cannot insert a negative number of plasma bags")
        self.inventory += count
        self.temperature += 2.0
        return self.inventory

    def open_door(self, minutes):
        duration = float(minutes)
        if duration < 0:
            raise ValueError("door duration cannot be negative")
        self.door_open_minutes += duration
        return self.door_open_minutes

    def remove(self, bags):
        count = int(bags)
        if count > self.inventory:
            raise ValueError("not enough plasma bags in the cooler")
        self.inventory -= count
        return self.inventory

    def monitor(self):
        too_warm = self.temperature > self.TEMPERATURE_LIMIT
        door_too_long = self.door_open_minutes > self.DOOR_LIMIT_MINUTES
        if too_warm or door_too_long:
            self.buzzer_active = True
        return self.buzzer_active

    def maintain(self):
        self.buzzer_active = False
        self.temperature = self.TARGET_TEMPERATURE
        self.door_open_minutes = 0.0
        return self.temperature


class CoolerController:
    def __init__(self, cooler):
        self.cooler = cooler
        self.handlers = {
            "insert": self.cooler.insert,
            "remove": self.cooler.remove,
            "door": self.cooler.open_door,
        }

    def apply(self, event):
        kind, value = self.normalize(event)
        if kind in self.handlers:
            self.handlers[kind](value)
            self.cooler.monitor()
        elif kind == "monitor":
            self.cooler.monitor()
        elif kind == "maintain":
            self.cooler.maintain()
        else:
            raise ValueError("unknown event type: %r" % (kind,))
        return self.cooler

    def normalize(self, event):
        if isinstance(event, str):
            parts = event.split()
            kind = parts[0]
            value = float(parts[1]) if len(parts) > 1 else 0.0
        else:
            kind, value = event
        return str(kind).strip().lower(), value

    def run(self, events):
        for event in events:
            self.apply(event)
        return self.summary()

