class PlasmaCooler:
    TARGET_TEMPERATURE = -20.0
    TEMPERATURE_LIMIT = -10.0
    DOOR_LIMIT_MINUTES = 5.0

    def __init__(this, temperature=TARGET_TEMPERATURE):
        this.temperature = float(temperature)
        this.inventory = 0
        this.buzzer_active = False
        this.door_open_minutes = 0.0

    def insert(this, bags):
        count = int(bags)
        if count < 0:
            raise ValueError("cannot insert a negative number of plasma bags")
        this.inventory += count
        this.temperature += 2.0
        return this.inventory

    def open_door(this, minutes):
        duration = float(minutes)
        if duration < 0:
            raise ValueError("door duration cannot be negative")
        this.door_open_minutes += duration
        return this.door_open_minutes

    def remove(this, bags):
        count = int(bags)
        if count > this.inventory:
            raise ValueError("not enough plasma bags in the cooler")
        this.inventory -= count
        return this.inventory

    def monitor(this):
        too_warm = this.temperature > this.TEMPERATURE_LIMIT
        door_too_long = this.door_open_minutes > this.DOOR_LIMIT_MINUTES
        if too_warm or door_too_long:
            this.buzzer_active = True
        return this.buzzer_active

    def maintain(this):
        this.buzzer_active = False
        this.temperature = this.TARGET_TEMPERATURE
        this.door_open_minutes = 0.0
        return this.temperature


class CoolerController:
    def __init__(this, cooler):
        this.cooler = cooler
        this.handlers = {
            "insert": this.cooler.insert,
            "remove": this.cooler.remove,
            "door": this.cooler.open_door,
        }

    def apply(this, event):
        kind, value = this.normalize(event)
        if kind in this.handlers:
            this.handlers[kind](value)
            this.cooler.monitor()
        elif kind == "monitor":
            this.cooler.monitor()
        elif kind == "maintain":
            this.cooler.maintain()
        else:
            raise ValueError("unknown event type: %r" % (kind,))
        return this.cooler

    def normalize(this, event):
        if isinstance(event, str):
            parts = event.split()
            kind = parts[0]
            value = float(parts[1]) if len(parts) > 1 else 0.0
        else:
            kind, value = event
        return str(kind).strip().lower(), value

    def run(this, events):
        for event in events:
            this.apply(event)
        return this.summary()

    def summary(this):
        return this.cooler.inventory, this.cooler.buzzer_active

    def describe(this):
        inventory, buzzer = this.summary()
        state = "ALERT" if buzzer else "normal"
        return "%d bags at %.1fC (%s)" % (inventory, this.cooler.temperature, state)


