class PulpBin:
    def __init__(self, capacity):
        self.capacity = capacity
        self.level = 0.0

    def add(self, cubic_feet):
        room = self.capacity - self.level
        accepted = min(cubic_feet, room)
        self.level += accepted
        return cubic_feet - accepted

    def empty(self):
        dumped = self.level
        self.level = 0.0
        return dumped


class BatchParser:
    def __init__(self, known_fruits):
        self.known_fruits = known_fruits

    def normalize(self, word):
        return word[:-1] if word.endswith("s") else word

    def parse(self, description):
        parts = description.lower().split()
        if not parts:
            raise ValueError("empty batch description")
        if parts[0] == "clean":
            return ("clean", None, 0.0)
        fruit = self.normalize(parts[0])
        if fruit not in self.known_fruits:
            raise ValueError("unknown fruit: " + parts[0])
        if len(parts) < 2:
            raise ValueError("missing weight for " + fruit)
        return ("press", fruit, float(parts[1]))


class FruitPress:
    HIGH_PRESSURE = 2800
    LOW_PRESSURE = 900
    RATES = {"grapefruit": (0.065, 0.35), "tangerine": (0.045, 0.30)}

    def __init__(self, bin_capacity=60.0):
        self.pressure = 0
        self.total_gallons = 0.0
        self.pulp_bin = PulpBin(bin_capacity)
        self.guard_engaged = False
        self.fruit = None

    def prepare(self, fruit):
        if fruit not in self.RATES:
            raise ValueError("press cannot handle " + fruit)
        self.guard_engaged = True
        self.fruit = fruit
        self.pressure = self.HIGH_PRESSURE if fruit == "grapefruit" else self.LOW_PRESSURE
        return self.pressure

    def press(self, pounds):
        if not self.guard_engaged:
            raise RuntimeError("safety guard is not engaged")
        juice_rate, pulp_rate = self.RATES[self.fruit]
        gallons = pounds * juice_rate
        self.total_gallons += gallons
        self.pulp_bin.add(pounds * pulp_rate)
        return gallons

    def clean(self):
        self.guard_engaged = False
        self.pressure = 0
        self.fruit = None
        return self.pulp_bin.empty()


def juice(batches):
    press = FruitPress()
    parser = BatchParser(FruitPress.RATES)
    for description in batches:
        action, fruit, pounds = parser.parse(description)
        if action == "clean":
            press.clean()
        else:
            press.prepare(fruit)
            press.press(pounds)
    return round(press.total_gallons, 2), round(press.pulp_bin.level, 2)


def main():
    gallons, pulp = juice(["grapefruits 120", "clean", "tangerines 200", "grapefruits 90"])
    print("total juice: {:.2f} gal, pulp bin at {:.2f} cu ft".format(gallons, pulp))


if __name__ == "__main__":
    main()

