class FermentationVessel:
    BASELINE_JACKET_TEMP = 18.0
    CRITICAL_PRESSURE = 15.0
    TERMINAL_GRAVITY = 1.008

    def __init__(self, gravity=1.060, jacket_temp=22.0):
        self.gravity = gravity
        self.jacket_temp = jacket_temp
        self.pressure = 0.0
        self.activity = 0.0

    def pitch(self):
        self.activity += 40.0
        self.jacket_temp = self.BASELINE_JACKET_TEMP
        return self.activity

    def take_daily_reading(self):
        attenuation = 0.0005 * self.activity
        self.gravity = max(self.TERMINAL_GRAVITY, self.gravity - attenuation)
        self.pressure += 0.12 * self.activity
        self.activity = self.next_activity()
        return self.snapshot()

    def next_activity(self):
        if self.gravity <= self.TERMINAL_GRAVITY:
            return self.activity * 0.4
        if self.jacket_temp <= self.BASELINE_JACKET_TEMP:
            return self.activity * 1.05
        return self.activity * 0.85

    def is_critical(self):
        return self.pressure >= self.CRITICAL_PRESSURE

    def vent(self):
        if not self.is_critical():
            return 0.0
        released = self.pressure - self.CRITICAL_PRESSURE / 3.0
        self.pressure -= released
        return released

    def snapshot(self):
        return {"gravity": round(self.gravity, 4), "jacket_temp": round(self.jacket_temp, 1),
                "pressure": round(self.pressure, 2), "activity": round(self.activity, 2)}


class FermentationRun:
    ACTIONS = ("PITCH", "READ", "VENT")

    def __init__(self, stages, vessel=None):
        self.stages = list(stages)
        self.vessel = vessel if vessel is not None else FermentationVessel()
        self.entries = []

    def validate(self):
        for code in self.stages:
            if code.upper() not in self.ACTIONS:
                raise ValueError("unknown action code: %r" % code)
        return len(self.stages)

    def apply(self, code):
        action = code.upper()
        if action == "PITCH":
            self.vessel.pitch()
        elif action == "READ":
            self.vessel.take_daily_reading()
            if self.vessel.is_critical():
                self.vessel.vent()
        else:
            self.vessel.vent()
        self.entries.append((action, self.vessel.snapshot()))

    def execute(self):
        self.validate()
        for code in self.stages:
            self.apply(code)
        return (round(self.vessel.gravity, 4), round(self.vessel.pressure, 2))

    def report(self):
        lines = ["day  action  gravity  pressure  activity"]
        for day, (action, state) in enumerate(self.entries, start=1):
            lines.append("%3d  %-6s  %7.4f  %8.2f  %8.2f"
                         % (day, action, state["gravity"], state["pressure"], state["activity"]))
        lines.append("final jacket temperature: %.1f C" % self.vessel.jacket_temp)
        return "\n".join(lines)


def ferment(stages):
    return FermentationRun(stages).execute()


if __name__ == "__main__":
    print(ferment(["PITCH", "READ", "READ", "READ"]))
    long_run = FermentationRun(["PITCH", "READ", "READ", "READ", "READ", "VENT", "READ"])
    print(long_run.execute())
    print(long_run.report())

