NORMAL_TEMPERATURE = 70.0


class MiningShovel:
    BUCKET_CAPACITY = 35.0
    FUEL_CAPACITY = 250.0
    LOW_FUEL = 40.0

    def __init__(self, fuel=120.0):
        self.fuel = fuel
        self.bucket_load = 0.0
        self.temperature = NORMAL_TEMPERATURE
        self.tons_moved = 0.0

    def dig(self, scoop=12.0):
        room = self.BUCKET_CAPACITY - self.bucket_load
        loaded = min(scoop, room)
        self.bucket_load += loaded
        self.temperature += 2.5 + 0.2 * loaded
        return loaded

    def dump(self):
        payload = self.bucket_load
        self.tons_moved += payload
        self.fuel = max(0.0, self.fuel - (1.5 + 0.08 * payload))
        self.bucket_load = 0.0
        return payload

    def rest(self):
        self.temperature = max(NORMAL_TEMPERATURE, self.temperature - 15.0)
        if self.fuel < self.LOW_FUEL:
            self.fuel = self.FUEL_CAPACITY
            return True
        return False

    def status_line(self):
        return (f"bucket {self.bucket_load:5.1f} t | fuel {self.fuel:6.1f} L | "
                f"engine {self.temperature:5.1f} C | moved {self.tons_moved:6.1f} t")


class ShiftLog:
    def __init__(self):
        self.entries = []

    def record(self, command, note):
        self.entries.append(f"{len(self.entries) + 1:>2}. {command:<4} {note}")

    def report(self):
        return "\n".join(self.entries)


class ShiftOperator:
    def __init__(self, shovel):
        self.shovel = shovel
        self.log = ShiftLog()

    def apply(self, command):
        action = str(command).strip().lower()
        if action == "dig":
            loaded = self.shovel.dig()
            self.log.record(action, f"scooped {loaded:.1f} t; {self.shovel.status_line()}")
        elif action == "dump":
            payload = self.shovel.dump()
            self.log.record(action, f"tipped  {payload:.1f} t; {self.shovel.status_line()}")
        elif action == "rest":
            refueled = self.shovel.rest()
            note = "cooled and refuelled" if refueled else "cooled down"
            self.log.record(action, f"{note}; {self.shovel.status_line()}")
        else:
            raise ValueError(f"unknown shift command: {command!r}")

    def run(self, shifts):
        for command in shifts:
            self.apply(command)
        return round(self.shovel.tons_moved, 2), round(self.shovel.temperature, 1)


def excavate(shifts):
    return ShiftOperator(MiningShovel()).run(shifts)


if __name__ == "__main__":
    operator = ShiftOperator(MiningShovel())
    tons, temperature = operator.run(["dig", "dig", "dump", "rest"])
    print(operator.log.report())
    print(f"total moved: {tons} t, engine: {temperature} C")
    print(excavate(["dig"] * 4 + ["dump", "rest", "dig", "dump", "rest"]))

