class DiningTab:
    def __init__(self):
        self.charges = []
        self.is_open = False

    def open_tab(self):
        self.charges = []
        self.is_open = True

    def add_charge(self, amount):
        if not self.is_open:
            raise ValueError("no dining car tab is open for this berth")
        if amount <= 0:
            raise ValueError("meal cost must be positive")
        self.charges.append(float(amount))
        return self.total()

    def total(self):
        return round(sum(self.charges), 2)


class AttendantCall:
    def __init__(self):
        self.pressed = False
        self.press_count = 0

    def press(self):
        self.pressed = True
        self.press_count += 1

    def reset(self):
        self.pressed = False

    def status(self):
        return "active" if self.pressed else "reset"


class SleeperBerth:
    def __init__(self, label):
        self.label = label
        self.occupied = False
        self.needs_morning_tea = False
        self.tab = DiningTab()
        self.call_button = AttendantCall()

    def board(self):
        self.occupied = True
        self.needs_morning_tea = True
        self.tab.open_tab()

    def order_meal(self, cost):
        if not self.occupied:
            raise ValueError("berth %s is unoccupied" % self.label)
        return self.tab.add_charge(cost)

    def call_attendant(self):
        self.call_button.press()

    def conductor_visit(self):
        self.needs_morning_tea = False
        self.call_button.reset()

    def report(self):
        tea = "tea pending" if self.needs_morning_tea else "tea served"
        return "Berth %s: tab %.2f, call %s, %s, %d call(s) logged" % (
            self.label, self.tab.total(), self.call_button.status(),
            tea, self.call_button.press_count)


def accommodate(demands):
    berth = SleeperBerth("A1")
    for demand in demands:
        action = demand[0] if isinstance(demand, (tuple, list)) else demand
        if action == "board":
            berth.board()
        elif action == "dine":
            berth.order_meal(demand[1])
        elif action == "call":
            berth.call_attendant()
        elif action == "service":
            berth.conductor_visit()
        else:
            raise ValueError("unknown demand: %r" % (action,))
    return berth.tab.total(), berth.call_button.status(), berth.report()


def main():
    tab, call, summary = accommodate(
        ["board", ("dine", 34.5), ("dine", 18.25), "call", "service"])
    print("Final tab: %.2f" % tab)
    print("Call button: %s" % call)
    print(summary)


if __name__ == "__main__":
    main()

