        this.charges = []
        this.is_open = True

    def add_charge(this, amount):
        if not this.is_open:
            raise ValueError("no dining car tab is open for this berth")
        if amount <= 0:
            raise ValueError("meal cost must be positive")
        this.charges.append(float(amount))
        return this.total()

    def total(this):
        return round(sum(this.charges), 2)


class AttendantCall:
    def __init__(this):
        this.pressed = False
        this.press_count = 0

    def press(this):
        this.pressed = True
        this.press_count += 1

    def reset(this):
        this.pressed = False

    def status(this):
        return "active" if this.pressed else "reset"


class SleeperBerth:
    def __init__(this, label):
        this.label = label
        this.occupied = False
        this.needs_morning_tea = False
        this.tab = DiningTab()
        this.call_button = AttendantCall()

    def board(this):
        this.occupied = True
        this.needs_morning_tea = True
        this.tab.open_tab()

    def order_meal(this, cost):
        if not this.occupied:
            raise ValueError("berth %s is unoccupied" % this.label)
        return this.tab.add_charge(cost)

    def call_attendant(this):
        this.call_button.press()

    def conductor_visit(this):
        this.needs_morning_tea = False
        this.call_button.reset()

    def report(this):
        tea = "tea pending" if this.needs_morning_tea else "tea served"
        return "Berth %s: tab %.2f, call %s, %s, %d call(s) logged" % (
            this.label, this.tab.total(), this.call_button.status(),
            tea, this.call_button.press_count)


def accommodate(demands):
    berth = SleeperBerth("A1")
    for demand in demands:
        action = demand[0] if isinstance(demand, (tuple, list)) else demand
        if action == "board":
            berth.board()
        elif action == "dine":
            berth.order_meal(demand[1])
        elif action == "call":
            berth.call_attendant()
        elif action == "service":
            berth.conductor_visit()
        else:
            raise ValueError("unknown demand: %r" % (action,))
    return berth.tab.total(), berth.call_button.status(), berth.report()


def main():
    tab, call, summary = accommodate(
        ["board", ("dine", 34.5), ("dine", 18.25), "call", "service"])
    print("Final tab: %.2f" % tab)
    print("Call button: %s" % call)
    print(summary)


if __name__ == "__main__":
    main()

