class CoolingFan:
    def __init__(self, cooldown_ticks=3):
        self.cooldown_ticks = cooldown_ticks
        self.active = False

    def engage(self):
        self.active = True

    def run_cooldown(self):
        remaining = self.cooldown_ticks
        while remaining > 0:
            remaining -= 1
        self.active = False

    def status(self):
