class StarProjector:
    DEFAULT_FOCUS = 120

    def __init__(self):
        self.bulb = LightBulb()
        self.fan = CoolingFan()
        self.lens_focus = 0
        self.rotation_speed = 0

    def startup(self):
        self.bulb.to_maximum()
        self.fan.engage()
        self.lens_focus = self.DEFAULT_FOCUS
        self.rotation_speed = 1

    def transition(self, speed, constellation=None):
        self.rotation_speed = speed
        if constellation is not None:
            key = constellation.strip().lower()
            if key not in CONSTELLATION_FOCUS:
                raise ValueError("unknown constellation: " + constellation)
            self.lens_focus = CONSTELLATION_FOCUS[key]

    def shutdown(self):
        self.bulb.turn_off()
        self.rotation_speed = 0
        self.fan.run_cooldown()

    def focus_label(self):
        return "wide" if self.lens_focus >= 90 else "narrow"

    def report(self):
