        }


class ShowRunner:
    SPEEDS = {"slow": 1, "medium": 3, "fast": 6}

    def __init__(self, projector):
        self.projector = projector

    def parse(self, command):
        if isinstance(command, str):
            return command.strip().lower(), {}
        name = str(command[0]).strip().lower()
        options = command[1] if len(command) > 1 else {}
        return name, dict(options)

    def apply(self, command):
        name, options = self.parse(command)
        if name == "startup":
            self.projector.startup()
        elif name == "transition":
            speed = options.get("speed", "medium")
            numeric = self.SPEEDS.get(speed, speed) if isinstance(speed, str) else speed
            self.projector.transition(numeric, options.get("constellation"))
        elif name == "shutdown":
            self.projector.shutdown()
        else:
            raise ValueError("unknown show command: " + name)

    def run(self, shows):
        for command in shows:
            self.apply(command)
        return self.projector.report()


def project(shows):
    return ShowRunner(StarProjector()).run(shows)


