class VibrationMotor:
    def __init__(self):
        self.active = False
        self.duration = 0.0
        self.log = []

    def pulse(self, duration, label):
        self.active = True
        self.duration = duration
        self.log.append((label, duration))

    def stop(self):
        self.active = False
        self.duration = 0.0

    def describe(self):
        if not self.active:
            return "motor idle"
        return "motor {} for {:.1f}s".format(self.log[-1][0], self.duration)


class GamingVest:
    FULL_HEALTH = 100
    STARTING_AMMO = 12

    def __init__(self, team_color):
        self.team_color = team_color
        self.health = self.FULL_HEALTH
        self.ammo = self.STARTING_AMMO
        self.motor = VibrationMotor()
        self.powered = True

    def fire(self):
        if not self.powered or self.ammo <= 0:
            return False
        self.ammo -= 1
        self.motor.pulse(0.2, "recoil")
        return True

    def receive_hit(self, damage):
        if not self.powered:
            return self.health
        self.health = max(0, self.health - damage)
        self.motor.pulse(1.0, "impact")
        if self.health == 0:
            self.shut_down()
        return self.health

    def shut_down(self):
        self.powered = False
        self.motor.stop()

    def status(self):
        state = "online" if self.powered else "offline"
        return "{} vest {}: {} hp, {} rounds, {}".format(
            self.team_color, state, self.health, self.ammo, self.motor.describe())


class GameSession:
    def __init__(self, team_color):
        self.vest = GamingVest(team_color)
        self.shots_fired = 0
        self.damage_taken = 0

    def apply(self, event):
        action = event[0]
        if action == "fire":
            if self.vest.fire():
                self.shots_fired += 1
        elif action == "hit":
            damage = event[1] if len(event) > 1 else 20
            before = self.vest.health
            self.damage_taken += before - self.vest.receive_hit(damage)
        else:
            raise ValueError("unknown game event: {!r}".format(action))

    def run(self, events):
        for event in events:
            self.apply(event)
        return self.report()

    def report(self):
        print(self.vest.status())
        print("shots fired: {}, damage taken: {}".format(self.shots_fired, self.damage_taken))
        return self.vest.health, self.vest.ammo


def play(hits):
    session = GameSession("red")
    return session.run(hits)


if __name__ == "__main__":
    print(play([("fire",), ("fire",), ("hit", 25)]))

