class Blower:
    CRITICAL_TEMPERATURE = 1600.0
    MAX_AIRFLOW = 90.0

    def __init__(self, target_temperature, airflow_rate=30.0, interval=2.0):
        self.target_temperature = float(target_temperature)
        self.airflow_rate = float(airflow_rate)
        self.interval = float(interval)
        self.emergency_bypass = False
        self.total_oxygen = 0.0

    def adjust(self, temperature):
        if self.emergency_bypass:
            return self.airflow_rate
        deviation = self.target_temperature - temperature
        self.airflow_rate = max(0.0, min(self.MAX_AIRFLOW, self.airflow_rate + deviation * 0.05))
        return self.airflow_rate

    def deliver(self):
        delivered = self.airflow_rate * self.interval * 0.21
        self.total_oxygen += delivered
        return delivered

    def enforce_safety(self, temperature):
        if temperature >= self.CRITICAL_TEMPERATURE:
            self.emergency_bypass = True
            self.airflow_rate = 0.0
        return self.emergency_bypass


class SmeltRun:
    def __init__(self, blower):
        self.blower = blower
        self.log = []

    def validate(self, reading):
        if isinstance(reading, bool) or not isinstance(reading, (int, float)):
            raise TypeError("temperature reading must be numeric, got %r" % (reading,))
        if reading < -273.15:
            raise ValueError("temperature below absolute zero: %r" % (reading,))
        return float(reading)

    def step(self, reading):
        temperature = self.validate(reading)
        if not self.blower.enforce_safety(temperature):
            self.blower.adjust(temperature)
        delivered = self.blower.deliver()
        self.log.append((temperature, self.blower.airflow_rate, delivered))
        return delivered

    def process(self, readings):
        for reading in readings:
            self.step(reading)
        return self.result()

    def result(self):
        return round(self.blower.total_oxygen, 3), self.blower.emergency_bypass

    def report(self):
        lines = ["temp      airflow   O2"]
        for temperature, airflow, delivered in self.log:
            lines.append("%8.1f  %7.2f  %6.2f" % (temperature, airflow, delivered))
        oxygen, bypass = self.result()
        lines.append("total oxygen: %.3f  bypass: %s" % (oxygen, "ACTIVE" if bypass else "clear"))
        return "\n".join(lines)


def smelt(readings):
    run = SmeltRun(Blower(target_temperature=1450.0))
    return run.process(readings)


def main():
    run = SmeltRun(Blower(target_temperature=1450.0))
    run.process([1400.0, 1430.0, 1455.0, 1720.0])
    print(run.report())
    print(smelt([1400.0, 1430.0, 1455.0, 1720.0]))


if __name__ == "__main__":
    main()

