class WinchOperation:
    VALID_NAMES = ("release", "hook", "pull")

    def __init__(self, name, amount):
        self.name = str(name).strip().lower()
        self.amount = float(amount)
        self.validate()

    def validate(self):
        if self.name not in self.VALID_NAMES:
            raise ValueError("unknown winch operation: %s" % self.name)
        if self.amount < 0:
            raise ValueError("%s amount must not be negative" % self.name)

    def apply_to(self, winch):
        if self.name == "release":
            return winch.release(self.amount)
        if self.name == "hook":
            return winch.hook(self.amount)
        return winch.pull(self.amount)

    def describe(self):
        unit = "kg" if self.name == "hook" else "m"
        return "%s %g%s" % (self.name, self.amount, unit)


class TowWinch:
    AMBIENT_TEMP = 20.0
    MAX_CABLE = 200.0
    OVERHEAT_TEMP = 140.0

    def __init__(self):
        self.cable_length = 0.0
        self.load_weight = 0.0
        self.brake_engaged = True
        self.motor_temp = self.AMBIENT_TEMP

    def release(self, length):
        self.brake_engaged = False
        self.cable_length = min(self.cable_length + length, self.MAX_CABLE)
        self.motor_temp += length * 0.05
        return self.cable_length

    def hook(self, weight):
        self.load_weight = weight
        self.brake_engaged = True
        return self.load_weight

    def pull(self, length):
        self.brake_engaged = False
        reeled = min(length, self.cable_length)
        self.cable_length -= reeled
        self.motor_temp += reeled * (0.4 + self.load_weight / 500.0)
        return self.cable_length

    def is_overheated(self):
        return self.motor_temp > self.OVERHEAT_TEMP

    def state_line(self):
        brake = "locked" if self.brake_engaged else "free"
        return "cable %.1fm | load %.0fkg | brake %s | motor %.1fC" % (
            self.cable_length, self.load_weight, brake, self.motor_temp)


class TowJob:
    def __init__(self, pulls):
        self.operations = [WinchOperation(*step) for step in pulls]
        self.winch = TowWinch()
        self.trace = []

    def run(self):
        for operation in self.operations:
            operation.apply_to(self.winch)
            self.trace.append("%-14s -> %s" % (operation.describe(), self.winch.state_line()))
        return self.result()

    def result(self):
        return (round(self.winch.cable_length, 1), round(self.winch.motor_temp, 1))

    def summary(self):
        lines = list(self.trace)
        if self.winch.is_overheated():
            lines.append("WARNING: motor overheated, pause winching")
        length, temp = self.result()
        lines.append("final: %.1fm of cable out, motor at %.1fC" % (length, temp))
        return "\n".join(lines)


def tow(pulls):
    return TowJob(pulls).run()


def main():
    job = TowJob([("release", 50), ("hook", 1500), ("pull", 20)])
    job.run()
    print(job.summary())
    print(tow([("release", 80), ("hook", 2200), ("pull", 80)]))


if __name__ == "__main__":
    main()

