    def is_overheated(this):
        return this.motor_temp > this.OVERHEAT_TEMP

    def state_line(this):
        brake = "locked" if this.brake_engaged else "free"
        return "cable %.1fm | load %.0fkg | brake %s | motor %.1fC" % (
            this.cable_length, this.load_weight, brake, this.motor_temp)


class TowJob:
    def __init__(this, pulls):
        this.operations = [WinchOperation(*step) for step in pulls]
        this.winch = TowWinch()
        this.trace = []

    def run(this):
        for operation in this.operations:
            operation.apply_to(this.winch)
            this.trace.append("%-14s -> %s" % (operation.describe(), this.winch.state_line()))
        return this.result()

    def result(this):
        return (round(this.winch.cable_length, 1), round(this.winch.motor_temp, 1))

    def summary(this):
        lines = list(this.trace)
        if this.winch.is_overheated():
            lines.append("WARNING: motor overheated, pause winching")
        length, temp = this.result()
        lines.append("final: %.1fm of cable out, motor at %.1fC" % (length, temp))
        return "\n".join(lines)


def tow(pulls):
    return TowJob(pulls).run()


def main():
