class PaceMonitor:
    def __init__(self, window=4):
        self.window = window
        self.intervals = []

    def reset(self):
        self.intervals = []

    def record(self, interval):
        if interval <= 0:
            raise ValueError("stroke interval must be positive seconds")
        self.intervals.append(float(interval))
        if len(self.intervals) > self.window:
            del self.intervals[0]
        return self.strokes_per_minute()

    def strokes_per_minute(self):
        if not self.intervals:
            return 0.0
        average = sum(self.intervals) / len(self.intervals)
        return round(60.0 / average, 1)


class Ergometer:
    PRESETS = {"light": 3, "moderate": 6, "vigorous": 9}

    def __init__(self):
        self.resistance = 1
        self.distance = 0.0
        self.calories = 0.0
        self.stroke_rate = 0.0
        self.monitor = PaceMonitor()

    def setup(self, preference):
        key = str(preference).strip().lower()
        if key not in self.PRESETS:
            raise ValueError("unknown resistance preference: %r" % (preference,))
        self.resistance = self.PRESETS[key]
        self.distance = 0.0
        self.calories = 0.0
        self.stroke_rate = 0.0
        self.monitor.reset()
        return self.resistance

    def drag_factor(self):
        return 0.6 + 0.04 * self.resistance

    def pull(self, intensity):
        if not 0.0 < intensity <= 1.5:
            raise ValueError("stroke intensity must be within (0, 1.5]")
        gained = 2.5 * intensity * self.drag_factor()
        self.distance += gained
        self.calories += 0.07 * self.resistance * intensity
        return gained

    def pace(self, interval):
        self.stroke_rate = self.monitor.record(interval)
        return self.stroke_rate

    def summary(self):
        return {"resistance": self.resistance, "distance": round(self.distance, 2),
                "calories": round(self.calories, 2), "stroke_rate": self.stroke_rate}


class WorkoutReport:
    def __init__(self, ergometer):
        self.ergometer = ergometer
        self.lines = []

    def add_stroke(self, index):
        state = self.ergometer.summary()
        self.lines.append("stroke %2d: %6.2f m  %5.2f kcal  %4.1f spm"
                          % (index, state["distance"], state["calories"], state["stroke_rate"]))

    def render(self):
        state = self.ergometer.summary()
        header = "resistance level %d" % state["resistance"]
        footer = "total %.2f m / %.2f kcal" % (state["distance"], state["calories"])
        return "\n".join([header] + self.lines + [footer])


class RowingSession:
    def __init__(self):
        self.ergometer = Ergometer()
        self.report = WorkoutReport(self.ergometer)

    def preference_for(self, strokes):
        peak = max((intensity for intensity, _ in strokes), default=0.0)
        if peak >= 0.9:
            return "vigorous"
        if peak >= 0.5:
            return "moderate"
        return "light"

    def run(self, strokes):
        self.ergometer.setup(self.preference_for(strokes))
        for index, (intensity, interval) in enumerate(strokes, 1):
            self.ergometer.pull(intensity)
            self.ergometer.pace(interval)
            self.report.add_stroke(index)
        return self.ergometer.distance, self.ergometer.calories

    def summary_text(self):
        return self.report.render()


def row(strokes):
    distance, calories = RowingSession().run(strokes)
    return round(distance, 2), round(calories, 2)


def main():
    vigorous = [(1.0, 1.6)] * 20
    session = RowingSession()
    session.run(vigorous)
    print(session.summary_text())
    print("row() on vigorous set:", row(vigorous))
    print("row() on easy set:", row([(0.4, 3.0), (0.35, 3.2), (0.4, 3.1)]))


if __name__ == "__main__":
    main()

