import random
from collections import Counter


class Reel:
    """A single reel carrying a fixed band of symbols."""

    def __init__(self, symbols, rng):
        self.symbols = tuple(symbols)
        self.rng = rng

    def spin(self):
        return self.rng.choice(self.symbols)

    def accepts(self, symbol):
        return symbol in self.symbols


class SlotMachine:
    """Mechanical gambling device: jackpot pool, payline, hopper, multiplier."""

    GRAND_SYMBOL = "7"
    BAND = ("cherry", "bell", "bar", "plum", GRAND_SYMBOL)

    def __init__(self, hopper=100, jackpot_pool=0, multiplier=2, rng=None):
        self.rng = rng if rng is not None else random.Random()
        self.reels = [Reel(self.BAND, self.rng) for _ in range(3)]
        self.hopper = hopper
        self.jackpot_pool = jackpot_pool
        self.multiplier = multiplier
        self.payline = []
        self.current_bet = 0
        self.last_win = 0

    def wager(self, amount):
        if amount <= 0:
            raise ValueError("a wager must be a positive amount")
        self.current_bet = amount
        self.jackpot_pool += amount
        self.hopper += amount

    def do_spin(self, outcome=None):
        if outcome is None:
            self.payline = [reel.spin() for reel in self.reels]
        else:
            self.payline = self._validated(outcome)
        symbol, count = Counter(self.payline).most_common(1)[0]
        if count == len(self.reels):
            factor = 5 if symbol == self.GRAND_SYMBOL else 3
            self.last_win = self.current_bet * self.multiplier * factor
        elif count > 1:
            self.last_win = self.current_bet * self.multiplier
        else:
            self.last_win = 0
        return self.last_win

    def _validated(self, outcome):
        line = list(outcome)
        if len(line) != len(self.reels):
            raise ValueError("an outcome must name one symbol per reel")
        for reel, symbol in zip(self.reels, line):
            if not reel.accepts(symbol):
                raise ValueError("unknown symbol on the payline: %r" % (symbol,))
        return line

    def is_grand(self):
        return all(symbol == self.GRAND_SYMBOL for symbol in self.payline)

    def payout(self):
        win = self.last_win
        if win and self.is_grand():
            win += self.jackpot_pool
            self.jackpot_pool = 0
        paid = min(win, self.hopper)
        self.hopper -= paid
        self.last_win = 0
        return paid


class Session:
    """Plays a list of wagers through one machine."""

    def __init__(self, machine):
        self.machine = machine

    def parse(self, entry):
        if isinstance(entry, (tuple, list)):
            amount, outcome = entry
            return amount, outcome
        return entry, None

    def play(self, wagers):
        for entry in wagers:
            amount, outcome = self.parse(entry)
            self.machine.wager(amount)
            self.machine.do_spin(outcome)
            self.machine.payout()
        return self.machine.hopper, self.machine.jackpot_pool


def spin(wagers):
    session = Session(SlotMachine(hopper=100, jackpot_pool=0, multiplier=2,
                                  rng=random.Random(7)))
    return session.play(wagers)


if __name__ == "__main__":
    minor = [(5, ("cherry", "cherry", "bar")), 5, (10, ("bell", "plum", "bar"))]
    print("minor payout run ->", spin(minor))
    print("grand payout run ->", spin([(5, ("7", "7", "7"))]))
    print("random run       ->", spin([5, 10, 25]))

