class LoadChart:
    """Capacity table of a lifting machine: capacity falls as the radius grows."""

    def __init__(self, max_capacity, rated_moment, min_radius, max_radius):
        self.max_capacity = max_capacity
        self.rated_moment = rated_moment
        self.min_radius = min_radius
        self.max_radius = max_radius

    def clamp_radius(self, radius):
        return min(self.max_radius, max(self.min_radius, radius))

    def limit_at(self, radius):
        working_radius = self.clamp_radius(radius)
        return min(self.max_capacity, self.rated_moment / working_radius)


class OperationLog:
    def __init__(self):
        self.entries = []

    def record(self, action, detail, status):
        self.entries.append((action, detail, status))

    def blocked(self):
        return [entry for entry in self.entries if entry[2] != "ok"]

    def summary(self):
        lines = ["%d directives processed" % len(self.entries)]
        for action, detail, status in self.blocked():
            lines.append("  refused %s (%s): %s" % (action, detail, status))
        return "\n".join(lines)


class Crane:
    def __init__(self, chart, log, max_height, wind_limit):
        self.chart = chart
        self.log = log
        self.max_height = max_height
        self.wind_limit = wind_limit
        self.elevation = 0.0
        self.radius = chart.min_radius
        self.payload = 0.0
        self.wind_warning = False

    def load(self, mass):
        if mass < 0:
            raise ValueError("payload mass cannot be negative")
        self.payload = float(mass)
        self.log.record("payload", "%.0f kg" % self.payload, "ok")

    def safe_limit(self):
        return self.chart.limit_at(self.radius)

    def lift(self, delta):
        if self.wind_warning:
            self.log.record("lift", "%+.1f m" % delta, "wind warning active")
        elif self.payload > self.safe_limit():
            self.log.record("lift", "%+.1f m" % delta, "over limit %.0f kg" % self.safe_limit())
        else:
            self.elevation = min(self.max_height, max(0.0, self.elevation + delta))
            self.log.record("lift", "%+.1f m" % delta, "ok")

    def traverse(self, delta):
        target = self.chart.clamp_radius(self.radius + delta)
        if self.wind_warning:
            self.log.record("traverse", "%+.1f m" % delta, "wind warning active")
        elif self.payload > self.chart.limit_at(target):
            self.log.record("traverse", "%+.1f m" % delta, "limit %.0f kg at %.1f m" % (self.chart.limit_at(target), target))
        else:
            self.radius = target
            self.log.record("traverse", "%+.1f m" % delta, "ok")

    def weather(self, wind_speed):
        self.wind_warning = wind_speed >= self.wind_limit
        state = "halted" if self.wind_warning else "ok"
        self.log.record("wind", "%.1f m/s" % wind_speed, state)

    def position(self):
        return (round(self.elevation, 2), round(self.radius, 2))


def hoist(movements):
    crane = Crane(LoadChart(12000.0, 48000.0, 3.0, 24.0), OperationLog(), 40.0, 14.0)
    handlers = {"lift": crane.lift, "traverse": crane.traverse,
                "wind": crane.weather, "payload": crane.load}
    for action, value in movements:
        if action not in handlers:
            raise ValueError("unknown directive: %s" % action)
        handlers[action](value)
    print(crane.log.summary())
    return crane.position()


if __name__ == "__main__":
    calm_shift = [("wind", 4.0), ("payload", 2500), ("lift", 18.0), ("traverse", 9.0)]
    print("final position:", hoist(calm_shift))
    gusty_shift = [("payload", 2500), ("lift", 12.0), ("wind", 17.5), ("traverse", 6.0)]
    print("final position:", hoist(gusty_shift))

