class RoadBarrier:
    def __init__(self, side):
        self.side = side
        self.is_open = True

    def close(self):
        self.is_open = False
        return self.describe()

    def open_to_traffic(self):
        self.is_open = True
        return self.describe()

    def describe(self):
        return "{} barrier {}".format(self.side, "open" if self.is_open else "closed")


class StructuralLock:
    def __init__(self, position):
        self.position = position
        self.engaged = True

    def engage(self):
        self.engaged = True
        return self.describe()

    def disengage(self):
        self.engaged = False
        return self.describe()

    def describe(self):
        return "{} lock {}".format(self.position, "engaged" if self.engaged else "released")


class MarineQueue:
    def __init__(self):
        self.waiting = []

    def enqueue(self, vessel):
        self.waiting.append(vessel)
        return self.size()

    def release_next(self):
        if self.waiting:
            return self.waiting.pop(0)
        return None

    def size(self):
