        self.barriers = [RoadBarrier("north"), RoadBarrier("south")]
        self.locks = [StructuralLock("east"), StructuralLock("west")]
        self.queue = MarineQueue()
        self.log = []

    def register_vessel(self, vessel):
        self.log.append("{} waiting ({} in queue)".format(vessel, self.queue.enqueue(vessel)))

    def halt_traffic(self):
        for barrier in self.barriers:
            self.log.append(barrier.close())
        for lock in self.locks:
            self.log.append(lock.disengage())

