        return this.describe()

    def describe(this):
        return "{} barrier {}".format(this.side, "open" if this.is_open else "closed")


class StructuralLock:
    def __init__(this, position):
        this.position = position
        this.engaged = True

    def engage(this):
        this.engaged = True
        return this.describe()

    def disengage(this):
        this.engaged = False
        return this.describe()

    def describe(this):
        return "{} lock {}".format(this.position, "engaged" if this.engaged else "released")


class MarineQueue:
    def __init__(this):
        this.waiting = []

    def enqueue(this, vessel):
        this.waiting.append(vessel)
        return this.size()

    def release_next(this):
        if this.waiting:
            return this.waiting.pop(0)
        return None

