class Bobbin:
    def __init__(self, capacity):
        self.capacity = capacity
        self.fill = 0.0

    def remaining(self):
        return self.capacity - self.fill

    def accept(self, yardage):
        stored = min(yardage, self.remaining())
        self.fill += stored
        return stored

    def is_full(self):
        return self.fill >= self.capacity

    def percent(self):
        return 100.0 * self.fill / self.capacity


class DriveBand:
    def __init__(self, tension=0.5):
        self.tension = min(1.0, max(0.1, tension))

    def adjust(self, delta):
        self.tension = min(1.0, max(0.1, self.tension + delta))
        return self.tension

    def winding_rate(self):
        return 2.0 * self.tension


class SpinningWheel:
    def __init__(self, wool=60.0, capacity=40.0):
        self.speed = 0.0
        self.wool = wool
        self.yardage = 0.0
        self.band = DriveBand()
        self.bobbin = Bobbin(capacity)
        self.stopped = False

    def pedal(self, strokes):
        self.speed += 1.5 * strokes
        spun = min(self.wool, 0.4 * self.speed * strokes)
        self.wool -= spun
        self.yardage += spun
        return spun

    def tension(self, delta):
        return self.band.adjust(delta)

    def wind(self):
        transfer = min(self.yardage, self.band.winding_rate() * self.speed)
        stored = self.bobbin.accept(transfer)
        self.yardage -= stored
        if self.bobbin.is_full():
            self.stopped = True
            self.speed = 0.0
        return stored

    def apply(self, action, amount):
        if self.stopped:
            return
        if action == "pedal":
            self.pedal(amount)
        elif action == "tension":
            self.tension(amount)
        elif action == "wind":
            self.wind()
        else:
            raise ValueError("unknown action: " + str(action))

    def report(self):
        return "yarn={0:.2f} bobbin={1:.2f} ({2:.1f}%)".format(
            self.yardage, self.bobbin.fill, self.bobbin.percent())


def weave(steps):
    wheel = SpinningWheel()
    for step in steps:
        action = step[0]
        amount = step[1] if len(step) > 1 else 0.0
        wheel.apply(action, amount)
    return round(wheel.yardage, 2), round(wheel.bobbin.fill, 2)


def main():
    program = [("pedal", 4), ("tension", 0.4), ("wind",),
               ("pedal", 3), ("wind",), ("tension", -0.2), ("pedal", 2), ("wind",)]
    yarn, fill = weave(program)
    print("final yarn: {0:.2f} yards".format(yarn))
    print("bobbin fill: {0:.2f} yards".format(fill))


if __name__ == "__main__":
    main()

