class BrakePad:
    def __init__(self, wear=0.0):
        self.wear = wear

    def apply(self, velocity, duration):
        friction = 0.45 * duration * (1.0 + velocity / 30.0)
        self.wear = min(100.0, self.wear + friction)
        return friction

    def efficiency(self):
        return max(0.2, 1.0 - self.wear / 150.0)


class ZipLineSystem:
    BASELINE_TENSION = 500.0

    def __init__(self, pad=None):
        self.pad = pad if pad is not None else BrakePad()
        self.velocity = 0.0
        self.tension = self.BASELINE_TENSION
        self.platform_occupied = False

    def launch(self, weight):
        if weight <= 0:
            raise ValueError("rider weight must be positive")
        self.velocity = 4.0 + weight * 0.14
        self.tension = self.BASELINE_TENSION + weight * 7.5
        self.platform_occupied = False
        return self.velocity

    def brake(self, duration):
        if duration < 0:
            raise ValueError("brake duration must be non-negative")
        elapsed = 0.0
        while elapsed < duration and self.velocity > 0.0:
            step = min(1.0, duration - elapsed)
            self.pad.apply(self.velocity, step)
            self.velocity = max(0.0, self.velocity - 6.0 * step * self.pad.efficiency())
            elapsed += step
        self.platform_occupied = True
        return self.velocity

    def safe_arrival(self):
        return self.platform_occupied and self.velocity <= 2.0

    def reset(self):
        self.platform_occupied = False
        self.velocity = 0.0
        self.tension = self.BASELINE_TENSION


class DescentReport:
    def __init__(self):
        self.entries = []

    def record(self, weight, arrival_speed, safe):
        self.entries.append((weight, arrival_speed, safe))

    def summary(self):
        safe_count = sum(1 for entry in self.entries if entry[2])
        return "{}/{} riders arrived safely".format(safe_count, len(self.entries))

    def lines(self):
        for weight, speed, safe in self.entries:
            status = "safe" if safe else "OVERSPEED"
            yield "{:.0f} kg -> {:.2f} m/s ({})".format(weight, speed, status)


def descend(riders):
    system = ZipLineSystem()
    report = DescentReport()
    for weight, duration in riders:
        system.launch(weight)
        arrival_speed = system.brake(duration)
        report.record(weight, arrival_speed, system.safe_arrival())
        system.reset()
    for line in report.lines():
        print(line)
    print(report.summary())
    return system.pad.wear, system.tension


if __name__ == "__main__":
    wear, tension = descend([(95.0, 6.0), (48.0, 1.0), (72.0, 4.5)])
    print("brake wear: {:.2f}%  cable tension: {:.1f} N".format(wear, tension))

