class Tire:
    NOMINAL_LOSS_PER_KM = 0.01
    HOT_LOSS_PER_KM = 0.015
    HOT_THRESHOLD = 65.0
    LEAK_THRESHOLD = 6.0

    def __init__(self, pressure=100.0, temperature=20.0, ambient=20.0):
        self.start_pressure = pressure
        self.pressure = pressure
        self.temperature = temperature
        self.ambient = ambient
        self.mileage = 0.0
        self.leak_warning = False

    def drive(self, distance):
        if distance <= 0:
            raise ValueError("driving distance must be positive")
        self.mileage += distance
        self.temperature += distance * 0.03
        loss = distance * self.NOMINAL_LOSS_PER_KM
        if self.temperature > self.HOT_THRESHOLD:
            loss += distance * self.HOT_LOSS_PER_KM
        self.pressure -= loss
        return loss

    def rest(self, hours):
        if hours <= 0:
            raise ValueError("resting period must be positive")
        self.temperature -= (self.temperature - self.ambient) * min(1.0, hours * 0.35)
        return self.temperature

    def diagnose(self):
        expected = self.mileage * self.NOMINAL_LOSS_PER_KM
        excess = (self.start_pressure - self.pressure) - expected
        if excess > self.LEAK_THRESHOLD:
            self.leak_warning = True
        return excess

    def state(self):
        return "{:.2f} psi | {:.1f} C | {:.0f} km".format(
            self.pressure, self.temperature, self.mileage)


class JourneyMonitor:
    def __init__(self, tire):
        self.tire = tire
        self.log = []

    def normalize(self, journey):
        action, amount = journey
        action = str(action).strip().lower()
        if action not in ("drive", "rest"):
            raise ValueError("unknown journey action: " + action)
        return action, float(amount)

    def step(self, journey):
        action, amount = self.normalize(journey)
        if action == "drive":
            self.tire.drive(amount)
        else:
            self.tire.rest(amount)
        self.log.append((action, amount, self.tire.pressure,
                         self.tire.temperature, self.tire.diagnose()))

    def run(self, journeys):
        for journey in journeys:
            self.step(journey)
        return self.tire

    def report(self):
        lines = ["action   amount   pressure   temp   excess loss"]
        for action, amount, pressure, temperature, excess in self.log:
            lines.append("{:<8} {:>6.1f} {:>10.2f} {:>6.1f} {:>13.2f}".format(
                action, amount, pressure, temperature, excess))
        lines.append("final state: " + self.tire.state())
        lines.append("slow leak warning: " + ("ON" if self.tire.leak_warning else "off"))
        return "\n".join(lines)


def monitor(journeys):
    tire = JourneyMonitor(Tire()).run(journeys)
    return round(tire.pressure, 2), tire.leak_warning


if __name__ == "__main__":
    trip = [("drive", 900), ("rest", 3), ("drive", 250), ("rest", 1)]
    session = JourneyMonitor(Tire())
    session.run(trip)
    print(session.report())
    print("monitor() ->", monitor(trip))
    print("short hop ->", monitor([("drive", 80), ("rest", 2)]))

