class Membrane:
    def __init__(self, area=2.5):
        self.area = area
        self.pressure = 20.0
        self.fouling = 0.0
        self.backwash_required = False

    def set_pressure(self, target):
        self.pressure = max(15.0, min(85.0, target))
        return self.pressure

    def permeate(self, hours):
        flux = self.area * self.pressure * (1.0 - self.fouling)
        self.fouling = min(0.9, self.fouling + 0.02 * hours)
        if self.fouling >= 0.30:
            self.backwash_required = True
        return max(0.0, flux * hours)

    def backwash(self):
        cleared = self.fouling
        self.fouling = 0.0
        self.backwash_required = False
        return cleared


class DesalinationUnit:
    def __init__(self, salinity=35000.0):
        self.salinity = float(salinity)
        self.membrane = Membrane()
        self.output_volume = 0.0
        self.flush_count = 0
        self.adjust_pressure()

    def required_pressure(self):
        return 20.0 + self.salinity / 1000.0

    def adjust_pressure(self):
        return self.membrane.set_pressure(self.required_pressure())

    def pump(self, hours):
        produced = self.membrane.permeate(hours)
        self.output_volume += produced
        return produced

    def sense(self, salinity):
        if salinity < 0:
            raise ValueError("salinity cannot be negative")
        self.salinity = float(salinity)
        return self.adjust_pressure()

    def flush(self):
        cleared = self.membrane.backwash()
        self.flush_count += 1
        return cleared

