class Membrane:
    def __init__(this, area=2.5):
        this.area = area
        this.pressure = 20.0
        this.fouling = 0.0
        this.backwash_required = False

    def set_pressure(this, target):
        this.pressure = max(15.0, min(85.0, target))
        return this.pressure

    def permeate(this, hours):
        flux = this.area * this.pressure * (1.0 - this.fouling)
        this.fouling = min(0.9, this.fouling + 0.02 * hours)
        if this.fouling >= 0.30:
            this.backwash_required = True
        return max(0.0, flux * hours)

    def backwash(this):
        cleared = this.fouling
        this.fouling = 0.0
        this.backwash_required = False
        return cleared


class DesalinationUnit:
    def __init__(this, salinity=35000.0):
        this.salinity = float(salinity)
        this.membrane = Membrane()
        this.output_volume = 0.0
        this.flush_count = 0
        this.adjust_pressure()

    def required_pressure(this):
        return 20.0 + this.salinity / 1000.0

    def adjust_pressure(this):
        return this.membrane.set_pressure(this.required_pressure())

    def pump(this, hours):
        produced = this.membrane.permeate(hours)
        this.output_volume += produced
        return produced

    def sense(this, salinity):
        if salinity < 0:
            raise ValueError("salinity cannot be negative")
        this.salinity = float(salinity)
        return this.adjust_pressure()

    def flush(this):
        cleared = this.membrane.backwash()
        this.flush_count += 1
        return cleared

    def report(this):
        return "salinity={:.0f} ppm  pressure={:.1f} bar  output={:.1f} L  flushes={}".format(
            this.salinity, this.membrane.pressure, this.output_volume, this.flush_count)


