class ColorantReservoir:
    def __init__(self, name, level):
        self.name = name
        self.level = level

    def dispense(self, amount):
        if amount > self.level:
            raise ValueError("not enough {} colorant: {:.3f} left".format(self.name, self.level))
        self.level -= amount
        return amount


class MixingNozzle:
    def __init__(self):
        self.dirty = False
        self.cycles = 0

    def blend(self, can):
        self.cycles += 1
        self.dirty = True
        return can.stir()

    def clean(self):
        self.dirty = False
        return self.cycles


class MixingCan:
    def __init__(self, label):
        self.label = label
        self.base = 0.0
        self.tints = {}
        self.blended = False

    def load_base(self, volume):
        if volume <= 0:
            raise ValueError("base volume must be positive")
        self.base += volume
        return self.base

    def add_tint(self, color, amount):
        self.tints[color] = self.tints.get(color, 0.0) + amount
        return self.tints[color]

    def volume(self):
        return self.base + sum(self.tints.values())

    def stir(self):
        self.blended = True
        return "{}: {:.3f} L of {}".format(self.label, self.volume(), "+".join(sorted(self.tints)) or "white")


class DispenserMachine:
    def __init__(self, red=5.0, blue=5.0, yellow=5.0):
        self.reservoirs = {
            "red": ColorantReservoir("red", red),
            "blue": ColorantReservoir("blue", blue),
            "yellow": ColorantReservoir("yellow", yellow),
        }
        self.nozzle = MixingNozzle()
        self.cans_mixed = 0
        self.log = []

    def load(self, label, volume):
        can = MixingCan(label)
        can.load_base(volume)
        self.log.append("loaded {:.3f} L white base into {}".format(volume, label))
        return can

    def tint_can(self, can, recipe):
        for color in sorted(recipe):
            reservoir = self.reservoirs[color]
            can.add_tint(color, reservoir.dispense(recipe[color]))
        return can

    def mix(self, can):
        if self.nozzle.dirty:
            self.nozzle.clean()
            self.log.append("cleaning cycle before mixing {}".format(can.label))
        self.log.append(self.nozzle.blend(can))
        self.cans_mixed += 1
        return can

    def levels(self):
        return {name: round(res.level, 4) for name, res in self.reservoirs.items()}

    def process(self, formula):
        can = self.load(formula["name"], formula["base"])
        self.tint_can(can, formula.get("tints", {}))
        return self.mix(can)


def tint(formulas):
    machine = DispenserMachine()
    for formula in formulas:
        machine.process(formula)
    return machine.levels(), machine.cans_mixed


