    formulas = [
        {"name": "purple-1", "base": 3.0, "tints": {"red": 0.05, "blue": 0.05}},
        {"name": "green-1", "base": 2.5, "tints": {"blue": 0.04, "yellow": 0.06}},
        {"name": "plain-white", "base": 1.0},
    ]
    remaining, cans = tint(formulas)
    for color in sorted(remaining):
        print("{:>6}: {:.3f} L".format(color, remaining[color]))
    print("cans mixed:", cans)


if __name__ == "__main__":
    main()

