class GasTube:
    MAX_SAFE_TEMPERATURE = 180.0
    AMBIENT_TEMPERATURE = 20.0

    def __init__(self, pressure=8.0):
        self.pressure = pressure
        self.temperature = self.AMBIENT_TEMPERATURE

    def excite(self, voltage, duration):
        self.pressure = min(12.0, self.pressure + voltage * duration * 0.0002)
        self.temperature += voltage * duration * 0.01 * (self.pressure / 8.0)
        return self.temperature

    def cool(self, duration):
        self.temperature = max(self.AMBIENT_TEMPERATURE, self.temperature - 1.5 * duration)
        self.pressure = max(6.0, self.pressure - 0.02 * duration)

    def is_overheated(self):
        return self.temperature > self.MAX_SAFE_TEMPERATURE

    def quench(self):
        self.temperature = min(self.temperature, self.MAX_SAFE_TEMPERATURE)
        self.pressure = 8.0


class NeonSign:
    FLICKER_VOLTAGE = 45.0

    def __init__(self, tube):
        self.tube = tube
        self.voltage = 0.0
        self.flickering = False

    def power(self, voltage, duration):
        if voltage < 0 or duration < 0:
            raise ValueError("voltage and duration must be non-negative")
        self.voltage = float(voltage)
        if self.voltage >= self.FLICKER_VOLTAGE:
            self.flickering = False
        self.tube.excite(self.voltage, duration)
        self.check_fault()

    def dim(self, voltage, duration):
        previous = self.voltage
        self.voltage = min(previous, float(voltage))
        if self.voltage < self.FLICKER_VOLTAGE and previous - self.voltage >= 20.0:
            self.flickering = True
        self.tube.cool(duration)
        self.check_fault()

    def hold(self, duration):
        if self.voltage > 0:
            self.tube.excite(self.voltage, duration)
            self.check_fault()
        else:
            self.tube.cool(duration)

    def check_fault(self):
        if self.tube.is_overheated():
            self.voltage = 0.0
            self.flickering = True
            self.tube.quench()
            return True
        return False

    def report(self):
        state = "flickering" if self.flickering else "steady"
        return "{0:.1f}V, {1:.1f}C, {2}".format(self.voltage, self.tube.temperature, state)


class PatternInterpreter:
    def __init__(self, sign):
        self.sign = sign
        self.actions = {"power": sign.power, "dim": sign.dim, "hold": sign.hold}

    def parse(self, pattern):
        if isinstance(pattern, str):
            parts = pattern.split()
            return parts[0].lower(), [float(p) for p in parts[1:]]
        name, args = pattern[0], [float(a) for a in pattern[1:]]
        return name.lower(), args

    def apply(self, pattern):
        name, args = self.parse(pattern)
        if name not in self.actions:
            raise ValueError("unknown lighting pattern: " + name)
        self.actions[name](*args)
        return self.sign.report()

    def run(self, patterns):
        return [self.apply(pattern) for pattern in patterns]


def illuminate(patterns):
    sign = NeonSign(GasTube())
    interpreter = PatternInterpreter(sign)
    interpreter.run(patterns)
    return round(sign.tube.temperature, 2), sign.flickering


if __name__ == "__main__":
    show = ["power 220 60", "hold 10", "dim 20 5"]
    temperature, flickering = illuminate(show)
    print("final temperature: {0}C, flickering: {1}".format(temperature, flickering))
    print(illuminate([("power", 90, 5), ("dim", 80, 2)]))
    print(illuminate(["power 0 0", "hold 30"]))

