        self.active = True
        self.temperature = 120 + 20 * level

    def deactivate(self):
        self.active = False
        self.temperature = self.ROOM_TEMPERATURE


class Toaster:
    MIN_DIAL = 1
    MAX_DIAL = 7

    def __init__(self, element):
        self.dial = 3
        self.lever = "up"
        self.crumbs = 0
        self.element = element

    def push(self):
        self.lever = "down"
        self.element.activate(self.dial)

    def set_dial(self, level):
        if not self.MIN_DIAL <= level <= self.MAX_DIAL:
            raise ValueError("dial level out of range: {}".format(level))
        self.dial = level
        if self.element.active:
            self.element.activate(level)

    def pop(self):
        self.element.deactivate()
        self.lever = "up"
        self.crumbs += self.dial * 2

    def clean(self):
        self.crumbs = 0

    def state(self):
        return (self.lever, self.element.active, self.crumbs)


class ActionRunner:
    def __init__(self, toaster):
        self.toaster = toaster

    def run(self, actions):
        for action in actions:
            self.apply(action)
        return self.toaster.state()

    def apply(self, action):
        parts = str(action).split()
        if not parts:
            raise ValueError("empty action")
        name = parts[0].lower()
        if name == "push":
            self.toaster.push()
        elif name == "dial":
            self.toaster.set_dial(int(parts[1]))
        elif name == "pop":
            self.toaster.pop()
        elif name == "clean":
            self.toaster.clean()
        else:
            raise ValueError("unknown action: {}".format(action))


def toast(actions):
    runner = ActionRunner(Toaster(HeatingElement()))
    return runner.run(actions)


