class GroundLoop:
    MIN_PRESSURE = 20
    MAX_PRESSURE = 80

    def __init__(self, pressure=50, valve="closed"):
        self.pressure = pressure
        self.valve = valve

    def open_valve(self):
        self.valve = "open"

    def close_valve(self):
        self.valve = "closed"

    def adjust_pressure(self, delta):
        target = self.pressure + delta
        if target > self.MAX_PRESSURE:
            target = self.MAX_PRESSURE
        elif target < self.MIN_PRESSURE:
            target = self.MIN_PRESSURE
        self.pressure = target

    def state(self):
        return self.valve, self.pressure


class IndoorFan:
    def __init__(self):
        self.speed = 0

    def set_speed(self, speed):
        self.speed = speed

    def state(self):
        return self.speed


class PumpSystem:
    COLD_LIMIT = 60
    HOT_LIMIT = 70

    def __init__(self):
        self.loop = GroundLoop()
        self.fan = IndoorFan()
        self.history = []

    def apply(self, reading):
        if reading < self.COLD_LIMIT:
            self.loop.open_valve()
            self.loop.adjust_pressure(10)
            self.fan.set_speed("high")
        elif reading > self.HOT_LIMIT:
            self.loop.close_valve()
            self.loop.adjust_pressure(-5)
            self.fan.set_speed("medium")
        else:
            self.loop.close_valve()
            self.fan.set_speed("low")
        return self.record()

    def record(self):
        valve, pressure = self.loop.state()
        snapshot = (valve, pressure, self.fan.state())
        self.history.append(snapshot)
        return snapshot

    def run(self, readings):
        for reading in readings:
            if not isinstance(reading, (int, float)) or isinstance(reading, bool):
                raise TypeError("readings must contain numbers, got %r" % (reading,))
            self.apply(reading)
        return list(self.history)

    def report(self):
        lines = []
        for index, (valve, pressure, speed) in enumerate(self.history, start=1):
            lines.append("%d: valve=%s pressure=%d fan=%s" % (index, valve, pressure, speed))
        return "\n".join(lines)


def regulate(readings):
    return PumpSystem().run(readings)


def main():
    system = PumpSystem()
    print(system.run([55, 75, 65, 50, 45, 40, 90, 95]))
    print(system.report())
    print(regulate([55, 75]))


if __name__ == "__main__":
    main()

