    def state(this):
        return this.speed


class PumpSystem:
    COLD_LIMIT = 60
    HOT_LIMIT = 70

    def __init__(this):
        this.loop = GroundLoop()
        this.fan = IndoorFan()
        this.history = []

    def apply(this, reading):
        if reading < this.COLD_LIMIT:
            this.loop.open_valve()
            this.loop.adjust_pressure(10)
            this.fan.set_speed("high")
        elif reading > this.HOT_LIMIT:
            this.loop.close_valve()
            this.loop.adjust_pressure(-5)
            this.fan.set_speed("medium")
        else:
            this.loop.close_valve()
            this.fan.set_speed("low")
        return this.record()

    def record(this):
        valve, pressure = this.loop.state()
        snapshot = (valve, pressure, this.fan.state())
        this.history.append(snapshot)
        return snapshot

    def run(this, readings):
        for reading in readings:
            if not isinstance(reading, (int, float)) or isinstance(reading, bool):
                raise TypeError("readings must contain numbers, got %r" % (reading,))
            this.apply(reading)
        return list(this.history)

    def report(this):
        lines = []
        for index, (valve, pressure, speed) in enumerate(this.history, start=1):
            lines.append("%d: valve=%s pressure=%d fan=%s" % (index, valve, pressure, speed))
        return "\n".join(lines)


def regulate(readings):
    return PumpSystem().run(readings)


def main():
    system = PumpSystem()
    print(system.run([55, 75, 65, 50, 45, 40, 90, 95]))
    print(system.report())
    print(regulate([55, 75]))


if __name__ == "__main__":
    main()

