class Reservoir:
    def __init__(self, volume=100):
        self.volume = volume

    def drain(self, amount):
        self.volume -= amount
        return self.volume

    def report(self):
        return "reservoir holds {0} units".format(self.volume)


class Pan:
    def __init__(self, temperature=60, concentration=2):
        self.temperature = temperature
        self.concentration = concentration

    def heat(self):
        self.temperature += 30
        if self.temperature >= 200:
            self.concentration += 10
        return self.temperature

    def cool(self, amount):
        self.temperature -= amount
        return self.temperature

    def draw_off(self):
        if self.concentration > 50:
            self.concentration -= 50
        return self.concentration

    def report(self):
        return "pan at {0} degrees, {1} percent sugar".format(
            self.temperature, self.concentration)


class Evaporator:
    def __init__(self):
        self.reservoir = Reservoir()
        self.pan = Pan()
        self.log = []

    def apply(self, step):
        action = step.strip().lower()
        if action == "heat":
            self.pan.heat()
        elif action == "fill":
            self.reservoir.drain(15)
            self.pan.cool(10)
        elif action == "draw":
            self.pan.draw_off()
        else:
            raise ValueError("unknown step: {0}".format(step))
        self.log.append(action)
        return self.state()

    def run(self, steps):
        for step in steps:
            self.apply(step)
        return self.state()

    def state(self):
        return (self.reservoir.volume, self.pan.temperature,
                self.pan.concentration)

    def summary(self):
        return "after {0} steps: {1}; {2}".format(
            len(self.log), self.reservoir.report(), self.pan.report())


