class AirBlower:
    def __init__(self):
        self.power = "normal"
        self.overheated = False

    def respond_to(self, stress):
        if stress > 50:
            self.power = "high"
            self.overheated = True
        elif 30 <= stress <= 50:
            self.power = "medium"
            self.overheated = False
        else:
            self.power = "normal"
            self.overheated = False
        return self.power

    def describe(self):
        state = "overheated" if self.overheated else "stable"
        return "blower on {0} ({1})".format(self.power, state)


class BouncyCastle:
    def __init__(self):
        self.kids = 0
        self.stress = 0
        self.blower = AirBlower()

    def enter(self):
        self.kids += 1
        self.stress += 5

    def exit(self):
        self.kids -= 1
        self.stress -= 3

    def bounce(self):
        self.stress += 10

    def apply(self, event):
        action = {"enter": self.enter, "exit": self.exit, "bounce": self.bounce}.get(event)
        if action is None:
            raise ValueError("unknown event: {0!r}".format(event))
        action()
        self.blower.respond_to(self.stress)

    def status(self):
        return (self.kids, self.stress, self.blower.power)

    def report(self):
        return "{0} kid(s), stress {1}, {2}".format(self.kids, self.stress, self.blower.describe())


class CastleSession:
    def __init__(self, events):
        self.events = list(events)
        self.castle = BouncyCastle()
        self.log = []

    def run(self):
        for event in self.events:
            self.castle.apply(event)
            self.log.append("{0} -> {1}".format(event, self.castle.report()))
        return self.castle.status()

    def transcript(self):
        return "\n".join(self.log)


def monitor(events):
    return CastleSession(events).run()


def main():
    session = CastleSession(["enter", "enter", "bounce"])
    result = session.run()
    print(session.transcript())
    print("final:", result)
    print("second run:", monitor(["enter", "bounce", "bounce", "bounce", "bounce", "bounce", "bounce"]))


if __name__ == "__main__":
    main()

