class Humidifier:
    def __init__(self, water_level=100):
        self.water_level = water_level
        self.is_on = False

    def has_water(self):
        return self.water_level > 0

    def turn_on(self, usage=5):
        if not self.has_water():
            self.is_on = False
            return False
        self.is_on = True
        self.water_level = max(0, self.water_level - usage)
        return True

    def turn_off(self):
        self.is_on = False


class VentilationFan:
    def __init__(self):
        self.speed = 0

    def set_low(self):
        self.speed = "low"

    def set_high(self):
        self.speed = "high"


class CaveController:
    LOW_LIMIT = 80
    HIGH_LIMIT = 90

    def __init__(self, humidifier, fan):
        self.humidifier = humidifier
        self.fan = fan
        self.log = []

    def validate(self, measurements):
        clean = []
        for value in measurements:
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise TypeError("humidity measurements must be numeric: %r" % (value,))
            clean.append(float(value))
        return clean

    def step(self, humidity):
        if humidity < self.LOW_LIMIT:
            self.humidifier.turn_on()
            self.fan.set_low()
        elif humidity > self.HIGH_LIMIT:
            self.humidifier.turn_off()
            self.fan.set_high()
        else:
            self.humidifier.turn_off()
            self.fan.set_low()
        self.log.append((humidity, self.humidifier.is_on, self.fan.speed))

    def run(self, measurements):
        for humidity in self.validate(measurements):
            self.step(humidity)
        return self.state()

    def state(self):
        return (self.humidifier.water_level, self.humidifier.is_on, self.fan.speed)

    def report(self):
        lines = ["%.1f%% -> humidifier=%s fan=%s" % entry for entry in self.log]
        water, running, speed = self.state()
        lines.append("final: water=%s running=%s fan=%s" % (water, running, speed))
        return "\n".join(lines)


def condition(measurements):
    controller = CaveController(Humidifier(), VentilationFan())
    return controller.run(measurements)


def main():
    readings = [70, 95, 85]
    controller = CaveController(Humidifier(), VentilationFan())
    controller.run(readings)
    print(controller.report())
    print(condition(readings))


if __name__ == "__main__":
    main()

