class Kart:
    """A go kart with a finite fuel load and tires that wear every lap."""

    def __init__(self):
        self.fuel = 10
        self.tire_wear = 0

    def run_lap(self):
        self.tire_wear += 2
        self.fuel -= 1

    def wear_penalty(self):
        if self.tire_wear > 10:
            return 5
        return 0

    def has_fuel(self):
        return self.fuel > 0

    def describe(self):
        return "fuel {} / tire wear {}".format(self.fuel, self.tire_wear)


class Session:
    """A race session recording the laps a single kart manages to complete."""

    def __init__(self, kart):
        self.kart = kart
        self.fastest_lap = 999
        self.laps_completed = 0
        self.lap_log = []

    def validate(self, laps):
        for lap_time in laps:
            if not isinstance(lap_time, (int, float)) or isinstance(lap_time, bool):
                raise TypeError("lap times must be numbers, got {!r}".format(lap_time))
            if lap_time <= 0:
                raise ValueError("lap times must be positive, got {!r}".format(lap_time))
        return list(laps)

    def record(self, lap_time):
        self.kart.run_lap()
        adjusted = lap_time + self.kart.wear_penalty()
        if adjusted < self.fastest_lap:
            self.fastest_lap = adjusted
        self.laps_completed += 1
        self.lap_log.append(adjusted)
        return adjusted

    def run(self, laps):
        for lap_time in self.validate(laps):
            self.record(lap_time)
            if not self.kart.has_fuel():
                break
        return self.result()

    def result(self):
        return (self.laps_completed, self.fastest_lap, self.kart.fuel, self.kart.tire_wear)


class RaceReport:
    """Turns a finished session into a readable summary."""

    def __init__(self, session):
        self.session = session

    def lap_lines(self):
        return ["  lap {}: {}s".format(i, t) for i, t in enumerate(self.session.lap_log, 1)]

    def render(self):
        lines = ["Laps completed: {}".format(self.session.laps_completed)]
        lines.extend(self.lap_lines())
        lines.append("Fastest lap: {}s".format(self.session.fastest_lap))
        lines.append("Kart at finish: {}".format(self.session.kart.describe()))
        return "\n".join(lines)


def run_session(laps):
    session = Session(Kart())
    session.run(laps)
    return session


def race(laps):
    return run_session(laps).result()


def main():
    for laps in ([40, 38, 42], [35, 34, 36, 33, 37, 34, 35, 36, 34, 33, 32, 31]):
        session = run_session(laps)
        print(RaceReport(session).render())
        print("Result: {}\n".format(session.result()))


if __name__ == "__main__":
    main()

