class ChlorineDispenser:
    """Holds the chlorine reserve used by shock treatments."""

    SHOCK_DOSE = 10

    def __init__(self, reserve=50):
        self.reserve = reserve

    def can_shock(self):
        return self.reserve >= self.SHOCK_DOSE

    def dispense_shock(self):
        if not self.can_shock():
            return False
        self.reserve -= self.SHOCK_DOSE
        return True


class FilterCycle:
    """Mechanical cleaning: raises cleanliness without spending chemicals."""

    def __init__(self, boost=10):
        self.boost = boost

    def run(self, tub):
        tub.raise_cleanliness(self.boost)


class HotTub:
    MAX_CLEANLINESS = 100

    def __init__(self, dispenser, cleanliness=100, volume=500):
        self.dispenser = dispenser
        self.filter_cycle = FilterCycle()
        self.cleanliness = cleanliness
        self.volume = volume

    def raise_cleanliness(self, amount):
        self.cleanliness = min(self.MAX_CLEANLINESS, self.cleanliness + amount)

    def bathe(self):
        self.cleanliness -= 20
        self.volume -= 2

    def shock(self):
        if self.dispenser.dispense_shock():
            self.cleanliness = self.MAX_CLEANLINESS

    def filter(self):
        self.filter_cycle.run(self)

    def apply(self, action):
        handler = {
            "bathe": self.bathe,
            "shock": self.shock,
            "filter": self.filter,
        }.get(action)
        if handler is None:
            raise ValueError("unknown action: %r" % (action,))
        handler()

    def state(self):
        return (self.cleanliness, self.dispenser.reserve, self.volume)

    def report(self):
        return "cleanliness={0} chlorine={1} volume={2}".format(*self.state())


def sanitize(actions):
    tub = HotTub(ChlorineDispenser())
    for action in actions:
        tub.apply(action)
    return tub.state()


def main():
    schedule = ["bathe", "bathe", "shock", "filter"]
    tub = HotTub(ChlorineDispenser())
    for action in schedule:
        tub.apply(action)
        print("after {0:6s}: {1}".format(action, tub.report()))
    print("final:", sanitize(schedule))


if __name__ == "__main__":
    main()

