class Motor:
    IDLE = "idle"
    RUNNING = "running"
    ERROR = "error"
    BASE_TEMPERATURE = 70
    MAX_TEMPERATURE = 120

    def __init__(self):
        self.temperature = float(self.BASE_TEMPERATURE)
        self.status = self.IDLE

    def is_overheated(self):
        return self.temperature > self.MAX_TEMPERATURE

    def engage(self, pages):
        self.status = self.RUNNING
        self.temperature += pages / 2

    def fail(self):
        self.status = self.ERROR

    def cool_down(self):
        self.temperature = max(float(self.BASE_TEMPERATURE), self.temperature - 5)

    def reading(self):
        if self.temperature.is_integer():
            return int(self.temperature)
        return round(self.temperature, 1)


class Bin:
    MAX_CAPACITY = 100

    def __init__(self):
        self.capacity = 0

    def can_accept(self, pages):
        return self.capacity + pages <= self.MAX_CAPACITY

    def load(self, pages):
        self.capacity += pages

    def free_space(self):
        return self.MAX_CAPACITY - self.capacity


class Shredder:
    def __init__(self):
        self.motor = Motor()
        self.bin = Bin()
        self.log = []

    def accepts(self, pages):
        return not self.motor.is_overheated() and self.bin.can_accept(pages)

    def run(self, batches):
        for pages in batches:
            if not isinstance(pages, int) or pages < 0:
                raise ValueError("page counts must be non-negative integers")
            if not self.accepts(pages):
                self.motor.fail()
                self.log.append("jammed on %d pages, %d slots free" % (pages, self.bin.free_space()))
                break
            self.motor.engage(pages)
            self.bin.load(pages)
            self.motor.cool_down()
            self.log.append("shredded %d pages at %s degrees" % (pages, self.motor.reading()))
        return self.state()

    def state(self):
        return (self.motor.status, self.motor.reading(), self.bin.capacity)

    def report(self):
        status, temperature, capacity = self.state()
        header = "status=%s temperature=%s capacity=%d" % (status, temperature, capacity)
        return "\n".join([header] + ["  - " + entry for entry in self.log])


def shred(batches):
    return Shredder().run(batches)


def main():
    machine = Shredder()
    print(machine.run([20, 40]))
    print(machine.report())
    print(shred([20, 40, 90]))


if __name__ == "__main__":
    main()

