class Roof:
    def __init__(self):
        self.debris = 0
        self.clog_limit = 3

    def accumulate(self):
        self.debris += 1
        return self.debris

    def wash(self):
        washed = self.debris
        self.debris = 0
        return washed

    def was_clogged(self, washed_amount):
        return washed_amount > self.clog_limit


class Tank:
    def __init__(self):
        self.volume = 0
        self.overflows = 0
        self.capacity = 1000

    def add(self, water):
        self.volume += water
        if self.volume > self.capacity:
            self.volume = self.capacity
            self.overflows += 1
        return self.volume

    def report(self):
        return self.volume, self.overflows


class WeatherEvent:
    def __init__(self, text):
        parts = str(text).split()
        if not parts:
            raise ValueError("empty weather event")
        self.kind = parts[0].lower()
        self.amount = self.parse_amount(parts[1:])

    def parse_amount(self, extra):
        if self.kind == "rain":
            if len(extra) != 1:
                raise ValueError("rain event needs exactly one amount")
            return float(extra[0])
        if self.kind != "dry":
            raise ValueError("unknown weather event: " + self.kind)
        if extra:
            raise ValueError("dry event takes no amount")
        return 0.0

    def is_rain(self):
        return self.kind == "rain"

    def yield_water(self):
        return self.amount * 10


class HarvestingSystem:
    def __init__(self):
        self.roof = Roof()
        self.tank = Tank()

    def process(self, event):
        if event.is_rain():
            washed = self.roof.wash()
            if not self.roof.was_clogged(washed):
                self.tank.add(event.yield_water())
        else:
            self.roof.accumulate()

    def run(self, weather):
        for text in weather:
            self.process(WeatherEvent(text))
        return self.state()

    def state(self):
        volume, overflows = self.tank.report()
        return int(volume), self.roof.debris, overflows


def collect(weather):
    return HarvestingSystem().run(weather)


if __name__ == "__main__":
    print(collect(["dry", "dry", "rain 5", "dry", "rain 10"]))

