class Trick:
    def __init__(self, base, landed):
        self.base = base
        self.landed = landed

    @classmethod
    def parse(cls, definition):
        if len(definition) != 2:
            raise ValueError("a trick needs a base value and a landed flag")
        base, landed = definition
        if not isinstance(base, (int, float)) or isinstance(base, bool):
            raise ValueError("base value must be numeric: %r" % (base,))
        return cls(base, bool(landed))

    def value_after(self, streak):
        return self.base + 5 * streak

    def label(self):
        return "%g (%s)" % (self.base, "landed" if self.landed else "missed")


class Run:
    def __init__(self):
        self.consecutive = 0
        self.base_score = 0

    def land(self, trick):
        earned = trick.value_after(self.consecutive)
        self.consecutive += 1
        self.base_score += earned
        return earned

    def fall(self):
        self.consecutive = 0
        self.base_score += 0
        return 0

    def perform(self, trick):
        if trick.landed:
            return self.land(trick)
        return self.fall()

    def summary(self):
        return self.base_score, self.consecutive


class JudgingPanel:
    def __init__(self):
        self.highest = 0
        self.run = Run()

    def judge(self, trick):
        earned = self.run.perform(trick)
        if earned > self.highest:
            self.highest = earned
        return earned

    def result(self):
        total, streak = self.run.summary()
        return total, self.highest, streak

    def describe(self):
        total, highest, streak = self.result()
        return "total=%g best=%g streak=%d" % (total, highest, streak)


def score(tricks):
    panel = JudgingPanel()
    for definition in tricks:
        panel.judge(Trick.parse(definition))
    return panel.result()


def main():
    routine = [[10, True], [20, True], [15, False]]
    panel = JudgingPanel()
    for definition in routine:
        trick = Trick.parse(definition)
        print("%-16s -> %g" % (trick.label(), panel.judge(trick)))
    print(panel.describe())
    print(score(routine))


if __name__ == "__main__":
    main()

