class Hopper:
    """Holds the raw soap that feeds the press."""

    def __init__(self, amount=50):
        self.amount = amount

    def withdraw(self, units):
        taken = min(units, self.amount)
        self.amount -= taken
        return taken

    def batches_available(self, unit_cost):
        return self.amount // unit_cost


class Die:
    """The extrusion die: it has a shape and a heat level."""

    def __init__(self, shape="round", heat="low"):
        self.shape = shape
        self.heat = heat

    def set_shape(self, shape):
        self.shape = shape

    def set_heat(self, heat):
        self.heat = heat

    def soap_per_bar(self):
        return 3 if self.heat == "low" else 2


class SoapPress:
    """Drives the hopper and the die from a list of textual commands."""

    def __init__(self, hopper=None, die=None):
        self.hopper = hopper if hopper is not None else Hopper()
        self.die = die if die is not None else Die()
        self.bars = 0

    def press(self, requested):
        cost = self.die.soap_per_bar()
        made = min(requested, self.hopper.batches_available(cost))
        self.hopper.withdraw(made * cost)
        self.bars += made
        return made

    def run_command(self, command):
        parts = command.split()
        if len(parts) != 2:
            raise ValueError("malformed command: {!r}".format(command))
        verb, argument = parts[0].lower(), parts[1]
        if verb == "shape":
            self.die.set_shape(argument)
        elif verb == "heat":
            self.die.set_heat(argument.lower())
        elif verb == "press":
            if not argument.isdigit():
                raise ValueError("press needs a number, got {!r}".format(argument))
            self.press(int(argument))
        else:
            raise ValueError("unknown command: {!r}".format(verb))

    def run(self, commands):
        for command in commands:
            self.run_command(command)
        return self.result()

    def result(self):
        return (self.hopper.amount, self.bars, self.die.shape)

    def report(self):
        soap, bars, shape = self.result()
        return "{} bars of {} soap, {} units of raw soap left".format(bars, shape, soap)


def extrude(commands):
    return SoapPress().run(commands)


def main():
    program = ["heat high", "shape square", "press 10"]
    print(extrude(program))
    press = SoapPress()
    press.run(["shape oval", "press 12", "heat high", "press 12"])
    print(press.report())


if __name__ == "__main__":
    main()

