class BungeeCord:
    """A bungee cord that wears out as jumpers use it."""

    def __init__(self, base_elasticity=100, max_weight=300, min_elasticity=50):
        self.base_elasticity = base_elasticity
        self.max_weight = max_weight
        self.min_elasticity = min_elasticity
        self.wear = 0
        self.retired = False

    def elasticity(self):
        return self.base_elasticity - self.wear // 5

    def absorb(self, weight):
        self.wear += weight // 50
        if self.elasticity() < self.min_elasticity:
            self.retired = True
        return self.elasticity()


class JumpLog:
    """Record of every attempted jump."""

    def __init__(self):
        self.total_jumps = 0
        self.successes = []
        self.rejections = []

    def record_success(self, weight, elasticity, wear):
        self.total_jumps += 1
        self.successes.append((weight, elasticity, wear))

    def record_rejection(self, weight, reason):
        self.rejections.append((weight, reason))

    def report(self):
        lines = ["jump %d: %dkg -> elasticity %d, wear %d" % (i, w, e, d)
                 for i, (w, e, d) in enumerate(self.successes, start=1)]
        lines.extend("rejected %dkg (%s)" % (w, why) for w, why in self.rejections)
        lines.append("total successful jumps: %d" % self.total_jumps)
        return "\n".join(lines)


class JumpSession:
    """Runs a list of jumpers over a single cord and keeps the log."""

    def __init__(self):
        self.cord = BungeeCord()
        self.log = JumpLog()

    def validate(self, weight):
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise TypeError("jumper weight must be a number, got %r" % (weight,))
        if weight <= 0:
            raise ValueError("jumper weight must be positive, got %r" % (weight,))
        return int(weight)

    def attempt(self, weight):
        if self.cord.retired:
            self.log.record_rejection(weight, "cord retired")
        elif weight > self.cord.max_weight:
            self.log.record_rejection(weight, "over weight limit")
        else:
            self.cord.absorb(weight)
            self.log.record_success(weight, self.cord.elasticity(), self.cord.wear)

    def run(self, weights):
        for raw_weight in weights:
            self.attempt(self.validate(raw_weight))
        return self.result()

    def result(self):
        return (self.log.total_jumps, self.cord.elasticity(), self.cord.wear)


def jump(weights):
    return JumpSession().run(weights)


def main():
    session = JumpSession()
    outcome = session.run([150, 200])
    print(session.log.report())
    print("result:", outcome)
    print("heavy jumper:", jump([320, 150, 200]))


