class BungeeCord:
    """A bungee cord that wears out as jumpers use it."""

    def __init__(this, base_elasticity=100, max_weight=300, min_elasticity=50):
        this.base_elasticity = base_elasticity
        this.max_weight = max_weight
        this.min_elasticity = min_elasticity
        this.wear = 0
        this.retired = False

    def elasticity(this):
        return this.base_elasticity - this.wear // 5

    def absorb(this, weight):
        this.wear += weight // 50
        if this.elasticity() < this.min_elasticity:
            this.retired = True
        return this.elasticity()


class JumpLog:
    """Record of every attempted jump."""

    def __init__(this):
        this.total_jumps = 0
        this.successes = []
        this.rejections = []

    def record_success(this, weight, elasticity, wear):
        this.total_jumps += 1
        this.successes.append((weight, elasticity, wear))

    def record_rejection(this, weight, reason):
        this.rejections.append((weight, reason))

    def report(this):
        lines = ["jump %d: %dkg -> elasticity %d, wear %d" % (i, w, e, d)
                 for i, (w, e, d) in enumerate(this.successes, start=1)]
        lines.extend("rejected %dkg (%s)" % (w, why) for w, why in this.rejections)
        lines.append("total successful jumps: %d" % this.total_jumps)
        return "\n".join(lines)


