class Heater:
    def __init__(self):
        self.temperature = 70

    def set_base(self, temperature):
        self.temperature = temperature

    def boost(self, units):
        self.temperature += 2 * units

    def describe(self):
        return "heater {}F".format(self.temperature)


class ExhaustFan:
    def __init__(self):
        self.speed = 0

    def set_base(self, speed):
        self.speed = speed

    def boost(self, units):
        self.speed += units

    def describe(self):
        return "fan {}rpm".format(self.speed)


class PaintProfile:
    def __init__(self, name, base_temperature, base_speed):
        self.name = name
        self.base_temperature = base_temperature
        self.base_speed = base_speed

    def apply_to(self, heater, fan):
        heater.set_base(self.base_temperature)
        fan.set_base(self.base_speed)


class DryingBooth:
    def __init__(self):
        self.heater = Heater()
        self.fan = ExhaustFan()
        self.profiles = {
            "enamel": PaintProfile("enamel", 100, 50),
            "acrylic": PaintProfile("acrylic", 80, 20),
        }
        self.log = []

    def profile_for(self, paint):
        if paint not in self.profiles:
            raise ValueError("unknown paint type: {!r}".format(paint))
        return self.profiles[paint]

    def configure(self, paint, thickness):
        if thickness < 0:
            raise ValueError("thickness must not be negative")
        self.profile_for(paint).apply_to(self.heater, self.fan)
        extra = max(0, thickness - 10)
        self.heater.boost(extra)
        self.fan.boost(extra)

    def cycle_time(self):
        return (self.heater.temperature + self.fan.speed) // 2

    def process(self, paint, thickness):
        self.configure(paint, thickness)
        minutes = self.cycle_time()
        self.log.append("{} @{}mil -> {} min ({}, {})".format(
            paint, thickness, minutes, self.heater.describe(), self.fan.describe()))
        return minutes

    def run(self, items):
        total = sum(self.process(paint, thickness) for paint, thickness in items)
        return total, self.heater.temperature, self.fan.speed

    def summary(self):
        return "\n".join(self.log)


def dry(items):
    booth = DryingBooth()
    return booth.run(items)


def main():
    booth = DryingBooth()
    result = booth.run([["enamel", 12], ["acrylic", 5]])
    print(booth.summary())
    print("total={} heater={} fan={}".format(*result))


if __name__ == "__main__":
    main()

