class Griddle:
    def __init__(self):
        self.temperature = 300
        self.clean = True

    def heat_for(self, burger_count):
        self.temperature += burger_count * 5
        return self.temperature

    def is_overheated(self):
        return self.temperature > 350

    def soil(self):
        self.clean = False

    def status_line(self):
        condition = "clean" if self.clean else "dirty"
        return "Griddle at {0}F and {1}".format(self.temperature, condition)


class TipJar:
    def __init__(self):
        self.money = 0

    def tip_for_served(self, served):
        self.money += served * 5
        return self.money

    def status_line(self):
        return "Tip jar holds ${0}".format(self.money)


class FoodTruck:
    BURN_LOSS = 2
    COMPLEX_THRESHOLD = 5

    def __init__(self):
        self.griddle = Griddle()
        self.tip_jar = TipJar()
        self.served_total = 0
        self.burned_total = 0

    def parse_order(self, order):
        burger_count, complexity = order
        if burger_count < 0:
            raise ValueError("burger count cannot be negative: {0}".format(burger_count))
        return burger_count, complexity

    def handle_order(self, order):
        burger_count, complexity = self.parse_order(order)
        self.griddle.heat_for(burger_count)
        if self.griddle.is_overheated():
            burned = min(self.BURN_LOSS, burger_count)
            self.burned_total += burned
            burger_count -= burned
        self.served_total += burger_count
        self.tip_jar.tip_for_served(burger_count)
        if complexity > self.COMPLEX_THRESHOLD:
            self.griddle.soil()

    def run(self, orders):
        for order in orders:
            self.handle_order(order)
        return self.result()

    def result(self):
        return (self.tip_jar.money, self.griddle.temperature, self.griddle.clean)

    def report(self):
        return "\n".join([
            "Served {0} burgers, burned {1}".format(self.served_total, self.burned_total),
            self.griddle.status_line(),
            self.tip_jar.status_line(),
        ])


def cook(orders):
    truck = FoodTruck()
    return truck.run(orders)


def main():
    orders = [[3, 4], [10, 6]]
    truck = FoodTruck()
    print(truck.run(orders))
    print(truck.report())
    print(cook([[1, 2]]))


if __name__ == "__main__":
    main()

