class SpinnerHead:
    MIN_SPEED = 0
    MAX_SPEED = 15

    def __init__(self):
        self.speed = 0
        self.total_sugar = 0

    def change_speed(self, delta):
        target = self.speed + delta
        self.speed = min(self.MAX_SPEED, max(self.MIN_SPEED, target))
        return self.speed

    def spin_for(self, duration):
        self.total_sugar += self.speed * duration
        return self.total_sugar

    def describe(self):
        return "head: speed={} sugar={}".format(self.speed, self.total_sugar)


class HeatElement:
    MIN_TEMP = 0
    MAX_TEMP = 12

    def __init__(self):
        self.temperature = 0

    def change_heat(self, delta):
        target = self.temperature + delta
        self.temperature = min(self.MAX_TEMP, max(self.MIN_TEMP, target))
        return self.temperature

    def describe(self):
        return "heat: temp={}".format(self.temperature)


class CottonCandyMachine:
    def __init__(self):
        self.head = SpinnerHead()
        self.element = HeatElement()
        self.log = []

    def parse_adjustment(self, adjustment):
        values = list(adjustment)
        if len(values) != 3:
            raise ValueError("each adjustment needs speed, heat and duration")
        speed_change, heat_change, duration = values
        if duration < 0:
            raise ValueError("duration cannot be negative")
        return speed_change, heat_change, duration

    def apply(self, adjustment):
        speed_change, heat_change, duration = self.parse_adjustment(adjustment)
        self.head.change_speed(speed_change)
        self.element.change_heat(heat_change)
        self.head.spin_for(duration)
        self.log.append(self.status())

    def run(self, adjustments):
        for adjustment in adjustments:
            self.apply(adjustment)
        return self.state()

    def state(self):
        return (self.head.speed, self.element.temperature, self.head.total_sugar)

    def status(self):
        return "{} | {}".format(self.head.describe(), self.element.describe())

    def report(self):
        lines = ["step {}: {}".format(i + 1, entry) for i, entry in enumerate(self.log)]
        lines.append("final: {}".format(self.status()))
        return "\n".join(lines)


def spin(adjustments):
    machine = CottonCandyMachine()
    return machine.run(adjustments)


def main():
    machine = CottonCandyMachine()
    machine.run([[5, 2, 10], [-2, -1, 5]])
    print(machine.report())
    print(spin([[5, 2, 10], [-2, -1, 5]]))


if __name__ == "__main__":
    main()

