class TensionSensor:
    def __init__(self):
        self.peak = 0
        self.current = 0

    def apply(self, delta):
        self.current += delta
        if self.current < 0:
            self.current = 0
        if self.current > self.peak:
            self.peak = self.current
        return self.current

    def release(self):
        self.current = 0

    def exceeds(self, limit):
        return self.current > limit


class TowHook:
    def __init__(self):
        self.is_open = False
        self.reason = "closed"

    def release(self, reason):
        self.is_open = True
        self.reason = reason

    def describe(self):
        if self.is_open:
            return "open ({0})".format(self.reason)
        return "closed"


class TowSystem:
    def __init__(self, safety_limit=500, manual_signal=999):
        self.hook = TowHook()
        self.sensor = TensionSensor()
        self.safety_limit = safety_limit
        self.manual_signal = manual_signal
        self.phases_applied = 0

    def process(self, change):
        if not isinstance(change, int):
            raise TypeError("phase tension change must be an integer")
        if self.hook.is_open:
            self.sensor.release()
            return
        self.phases_applied += 1
        if change == self.manual_signal:
            self.hook.release("manual signal")
            self.sensor.release()
            return
        self.sensor.apply(change)
        if self.sensor.exceeds(self.safety_limit):
            self.hook.release("safety limit exceeded")
            self.sensor.release()

    def run(self, phases):
        for change in phases:
            self.process(change)
        return self.result()

    def result(self):
        return (self.hook.is_open, self.sensor.peak, self.sensor.current)

    def report(self):
        return "hook {0} | phases applied {1} | peak {2} | current {3}".format(
            self.hook.describe(), self.phases_applied,
            self.sensor.peak, self.sensor.current)


def tow(phases):
    return TowSystem().run(phases)


def main():
    for phases in ([100, 50, 400, 50], [200, -300, 100], [50, 999, 100]):
        system = TowSystem()
        print(phases, "->", system.run(phases))
        print("   ", system.report())


if __name__ == "__main__":
    main()

