class CoinChute:
    QUARTER = 25
    REQUIRED = 4

    def __init__(self):
        self.collected = 0
        self.rejected = []

    def insert(self, value):
        if value == self.QUARTER:
            self.collected += 1
            return True
        self.rejected.append(value)
        return False

    def is_satisfied(self):
        return self.collected >= self.REQUIRED

    def reset(self):
        self.collected = 0

    def rejected_total(self):
        return sum(self.rejected)


class Trapdoor:
    def __init__(self):
        self.state = "closed"
        self.games = 0

    def open(self):
        self.state = "open"
        self.games += 1

    def pull(self):
        if self.state == "open":
            self.state = "closed"
            return True
        return False


class PoolTable:
    def __init__(self):
        self.chute = CoinChute()
        self.door = Trapdoor()
        self.log = []

    def handle(self, coin):
        if coin == "pull":
            if self.door.pull():
                self.log.append("balls released")
            else:
                self.log.append("pull ignored, trapdoor closed")
            return
        if self.chute.insert(coin):
            self.log.append("accepted %d" % coin)
            if self.chute.is_satisfied():
                self.door.open()
                self.chute.reset()
