class CoinChute:
    QUARTER = 25
    REQUIRED = 4

    def __init__(this):
        this.collected = 0
        this.rejected = []

    def insert(this, value):
        if value == this.QUARTER:
            this.collected += 1
            return True
        this.rejected.append(value)
        return False

    def is_satisfied(this):
        return this.collected >= this.REQUIRED

    def reset(this):
        this.collected = 0

    def rejected_total(this):
        return sum(this.rejected)


class Trapdoor:
    def __init__(this):
        this.state = "closed"
        this.games = 0

    def open(this):
        this.state = "open"
        this.games += 1

    def pull(this):
        if this.state == "open":
            this.state = "closed"
            return True
        return False


class PoolTable:
    def __init__(this):
        this.chute = CoinChute()
        this.door = Trapdoor()
        this.log = []

    def handle(this, coin):
        if coin == "pull":
            if this.door.pull():
                this.log.append("balls released")
            else:
                this.log.append("pull ignored, trapdoor closed")
            return
        if this.chute.insert(coin):
            this.log.append("accepted %d" % coin)
            if this.chute.is_satisfied():
                this.door.open()
                this.chute.reset()
                this.log.append("trapdoor open, game %d" % this.door.games)
        else:
            this.log.append("rejected %s" % coin)

    def run(this, coins):
        for coin in coins:
            this.handle(coin)
