def tidy(value):
    return int(value) if float(value).is_integer() else value


class DriveTrack:
    def __init__(self):
        self.total_distance = 0
        self.battery_level = 100

    def has_power(self):
        return self.battery_level > 0

    def move(self, length):
        if not self.has_power():
            return False
        self.total_distance += length
        self.battery_level -= length / 2
        return True

    def drain(self, amount):
        self.battery_level -= amount


class CleaningBrush:
    def __init__(self, track):
        self.track = track
        self.dirt_collected = 0
        self.active = True

    def collect(self, dirt):
        if not self.active:
            return 0
        self.dirt_collected += dirt
        self.track.drain(dirt / 5)
        return dirt

    def shut_down(self):
        self.active = False


class GutterRobot:
    def __init__(self):
        self.track = DriveTrack()
        self.brush = CleaningBrush(self.track)
        self.sections_done = 0

    def parse_sections(self, sections):
        parsed = []
        for entry in sections:
            length, dirt = entry
            if length < 0 or dirt < 0:
                raise ValueError("section length and dirt must be non-negative")
            parsed.append((length, dirt))
        return parsed

    def sweep_section(self, length, dirt):
        if not self.track.move(length):
            return False
        self.brush.collect(dirt)
        self.sections_done += 1
        return True

    def run(self, sections):
        for length, dirt in self.parse_sections(sections):
            if not self.track.has_power():
                self.brush.shut_down()
                break
            self.sweep_section(length, dirt)
            if not self.track.has_power():
                self.brush.shut_down()
                break
        return self.totals()

    def totals(self):
        return (tidy(self.track.total_distance),
                tidy(self.brush.dirt_collected),
                tidy(self.track.battery_level))

    def report(self):
        distance, dirt, battery = self.totals()
        state = "brush active" if self.brush.active else "brush stopped"
        return ("swept {0} section(s): {1} units of gutter, {2} units of dirt, "
                "battery {3}% ({4})").format(self.sections_done, distance, dirt,
                                             battery, state)


def clean(sections):
    robot = GutterRobot()
    return robot.run(sections)


if __name__ == "__main__":
    print(clean([[10, 20], [20, 10]]))
    long_job = GutterRobot()
    long_job.run([[40, 60], [50, 80], [30, 40], [20, 10]])
    print(long_job.report())

