class Pegbox:
    """Holds the pegs; gears wear out as the instrument is played."""

    def __init__(self):
        self.gear_wear = 0
        self.slip_threshold = 50

    def wear_gears(self):
        self.gear_wear += 1
        return self.gear_wear

    def is_slipping(self):
        return self.gear_wear > self.slip_threshold


class ViolinString:
    """A single string with a pitch in hertz and a tension reading."""

    def __init__(self):
        self.pitch = 400
        self.tension = 10

    def tighten(self):
        self.tension += 2
        self.pitch += 5

    def loosen(self):
        self.tension -= 1
        self.pitch -= 3

    def slip(self):
        self.pitch -= 10
        self.tension -= 5

    def reading(self):
        return self.pitch, self.tension


class Tuner:
    """Applies tuning actions to a pegbox/string pair."""

    def __init__(self, pegbox, string):
        self.pegbox = pegbox
        self.string = string
        self.handlers = {
            "tighten": self.do_tighten,
            "loosen": self.string.loosen,
            "play": self.pegbox.wear_gears,
        }

    def do_tighten(self):
        if self.pegbox.is_slipping():
            self.string.slip()
        else:
            self.string.tighten()

    def apply(self, action):
        handler = self.handlers.get(action)
        if handler is None:
            raise ValueError("unknown tuning action: {!r}".format(action))
        handler()

    def run(self, actions):
        for action in actions:
            self.apply(action)
        return self.state()

    def state(self):
        pitch, tension = self.string.reading()
        return pitch, tension, self.pegbox.gear_wear

    def report(self):
        pitch, tension, wear = self.state()
        return "pitch={0}Hz tension={1} wear={2}/{3}".format(
            pitch, tension, wear, self.pegbox.slip_threshold
        )


def tune(actions):
    return Tuner(Pegbox(), ViolinString()).run(actions)


def main():
    tuner = Tuner(Pegbox(), ViolinString())
    print(tuner.run(["tighten", "play", "tighten"]))
    print(tuner.report())
    print(tune(["play"] * 51 + ["tighten", "loosen"]))


if __name__ == "__main__":
    main()

