class Agitator:
    def __init__(self):
        self.speed = 0

    def set_speed(self, speed):
        if speed < 0:
            raise ValueError("agitator speed cannot be negative")
        self.speed = speed
        return self.speed

    def is_running(self):
        return self.speed > 0

    def describe(self):
        if self.is_running():
            return "agitator turning at {} rpm".format(self.speed)
        return "agitator at rest"


class CheeseVat:
    def __init__(self, agitator):
        self.milk_volume = 500
        self.rennet_added = False
        self.curd_firmness = 0
        self.agitator = agitator

    def add_rennet(self):
        self.rennet_added = True
        return self.rennet_added

    def wait(self, minutes):
        if minutes < 0:
            raise ValueError("wait time cannot be negative")
        if self.rennet_added:
            if self.agitator.is_running():
                self.curd_firmness -= minutes
            else:
                self.curd_firmness += minutes * 2
        return self.curd_firmness

    def state(self):
        return (self.curd_firmness, self.agitator.speed, self.rennet_added)

    def report(self):
        return "{} L milk, firmness {}, rennet {}, {}".format(
            self.milk_volume,
            self.curd_firmness,
            "added" if self.rennet_added else "not added",
            self.agitator.describe(),
        )


class CoagulationRun:
    def __init__(self, steps):
        self.steps = steps
        self.agitator = Agitator()
        self.vat = CheeseVat(self.agitator)

    def parse(self, step):
        parts = str(step).split()
        if not parts:
            raise ValueError("empty step")
        action = parts[0].lower()
        if len(parts) == 1:
            return action, None
        if len(parts) > 2:
            raise ValueError("malformed step: {!r}".format(step))
        return action, int(parts[1])

    def apply(self, step):
        action, value = self.parse(step)
        if action == "stir":
            self.agitator.set_speed(value if value is not None else 0)
        elif action == "rennet":
            self.vat.add_rennet()
        elif action == "wait":
            self.vat.wait(value if value is not None else 0)
        else:
            raise ValueError("unknown step: {!r}".format(action))

    def execute(self):
        for step in self.steps:
            self.apply(step)
        return self.vat.state()

    def summary(self):
        firmness, speed, rennet = self.execute()
        return "after {} steps -> {} | result {}".format(
            len(self.steps), self.vat.report(), (firmness, speed, rennet)
        )


def coagulate(steps):
    return CoagulationRun(steps).execute()


def main():
    recipe = ["rennet", "stir 0", "wait 10", "stir 5"]
    print(coagulate(recipe))
    print(CoagulationRun(recipe).summary())


if __name__ == "__main__":
    main()

