class Bellows:
    """Foot pump bellows holding the air pressure that drives the action."""

    IDLE_CHARGE = 20
    PUMP_CHARGE = 40

    def __init__(self, pressure=50):
        self.pressure = pressure
        self.pump_actions = 0

    def can_supply(self, holes):
        return self.pressure > holes

    def draw(self, holes):
        self.pressure -= holes

    def pump(self):
        self.pressure += self.PUMP_CHARGE
        self.pump_actions += 1

    def idle_charge(self):
        self.pressure += self.IDLE_CHARGE


class ReadingBar:
    """Pneumatic reading bar counting struck notes and scrolled paper."""

    def __init__(self):
        self.notes_struck = 0
        self.paper_scrolled = 0

    def strike(self, holes):
        self.notes_struck += holes
        self.paper_scrolled += 1

    def tally(self):
        return self.notes_struck, self.paper_scrolled


class PlayerPiano:
    def __init__(self):
        self.bellows = Bellows()
        self.bar = ReadingBar()

    def validate(self, perforations):
        for index, holes in enumerate(perforations):
            if not isinstance(holes, int) or isinstance(holes, bool):
                raise TypeError("step %d is not an integer: %r" % (index, holes))
            if holes < 0:
                raise ValueError("step %d has negative holes: %d" % (index, holes))
        return list(perforations)

    def step(self, holes):
        if holes == 0:
            self.bellows.idle_charge()
            return
        while not self.bellows.can_supply(holes):
            self.bellows.pump()
        self.bellows.draw(holes)
        self.bar.strike(holes)

    def run(self, perforations):
        for holes in self.validate(perforations):
            self.step(holes)
        return self.result()

    def result(self):
        notes, scrolled = self.bar.tally()
        return notes, scrolled, self.bellows.pressure

    def report(self):
        notes, scrolled, pressure = self.result()
        return ("notes struck: %d | paper scrolled: %d | air pressure: %d "
                "| pump actions: %d" % (notes, scrolled, pressure,
                                        self.bellows.pump_actions))


def play(perforations):
    return PlayerPiano().run(perforations)


def main():
    roll = [2, 5, 0, 4]
    piano = PlayerPiano()
    print(piano.run(roll))
    print(piano.report())


if __name__ == "__main__":
    main()

