class Barometer:
    def __init__(self, altitude=10000.0):
        self.altitude = float(altitude)
        self.descent_rate = 0.0

    def register(self, reading):
        self.descent_rate = self.altitude - reading
        self.altitude = reading
        return self.descent_rate

    def is_below(self, limit):
        return self.altitude < limit

    def falling_faster_than(self, limit):
        return self.descent_rate > limit


class DeploymentSwitch:
    def __init__(self):
        self.deployed = False
        self.reserve_deployed = False

    def deploy_main(self):
        self.deployed = True

    def deploy_reserve(self):
        self.reserve_deployed = True

    def state(self):
        return self.deployed, self.reserve_deployed


class Altimeter:
    def __init__(self, start_altitude=10000.0):
        self.barometer = Barometer(start_altitude)
        self.switch = DeploymentSwitch()
        self.log = []

    def validate(self, readings):
        clean = []
        for reading in readings:
            if not isinstance(reading, (int, float)) or isinstance(reading, bool):
                raise TypeError("altitude readings must be numeric: %r" % (reading,))
            clean.append(float(reading))
        return clean

    def step(self, reading):
