MORSE = {
    'a': '.-', 'b': '-...', 'c': '-.-.', 'd': '-..', 'e': '.', 'f': '..-.',
    'g': '--.', 'h': '....', 'i': '..', 'j': '.---', 'k': '-.-', 'l': '.-..',
    'm': '--', 'n': '-.', 'o': '---', 'p': '.--.', 'q': '--.-', 'r': '.-.',
    's': '...', 't': '-', 'u': '..-', 'v': '...-', 'w': '.--', 'x': '-..-',
    'y': '-.--', 'z': '--..',
}
CODE_TO_LETTER = {code: letter for letter, code in MORSE.items()}


class TelegraphLine:
    def __init__(self, line_id):
        self.line_id = line_id
        self.buffer = []
        self.current_word = []
        self.words = []

    def add_dot(self):
        self.buffer.append('.')

    def add_dash(self):
        self.buffer.append('-')

    def resolve_letter(self):
        if self.buffer:
            code = ''.join(self.buffer)
            self.current_word.append(CODE_TO_LETTER.get(code, '?'))
            self.buffer.clear()

    def resolve_word(self):
        self.resolve_letter()
        if self.current_word:
            self.words.append(''.join(self.current_word))
            self.current_word = []

    def receive(self, kind):
        if kind == 'short':
            self.add_dot()
        elif kind == 'long':
            self.add_dash()
        elif kind == 'pause':
            self.resolve_letter()
        elif kind == 'long_pause':
            self.resolve_word()
        else:
            raise ValueError('line %r got unknown pulse %r' % (self.line_id, kind))

    def sentence(self):
        self.resolve_word()
        return ' '.join(self.words)


class RelayStation:
    def __init__(self):
        self.lines = {}

    def line_for(self, line_id):
        if not isinstance(line_id, int):
            raise TypeError('line identifier must be an integer, got %r' % (line_id,))
        if line_id not in self.lines:
            self.lines[line_id] = TelegraphLine(line_id)
        return self.lines[line_id]

    def route(self, pulse):
        line_id, kind = pulse
        self.line_for(line_id).receive(kind)

    def transmit(self, pulses):
        for pulse in pulses:
            self.route(pulse)
        return self.sentences()

    def sentences(self):
        return [self.lines[line_id].sentence() for line_id in sorted(self.lines)]

    def report(self):
        return '\n'.join('line %d: %s' % (line_id, self.lines[line_id].sentence())
                         for line_id in sorted(self.lines))


def relay(pulses):
    station = RelayStation()
    return station.transmit(pulses)


def main():
    station = RelayStation()
    station.transmit([(1, 'short'), (1, 'long'), (1, 'long_pause'),
                      (2, 'long'), (2, 'pause'), (2, 'short'), (2, 'pause'),
                      (1, 'short'), (1, 'short'), (1, 'short')])
    print(station.report())


if __name__ == '__main__':
    main()

