class Spring:
    """Stores the wound-up energy that drives the escapement."""

    def __init__(self, capacity=100.0):
        self.capacity = float(capacity)
        self.energy = 0.0

    def wind(self, amount):
        if amount < 0:
            raise ValueError("cannot wind a negative amount")
        self.energy = min(self.capacity, self.energy + float(amount))
        return self.energy

    def draw(self, amount):
        if amount > self.energy:
            return False
        self.energy -= amount
        return True

    def is_empty(self):
        return self.energy <= 0.0


class Pendulum:
    """Sliding weight on the rod: higher weight means a slower beat."""

    MIN_BPM = 40
    MAX_BPM = 208
    BPM_PER_NOTCH = 8

    def __init__(self, tempo=120):
        self.tempo = self.clamp(tempo)

    def clamp(self, bpm):
        return max(self.MIN_BPM, min(self.MAX_BPM, int(bpm)))

    def slide_up(self, notches):
        self.tempo = self.clamp(self.tempo - notches * self.BPM_PER_NOTCH)
        return self.tempo

    def slide_down(self, notches):
        self.tempo = self.clamp(self.tempo + notches * self.BPM_PER_NOTCH)
        return self.tempo


class Metronome:
    """Couples the spring and the pendulum and emits tick sounds."""

    def __init__(self, capacity=100.0, tempo=120):
        self.spring = Spring(capacity)
        self.pendulum = Pendulum(tempo)
        self.running = False
        self.sounds = []

    def wind(self, amount):
        self.spring.wind(amount)
        self.running = not self.spring.is_empty()

    def move_weight(self, direction, notches=1):
        if direction == "up":
            return self.pendulum.slide_up(notches)
        if direction == "down":
            return self.pendulum.slide_down(notches)
        raise ValueError("unknown direction: %r" % (direction,))

    def tick(self):
        if not self.running:
            return False
        cost = self.pendulum.tempo / 60.0
        if not self.spring.draw(cost):
            self.running = False
            return False
        self.sounds.append("tick@%dbpm" % self.pendulum.tempo)
        return True

    def report(self):
        return "%d ticks, %.2f energy left, tempo %d bpm, %s" % (
            len(self.sounds),
            self.spring.energy,
            self.pendulum.tempo,
            "running" if self.running else "stopped",
        )


class ActionRunner:
    """Applies a sequence of (command, *args) actions to a metronome."""

    def __init__(self, metronome):
        self.metronome = metronome
        self.successful_ticks = 0

    def parse(self, action):
        if isinstance(action, str):
            return action, ()
        command = action[0]
        return command, tuple(action[1:])

    def apply(self, action):
        command, args = self.parse(action)
        if command == "wind":
            self.metronome.wind(args[0] if args else 10)
        elif command in ("up", "down"):
            self.metronome.move_weight(command, args[0] if args else 1)
        elif command == "move":
            self.metronome.move_weight(args[0], args[1] if len(args) > 1 else 1)
        elif command == "tick":
            if self.metronome.tick():
                self.successful_ticks += 1
        else:
            raise ValueError("unknown action: %r" % (command,))

    def run(self, actions):
        for action in actions:
            self.apply(action)
        return self.successful_ticks


def tick(actions):
    runner = ActionRunner(Metronome())
    return runner.run(actions)


if __name__ == "__main__":
    fast = [("wind", 10), ("down", 11)] + ["tick"] * 20
    slow = [("wind", 10), ("up", 10)] + ["tick"] * 20
    print("fast tempo ticks:", tick(fast))
    print("slow tempo ticks:", tick(slow))
    machine = Metronome()
    driver = ActionRunner(machine)
    driver.run(slow)
    print(machine.report())

