import math


class GearTrain:
    """A gear train driven by the main wheel through a fixed ratio."""

    def __init__(self, name, ratio):
        self.name = name
        self.ratio = ratio
        self.angle = 0.0
        self.travelled = 0.0

    def advance(self, drive_degrees):
        turned = drive_degrees * self.ratio
        self.travelled += turned
        position = self.angle + turned
        self.angle = position % 360.0
        return self.angle

    def indicated(self):
        return self.angle

    def rotations(self):
        return self.travelled / 360.0

    def describe(self):
        return "{:<6} {:7.2f} deg  ({:+.3f} rotations)".format(
            self.name, self.indicated(), self.rotations())


class MoonTrain(GearTrain):
    """Lunar train whose pin-and-slot device models an elliptical orbit."""

    def __init__(self, name, ratio, apsidal_ratio, eccentricity):
        super().__init__(name, ratio)
        self.apsidal_ratio = apsidal_ratio
        self.eccentricity = eccentricity
        self.apsis_angle = 0.0

    def advance(self, drive_degrees):
        apsis = self.apsis_angle + drive_degrees * self.apsidal_ratio
        self.apsis_angle = apsis % 360.0
        return super().advance(drive_degrees)

    def anomaly(self):
        offset = self.angle - self.apsis_angle
        return math.radians(offset)

    def indicated(self):
        wobble = math.degrees(2.0 * self.eccentricity * math.sin(self.anomaly()))
        return (self.angle + wobble) % 360.0


class Mechanism:
    """The main drive wheel and every celestial pointer it carries."""

    def __init__(self, drive_teeth=223):
        self.drive_teeth = drive_teeth
        self.drive_angle = 0.0
        self.trains = [
            GearTrain("sun", 1.0),
            MoonTrain("moon", 254.0 / 19.0, -1.0 / 8.85, 0.0549),
            GearTrain("saros", 1.0 / 18.03),
        ]

    def degrees_per_tooth(self):
        return 360.0 / self.drive_teeth

    def turn(self, teeth):
        drive_degrees = teeth * self.degrees_per_tooth()
        position = self.drive_angle + drive_degrees
        self.drive_angle = position % 360.0
        for train in self.trains:
            train.advance(drive_degrees)
        return self.drive_angle

    def positions(self):
        readings = {"drive": round(self.drive_angle, 4)}
        for train in self.trains:
            readings[train.name] = round(train.indicated(), 4)
        return readings

    def report(self):
        header = "drive  {:7.2f} deg  ({} teeth per turn)".format(
            self.drive_angle, self.drive_teeth)
        lines = [header]
        lines.extend(train.describe() for train in self.trains)
        return "\n".join(lines)


def antikythera(turns):
    mechanism = Mechanism()
    for teeth in turns:
        if not isinstance(teeth, (int, float)) or isinstance(teeth, bool):
            raise TypeError("each turn must be a number of teeth: {!r}".format(teeth))
        mechanism.turn(teeth)
    return mechanism.positions()


if __name__ == "__main__":
    year = Mechanism()
    year.turn(year.drive_teeth)
    print("after one full year of drive:")
    print(year.report())
    print("\nsequence of turns:", antikythera([100, 50, -25, 223, 223]))

