import math


class Oscillator:
    WAVEFORMS = ("sine", "square", "triangle", "saw")

    def __init__(self, waveform, frequency, sample_rate):
        if waveform not in self.WAVEFORMS:
            raise ValueError("unknown waveform: %r" % (waveform,))
        self.waveform = waveform
        self.sample_rate = sample_rate
        self.phase = 0.0
        self.muted = False
        self.set_frequency(frequency)

    def set_frequency(self, frequency):
        if frequency < 0.0 or frequency * 2.0 > self.sample_rate:
            raise ValueError("frequency out of range: %r" % (frequency,))
        self.frequency = float(frequency)

    def set_muted(self, flag):
