class Tooth:
    """A single tuned tooth of the comb."""

    def __init__(self, note, fatigue_limit=3):
        self.note = note
        self.fatigue_limit = fatigue_limit
        self.fatigue = 0
        self.broken = False

    def pluck(self):
        if self.broken:
            return None
        self.fatigue += 1
        if self.fatigue > self.fatigue_limit:
            self.broken = True
            return None
        return self.note

    def status(self):
        state = "broken" if self.broken else "sound"
        return "{0}: fatigue {1}/{2} ({3})".format(
            self.note, self.fatigue, self.fatigue_limit, state)


class Comb:
    """The tuned metal comb: a set of teeth addressed by note name."""

    def __init__(self, specs):
        self.teeth = {}
        for note, limit in specs:
            self.teeth[note] = Tooth(note, limit)

    def strike(self, note):
        tooth = self.teeth.get(note)
        if tooth is None:
            return None
        return tooth.pluck()

    def broken_notes(self):
        return sorted(note for note, tooth in self.teeth.items() if tooth.broken)

    def describe(self):
        return [self.teeth[note].status() for note in sorted(self.teeth)]


class Cylinder:
    """The pinned cylinder; each rotational step carries zero or more pins."""

    def __init__(self, layout):
        self.layout = layout
        self.angle = 0

    def advance(self):
        pins = self.layout[self.angle % len(self.layout)]
        self.angle += 1
        return pins


class MusicBox:
    def __init__(self, comb, cylinder):
        self.comb = comb
        self.cylinder = cylinder
        self.sounded = []

    def step(self):
        for note in self.cylinder.advance():
            tone = self.comb.strike(note)
            if tone is not None:
                self.sounded.append(tone)

    def run(self, rotations):
        for _ in range(rotations):
            self.step()
        return list(self.sounded)

    def report(self):
        lines = self.comb.describe()
        lines.append("notes played: " + " ".join(self.sounded))
        lines.append("broken teeth: " + (", ".join(self.comb.broken_notes()) or "none"))
        return "\n".join(lines)


LAYOUT = [["C"], ["E", "G"], ["C"], [], ["C", "E"], ["C"]]
COMB_SPECS = [("C", 4), ("E", 3), ("G", 2)]


def play(rotations):
    box = MusicBox(Comb(COMB_SPECS), Cylinder(LAYOUT))
    return box.run(rotations)


def main():
    box = MusicBox(Comb(COMB_SPECS), Cylinder(LAYOUT))
    box.run(12)
    print(box.report())
    print("two rotations:", play(2))


if __name__ == "__main__":
    main()

