from string import ascii_lowercase


class CastingFailure(Exception):
    """Raised when a line cannot be completed or cast."""


class OutOfMatrices(CastingFailure):
    pass


class LeadDepleted(CastingFailure):
    pass


class Magazine:
    def __init__(self, copies=4):
        self.copies = copies
        self.molds = {letter: copies for letter in ascii_lowercase}

    def take(self, letter):
        if self.molds.get(letter, 0) <= 0:
            raise OutOfMatrices("no matrix left for %r" % letter)
        self.molds[letter] -= 1

    def restore(self, letters):
        for letter in letters:
            self.molds[letter] += 1

    def stock_report(self):
        missing = sorted(l for l, n in self.molds.items() if n < self.copies)
        return "magazine short of: " + (", ".join(missing) if missing else "nothing")


class Crucible:
    def __init__(self, mass_grams=120.0, grams_per_mold=2.5):
        self.mass = mass_grams
        self.grams_per_mold = grams_per_mold

    def pour(self, mold_count):
        needed = mold_count * self.grams_per_mold
        if needed > self.mass:
            raise LeadDepleted("only %.1f g of lead left" % self.mass)
        self.mass -= needed
        return needed


class AssemblyLine:
    def __init__(self, magazine, width=20):
        self.magazine = magazine
        self.width = width
        self.molds = []
        self.words = []

    def is_empty(self):
        return not self.words

    def fits(self, word):
        gap = 1 if self.words else 0
        return len(self.text()) + gap + len(word) <= self.width

    def text(self):
        return " ".join(self.words)

    def feed(self, word):
        if not self.fits(word):
            raise CastingFailure("%r does not fit a %d-em line" % (word, self.width))
        for letter in word:
            self.magazine.take(letter)
            self.molds.append(letter)
        self.words.append(word)

    def discard(self):
        self.magazine.restore(self.molds)
        self.molds = []
        self.words = []

    def cast(self, crucible):
        slug = self.text()
        lead = crucible.pour(len(self.molds))
        self.discard()
        return slug, lead


class TypesettingMachine:
    def __init__(self, copies=4, width=20, mass_grams=120.0):
        self.magazine = Magazine(copies)
        self.crucible = Crucible(mass_grams)
        self.line = AssemblyLine(self.magazine, width)
        self.failures = []
        self.lead_used = 0.0

    def _normalize(self, raw):
        word = str(raw).strip().lower()
        if not word.isalpha():
            raise ValueError("not typesettable: %r" % (raw,))
        return word

    def _cast(self):
        try:
            slug, lead = self.line.cast(self.crucible)
        except CastingFailure as failure:
            self.failures.append("%r: %s" % (self.line.text(), failure))
            self.line.discard()
            return None
        self.lead_used += lead
        return slug

    def typeset(self, words):
        slugs = []
        for raw in words:
            word = self._normalize(raw)
            if not self.line.is_empty() and not self.line.fits(word):
                slug = self._cast()
                if slug is not None:
                    slugs.append(slug)
            try:
                self.line.feed(word)
            except CastingFailure as failure:
                self.failures.append("%s: %s" % (word, failure))
                self.line.discard()
        if not self.line.is_empty():
            slug = self._cast()
            if slug is not None:
                slugs.append(slug)
        return slugs

    def summary(self):
        return "%d failed line(s), %.1f g lead poured, %.1f g remaining; %s" % (
            len(self.failures), self.lead_used, self.crucible.mass,
            self.magazine.stock_report(),
        )


def typeset(words):
    return TypesettingMachine().typeset(words)


def main():
    copy = ["the", "quick", "brown", "fox", "aaaaa", "jumps", "over", "lazy", "dogs"]
    machine = TypesettingMachine()
    for slug in machine.typeset(copy):
        print("|%s|" % slug)
    for failure in machine.failures:
        print("FAILED", failure)
    print(machine.summary())


if __name__ == "__main__":
    main()

