class LiftLine:
    def __init__(self, name, weight, grid_height=30.0):
        self.name = name
        self.weight = float(weight)
        self.grid_height = float(grid_height)
        self.height = 0.0

    def move(self, direction, distance):
        if direction == "up":
            target = min(self.height + distance, self.grid_height)
        elif direction == "down":
            target = max(self.height - distance, 0.0)
        else:
            raise ValueError("unknown direction: %s" % direction)
        travelled = abs(target - self.height)
        self.height = target
        return travelled

    def describe(self):
        return "%s (%glb) at %gft" % (self.name, self.weight, self.height)


class Arbor:
    def __init__(self, capacity=2000.0):
        self.capacity = float(capacity)
        self.loaded = 0.0

    def add(self, amount):
        if self.loaded + amount > self.capacity:
            raise ValueError("arbor capacity %g exceeded" % self.capacity)
        self.loaded += amount
        return self.loaded

    def remove(self, amount):
        if amount > self.loaded:
            raise ValueError("only %g lb on the arbor" % self.loaded)
        self.loaded -= amount
        return self.loaded

    def balances(self, weight):
        return abs(self.loaded - weight) < 1e-9


class RiggingSystem:
    def __init__(self, arbor_capacity=2000.0):
        self.arbor = Arbor(arbor_capacity)
        self.lines = {}
        self.failures = []

    def register(self, name, weight):
        self.lines[name] = LiftLine(name, weight)

    def pull(self, name, direction, distance):
        line = self.lines[name]
        if not self.arbor.balances(line.weight):
            self.failures.append("%s: imbalance (arbor %gvs scenery %g)"
                                 % (name, self.arbor.loaded, line.weight))
            return 0.0
        return line.move(direction, distance)

    def apply(self, cue):
        action = cue[0]
        if action == "line":
            self.register(cue[1], cue[2])
        elif action == "add":
            self.arbor.add(cue[1])
        elif action == "remove":
            self.arbor.remove(cue[1])
        elif action == "pull":
            self.pull(cue[1], cue[2], cue[3])
        else:
            raise ValueError("unknown cue: %s" % action)

    def run(self, cues):
        for cue in cues:
            self.apply(cue)
        return self.heights()

    def heights(self):
        return {name: line.height for name, line in self.lines.items()}

    def report(self):
        rows = [line.describe() for line in self.lines.values()]
        rows.append("arbor: %g lb" % self.arbor.loaded)
        rows.extend("FAILED " + note for note in self.failures)
        return "\n".join(rows)


def rigging(cues):
    return RiggingSystem().run(cues)


if __name__ == "__main__":
    show = [
        ("line", "backdrop", 800),
        ("line", "chandelier", 150),
        ("add", 800),
        ("pull", "backdrop", "up", 25),
        ("pull", "chandelier", "up", 10),
        ("remove", 650),
        ("pull", "chandelier", "up", 12),
        ("pull", "backdrop", "down", 5),
