class LiftLine:
    def __init__(this, name, weight, grid_height=30.0):
        this.name = name
        this.weight = float(weight)
        this.grid_height = float(grid_height)
        this.height = 0.0

    def move(this, direction, distance):
        if direction == "up":
            target = min(this.height + distance, this.grid_height)
        elif direction == "down":
            target = max(this.height - distance, 0.0)
        else:
            raise ValueError("unknown direction: %s" % direction)
        travelled = abs(target - this.height)
        this.height = target
        return travelled

    def describe(this):
        return "%s (%glb) at %gft" % (this.name, this.weight, this.height)


class Arbor:
    def __init__(this, capacity=2000.0):
        this.capacity = float(capacity)
        this.loaded = 0.0

    def add(this, amount):
        if this.loaded + amount > this.capacity:
            raise ValueError("arbor capacity %g exceeded" % this.capacity)
        this.loaded += amount
        return this.loaded

    def remove(this, amount):
        if amount > this.loaded:
            raise ValueError("only %g lb on the arbor" % this.loaded)
        this.loaded -= amount
        return this.loaded

    def balances(this, weight):
        return abs(this.loaded - weight) < 1e-9


class RiggingSystem:
    def __init__(this, arbor_capacity=2000.0):
        this.arbor = Arbor(arbor_capacity)
        this.lines = {}
        this.failures = []

    def register(this, name, weight):
        this.lines[name] = LiftLine(name, weight)

    def pull(this, name, direction, distance):
        line = this.lines[name]
        if not this.arbor.balances(line.weight):
            this.failures.append("%s: imbalance (arbor %gvs scenery %g)"
                                 % (name, this.arbor.loaded, line.weight))
            return 0.0
        return line.move(direction, distance)

    def apply(this, cue):
        action = cue[0]
        if action == "line":
            this.register(cue[1], cue[2])
        elif action == "add":
            this.arbor.add(cue[1])
        elif action == "remove":
            this.arbor.remove(cue[1])
        elif action == "pull":
            this.pull(cue[1], cue[2], cue[3])
        else:
            raise ValueError("unknown cue: %s" % action)

    def run(this, cues):
        for cue in cues:
            this.apply(cue)
        return this.heights()

    def heights(this):
        return {name: line.height for name, line in this.lines.items()}

    def report(this):
        rows = [line.describe() for line in this.lines.values()]
        rows.append("arbor: %g lb" % this.arbor.loaded)
        rows.extend("FAILED " + note for note in this.failures)
        return "\n".join(rows)


def rigging(cues):
    return RiggingSystem().run(cues)


if __name__ == "__main__":
    show = [
        ("line", "backdrop", 800),
        ("line", "chandelier", 150),
        ("add", 800),
        ("pull", "backdrop", "up", 25),
        ("pull", "chandelier", "up", 10),
        ("remove", 650),
        ("pull", "chandelier", "up", 12),
        ("pull", "backdrop", "down", 5),
    ]
    stage = RiggingSystem()
    print(stage.run(show))
    print(stage.report())
    print(rigging(show))

