class PulpVat:
    def __init__(self, water=0.0, fiber=0.0):
        self.water = float(water)
        self.fiber = float(fiber)

    def add(self, water, fiber):
        if water < 0 or fiber < 0:
            raise ValueError("cannot add negative water or fiber")
        self.water += water
        self.fiber += fiber

    def concentration(self):
        if self.water <= 0:
            return 0.0
        return self.fiber / self.water

    def draw(self, volume):
        if volume <= 0:
            raise ValueError("dip volume must be positive")
        taken_water = min(volume, self.water)
        taken_fiber = self.concentration() * taken_water
        self.water -= taken_water
        self.fiber -= taken_fiber
        return taken_water, taken_fiber

    def report(self):
        return "vat: {:.2f} L water, {:.2f} g fiber, {:.3f} g/L".format(
            self.water, self.fiber, self.concentration())


class MoldingFrame:
    def __init__(self, area_cm2=600.0, fiber_density=0.5):
        if area_cm2 <= 0 or fiber_density <= 0:
            raise ValueError("frame area and fiber density must be positive")
        self.area = area_cm2
        self.density = fiber_density
        self.thickness = 0.0

    def form_sheet(self, fiber_grams):
        sheet = fiber_grams / (self.area * self.density) * 10.0
        self.thickness += sheet
        return sheet

    def couch(self):
        removed = self.thickness
        self.thickness = 0.0
        return removed


class PaperMill:
    def __init__(self, vat=None, frame=None):
        self.vat = vat if vat is not None else PulpVat()
        self.frame = frame if frame is not None else MoldingFrame()
        self.sheets = []
        self.log = []

    def run(self, steps):
        for step in steps:
            self.execute(step)
        return list(self.sheets)

    def execute(self, step):
        action = step[0]
        if action == "add":
            self.vat.add(step[1], step[2])
            self.log.append("added {} L / {} g -> {}".format(step[1], step[2], self.vat.report()))
        elif action == "dip":
            self.dip(step[1])
        else:
            raise ValueError("unknown step: {!r}".format(action))

    def dip(self, volume):
        _water, fiber = self.vat.draw(volume)
        self.frame.form_sheet(fiber)
        sheet = self.frame.couch()
        self.sheets.append(sheet)
        self.log.append("dipped {} L -> sheet {:.4f} mm; {}".format(volume, sheet, self.vat.report()))
        return sheet


def papermill(steps):
    return PaperMill().run(steps)


def main():
    mill = PaperMill()
    thicknesses = mill.run([
        ("add", 40.0, 300.0),
        ("dip", 5.0),
        ("dip", 5.0),
        ("dip", 5.0),
        ("add", 10.0, 120.0),
        ("dip", 5.0),
    ])
    for line in mill.log:
        print(line)
    print("sheets:", ["{:.4f}".format(t) for t in thicknesses])


if __name__ == "__main__":
    main()

