class Particle:
    def __init__(self, p_id, mass):
        self.p_id = p_id
        self.mass = mass
        self.threshold = 10000.0 / self.mass

class Motor:
    def __init__(self):
        self.speed = 0.0

    def accelerate(self, amount):
        self.speed += amount

    def brake(self, amount):
        self.speed -= amount
        if self.speed < 0.0:
            self.speed = 0.0

class Drum:
    def __init__(self):
        self.particles = []

    def load(self, particle):
        self.particles.append(particle)

    def eject_particles(self, current_speed):
        ejected = []
        retained = []
        for p in self.particles:
            if current_speed >= p.threshold:
                ejected.append(p)
            else:
                retained.append(p)
        self.particles = retained
        return ejected

class CentrifugeSystem:
    def __init__(self):
        self.motor = Motor()
        self.drum = Drum()
        self.ejection_log = []

    def process_command(self, cmd):
        action = cmd[0]
        if action == "LOAD":
            p = Particle(cmd[1], cmd[2])
            self.drum.load(p)
        elif action == "ACCELERATE":
            self.motor.accelerate(cmd[1])
            self._check_ejections()
        elif action == "BRAKE":
            self.motor.brake(cmd[1])

    def _check_ejections(self):
        ejected = self.drum.eject_particles(self.motor.speed)
        for p in ejected:
            self.ejection_log.append((p.p_id, self.motor.speed))

def centrifuge(commands):
    system = CentrifugeSystem()
    for cmd in commands:
        system.process_command(cmd)
    return system.ejection_log

