class GlassPiece:
    def __init__(self, identifier, temperature, brittleness=0.02):
        self.identifier = identifier
        self.temperature = float(temperature)
        self.brittleness = brittleness
        self.stress = 0.0
        self.position = -1
        self.intact = True

    def advance(self):
        self.position += 1
        return self.position

    def absorb(self, delta):
        self.temperature += delta
        if delta < 0.0:
            self.stress += (-delta) * self.brittleness

    def relieve(self, zone_temperature):
        if zone_temperature >= 450.0:
            self.stress *= 0.70
        else:
            self.stress *= 0.95

    def check_integrity(self, critical_stress):
        if self.stress > critical_stress:
            self.intact = False
        return self.intact

    def describe(self):
        state = "intact" if self.intact else "shattered"
        return "%s: %.0fC stress=%.2f (%s)" % (self.identifier, self.temperature, self.stress, state)


class Zone:
    def __init__(self, index, temperature, transfer_rate):
        self.index = index
        self.temperature = float(temperature)
        self.transfer_rate = transfer_rate

    def equalize(self, piece):
        delta = (self.temperature - piece.temperature) * self.transfer_rate
        piece.absorb(delta)
        piece.relieve(self.temperature)
        return delta

    def label(self):
        return "zone %d @ %.0fC" % (self.index, self.temperature)


class Lehr:
    def __init__(self, zone_temperatures, critical_stress=1.0, transfer_rate=0.35):
        self.zones = [Zone(i, t, transfer_rate) for i, t in enumerate(zone_temperatures)]
        self.critical_stress = critical_stress
        self.belt = []
        self.exited = []
        self.shattered = []

    def load(self, pieces):
        self.belt.extend(pieces)

    def tick(self):
        remaining = []
        for piece in self.belt:
            if piece.advance() >= len(self.zones):
                self.exited.append(piece)
                continue
            self.zones[piece.position].equalize(piece)
            if piece.check_integrity(self.critical_stress):
                remaining.append(piece)
            else:
                self.shattered.append(piece)
        self.belt = remaining

    def run(self):
        while self.belt:
            self.tick()
        return self.survivors()

    def survivors(self):
        return [piece for piece in self.exited if piece.intact]

    def report(self):
        header = "lehr [%s] critical=%.2f" % (", ".join(z.label() for z in self.zones), self.critical_stress)
        lines = [header]
        for piece in self.exited + self.shattered:
            lines.append("  " + piece.describe())
        lines.append("  surviving: %d of %d" % (len(self.survivors()), len(self.exited) + len(self.shattered)))
        return "\n".join(lines)


def anneal(batches):
    total = 0
    for batch in batches:
        lehr = Lehr(batch["zones"], batch.get("critical_stress", 1.0), batch.get("transfer_rate", 0.35))
        lehr.load([GlassPiece(spec[0], spec[1], spec[2] if len(spec) > 2 else 0.02)
                   for spec in batch["pieces"]])
        survivors = lehr.run()
        print(lehr.report())
        total += len(survivors)
    return total


def main():
    batches = [
        {"zones": [560, 520, 470, 420, 360, 280, 180, 80],
         "pieces": [("gentle-A", 600), ("gentle-B", 580), ("gentle-C", 620, 0.03)]},
        {"zones": [600, 120, 25],
         "pieces": [("steep-A", 640), ("steep-B", 610), ("steep-C", 650, 0.04)]},
    ]
    print("total survivors: %d" % anneal(batches))


if __name__ == "__main__":
    main()

