import math


class SunTracker:
    """Computes solar elevation and azimuth for a location."""

    def __init__(self, latitude):
        self.latitude = latitude
        self.lat_rad = math.radians(latitude)

    def declination(self, day):
        return math.radians(23.44 * math.sin(math.radians(360.0 * (284 + day) / 365.0)))

    def hour_angle(self, hour):
        return math.radians(15.0 * (hour - 12.0))

    def elevation(self, day, hour):
        dec = self.declination(day)
        ha = self.hour_angle(hour)
        sin_alt = (math.sin(self.lat_rad) * math.sin(dec) +
                   math.cos(self.lat_rad) * math.cos(dec) * math.cos(ha))
        return math.degrees(math.asin(max(-1.0, min(1.0, sin_alt))))

    def azimuth(self, day, hour):
        dec = self.declination(day)
        ha = self.hour_angle(hour)
        alt = math.radians(self.elevation(day, hour))
        y = -math.sin(ha) * math.cos(dec)
        x = (math.sin(dec) * math.cos(self.lat_rad) -
             math.cos(dec) * math.sin(self.lat_rad) * math.cos(ha))
        if abs(math.cos(alt)) < 1e-9:
            return 0.0
        return math.degrees(math.atan2(y, x)) % 360.0

    def position(self, day, hour):
        return self.elevation(day, hour), self.azimuth(day, hour)


class Sundial:
    """A gnomon of a given height standing at a given latitude."""

    COMPASS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]

    def __init__(self, latitude, gnomon_height):
        if gnomon_height <= 0:
            raise ValueError("gnomon height must be positive")
        self.latitude = latitude
        self.gnomon_height = gnomon_height
        self.tracker = SunTracker(latitude)

    def shadow_length(self, day, hour):
        elevation = self.tracker.elevation(day, hour)
        if elevation <= 0.0:
            return 0.0
        return self.gnomon_height / math.tan(math.radians(elevation))

    def shadow_bearing(self, day, hour):
        return (self.tracker.azimuth(day, hour) + 180.0) % 360.0

    def compass_point(self, bearing):
        index = int(round(bearing / 45.0)) % len(self.COMPASS)
        return self.COMPASS[index]

    def cast(self, day, hour):
        elevation = self.tracker.elevation(day, hour)
        length = self.shadow_length(day, hour)
        if length == 0.0:
            return {"day": day, "hour": hour, "elevation": elevation,
                    "length": 0.0, "direction": None}
        bearing = self.shadow_bearing(day, hour)
        return {"day": day, "hour": hour, "elevation": elevation,
                "length": length, "direction": self.compass_point(bearing)}

    def report(self, times):
        lines = []
        for day, hour in times:
            shadow = self.cast(day, hour)
            if shadow["direction"] is None:
                lines.append("day %3d %05.2fh: sun below horizon" % (day, hour))
            else:
                lines.append("day %3d %05.2fh: %6.2f units toward %s" %
                             (day, hour, shadow["length"], shadow["direction"]))
        return "\n".join(lines)

    def lengths(self, times):
        return [self.cast(day, hour)["length"] for day, hour in times]


def sundial(times):
    dial = Sundial(latitude=45.0, gnomon_height=1.0)
    return dial.lengths(times)


if __name__ == "__main__":
    schedule = [(172, 6), (172, 12), (172, 18), (355, 12), (355, 22)]
    print(Sundial(45.0, 1.0).report(schedule))
    print(sundial(schedule))

