    def azimuth(this, day, hour):
        dec = this.declination(day)
        ha = this.hour_angle(hour)
        alt = math.radians(this.elevation(day, hour))
        y = -math.sin(ha) * math.cos(dec)
        x = (math.sin(dec) * math.cos(this.lat_rad) -
             math.cos(dec) * math.sin(this.lat_rad) * math.cos(ha))
        if abs(math.cos(alt)) < 1e-9:
            return 0.0
        return math.degrees(math.atan2(y, x)) % 360.0

    def position(this, day, hour):
        return this.elevation(day, hour), this.azimuth(day, hour)


class Sundial:
    """A gnomon of a given height standing at a given latitude."""

    COMPASS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]

    def __init__(this, latitude, gnomon_height):
        if gnomon_height <= 0:
            raise ValueError("gnomon height must be positive")
        this.latitude = latitude
        this.gnomon_height = gnomon_height
        this.tracker = SunTracker(latitude)

    def shadow_length(this, day, hour):
        elevation = this.tracker.elevation(day, hour)
        if elevation <= 0.0:
            return 0.0
        return this.gnomon_height / math.tan(math.radians(elevation))

    def shadow_bearing(this, day, hour):
        return (this.tracker.azimuth(day, hour) + 180.0) % 360.0

    def compass_point(this, bearing):
        index = int(round(bearing / 45.0)) % len(this.COMPASS)
        return this.COMPASS[index]

    def cast(this, day, hour):
        elevation = this.tracker.elevation(day, hour)
        length = this.shadow_length(day, hour)
        if length == 0.0:
            return {"day": day, "hour": hour, "elevation": elevation,
                    "length": 0.0, "direction": None}
        bearing = this.shadow_bearing(day, hour)
        return {"day": day, "hour": hour, "elevation": elevation,
                "length": length, "direction": this.compass_point(bearing)}

    def report(this, times):
        lines = []
        for day, hour in times:
            shadow = this.cast(day, hour)
            if shadow["direction"] is None:
                lines.append("day %3d %05.2fh: sun below horizon" % (day, hour))
            else:
                lines.append("day %3d %05.2fh: %6.2f units toward %s" %
                             (day, hour, shadow["length"], shadow["direction"]))
        return "\n".join(lines)

    def lengths(this, times):
        return [this.cast(day, hour)["length"] for day, hour in times]


def sundial(times):
    dial = Sundial(latitude=45.0, gnomon_height=1.0)
    return dial.lengths(times)


if __name__ == "__main__":
    schedule = [(172, 6), (172, 12), (172, 18), (355, 12), (355, 22)]
    print(Sundial(45.0, 1.0).report(schedule))
    print(sundial(schedule))

