SECRET = (230.0, 30.0, 90.0)


class Turn:
    """A single dial action: a direction plus a distance in degrees."""

    SIGNS = {"left": -1.0, "right": 1.0}

    def __init__(self, direction, degrees):
        self.direction = str(direction).strip().lower()
        if self.direction not in self.SIGNS:
            raise ValueError("direction must be 'left' or 'right', got %r" % direction)
        self.degrees = float(degrees)
        if self.degrees < 0.0:
            raise ValueError("degrees must not be negative, got %r" % degrees)

    @property
    def signed_degrees(self):
        return self.SIGNS[self.direction] * self.degrees

    @classmethod
    def parse(cls, item):
        if isinstance(item, Turn):
            return item
        if isinstance(item, str):
            direction, degrees = item.split()
            return cls(direction, degrees)
        return cls(item[0], item[1])

    def __str__(self):
        return "%s %g deg" % (self.direction, self.degrees)


class Tumbler:
    """A wheel that carries the next wheel only after its free play is used up."""

    FULL = 360.0

    def __init__(self, name):
        self.name = name
        self.angle = 0.0
        self.slack = self.FULL
        self.carry_direction = None

    def drive(self, direction, degrees):
        if direction != self.carry_direction:
            self.carry_direction = direction
            self.slack = self.FULL
        self.angle = (self.angle + Turn.SIGNS[direction] * degrees) % self.FULL
        absorbed = min(self.slack, degrees)
        self.slack -= absorbed
        return degrees - absorbed

    def matches(self, target, tolerance):
        delta = abs(self.angle - target) % self.FULL
        return min(delta, self.FULL - delta) <= tolerance

    def __str__(self):
        return "%s@%g deg" % (self.name, self.angle)


class Spindle:
    def __init__(self):
        self.angle = 0.0

    def rotate(self, turn):
        self.angle = (self.angle + turn.signed_degrees) % 360.0
        return self.angle


class CombinationLock:
    def __init__(self, secret, tolerance=1.0):
        self.secret = tuple(float(angle) % 360.0 for angle in secret)
        if len(self.secret) != 3:
            raise ValueError("a three-wheel lock needs exactly three secret angles")
        self.tolerance = float(tolerance)
        self.spindle = Spindle()
        self.tumblers = [Tumbler("wheel%d" % (index + 1)) for index in range(3)]

    def apply_turn(self, turn):
        self.spindle.rotate(turn)
        carried = turn.degrees
        for tumbler in self.tumblers:
            if carried <= 0.0:
                break
            carried = tumbler.drive(turn.direction, carried)
        return self.spindle.angle

    def pull_handle(self):
        pairs = zip(self.tumblers, self.secret)
        return all(tumbler.matches(target, self.tolerance) for tumbler, target in pairs)

    def run(self, turns):
        for item in turns:
            self.apply_turn(Turn.parse(item))
        return self.pull_handle()

    def report(self):
        rows = ["%s (target %g deg)" % (t, s) for t, s in zip(self.tumblers, self.secret)]
        return "spindle %g deg | %s" % (self.spindle.angle, ", ".join(rows))


def unlock(turns):
    return CombinationLock(SECRET).run(turns)


if __name__ == "__main__":
    good = ["left 1470", "right 1200", "left 420", "right 200"]
    lock = CombinationLock(SECRET)
    print("opened:", lock.run(good))
    print(lock.report())
    print("opened:", unlock([("left", 1470), ("right", 1200), ("left", 425)]))

