import math


class CounterweightBox:
    GRAVITY = 9.81

    def __init__(self, drop_height):
        self.drop_height = drop_height
        self.mass = 0.0

    def load(self, stone_mass):
        if stone_mass <= 0:
            raise ValueError("stone mass must be positive")
        self.mass += stone_mass
        return self.mass

    def potential_energy(self):
        return self.mass * self.GRAVITY * self.drop_height


class ThrowingArm:
    def __init__(self, long_length, short_length):
        self.long_length = long_length
        self.short_length = short_length

    def ratio(self):
        return self.long_length / self.short_length

    def transfer_efficiency(self):
        return 0.55 + 0.05 * min(self.ratio(), 6.0)


class Sling:
    def __init__(self, length):
        self.length = length
        self.projectile_mass = None

    def load(self, projectile_mass):
        if projectile_mass <= 0:
            raise ValueError("projectile mass must be positive")
        self.projectile_mass = projectile_mass

    def release(self):
        stone = self.projectile_mass
        self.projectile_mass = None
        return stone

    def boost(self, arm_ratio):
        return arm_ratio * (1.0 + self.length / (self.length + 1.0))


class Trebuchet:
    def __init__(self, arm, box, sling):
        self.arm = arm
        self.box = box
        self.sling = sling
        self.shots = []

    def launch_velocity(self):
        energy = self.box.potential_energy() * self.arm.transfer_efficiency()
        mass = self.sling.projectile_mass
        base = math.sqrt(2.0 * energy / mass)
        return base * math.sqrt(self.sling.boost(self.arm.ratio()) / self.arm.ratio())

    def fire(self):
        if self.sling.projectile_mass is None:
            raise ValueError("no projectile in the sling")
        if self.box.mass <= 0:
            raise ValueError("counterweight box is empty")
        velocity = self.launch_velocity()
        distance = velocity ** 2 / CounterweightBox.GRAVITY
        self.sling.release()
        self.shots.append(distance)
        return distance

    def report(self):
        lines = ["shot %d: %.2f m" % (i + 1, d) for i, d in enumerate(self.shots)]
        lines.append("arm ratio %.2f, counterweight %.1f kg" % (self.arm.ratio(), self.box.mass))
        return "\n".join(lines)


def siege(commands):
    machine = Trebuchet(ThrowingArm(6.0, 1.5), CounterweightBox(4.0), Sling(2.0))
    distances = []
    for command in commands:
        action = command[0]
        if action == "load_counterweight":
            machine.box.load(command[1])
        elif action == "load_projectile":
            machine.sling.load(command[1])
        elif action == "fire":
            distances.append(machine.fire())
        else:
            raise ValueError("unknown command: %s" % action)
    return distances


if __name__ == "__main__":
    siege_plan = [
        ("load_counterweight", 800.0),
        ("load_projectile", 15.0),
        ("fire",),
        ("load_counterweight", 400.0),
        ("load_projectile", 3.0),
        ("fire",),
    ]
    for shot_distance in siege(siege_plan):
        print("hurled %.2f metres" % shot_distance)

