class Wick:
    AMBIENT = 20.0
    MAX_DIP_TEMPERATURE = 40.0
    WAX_TEMPERATURE = 70.0
    COOLING_RATE = 6.0
    THICKNESS_PER_UNIT = 0.4

    def __init__(self, index):
        self.index = index
        self.thickness = 0.0
        self.temperature = self.AMBIENT

    def is_cool_enough(self):
        return self.temperature <= self.MAX_DIP_TEMPERATURE

    def add_layer(self, wax_units):
        self.thickness += wax_units * self.THICKNESS_PER_UNIT
        self.temperature = self.WAX_TEMPERATURE

    def melt_layer(self, wax_units):
        lost = min(self.thickness, wax_units * self.THICKNESS_PER_UNIT)
        self.thickness -= lost
        self.temperature = self.WAX_TEMPERATURE
        return lost / self.THICKNESS_PER_UNIT

    def cool(self, minutes):
        cooled = self.temperature - self.COOLING_RATE * minutes
        self.temperature = max(self.AMBIENT, cooled)

    def describe(self):
        return "wick {0}: {1:.2f} mm at {2:.1f} C".format(
            self.index, self.thickness, self.temperature)


class Vat:
    def __init__(self, level):
        self.level = level

    def draw(self, wax_units):
        if self.level < wax_units:
            available = self.level
            self.level = 0.0
            return available
        self.level -= wax_units
        return wax_units

    def pour_back(self, wax_units):
        self.level += wax_units


class Carousel:
    WAX_PER_DIP = 1.0

    def __init__(self, wick_count, vat):
        self.position = 0
        self.wicks = [Wick(i) for i in range(wick_count)]
        self.vat = vat

    def current_wick(self):
        return self.wicks[self.position]

    def rotate(self, steps):
        self.position = (self.position + steps) % len(self.wicks)

    def delay(self, minutes):
        for wick in self.wicks:
            wick.cool(minutes)

    def dip(self):
        wick = self.current_wick()
        if wick.is_cool_enough():
            wick.add_layer(self.vat.draw(self.WAX_PER_DIP))
        else:
            self.vat.pour_back(wick.melt_layer(self.WAX_PER_DIP))

    def perform(self, operation):
        name, amount = parse_operation(operation)
        if name == "rotate":
            self.rotate(int(amount))
        elif name == "delay":
            self.delay(amount)
        elif name == "dip":
            self.dip()
        else:
            raise ValueError("unknown operation: {0}".format(name))

    def run(self, operations):
        for operation in operations:
            self.perform(operation)
        return self.thicknesses()

    def thicknesses(self):
        return [round(wick.thickness, 3) for wick in self.wicks]

    def report(self):
        header = "carousel at position {0}, vat {1:.2f} units".format(
            self.position, self.vat.level)
        return "\n".join([header] + [wick.describe() for wick in self.wicks])


def parse_operation(operation):
    if isinstance(operation, (tuple, list)):
        name, amount = operation[0], float(operation[1])
    else:
        parts = str(operation).split()
        name = parts[0]
        amount = float(parts[1]) if len(parts) > 1 else 1.0
    return name.lower(), amount


def candle(operations, wick_count=4, wax_level=100.0):
    carousel = Carousel(wick_count, Vat(wax_level))
    return carousel.run(operations)


def main():
    script = ["dip", "rotate 1", "dip", "rotate 1", "dip",
              "delay 10", "rotate -2", "dip", "dip",
              "delay 10", "dip"]
    carousel = Carousel(3, Vat(20.0))
    print(carousel.run(script))
    print(carousel.report())
    print(candle(["dip", "dip", "delay 10", "dip"], wick_count=2))


if __name__ == "__main__":
    main()

