class Boiler:
    PRESSURE_PER_LOG = 12.0
    MAX_PRESSURE = 180.0

    def __init__(self, wood=0, pressure=0.0):
        self.wood = wood
        self.pressure = pressure

    def load_wood(self, logs):
        self.wood += max(0, int(logs))
        return self.wood

    def stoke(self, logs):
        burned = min(self.wood, max(0, int(logs)))
        self.wood -= burned
        gained = burned * self.PRESSURE_PER_LOG
        self.pressure = min(self.MAX_PRESSURE, self.pressure + gained)
        return burned

    def draw_steam(self, demand):
        released = min(self.pressure, max(0.0, float(demand)))
