import math

GRAVITY = 9.80665


class Reservoir:
    """Upper vessel whose falling water level lowers the outflow pressure."""

    def __init__(self, volume, area):
        self.volume = float(volume)
        self.area = float(area)

    def height(self):
        return self.volume / self.area

    def pressure(self):
        return 1000.0 * GRAVITY * self.height()

    def is_empty(self):
        return self.volume <= 1e-12

    def draw(self, amount):
        taken = min(amount, self.volume)
        self.volume -= taken
        return taken


class DripValve:
    """Adjustable orifice; discharge follows Torricelli's law."""

    def __init__(self, aperture):
        self.discharge_coefficient = 0.62
        self.aperture = 0.0
        self.set_aperture(aperture)

    def set_aperture(self, aperture):
        if aperture < 0.0:
            raise ValueError("aperture cannot be negative")
        self.aperture = float(aperture)

    def flow_rate(self, reservoir):
        if reservoir.is_empty():
            return 0.0
        return self.discharge_coefficient * self.aperture * math.sqrt(2.0 * GRAVITY * reservoir.height())


class Basin:
    """Lower basin with a float whose height is read off a time scale."""

    def __init__(self, area):
        self.area = float(area)
        self.volume = 0.0
        self.seconds_per_metre = 0.0

    def receive(self, volume):
        self.volume += volume

    def float_height(self):
        return self.volume / self.area

    def calibrate(self, reference_rate):
        if reference_rate <= 0.0:
            raise ValueError("cannot calibrate a basin that receives no water")
        self.seconds_per_metre = self.area / reference_rate

    def reading(self):
        return self.float_height() * self.seconds_per_metre


class WaterClock:
    def __init__(self, reservoir, valve, basin, step=0.05):
        self.reservoir = reservoir
        self.valve = valve
        self.basin = basin
        self.step = float(step)
        self.elapsed = 0.0
        self.basin.calibrate(self.valve.flow_rate(self.reservoir))

    def adjust(self, aperture):
        self.valve.set_aperture(aperture)

    def run(self, duration):
        if duration < 0.0:
            raise ValueError("time intervals must run forward")
        remaining = duration
        while remaining > 1e-12:
            dt = min(self.step, remaining)
            drained = self.reservoir.draw(self.valve.flow_rate(self.reservoir) * dt)
            self.basin.receive(drained)
            self.elapsed += dt
            remaining -= dt

    def handle(self, kind, value):
        if kind == "valve":
            self.adjust(value)
        elif kind == "wait":
            self.run(value)
        else:
            raise ValueError("unknown event: %r" % (kind,))

    def report(self):
        return ("true %.1fs / read %.1fs (float at %.3f m, reservoir %.4f m3)"
                % (self.elapsed, self.basin.reading(), self.basin.float_height(), self.reservoir.volume))


def clepsydra(events):
    clock = WaterClock(Reservoir(0.05, 0.05), DripValve(2e-5), Basin(0.02))
    for kind, value in events:
        clock.handle(kind, value)
    return round(clock.basin.reading(), 3)


def main():
    schedule = [("wait", 300.0), ("valve", 4e-5), ("wait", 600.0), ("valve", 2e-5), ("wait", 900.0)]
    clock = WaterClock(Reservoir(0.05, 0.05), DripValve(2e-5), Basin(0.02))
    for kind, value in schedule:
        clock.handle(kind, value)
        print("after %-5s %-8g -> %s" % (kind, value, clock.report()))
    print("final reading:", clepsydra(schedule))


if __name__ == "__main__":
    main()

