import math

STAR_CATALOG = {
    "sirius": (6.752, -16.716),
    "vega": (18.615, 38.784),
    "arcturus": (14.261, 19.182),
    "betelgeuse": (5.919, 7.407),
    "aldebaran": (4.599, 16.509),
}
DEFAULT_LATITUDE = 51.48
DEFAULT_SUN_RA = 18.752


class Star:
    def __init__(self, name, ra_hours, dec_deg):
        self.name = name
        self.ra_hours = ra_hours
        self.dec_deg = dec_deg

    def declination_rad(self):
        return math.radians(self.dec_deg)

    def right_ascension_deg(self):
        return self.ra_hours * 15.0


class BasePlate:
    def __init__(self, latitude):
        self.latitude = latitude
        self.lat_rad = math.radians(latitude)

    def culmination_altitude(self, star):
        return 90.0 - abs(self.latitude - star.dec_deg)

    def hour_angle(self, star, altitude):
        top = self.culmination_altitude(star)
        if altitude > top + 1e-6:
            raise ValueError("%s never reaches %.2f deg at latitude %.2f"
                             % (star.name, altitude, self.latitude))
        dec = star.declination_rad()
        numerator = math.sin(math.radians(altitude)) - math.sin(self.lat_rad) * math.sin(dec)
        cos_h = numerator / (math.cos(self.lat_rad) * math.cos(dec))
        return math.degrees(math.acos(max(-1.0, min(1.0, cos_h))))


class Rete:
    def __init__(self, catalog):
        self.stars = {name: Star(name, ra, dec) for name, (ra, dec) in catalog.items()}
        self.rotation = 0.0
        self.aligned = None

    def select(self, name):
        key = name.strip().lower().replace("the ", "").replace(" star", "")
        if key not in self.stars:
            raise KeyError("star %r is not engraved on the rete" % name)
        return self.stars[key]

    def rotate_to(self, plate, name, altitude, direction):
        star = self.select(name)
        offset = plate.hour_angle(star, altitude)
        self.aligned = star
        self.rotation = offset if direction.lower().startswith("w") else -offset
        return self.rotation


class Astrolabe:
    def __init__(self, latitude=DEFAULT_LATITUDE, sun_ra_hours=DEFAULT_SUN_RA):
        self.plate = BasePlate(latitude)
        self.rete = Rete(STAR_CATALOG)
        self.sun_ra_deg = sun_ra_hours * 15.0

    def solar_time(self, star, hour_angle_deg):
        sidereal = star.right_ascension_deg() + hour_angle_deg
        return ((sidereal - self.sun_ra_deg) / 15.0 + 12.0) % 24.0

    def format_time(self, hours):
        minutes = round(hours * 60.0) % 1440
        return "%02d:%02d" % (minutes // 60, minutes % 60)

    def sight(self, sighting):
        name, altitude = sighting[0], float(sighting[1])
        direction = sighting[2] if len(sighting) > 2 else "east"
        rotation = self.rete.rotate_to(self.plate, name, altitude, direction)
        return self.format_time(self.solar_time(self.rete.aligned, rotation))

    def process(self, sightings):
        return [self.sight(s) for s in sightings]


def astrolabe(sightings):
    return Astrolabe().process(sightings)


if __name__ == "__main__":
    observations = [("sirius", 21.80), ("vega", 60.0, "west"),
                    ("arcturus", 40.0, "east"), ("aldebaran", 30.0, "west")]
    for observation, local_time in zip(observations, astrolabe(observations)):
        print("%-11s %6.2f deg -> %s" % (observation[0], observation[1], local_time))

