class Mainspring:
    """Stores wound tension, measured in degrees of cylinder rotation it can drive."""

    def __init__(self, capacity, tension_per_turn=45):
        self.capacity = capacity
        self.tension_per_turn = tension_per_turn
        self.tension = 0

    def wind(self, turns):
        if turns < 0:
            raise ValueError("cannot wind a negative number of turns")
        before = self.tension
        self.tension = min(self.capacity, self.tension + turns * self.tension_per_turn)
        return self.tension - before

    def draw(self, degrees):
        spent = min(self.tension, max(0, degrees))
        self.tension -= spent
        return spent

    def report(self):
        return "spring at {}/{} degrees of drive".format(self.tension, self.capacity)


class CamTrack:
    """One track on the cylinder: raised cams at fixed angles move one limb."""

    def __init__(self, limb, movement, angles):
        self.limb = limb
        self.movement = movement
        self.angles = sorted(angle % 360 for angle in angles)

    def strikes_at(self, angle):
        return angle % 360 in self.angles

    def describe(self):
        return "{} {}".format(self.limb, self.movement)


class Cylinder:
    """A rotating cylinder carrying several cam tracks, read one degree at a time."""

    def __init__(self, tracks):
        self.tracks = tracks
        self.angle = 0

    def advance_one_degree(self):
        self.angle = (self.angle + 1) % 360
        return [track.describe() for track in self.tracks if track.strikes_at(self.angle)]

    def rotate(self, degrees):
        struck = []
        for _ in range(degrees):
            struck.extend(self.advance_one_degree())
        return struck


class Automaton:
    """The figure itself: brake released, the spring drives the cylinder."""

    def __init__(self, spring, cylinder):
        self.spring = spring
        self.cylinder = cylinder
        self.performed = []

    def wind(self, turns):
        return self.spring.wind(turns)

    def run(self, degrees):
        driven = self.spring.draw(degrees)
        moves = self.cylinder.rotate(driven)
        self.performed.extend(moves)
        return moves

    def perform(self, operations):
        for index, (action, amount) in enumerate(operations):
            if action == "wind":
                self.wind(amount)
            elif action == "run":
                self.run(amount)
            else:
                raise ValueError("unknown operation {!r} at step {}".format(action, index))
        return list(self.performed)

    def status(self):
        return "cylinder at {} degrees, {}, {} movements performed".format(
            self.cylinder.angle, self.spring.report(), len(self.performed))


def animate(winds):
    tracks = [
        CamTrack("right arm", "waves", [30, 90, 150, 210, 270, 330]),
        CamTrack("head", "nods", [60, 180, 300]),
        CamTrack("left hand", "raises the fan", [120, 240]),
    ]
    figure = Automaton(Mainspring(360), Cylinder(tracks))
    movements = figure.perform(winds)
    print(figure.status())
    return movements


if __name__ == "__main__":
    for movement in animate([("wind", 8), ("run", 360)]):
        print(movement)
    print(animate([("wind", 1), ("run", 360), ("wind", 2), ("run", 100)]))

