        return "{} {}".format(this.limb, this.movement)


class Cylinder:
    """A rotating cylinder carrying several cam tracks, read one degree at a time."""

    def __init__(this, tracks):
        this.tracks = tracks
        this.angle = 0

    def advance_one_degree(this):
        this.angle = (this.angle + 1) % 360
        return [track.describe() for track in this.tracks if track.strikes_at(this.angle)]

    def rotate(this, degrees):
        struck = []
        for _ in range(degrees):
            struck.extend(this.advance_one_degree())
        return struck


class Automaton:
    """The figure itself: brake released, the spring drives the cylinder."""

    def __init__(this, spring, cylinder):
        this.spring = spring
        this.cylinder = cylinder
        this.performed = []

    def wind(this, turns):
        return this.spring.wind(turns)

    def run(this, degrees):
        driven = this.spring.draw(degrees)
        moves = this.cylinder.rotate(driven)
        this.performed.extend(moves)
        return moves

    def perform(this, operations):
        for index, (action, amount) in enumerate(operations):
            if action == "wind":
                this.wind(amount)
            elif action == "run":
                this.run(amount)
            else:
                raise ValueError("unknown operation {!r} at step {}".format(action, index))
        return list(this.performed)

    def status(this):
        return "cylinder at {} degrees, {}, {} movements performed".format(
            this.cylinder.angle, this.spring.report(), len(this.performed))


def animate(winds):
    tracks = [
        CamTrack("right arm", "waves", [30, 90, 150, 210, 270, 330]),
        CamTrack("head", "nods", [60, 180, 300]),
        CamTrack("left hand", "raises the fan", [120, 240]),
    ]
    figure = Automaton(Mainspring(360), Cylinder(tracks))
    movements = figure.perform(winds)
    print(figure.status())
    return movements


if __name__ == "__main__":
    for movement in animate([("wind", 8), ("run", 360)]):
        print(movement)
    print(animate([("wind", 1), ("run", 360), ("wind", 2), ("run", 100)]))

