class TensionSpring:
    def __init__(self, capacity):
        self.capacity = float(capacity)
        self.energy = 0.0

    def wind(self, amount):
        if amount < 0:
            raise ValueError("crank amount must not be negative")
        accepted = min(float(amount), self.capacity - self.energy)
        self.energy += accepted
        return accepted

    def draw(self, amount):
        released = min(float(amount), self.energy)
        self.energy -= released
        return released

    def charge_ratio(self):
        return self.energy / self.capacity


class WaxCylinder:
    def __init__(self, grooves):
        self.grooves = list(grooves)

    def groove_count(self):
        return len(self.grooves)

    def sample_at(self, index):
        if index >= self.groove_count():
            return None
        return self.grooves[index]


class SoundBox:
    def __init__(self, cylinder):
        self.cylinder = cylinder
        self.position = 0

    def read_next(self):
        sample = self.cylinder.sample_at(self.position)
        if sample is not None:
            self.position += 1
        return sample

    def at_end(self):
        return self.position >= self.cylinder.groove_count()


class Phonograph:
    def __init__(self, grooves, capacity=100.0, energy_per_step=4.0):
        self.spring = TensionSpring(capacity)
        self.sound_box = SoundBox(WaxCylinder(grooves))
        self.energy_per_step = float(energy_per_step)
        self.samples = []
        self.events = []

    def crank(self, amount):
        accepted = self.spring.wind(amount)
        self.events.append("cranked %.1f (%.1f absorbed, spring at %d%%)"
                           % (amount, accepted, round(100 * self.spring.charge_ratio())))

    def play(self, duration):
        for _ in range(int(duration)):
            if self.sound_box.at_end():
                self.events.append("cylinder finished")
                return
            if self.spring.draw(self.energy_per_step) < self.energy_per_step:
                self.events.append("spring depleted at groove %d" % self.sound_box.position)
                return
            self.samples.append(self.sound_box.read_next())

    def run(self, actions):
        for kind, value in actions:
            if kind == "crank":
                self.crank(value)
            elif kind == "play":
                self.play(value)
            else:
                raise ValueError("unknown action: %r" % (kind,))
        return self.samples

    def report(self):
        header = "played %d of %d grooves" % (self.sound_box.position,
                                              self.sound_box.cylinder.groove_count())
        return "\n".join([header] + ["  - " + line for line in self.events])


SONG = ["do", "re", "mi", "fa", "sol", "la", "ti", "do'", "ti", "la", "sol", "fa"]


def phonograph(actions):
    machine = Phonograph(SONG)
    samples = machine.run(actions)
    print(machine.report())
