class SluiceGate:
    MAX_FLOW = 120.0

    def __init__(self):
        self.open_percent = 0.0

    def adjust(self, percent):
        self.open_percent = min(100.0, max(0.0, float(percent)))
        return self.open_percent

    def flow(self):
        return self.MAX_FLOW * self.open_percent / 100.0


class Waterwheel:
    def __init__(self, gate):
        self.gate = gate
        self.efficiency = 0.22
        self.rpm = 0.0

    def spin(self):
        self.rpm = self.gate.flow() * self.efficiency
        return self.rpm


class GrindingStones:
    def __init__(self):
        self.wear = 0.0
        self.yield_per_rotation = 0.02

    def sharpness(self):
        return max(0.15, 1.0 - self.wear)

    def grind(self, rpm, minutes, available):
        rotations = rpm * minutes
        milled = min(available, rotations * self.yield_per_rotation * self.sharpness())
        self.wear = min(1.0, self.wear + rotations * 0.00004)
        return milled


class Watermill:
    def __init__(self):
        self.gate = SluiceGate()
        self.wheel = Waterwheel(self.gate)
        self.stones = GrindingStones()
        self.hopper = 0.0
        self.flour = 0.0
        self.log = []

    def set_gate(self, percent):
        opening = self.gate.adjust(percent)
        speed = self.wheel.spin()
        self.log.append("gate at %.0f%% -> %.2f rpm" % (opening, speed))

    def add_grain(self, pounds):
        if pounds < 0:
            raise ValueError("cannot dump negative grain")
        self.hopper += float(pounds)
        self.log.append("hopper holds %.2f lb of grain" % self.hopper)

    def operate(self, minutes):
        if minutes < 0:
            raise ValueError("cannot run the mill backwards")
        milled = self.stones.grind(self.wheel.rpm, minutes, self.hopper)
        self.hopper -= milled
        self.flour += milled
        self.log.append("milled %.2f lb in %g min (wear %.0f%%)"
                        % (milled, minutes, self.stones.wear * 100))
        return milled

    def run(self, flows):
        actions = {"gate": self.set_gate, "grain": self.add_grain, "run": self.operate}
        for action, amount in flows:
            if action not in actions:
                raise ValueError("unknown mill action: %r" % (action,))
            actions[action](amount)
        return round(self.flour, 3)

    def report(self):
        header = "Flour: %.2f lb | Grain left: %.2f lb | Stone wear: %.0f%%" % (
            self.flour, self.hopper, self.stones.wear * 100)
        return "\n".join(self.log + [header])


def mill(flows):
    return Watermill().run(flows)


if __name__ == "__main__":
    day = [("grain", 400), ("gate", 100), ("run", 60),
           ("gate", 40), ("run", 120), ("grain", 250), ("run", 90)]
    house = Watermill()
    print("total flour: %.2f lb" % house.run(day))
    print(house.report())
    print("quick check:", mill([("grain", 50), ("gate", 50), ("run", 30)]))

