class CodeTable:
    """Baudot ITA2 letter-shift codes, one 5-bit pattern per key."""

    LETTERS = {
        "A": "11000", "B": "10011", "C": "01110", "D": "10010", "E": "10000",
        "F": "10110", "G": "01011", "H": "00101", "I": "01100", "J": "11010",
        "K": "11110", "L": "01001", "M": "00111", "N": "00110", "O": "00011",
        "P": "01101", "Q": "11101", "R": "01010", "S": "10100", "T": "00001",
        "U": "11100", "V": "01111", "W": "11001", "X": "10111", "Y": "10101",
        "Z": "10001", " ": "00100",
    }

    def __init__(self):
        self.width = 5
        self.table = {key: [int(bit) for bit in bits] for key, bits in self.LETTERS.items()}

    def lookup(self, char):
        return list(self.table[char.upper()])

    def unsupported(self, text):
        return sorted({char for char in text.upper() if char not in self.table})


class PinBank:
    """The five piercing pins; they are loaded, struck, then retracted."""

    def __init__(self, count):
        self.count = count
        self.state = [0] * count

    def load(self, pattern):
        if len(pattern) != self.count:
            raise ValueError("pattern needs %d bits" % self.count)
        self.state = list(pattern)

    def strike(self):
        holes = list(self.state)
        self.state = [0] * self.count
        return holes


class TapeStrip:
    """A continuous paper strip with a lengthwise position, in millimetres."""

    def __init__(self, step_mm):
        self.step_mm = step_mm
        self.position = 0.0
        self.rows = []

    def punch_row(self, holes):
        self.rows.append(holes)
        self.position += self.step_mm

    def consumed(self):
        return self.position

    def render(self):
        return ["".join("o" if hole else "." for hole in row) for row in self.rows]


class PunchMachine:
    def __init__(self, step_mm=2.54):
        self.codes = CodeTable()
        self.pins = PinBank(self.codes.width)
        self.tape = TapeStrip(step_mm)
        self.keys_typed = 0

    def type_character(self, char):
        self.pins.load(self.codes.lookup(char))
        holes = self.pins.strike()
        self.tape.punch_row(holes)
        self.keys_typed += 1
        return holes

    def type_message(self, text):
        bad = self.codes.unsupported(text)
        if bad:
            raise ValueError("keyboard has no pins for: %s" % ", ".join(repr(c) for c in bad))
        return [self.type_character(char) for char in text]

    def report(self):
        header = "%d keys typed, %.2f mm of paper used" % (self.keys_typed, self.tape.consumed())
        return "\n".join([header] + self.tape.render())


def punch(messages):
    if isinstance(messages, str):
        messages = [messages]
    machine = PunchMachine()
    patterns = []
    for message in messages:
        patterns.extend(machine.type_message(message))
    return patterns, machine.tape.consumed()


def main():
    holes, length = punch("HELLO WORLD")
    for row in holes:
        print("".join(str(bit) for bit in row))
    print("total length: %.2f mm" % length)
    machine = PunchMachine()
    machine.type_message("SOS")
    print(machine.report())


if __name__ == "__main__":
    main()

