import math


class HalogenBulb:
    AMBIENT = 20.0
    SAFE_LIMIT = 120.0

    def __init__(self, wattage=75.0):
        self.wattage = wattage
        self.temperature = self.AMBIENT
        self.lit = False

    def switch_on(self):
        self.lit = True

    def switch_off(self):
        self.lit = False

    def intensity(self):
        if not self.lit:
            return 0.0
        return self.wattage / 10.0

    def burn(self, seconds):
        self.temperature += seconds * self.wattage / 25.0

    def cool(self, seconds):
        excess = self.temperature - self.AMBIENT
        self.temperature = self.AMBIENT + excess * math.pow(0.5, seconds / 10.0)

    def overheated(self):
        return self.temperature > self.SAFE_LIMIT


class FocusLens:
    STOPS = (2.8, 4.0, 5.6, 8.0, 11.0, 16.0)
    REFERENCE = 2.8

    def __init__(self, aperture=8.0):
        self.aperture = None
        self.set_aperture(aperture)

    def set_aperture(self, aperture):
        value = float(aperture)
        if value not in self.STOPS:
            raise ValueError("unsupported f-stop: %s" % aperture)
        self.aperture = value

    def transmission(self):
        return (self.REFERENCE / self.aperture) ** 2


class PhotoPaper:
    SENSITIVITY = 0.5

    def __init__(self):
        self.darkness = 0.0
        self.damaged = False

    def expose(self, light, seconds):
        gained = light * seconds * self.SENSITIVITY
        self.darkness = min(100.0, self.darkness + gained)

    def ruin(self):
        self.damaged = True

    def report(self):
        if self.damaged:
            return "ERROR: negative damaged by overheated bulb"
        return round(self.darkness, 2)


class Enlarger:
    def __init__(self, wattage=75.0):
        self.bulb = HalogenBulb(wattage)
        self.lens = FocusLens()
        self.paper = PhotoPaper()

    def run_step(self, aperture, expose_seconds, rest_seconds):
        if expose_seconds < 0 or rest_seconds < 0:
            raise ValueError("durations must not be negative")
        self.lens.set_aperture(aperture)
        self.bulb.switch_on()
        light = self.bulb.intensity() * self.lens.transmission()
        self.paper.expose(light, expose_seconds)
        self.bulb.burn(expose_seconds)
        self.bulb.switch_off()
        if self.bulb.overheated():
            self.paper.ruin()
            return False
        self.bulb.cool(rest_seconds)
        return True

    def process(self, exposures):
        for aperture, expose_seconds, rest_seconds in exposures:
            if not self.run_step(aperture, expose_seconds, rest_seconds):
                break
        return self.paper.report()


def enlarge(exposures):
    return Enlarger().process(exposures)


def main():
    schedules = {
        "short bursts": [(8.0, 5, 20), (8.0, 5, 20), (5.6, 4, 30)],
        "wide open dodge": [(2.8, 3, 15), (4.0, 6, 40)],
        "no cooling": [(11.0, 20, 0), (11.0, 20, 0), (11.0, 20, 0)],
    }
    for name, steps in schedules.items():
        print("%-16s -> %s" % (name, enlarge(steps)))


if __name__ == "__main__":
    main()

