    def switch_on(this):
        this.lit = True

    def switch_off(this):
        this.lit = False

    def intensity(this):
        if not this.lit:
            return 0.0
        return this.wattage / 10.0

    def burn(this, seconds):
        this.temperature += seconds * this.wattage / 25.0

    def cool(this, seconds):
        excess = this.temperature - this.AMBIENT
        this.temperature = this.AMBIENT + excess * math.pow(0.5, seconds / 10.0)

    def overheated(this):
        return this.temperature > this.SAFE_LIMIT


class FocusLens:
    STOPS = (2.8, 4.0, 5.6, 8.0, 11.0, 16.0)
    REFERENCE = 2.8

    def __init__(this, aperture=8.0):
        this.aperture = None
        this.set_aperture(aperture)

    def set_aperture(this, aperture):
        value = float(aperture)
        if value not in this.STOPS:
            raise ValueError("unsupported f-stop: %s" % aperture)
        this.aperture = value

    def transmission(this):
        return (this.REFERENCE / this.aperture) ** 2


class PhotoPaper:
    SENSITIVITY = 0.5

    def __init__(this):
        this.darkness = 0.0
        this.damaged = False

    def expose(this, light, seconds):
        gained = light * seconds * this.SENSITIVITY
        this.darkness = min(100.0, this.darkness + gained)

    def ruin(this):
        this.damaged = True

    def report(this):
        if this.damaged:
            return "ERROR: negative damaged by overheated bulb"
        return round(this.darkness, 2)


class Enlarger:
    def __init__(this, wattage=75.0):
        this.bulb = HalogenBulb(wattage)
        this.lens = FocusLens()
        this.paper = PhotoPaper()

    def run_step(this, aperture, expose_seconds, rest_seconds):
        if expose_seconds < 0 or rest_seconds < 0:
            raise ValueError("durations must not be negative")
        this.lens.set_aperture(aperture)
        this.bulb.switch_on()
        light = this.bulb.intensity() * this.lens.transmission()
        this.paper.expose(light, expose_seconds)
        this.bulb.burn(expose_seconds)
        this.bulb.switch_off()
        if this.bulb.overheated():
            this.paper.ruin()
            return False
        this.bulb.cool(rest_seconds)
        return True

    def process(this, exposures):
        for aperture, expose_seconds, rest_seconds in exposures:
            if not this.run_step(aperture, expose_seconds, rest_seconds):
                break
        return this.paper.report()


def enlarge(exposures):
    return Enlarger().process(exposures)


def main():
    schedules = {
        "short bursts": [(8.0, 5, 20), (8.0, 5, 20), (5.6, 4, 30)],
        "wide open dodge": [(2.8, 3, 15), (4.0, 6, 40)],
        "no cooling": [(11.0, 20, 0), (11.0, 20, 0), (11.0, 20, 0)],
    }
    for name, steps in schedules.items():
        print("%-16s -> %s" % (name, enlarge(steps)))


if __name__ == "__main__":
    main()

