class Warehouse:
    """A storage site with a fixed number of box slots."""

    def __init__(self, name, capacity):
        self.name = name
        self.capacity = capacity
        self.boxes = []

    def is_full(self):
        return len(self.boxes) >= self.capacity

    def store(self, box_id):
        if self.is_full():
            return False
        self.boxes.append(box_id)
        return True

    def count(self):
