    def describe(self):
        return "{0}: {1}/{2}".format(self.name, self.count(), self.capacity)


class Dispatch:
    """Central router: keeps warehouses and an overflow queue for rejected boxes."""

    def __init__(self, default_capacity):
        self.default_capacity = default_capacity
        self.warehouses = {}
        self.order = []
        self.overflow = []

    def register(self, warehouse):
        self.warehouses[warehouse.name] = warehouse
        self.order.append(warehouse.name)
        return warehouse

    def warehouse_for(self, name):
        if name not in self.warehouses:
            return self.register(Warehouse(name, self.default_capacity))
        return self.warehouses[name]

    def insert(self, box_id, destination):
        warehouse = self.warehouse_for(destination)
        if not warehouse.store(box_id):
            self.overflow.append((box_id, destination))

    def overflow_count(self, destination):
        return sum(1 for _, dest in self.overflow if dest == destination)

    def summary(self):
        return [[self.warehouses[name].count(), self.overflow_count(name)]
                for name in self.order]

    def report_lines(self):
        lines = []
        for name in self.order:
            held = self.overflow_count(name)
            lines.append("{0} (overflow {1})".format(self.warehouses[name].describe(), held))
        lines.append("overflow queue total: {0}".format(len(self.overflow)))
        return lines


