    """Validates and normalises the raw manifest rows."""

    def __init__(self, manifest):
        self.manifest = manifest

    def entries(self):
        return [self.normalise(index, row) for index, row in enumerate(self.manifest)]

    def normalise(self, index, row):
        if len(row) != 2:
            raise ValueError("row {0} must hold a box id and a destination".format(index))
        box_id, destination = row
        if not isinstance(box_id, str) or not isinstance(destination, str):
            raise ValueError("row {0} must contain strings".format(index))
        return box_id.strip(), destination.strip()


