class Property:
    """A single housing unit offered on the market."""

    LUXURY_PREMIUM = 0.15

    def __init__(self, base_price, zone):
        self.base_price = float(base_price)
        self.zone = str(zone).strip().lower()
        self.sold = False

    def is_luxury(self):
        return self.zone == "luxury"

    def apply_zone_adjustment(self):
        if self.is_luxury():
            self.base_price *= 1.0 + self.LUXURY_PREMIUM
        return self.base_price

    def mark_sold(self):
        self.sold = True

    def describe(self):
        state = "sold" if self.sold else "listed"
        return "{0:>7} zone | {1:>12,.2f} | {2}".format(self.zone, self.base_price, state)


class Broker:
    """An agent representing properties up to a fixed sales quota."""

    def __init__(self, name, quota):
        self.name = name
        self.quota = quota
        self.active = []

    def has_capacity(self):
        return len(self.active) < self.quota

    def assign(self, prop):
        if self.has_capacity():
            prop.mark_sold()
        self.active.append(prop)
        return prop

    def projected_revenue(self):
        return round(sum(p.base_price for p in self.active if p.sold), 2)

    def report(self):
        return "{0}: {1} listing(s), quota {2}, projected {3:,.2f}".format(
            self.name, len(self.active), self.quota, self.projected_revenue())


class Agency:
    """Distributes incoming listings round robin across three brokers."""

    def __init__(self, name, quota=2):
        self.name = name
        self.brokers = [Broker(label, quota) for label in ("Ada", "Boris", "Chen")]
        self.properties = []
        self.cursor = 0

    def next_broker(self):
        broker = self.brokers[self.cursor % len(self.brokers)]
        self.cursor += 1
        return broker

    def intake(self, listings):
        for index, listing in enumerate(listings):
            if len(listing) != 2:
                raise ValueError("listing {0} must be a (price, zone) pair".format(index))
            price, zone = listing
            if price < 0:
                raise ValueError("listing {0} has a negative price".format(index))
            prop = Property(price, zone)
            prop.apply_zone_adjustment()
            self.properties.append(prop)
            self.next_broker().assign(prop)
        return self.revenue_table()

    def revenue_table(self):
        return {broker.name: broker.projected_revenue() for broker in self.brokers}

    def summary(self):
        lines = ["{0} portfolio ({1} properties)".format(self.name, len(self.properties))]
        lines.extend("  " + prop.describe() for prop in self.properties)
        lines.extend("  " + broker.report() for broker in self.brokers)
        return "\n".join(lines)


def evaluate(listings):
    agency = Agency("Skyline Realty")
    table = agency.intake(listings)
    print(agency.summary())
    return table


if __name__ == "__main__":
    print(evaluate([(250000, "urban"), (400000, "luxury"), (180000, "rural"),
                    (320000, "luxury"), (210000, "urban"), (275000, "suburb"),
                    (500000, "luxury")]))

