class Enclosure:
    def __init__(self, name, climate, capacity, residents=0):
        if capacity < 0:
            raise ValueError("capacity cannot be negative")
        if residents > capacity:
            raise ValueError("residents cannot exceed capacity")
        self.name = name
        self.climate = climate
        self.capacity = capacity
        self.residents = residents
        self.log = []

    def free_space(self):
        return self.capacity - self.residents

    def matches(self, climate):
        return self.climate == climate and self.free_space() > 0

    def admit(self, animal):
        self.residents += 1
        self.log.append(animal)
        return self.name

    def describe(self):
        return "{0} [{1}] {2}/{3}".format(
            self.name, self.climate, self.residents, self.capacity)


class Park:
    def __init__(self, name, enclosures):
        self.name = name
        self.enclosures = list(enclosures)
        self.rejected = []

    def climates(self):
        return {enclosure.climate for enclosure in self.enclosures}

    def house(self, animal, climate):
        if climate in self.climates():
            for enclosure in self.enclosures:
                if enclosure.matches(climate):
                    return enclosure.admit(animal)
        self.rejected.append((animal, climate))
        return None

    def intake(self, animals):
        placements = []
        for animal, climate in animals:
            placements.append((animal, self.house(animal, climate)))
        return placements

    def occupancy(self):
        return {enclosure.name: enclosure.residents for enclosure in self.enclosures}

    def report(self):
        lines = ["Park: " + self.name]
        for enclosure in self.enclosures:
            lines.append("  " + enclosure.describe())
        for animal, climate in self.rejected:
            lines.append("  rejected: {0} (needs {1})".format(animal, climate))
        return "\n".join(lines)


def allocate(animals):
    park = Park("Highland Wildlife Park", [
        Enclosure("Tundra Ridge", "arctic", 2),
        Enclosure("Frost Hollow", "arctic", 1),
        Enclosure("Palm Basin", "tropical", 3),
        Enclosure("Dune Field", "desert", 2),
    ])
    park.intake(animals)
    return park.occupancy(), len(park.rejected), park.report()


def main():
    arrivals = [
        ("snowy owl", "arctic"),
        ("polar bear", "arctic"),
        ("arctic fox", "arctic"),
        ("penguin", "arctic"),
        ("toucan", "tropical"),
        ("fennec fox", "desert"),
        ("kangaroo", "savanna"),
    ]
    occupancy, rejected, report = allocate(arrivals)
    print(report)
    print("occupancy:", occupancy)
    print("rejected count:", rejected)


if __name__ == "__main__":
    main()

