class Magistrate:
    def __init__(self, name, expertise, daily_hours):
        self.name = name
        self.expertise = expertise
        self.daily_hours = daily_hours
        self.remaining_hours = daily_hours
        self.docket = []

    def can_handle(self, dispute):
        if dispute.subject != self.expertise:
            return False
        return dispute.hours <= self.remaining_hours

    def assign(self, dispute):
        self.remaining_hours -= dispute.hours
        self.docket.append(dispute)
        dispute.magistrate = self.name

    def workload_summary(self):
        used = self.daily_hours - self.remaining_hours
        return "{} ({}): {}/{}h over {} dispute(s)".format(
            self.name, self.expertise, used, self.daily_hours, len(self.docket))


class Dispute:
    def __init__(self, subject, hours):
        self.subject = str(subject).strip().lower()
        self.hours = float(hours)
        self.magistrate = None
        if self.hours <= 0:
            raise ValueError("dispute duration must be positive: {}".format(hours))

    def is_scheduled(self):
        return self.magistrate is not None

    def describe(self):
        if self.is_scheduled():
            return "{} [{}h] -> {}".format(self.subject, self.hours, self.magistrate)
        return "{} [{}h] -> unassigned".format(self.subject, self.hours)


class Courthouse:
    def __init__(self, magistrates):
        self.magistrates = list(magistrates)
        self.disputes = []

    def intake(self, subject, hours):
        dispute = Dispute(subject, hours)
        self.disputes.append(dispute)
        return dispute

    def match(self, dispute):
        candidates = [m for m in self.magistrates if m.can_handle(dispute)]
        if not candidates:
            return None
        chosen = max(candidates, key=lambda m: m.remaining_hours)
        chosen.assign(dispute)
        return chosen

    def process(self, cases):
        for subject, hours in cases:
            self.match(self.intake(subject, hours))
        return self.scheduled_count()

    def scheduled_count(self):
        return sum(1 for d in self.disputes if d.is_scheduled())

    def report(self):
        lines = [m.workload_summary() for m in self.magistrates]
        lines.extend(d.describe() for d in self.disputes)
        lines.append("scheduled {}/{}".format(self.scheduled_count(), len(self.disputes)))
        return "\n".join(lines)


def schedule(cases):
    courthouse = Courthouse([
        Magistrate("Alvarez", "family", 8),
        Magistrate("Boateng", "contract", 6),
        Magistrate("Chen", "criminal", 7),
        Magistrate("Dumont", "contract", 4),
    ])
    return courthouse.process(cases)


if __name__ == "__main__":
    docket = [("contract", 3), ("family", 5), ("criminal", 8),
              ("contract", 3), ("contract", 4), ("tax", 2)]
    print("successfully scheduled:", schedule(docket))
    house = Courthouse([Magistrate("Alvarez", "family", 8),
                        Magistrate("Boateng", "contract", 6)])
    house.process(docket[:4])
    print(house.report())

