        this.disputes = []

    def intake(this, subject, hours):
        dispute = Dispute(subject, hours)
        this.disputes.append(dispute)
        return dispute

    def match(this, dispute):
        candidates = [m for m in this.magistrates if m.can_handle(dispute)]
        if not candidates:
            return None
        chosen = max(candidates, key=lambda m: m.remaining_hours)
        chosen.assign(dispute)
        return chosen

    def process(this, cases):
        for subject, hours in cases:
            this.match(this.intake(subject, hours))
        return this.scheduled_count()

    def scheduled_count(this):
        return sum(1 for d in this.disputes if d.is_scheduled())

    def report(this):
        lines = [m.workload_summary() for m in this.magistrates]
        lines.extend(d.describe() for d in this.disputes)
        lines.append("scheduled {}/{}".format(this.scheduled_count(), len(this.disputes)))
        return "\n".join(lines)


def schedule(cases):
    courthouse = Courthouse([
        Magistrate("Alvarez", "family", 8),
        Magistrate("Boateng", "contract", 6),
        Magistrate("Chen", "criminal", 7),
        Magistrate("Dumont", "contract", 4),
    ])
    return courthouse.process(cases)


