SPACE_PER_PERSON = 50


class Soundstage:
    def __init__(self, name, square_footage):
        self.name = name
        self.square_footage = square_footage
        self.occupied = False
        self.crew = None

    def fits(self, crew):
        return not self.occupied and self.square_footage >= crew.required_footage()

    def book(self, crew):
        self.occupied = True
        self.crew = crew
        return self

    def summary(self):
        if self.crew is None:
            return "{} ({} sq ft): free".format(self.name, self.square_footage)
        return "{} ({} sq ft): {} for {} day(s)".format(
            self.name, self.square_footage, self.crew.name, self.crew.days)


class FilmingCrew:
    def __init__(self, name, personnel, days):
        self.name = name
        self.personnel = personnel
        self.days = days

    def required_footage(self):
        return self.personnel * SPACE_PER_PERSON

    def describe(self):
        return "{}: {} people, {} day(s)".format(self.name, self.personnel, self.days)


class Studio:
    def __init__(self, name):
        self.name = name
        self.stages = []
        self.crews = []

    def add_stage(self, square_footage):
        stage = Soundstage("Stage {}".format(len(self.stages) + 1), square_footage)
        self.stages.append(stage)
        return stage

    def hire_crew(self, personnel, days):
        crew = FilmingCrew("Crew {}".format(len(self.crews) + 1), personnel, days)
        self.crews.append(crew)
        return crew

    def evaluate(self, personnel, days):
        crew = self.hire_crew(personnel, days)
        for stage in self.stages:
            if stage.fits(crew):
                return stage.book(crew)
        return None

    def occupancy(self):
        return [stage.occupied for stage in self.stages]

    def report(self):
        lines = ["{} schedule".format(self.name)]
        lines.extend(crew.describe() for crew in self.crews)
        lines.extend(stage.summary() for stage in self.stages)
        return "\n".join(lines)


def produce(scripts):
    studio = Studio("Backlot Studio")
    for personnel, days in scripts:
        if personnel <= 0 or days <= 0:
            raise ValueError("scripts need positive personnel and days")
        studio.add_stage(personnel * SPACE_PER_PERSON)
    for personnel, days in scripts:
        studio.evaluate(personnel, days)
    print(studio.report())
    return studio.occupancy()


if __name__ == "__main__":
    print(produce([(10, 5), (4, 12), (25, 3)]))

