class Sector:
    def __init__(self, name, threshold):
        self.name = name
        self.threshold = threshold
        self.level = None
        self.valve_open = False

    def apply_reading(self, reading):
        self.level = reading
        self.valve_open = self.level < self.threshold
        return self.valve_open

    def process(self, readings):
        for reading in readings:
            self.apply_reading(reading)
        return self.valve_open

    def describe(self):
        state = "IRRIGATING" if self.valve_open else "idle"
        if self.level is None:
            return "{0}: no data (threshold {1})".format(self.name, self.threshold)
        return "{0}: level {1}, threshold {2} -> {3}".format(
            self.name, self.level, self.threshold, state)


class GreenhouseController:
    DEFAULT_THRESHOLD = 30

    def __init__(self, sector_count, thresholds=None):
        self.thresholds = thresholds or []
        self.sectors = []
        for index in range(sector_count):
            self.sectors.append(Sector("Sector-%d" % (index + 1),
                                       self.threshold_for(index)))

    def threshold_for(self, index):
        if index < len(self.thresholds):
            return self.thresholds[index]
        return self.DEFAULT_THRESHOLD

    def update(self, readings):
        for sector, sector_readings in zip(self.sectors, readings):
            sector.process(sector_readings)
        return self.valve_states()

    def valve_states(self):
        return [sector.valve_open for sector in self.sectors]

    def report(self):
        lines = [sector.describe() for sector in self.sectors]
        lines.append("open valves: {0}/{1}".format(
            sum(1 for sector in self.sectors if sector.valve_open),
            len(self.sectors)))
        return "\n".join(lines)


def water(readings):
    if not isinstance(readings, list):
        raise TypeError("readings must be a list of lists")
    for sector_readings in readings:
        if not isinstance(sector_readings, list):
            raise TypeError("each sector's readings must be a list")
    controller = GreenhouseController(len(readings), [35, 25, 40])
    states = controller.update(readings)
    print(controller.report())
    return states


if __name__ == "__main__":
    data = [
        [50, 44, 38, 33],
        [60, 41, 28, 22],
        [70, 66, 58, 51],
        [45, 39, 31, 29],
    ]
    print(water(data))
    print(water([[10], [55, 12], [], [80, 90]]))

