class Flyer:
    TRAVEL_RATE = 2
    SCAN_COST = 3

    def __init__(self, name, altitude, battery):
        self.name = name
        self.altitude = altitude
        self.battery = battery
        self.position = (0, 0)
        self.scanned = []

    def distance_to(self, coord):
        return abs(coord[0] - self.position[0]) + abs(coord[1] - self.position[1])

    def energy_for(self, coord):
        return self.distance_to(coord) * self.TRAVEL_RATE + self.SCAN_COST

    def can_reach(self, coord):
        return self.battery >= self.energy_for(coord)

    def scan(self, coord):
        self.battery -= self.energy_for(coord)
        self.position = coord
        self.scanned.append(coord)

    def status(self):
        return "{} at altitude {}m: {} battery left, {} scans".format(
            self.name, self.altitude, self.battery, len(self.scanned))


class CommandCenter:
    def __init__(self, fleet_size=3, base_altitude=40):
        self.fleet = [Flyer("flyer-%d" % i, base_altitude + 10 * i, 60 + 20 * i)
                      for i in range(fleet_size)]
        self.skipped = []

    def best_candidate(self, coord):
        able = [flyer for flyer in self.fleet if flyer.can_reach(coord)]
        if not able:
            return None
        return max(able, key=lambda flyer: flyer.battery - flyer.energy_for(coord))

    def assign(self, coord):
        flyer = self.best_candidate(coord)
        if flyer is None:
            self.skipped.append(coord)
            return None
        flyer.scan(coord)
        return flyer

    def dispatch(self, targets):
        for coord in targets:
            self.assign(coord)
        return self.unique_scanned()

    def unique_scanned(self):
        covered = set()
        for flyer in self.fleet:
            covered.update(flyer.scanned)
        return covered

    def report(self):
        lines = [flyer.status() for flyer in self.fleet]
        lines.append("unique coordinates scanned: %d" % len(self.unique_scanned()))
        if self.skipped:
            lines.append("targets out of range: %d" % len(self.skipped))
        return "\n".join(lines)


def _as_coord(item):
    pair = tuple(item)
    if len(pair) != 2 or not all(isinstance(value, int) for value in pair):
        raise ValueError("each target must be a pair of integers: %r" % (item,))
    return pair


def survey(grid):
    center = CommandCenter()
    return len(center.dispatch([_as_coord(item) for item in grid]))


def main():
    grid = [(1, 1), (2, 3), (1, 1), (5, 5), (6, 6), (-3, 4), (0, 9), (7, 7)]
    print("total unique coordinates scanned: %d" % survey(grid))
    center = CommandCenter()
    center.dispatch([_as_coord(item) for item in grid])
    print(center.report())


if __name__ == "__main__":
    main()

