class WarningSignal:
    def __init__(self, sensor_id, pressure, deviation):
        self.sensor_id = sensor_id
        self.pressure = pressure
        self.deviation = deviation

    def __str__(self):
        return "!! {} read {:.1f} (deviation {:+.1f})".format(
            self.sensor_id, self.pressure, self.deviation)


class PressureSensor:
    def __init__(self, sensor_id, baseline, threshold):
        self.sensor_id = sensor_id
        self.baseline = float(baseline)
        self.threshold = float(threshold)
        self.samples = 0
        self.warnings = []

    def receive(self, pressure):
        self.samples += 1
        deviation = pressure - self.baseline
        if abs(deviation) > self.threshold:
            signal = WarningSignal(self.sensor_id, pressure, deviation)
            self.warnings.append(signal)
            return signal
        return None

    def summary(self):
        return "{}: baseline {:.1f}, threshold {:.1f}, {} samples, {} warnings".format(
            self.sensor_id, self.baseline, self.threshold, self.samples, len(self.warnings))


class SensorNetwork:
    def __init__(self, sensors):
        self.sensors = dict((sensor.sensor_id, sensor) for sensor in sensors)
        self.order = [sensor.sensor_id for sensor in sensors]
        self.signals = []
        self.dispatched = 0

    def _target(self, reading):
        if isinstance(reading, (tuple, list)):
            sensor_id, pressure = reading
            if sensor_id not in self.sensors:
                raise KeyError("unknown sensor %r" % (sensor_id,))
            return self.sensors[sensor_id], float(pressure)
        sensor_id = self.order[self.dispatched % len(self.order)]
        return self.sensors[sensor_id], float(reading)

    def feed(self, reading):
        sensor, pressure = self._target(reading)
        self.dispatched += 1
        signal = sensor.receive(pressure)
        if signal is not None:
            self.signals.append(signal)
        return signal

    def run(self, waves):
        for reading in waves:
            self.feed(reading)
        return len(self.signals)

    def report(self):
        lines = ["%d warnings from %d readings" % (len(self.signals), self.dispatched)]
        for sensor_id in self.order:
            lines.append("  " + self.sensors[sensor_id].summary())
        for signal in self.signals:
            lines.append("  " + str(signal))
        return "\n".join(lines)


def build_network():
    return SensorNetwork([
        PressureSensor("buoy-A", 1013.0, 4.0),
        PressureSensor("buoy-B", 1010.0, 2.5),
        PressureSensor("buoy-C", 1015.0, 6.0),
    ])


def monitor(waves):
    return build_network().run(waves)


def main():
    waves = [1013.5, 1009.0, 1021.0, 1006.0, 1010.5, 1016.0,
             ("buoy-B", 1020.0), ("buoy-C", 1015.5), ("buoy-A", 1000.0)]
    network = build_network()
    total = network.run(waves)
    print(network.report())
    print("monitor() ->", total)
    print("calm sea ->", monitor([1013.0, 1010.0, 1015.0]))


if __name__ == "__main__":
    main()

