class Carriage:
    def __init__(self, carriage_id, capacity):
        self.carriage_id = carriage_id
        self.capacity = capacity
        self.station_index = 0
        self.passenger_load = 0

    def board(self, count):
        room = self.capacity - self.passenger_load
        admitted = min(count, max(room, 0))
        self.passenger_load += admitted
        return admitted

    def advance(self, station_count):
        self.station_index = (self.station_index + 1) % station_count
        return self.station_index

    def describe(self):
        return "carriage {0}: {1}/{2} riders at station {3}".format(
            self.carriage_id, self.passenger_load, self.capacity, self.station_index)


class RailRoute:
    def __init__(self, name, station_count, fleet_size, capacity=120):
        self.name = name
        self.station_count = station_count
        self.total_delay = 0
        self.carriages = [Carriage("{0}-{1}".format(name, i), capacity)
                          for i in range(fleet_size)]

    def carriage_at(self, index):
        return self.carriages[index % len(self.carriages)]

    def load_passengers(self, carriage_index, count):
        carriage = self.carriage_at(carriage_index)
        admitted = carriage.board(count)
        carriage.advance(self.station_count)
        return admitted

    def register_obstacle(self, penalty):
        self.total_delay += penalty
        return self.total_delay

    def report(self):
