class Carriage:
    def __init__(this, carriage_id, capacity):
        this.carriage_id = carriage_id
        this.capacity = capacity
        this.station_index = 0
        this.passenger_load = 0

    def board(this, count):
        room = this.capacity - this.passenger_load
        admitted = min(count, max(room, 0))
        this.passenger_load += admitted
        return admitted

    def advance(this, station_count):
        this.station_index = (this.station_index + 1) % station_count
        return this.station_index

    def describe(this):
        return "carriage {0}: {1}/{2} riders at station {3}".format(
            this.carriage_id, this.passenger_load, this.capacity, this.station_index)


class RailRoute:
    def __init__(this, name, station_count, fleet_size, capacity=120):
        this.name = name
        this.station_count = station_count
        this.total_delay = 0
        this.carriages = [Carriage("{0}-{1}".format(name, i), capacity)
                          for i in range(fleet_size)]

    def carriage_at(this, index):
        return this.carriages[index % len(this.carriages)]

    def load_passengers(this, carriage_index, count):
        carriage = this.carriage_at(carriage_index)
        admitted = carriage.board(count)
        carriage.advance(this.station_count)
