class Receiver:
    def __init__(self, ident, dosage):
        if not isinstance(dosage, int) or isinstance(dosage, bool):
            raise TypeError("dosage must be an integer: %r" % (dosage,))
        if dosage <= 0:
            raise ValueError("dosage must be positive: %d" % dosage)
        self.ident = ident
        self.dosage = dosage
        self.health = 20
        self.deliveries = 0

    def receive(self, amount):
        self.deliveries += 1
        self.health = min(100, self.health + amount * 2)
        return self.health

    def is_stable(self):
        return self.health >= 60

    def label(self):
        condition = "stable" if self.is_stable() else "fragile"
        return "%s: %d (%s)" % (self.ident, self.health, condition)


class CareUnit:
    def __init__(self, name):
        self.name = name
        self.receivers = []
        self.fulfilled = 0

    def admit(self, receiver):
        self.receivers.append(receiver)
        return len(self.receivers)

    def holds(self, receiver):
        return receiver in self.receivers

    def administer(self, receiver, amount):
        if not self.holds(receiver):
            raise ValueError("%s is not admitted to %s" % (receiver.ident, self.name))
        health = receiver.receive(amount)
        self.fulfilled += 1
        return health

    def fragile(self):
        return [r for r in self.receivers if not r.is_stable()]

    def summary(self):
        return "%s: %d deliveries, %d still fragile" % (
            self.name, self.fulfilled, len(self.fragile()))


class Dispensary:
    def __init__(self, inventory):
        self.inventory = inventory
        self.units = []
        self.denied = []

    def register(self, unit):
        self.units.append(unit)
        return unit

    def unit_of(self, receiver):
        for unit in self.units:
            if unit.holds(receiver):
                return unit
        return None

    def request(self, receiver, amount):
        unit = self.unit_of(receiver)
        if unit is None or amount > self.inventory:
            self.denied.append(receiver.ident)
            return False
        self.inventory -= amount
        unit.administer(receiver, amount)
        return True

    def report(self):
        lines = ["remaining inventory: %d" % self.inventory]
        lines.extend(unit.summary() for unit in self.units)
        if self.denied:
            lines.append("denied requests: " + ", ".join(self.denied))
        return lines


def dispense(prescriptions):
    dispensary = Dispensary(sum(p for p in prescriptions if isinstance(p, int)) - 4)
    units = [dispensary.register(CareUnit(name)) for name in ("Ward A", "Ward B", "ICU")]
    receivers = []
    for index, dosage in enumerate(prescriptions):
        receiver = Receiver("P%d" % (index + 1), dosage)
        units[index % len(units)].admit(receiver)
        receivers.append(receiver)
    for receiver in receivers:
        dispensary.request(receiver, receiver.dosage)
    for line in dispensary.report():
        print(line)
    return [receiver.label() for receiver in receivers]


if __name__ == "__main__":
    for status in dispense([10, 5, 30, 8, 12, 3]):
        print(status)

