class Participant:
    def __init__(self, name, faction, skill, energy):
        self.name = name
        self.faction = faction
        self.skill = skill
        self.energy = energy

    def is_exhausted(self):
        return self.energy <= 0

    def spend_energy(self, amount):
        self.energy = max(0, self.energy - amount)
        return self.energy

    def label(self):
        return "{} of {} (skill {}, energy {})".format(
            self.name, self.faction.name, self.skill, self.energy)


class Faction:
    def __init__(self, name):
        self.name = name
        self.score = 0
        self.members = {}

    def enroll(self, name, skill, energy):
        if name not in self.members:
            self.members[name] = Participant(name, self, skill, energy)
        return self.members[name]

    def award(self, points):
        self.score += points
        return self.score

    def summary(self):
        return "{}: {} points from {} participants".format(
            self.name, self.score, len(self.members))


class Organizer:
    WIN_POINTS = 3
    FORFEIT_POINTS = 1
    ENERGY_COST = 1

    def __init__(self):
        self.factions = {}
        self.log = []

    def register(self, spec):
        name, faction_name, skill, energy = spec
        if faction_name not in self.factions:
            self.factions[faction_name] = Faction(faction_name)
        return self.factions[faction_name].enroll(name, skill, energy)

    def challenge(self, first, second):
        if first.is_exhausted() and second.is_exhausted():
            self.log.append("{} and {} both forfeit".format(first.name, second.name))
            return None
        if first.is_exhausted():
            return self.resolve_forfeit(second, first)
        if second.is_exhausted():
            return self.resolve_forfeit(first, second)
        first.spend_energy(self.ENERGY_COST)
        second.spend_energy(self.ENERGY_COST)
        if first.skill == second.skill:
            self.log.append("{} vs {} ends in a draw".format(first.name, second.name))
            return None
        winner = first if first.skill > second.skill else second
        winner.faction.award(self.WIN_POINTS)
        self.log.append("{} wins the duel".format(winner.label()))
        return winner

    def resolve_forfeit(self, winner, loser):
        winner.faction.award(self.FORFEIT_POINTS)
        self.log.append("{} takes the win, {} had no energy".format(winner.name, loser.name))
        return winner

    def run(self, matches):
        for left, right in matches:
            self.challenge(self.register(left), self.register(right))
        return self.standings()

    def standings(self):
        return {name: faction.score for name, faction in self.factions.items()}

    def report(self):
        lines = list(self.log)
        for faction in sorted(self.factions.values(), key=lambda f: -f.score):
            lines.append(faction.summary())
        return "\n".join(lines)


def compete(matches):
    organizer = Organizer()
    return organizer.run(matches)


if __name__ == "__main__":
    duels = [
        (("Mira", "Ravens", 7, 2), ("Jonas", "Owls", 5, 2)),
        (("Mira", "Ravens", 7, 2), ("Tal", "Owls", 9, 1)),
        (("Mira", "Ravens", 7, 2), ("Tal", "Owls", 9, 1)),
        (("Jonas", "Owls", 5, 2), ("Selen", "Ravens", 5, 3)),
    ]
    print(compete(duels))

