class Staff:
    def __init__(self, name, base_salary, multiplier):
        self.name = name
        self.base_salary = float(base_salary)
        self.multiplier = float(multiplier)

    def raise_amount(self):
        return self.base_salary * 0.05 * self.multiplier

    def apply_raise(self):
        amount = self.raise_amount()
        self.base_salary += amount
        return amount

    def describe(self):
        return "{:<10} {:>10.2f}  x{:.2f}".format(self.name, self.base_salary, self.multiplier)


class Division:
    def __init__(self, name, target_fund, fund):
        self.name = name
        self.target_fund = float(target_fund)
        self.fund = float(fund)
        self.staff = []

    def hire(self, member):
        self.staff.append(member)
        return self

    def deficit(self):
        return max(0.0, self.target_fund - self.fund)

    def receive(self, amount):
        self.fund += amount

    def pay_raises(self):
        spent = 0.0
        for member in self.staff:
            cost = member.raise_amount()
            if cost > self.fund:
                break
            member.apply_raise()
            self.fund -= cost
            spent += cost
        return spent

    def report(self):
        lines = ["{} fund {:.2f} of target {:.2f}".format(self.name, self.fund, self.target_fund)]
        for member in self.staff:
            lines.append("    " + member.describe())
        return "\n".join(lines)


class Corporation:
    def __init__(self, name):
        self.name = name
        self.divisions = []
        self.total_received = 0.0
        self.total_spent = 0.0

    def add_division(self, division):
        self.divisions.append(division)
        return division

    def distribute(self, package):
        deficits = [division.deficit() for division in self.divisions]
        total_deficit = sum(deficits)
        self.total_received += package
        for division, deficit in zip(self.divisions, deficits):
            if total_deficit > 0:
                division.receive(package * deficit / total_deficit)
            else:
                division.receive(package / len(self.divisions))

    def pay_raises(self):
        round_cost = sum(division.pay_raises() for division in self.divisions)
        self.total_spent += round_cost
        return round_cost

    def balances(self):
        return [round(division.fund, 2) for division in self.divisions]

    def summary(self):
        header = "{}: received {:.2f}, paid out {:.2f}".format(
            self.name, self.total_received, self.total_spent)
        return "\n".join([header] + [division.report() for division in self.divisions])


def simulate(budgets):
    corp = Corporation("Meridian Group")
    research = corp.add_division(Division("Research", 40000.0, 9000.0))
    research.hire(Staff("Ada", 82000.0, 1.4)).hire(Staff("Linus", 74000.0, 0.9))
    sales = corp.add_division(Division("Sales", 25000.0, 15000.0))
    sales.hire(Staff("Grace", 61000.0, 1.1)).hire(Staff("Ken", 58000.0, 1.6))
    support = corp.add_division(Division("Support", 18000.0, 2500.0))
    support.hire(Staff("Barbara", 47000.0, 1.2))
    for package in budgets:
        if not isinstance(package, (int, float)) or package < 0:
            raise ValueError("budget packages must be non-negative numbers")
        corp.distribute(float(package))
        corp.pay_raises()
    return corp


def restructure(budgets):
    return simulate(budgets).balances()


if __name__ == "__main__":
    packages = [30000, 12000, 5000]
    print(restructure(packages))
    print(simulate(packages).summary())

