class Fragment:
    def __init__(self, source, destination, payload):
        self.source = source
        self.destination = destination
        self.payload = payload

    def size(self):
        return len(self.payload)

    def describe(self):
        return "{} -> {} ({} bytes)".format(self.source, self.destination, self.size())


class Gateway:
    def __init__(self, name):
        self.name = name
        self.routes = {}
        self.buffer = []

    def add_route(self, destination, next_hop):
        self.routes[destination] = next_hop

    def accept(self, fragment):
        self.buffer.append(fragment)

    def next_hop(self, fragment):
        if fragment.destination == self.name:
            return None
        if fragment.destination not in self.routes:
            raise ValueError("gateway {} has no route to {}".format(self.name, fragment.destination))
        return self.routes[fragment.destination]

    def load(self):
        return sum(fragment.size() for fragment in self.buffer)

    def report(self):
        return "{}: {} fragment(s), {} bytes".format(self.name, len(self.buffer), self.load())


class Internetwork:
    def __init__(self, entry):
        self.entry = entry
        self.gateways = {}
        self.trace = []

    def build_chain(self, names):
        for name in names:
            self.gateways[name] = Gateway(name)
        for index, name in enumerate(names):
            gateway = self.gateways[name]
            for other_index, other in enumerate(names):
                if other_index > index:
                    gateway.add_route(other, names[index + 1])
                elif other_index < index:
                    gateway.add_route(other, names[index - 1])

    def deliver(self, fragment):
        gateway = self.gateways[fragment.source]
        gateway.accept(fragment)
        self.trace.append("{} at {}".format(fragment.describe(), gateway.name))
        hop = gateway.next_hop(fragment)
        while hop is not None:
            gateway = self.gateways[hop]
            gateway.accept(fragment)
            self.trace.append("{} at {}".format(fragment.describe(), gateway.name))
            hop = gateway.next_hop(fragment)
        return gateway

    def transmit(self, traffic):
        terminal = None
        for destination, payload in traffic:
            if destination not in self.gateways:
                raise ValueError("unknown destination gateway: {}".format(destination))
            terminal = self.deliver(Fragment(self.entry, destination, payload))
        return terminal

    def topology(self):
        return " - ".join(sorted(self.gateways))


def route(traffic):
    entries = [(str(destination), str(payload)) for destination, payload in traffic]
    if not entries:
        return 0
    names = ["A"]
    for destination, _payload in entries:
        if destination not in names:
            names.append(destination)
    network = Internetwork("A")
    network.build_chain(sorted(names))
    terminal = network.transmit(entries)
    return len(terminal.buffer)


def main():
    traffic = [("C", "hello"), ("D", "world"), ("C", "again"), ("C", "final")]
    print("fragments at ultimate destination:", route(traffic))
    network = Internetwork("A")
    network.build_chain(["A", "B", "C", "D"])
    network.transmit(traffic)
    print("topology:", network.topology())
    for name in sorted(network.gateways):
        print(network.gateways[name].report())
    for step in network.trace:
        print(step)


if __name__ == "__main__":
    main()

