class Generator:
    def __init__(self, name, rated_output):
        self.name = name
        self.rated_output = rated_output
        self.derating = 0

    def apply_drop(self, amount):
        self.derating = max(0, min(amount, self.rated_output))

    def output(self):
        return self.rated_output - self.derating

    def describe(self):
        return "{0}: {1}/{2} W".format(self.name, self.output(), self.rated_output)


class Sector:
    TIER_DEMAND = {0: 0, 1: 40, 2: 90, 3: 160}

    def __init__(self, name, tier=3):
        self.name = name
        self.tier = tier

    def demand(self):
        return self.TIER_DEMAND[self.tier]

    def can_lower(self):
        return self.tier > 0

    def lower_tier(self):
        self.tier -= 1
        return self.demand()

    def can_raise(self, headroom):
        if self.tier >= max(self.TIER_DEMAND):
            return False
        return self.TIER_DEMAND[self.tier + 1] - self.demand() <= headroom

    def raise_tier(self):
        self.tier += 1
        return self.demand()

    def describe(self):
        return "{0}: tier {1} ({2} W)".format(self.name, self.tier, self.demand())


class Grid:
    def __init__(self, generators, sectors):
        self.generators = generators
        self.sectors = sectors

    def production(self):
        return sum(unit.output() for unit in self.generators)

    def consumption(self):
        return sum(sector.demand() for sector in self.sectors)

    def regulate(self):
        available = self.production()
        while self.consumption() > available:
            greedy = [s for s in self.sectors if s.can_lower()]
            if not greedy:
                break
            greedy.sort(key=lambda s: (-s.demand(), s.name))
            greedy[0].lower_tier()
        for sector in self.sectors:
            while sector.can_raise(available - self.consumption()):
                sector.raise_tier()
        return self.consumption()

    def dispatch(self, index, drop):
        unit = self.generators[index % len(self.generators)]
        unit.apply_drop(drop)
        return self.regulate()

    def tiers(self):
        return [sector.tier for sector in self.sectors]

    def report(self):
        lines = [unit.describe() for unit in self.generators]
        lines += [sector.describe() for sector in self.sectors]
        lines.append("load {0} W of {1} W".format(self.consumption(), self.production()))
        return "\n".join(lines)


def balance(fluctuations):
    generators = [Generator("GEN-A", 220), Generator("GEN-B", 180), Generator("GEN-C", 150)]
    sectors = [Sector("HAB-1"), Sector("HAB-2"), Sector("HAB-3"), Sector("HAB-4")]
    grid = Grid(generators, sectors)
    grid.regulate()
    for index, drop in enumerate(fluctuations):
        grid.dispatch(index, drop)
    return grid.tiers()


if __name__ == "__main__":
    generators = [Generator("GEN-A", 220), Generator("GEN-B", 180), Generator("GEN-C", 150)]
    sectors = [Sector("HAB-1"), Sector("HAB-2"), Sector("HAB-3"), Sector("HAB-4")]
