class Champion:
    def __init__(self, name, health, attack, defense):
        self.name = name
        self.health = health
        self.attack = attack
        self.defense = defense
        self.defeated = False

    def strike_power(self):
        return self.attack

    def receive_attack(self, power):
        damage = power - self.defense
        if damage > 0:
            self.health -= damage
        if self.health < 0:
            self.defeated = True
        return self.health

    def is_alive(self):
        return not self.defeated

    def describe(self):
        state = "defeated" if self.defeated else "hp=%d" % self.health
        return "%s(%s)" % (self.name, state)


class Group:
    def __init__(self, label, roster):
        self.label = label
        self.champions = [Champion(*entry) for entry in roster]

    def champion_at(self, index):
        if index < 0 or index >= len(self.champions):
            raise IndexError("%s has no champion %d" % (self.label, index))
        return self.champions[index]

    def survivors(self):
        return sum(1 for champion in self.champions if champion.is_alive())

    def summary(self):
        return "%s: %s" % (self.label, ", ".join(c.describe() for c in self.champions))


class Arena:
    def __init__(self, left_roster, right_roster):
        self.left = Group("Left", left_roster)
        self.right = Group("Right", right_roster)
        self.turn = 0

    def sides(self):
        if self.turn % 2 == 0:
            return self.left, self.right
        return self.right, self.left

    def play(self, attacker_index, target_index):
        offense, defense = self.sides()
        self.turn += 1
        attacker = offense.champion_at(attacker_index)
        target = defense.champion_at(target_index)
        if attacker.is_alive() and target.is_alive():
            target.receive_attack(attacker.strike_power())

    def run(self, actions):
        for attacker_index, target_index in actions:
            self.play(attacker_index, target_index)
        return self.left.survivors(), self.right.survivors()

    def report(self):
        return "%s\n%s" % (self.left.summary(), self.right.summary())


def resolve(actions):
    left_roster = [("A1", 30, 12, 3), ("A2", 25, 9, 5), ("A3", 40, 7, 2)]
    right_roster = [("B1", 28, 11, 4), ("B2", 35, 8, 6), ("B3", 22, 14, 1)]
    arena = Arena(left_roster, right_roster)
    result = arena.run(actions)
    print(arena.report())
    return result


