PRICE = 100.0


class Holding:
    def __init__(self, ticker, shares):
        self.ticker = ticker
        self.shares = shares

    def add_shares(self, count):
        self.shares += count
        return self.shares

    def remove_shares(self, count):
        sold = min(count, self.shares)
        self.shares -= sold
        return sold

    def describe(self):
        return "{}x{}".format(self.ticker, self.shares)


class Account:
    def __init__(self, name, cash, holdings):
        self.name = name
        self.cash = cash
        self.holdings = list(holdings)

    def holding_for(self, ticker):
        for holding in self.holdings:
            if holding.ticker == ticker:
                return holding
        return None

    def buy(self, ticker, shares):
        cost = shares * PRICE
        if self.cash < cost:
            return False
        self.cash -= cost
        holding = self.holding_for(ticker)
        if holding is None:
            holding = Holding(ticker, 0)
            self.holdings.append(holding)
        holding.add_shares(shares)
        return True

    def sell(self, ticker, shares):
        holding = self.holding_for(ticker)
        if holding is None:
            return False
        sold = holding.remove_shares(shares)
        self.cash += sold * PRICE
        return sold > 0

    def report(self):
        positions = ", ".join(h.describe() for h in self.holdings) or "no positions"
        return "{:<8} cash={:>10.2f}  {}".format(self.name, self.cash, positions)


class WealthTracker:
    def __init__(self, accounts):
        self.accounts = accounts
        self.executed = 0
        self.skipped = 0

    def route(self, ticker):
        for account in self.accounts:
            if account.holding_for(ticker) is not None:
                return account
        return max(self.accounts, key=lambda account: account.cash)

    def execute(self, ticker, side, shares):
        account = self.route(ticker)
        if side == "buy":
            done = account.buy(ticker, shares)
        elif side == "sell":
            done = account.sell(ticker, shares)
        else:
            raise ValueError("unknown transaction type: {}".format(side))
        if done:
            self.executed += 1
        else:
            self.skipped += 1

    def process(self, orders):
        for ticker, side, shares in orders:
            self.execute(ticker, side, shares)
        return self.balances()

    def balances(self):
        return [account.cash for account in self.accounts]

    def summary(self):
        lines = [account.report() for account in self.accounts]
        lines.append("executed={} skipped={}".format(self.executed, self.skipped))
        return "\n".join(lines)


def trade(orders):
    tracker = WealthTracker([
        Account("alpha", 5000.0, [Holding("AAPL", 10), Holding("MSFT", 5)]),
        Account("beta", 1200.0, [Holding("TSLA", 4)]),
    ])
    final = tracker.process(orders)
    print(tracker.summary())
    return final


