class Worker:
    MAX_SHIFT = 8

    def __init__(self, certification):
        self.certification = certification
        self.shift_hours = 0

    def is_qualified_for(self, mixture):
        return self.certification >= mixture.required_level

    def is_available(self):
        return self.shift_hours < self.MAX_SHIFT

    def handle(self, mixture):
        self.shift_hours += 1
        mixture.mark_prepared(self)
        return self

    def describe(self):
        return "worker(level {}) worked {}h".format(self.certification, self.shift_hours)


class Mixture:
    def __init__(self, required_level):
        self.required_level = required_level
        self.prepared = False
        self.handler = None

    def mark_prepared(self, worker):
        self.prepared = True
        self.handler = worker

    def describe(self):
        if not self.prepared:
            return "mixture(level {}) pending".format(self.required_level)
        return "mixture(level {}) by level-{} worker".format(
            self.required_level, self.handler.certification)


class Facility:
    def __init__(self, certifications):
        self.workers = [Worker(level) for level in sorted(certifications)]
        self.mixtures = []

    def hire(self, certification):
        worker = Worker(certification)
        self.workers.append(worker)
        self.workers.sort(key=lambda w: w.certification)
        return worker

    def pick_worker(self, mixture):
        candidates = [w for w in self.workers if w.is_qualified_for(mixture) and w.is_available()]
        if not candidates:
            return self.hire(mixture.required_level)
        return min(candidates, key=lambda w: (w.shift_hours, w.certification))

    def submit(self, required_level):
        mixture = Mixture(required_level)
        self.mixtures.append(mixture)
        self.pick_worker(mixture).handle(mixture)
        return mixture

    def shift_report(self):
        return [worker.shift_hours for worker in self.workers]

    def summary(self):
        lines = [worker.describe() for worker in self.workers]
        lines.extend(mixture.describe() for mixture in self.mixtures)
        return "\n".join(lines)


def synthesize(formulas):
    levels = []
    for level in formulas:
        if not isinstance(level, int) or isinstance(level, bool) or level < 0:
            raise ValueError("safety levels must be non-negative integers: {!r}".format(level))
        levels.append(level)
    facility = Facility(set(levels))
    for level in levels:
        facility.submit(level)
    print(facility.summary())
    return facility.shift_report()


if __name__ == "__main__":
    print(synthesize([1, 2, 2, 3, 1, 5]))

