SAFE_THRESHOLD = 100.0


class AudioSensor:
    def __init__(self, label, base_volume, clarity):
        self.label = label
        self.base_volume = float(base_volume)
        self.clarity = float(clarity)

    def boost(self, amount):
        self.base_volume += amount
        if self.base_volume > SAFE_THRESHOLD:
            self.degrade()

    def degrade(self):
        excess = self.base_volume - SAFE_THRESHOLD
        self.clarity = max(0.0, self.clarity - 0.5 * excess)

    def describe(self):
        return "{0}: {1:.1f} dB / clarity {2:.2f}".format(
            self.label, self.base_volume, self.clarity)


class SeatingZone:
    def __init__(self, zone_id, sensor_count=3):
        self.zone_id = zone_id
        self.sensors = [
            AudioSensor("{0}-S{1}".format(zone_id, i + 1), 70 + 5 * i, 100.0)
            for i in range(sensor_count)
        ]

    def average_volume(self):
        return sum(s.base_volume for s in self.sensors) / len(self.sensors)

    def average_clarity(self):
        return sum(s.clarity for s in self.sensors) / len(self.sensors)

    def apply_spike(self, spike):
        share = spike / len(self.sensors)
        for sensor in self.sensors:
            sensor.boost(share)
        return self.average_volume()

    def summary(self):
        lines = ["Zone {0} (avg {1:.1f} dB)".format(self.zone_id, self.average_volume())]
        for sensor in self.sensors:
            lines.append("  " + sensor.describe())
        return "\n".join(lines)


class Building:
    def __init__(self, zone_ids):
        self.zones = {}
        self.order = []
        for zone_id in zone_ids:
            if zone_id not in self.zones:
                self.zones[zone_id] = SeatingZone(zone_id)
                self.order.append(zone_id)

    def dispatch(self, zone_id, spike):
        if zone_id not in self.zones:
            raise KeyError("unknown seating zone: {0!r}".format(zone_id))
        return self.zones[zone_id].apply_spike(spike)

    def run(self, events):
        for zone_id, spike in events:
            self.dispatch(zone_id, spike)
        return self.report()

    def report(self):
        return {zone_id: self.zones[zone_id].average_clarity() for zone_id in self.order}

    def render(self):
        return "\n".join(self.zones[zone_id].summary() for zone_id in self.order)


def calibrate(sounds):
    events = []
    for entry in sounds:
        zone_id, spike = entry
        events.append((zone_id, int(spike)))
    building = Building(zone_id for zone_id, _ in events)
    return building.run(events)


def main():
    sounds = [("A", 30), ("B", 120), ("A", 90), ("C", 15), ("B", 60)]
    building = Building(zone_id for zone_id, _ in sounds)
    building.run(sounds)
    print(building.render())
    for zone_id, clarity in calibrate(sounds).items():
        print("zone {0} clarity {1:.2f}".format(zone_id, clarity))


if __name__ == "__main__":
    main()

