import math

class NumberChecker:
    def __init__(self, number):
        self.number = number
        self.is_greater_than_one = False
        self.divisors = []

    def check_greater_than_one(self):
        self.is_greater_than_one = self.number > 1
        return self.is_greater_than_one

    def find_divisors(self):
        self.divisors = []
        for i in range(2, int(math.sqrt(self.number)) + 1):
            if self.number % i == 0:
                self.divisors.append(i)
                self.divisors.append(self.number // i)
        return self.divisors

class PrimeValidator:
    def __init__(self, checker):
        self.checker = checker
        self.is_prime_status = False

    def validate_prime(self):
        if not self.checker.check_greater_than_one():
            self.is_prime_status = False
            return self.is_prime_status
        self.checker.find_divisors()
        self.is_prime_status = not self.checker.divisors
        return self.is_prime_status

class PrimeDeterminer:
    def __init__(self, value):
        self.value = value
        self.number_checker = NumberChecker(self.value)
        self.prime_validator = PrimeValidator(self.number_checker)
        self.result = False

    def determine(self):
        self.result = self.prime_validator.validate_prime()
        return self.result

def is_prime(n):
    determiner = PrimeDeterminer(n)
    return determiner.determine()

