class TemperatureConverter:
    def __init__(self):
        self.conversion_factor = 9/5
        self.offset = 32

    def _convert_celsius(self, celsius_value):
        self.celsius = celsius_value
        return self.celsius * self.conversion_factor

    def to_fahrenheit(self, celsius_value):
        self.fahrenheit_temp = self._convert_celsius(celsius_value) + self.offset
        return self.fahrenheit_temp

class TemperatureFormatter:
    def __init__(self, precision=1):
        self.precision = precision

    def format_temperature(self, temp_value):
        self.formatted_string = f"{temp_value:.{self.precision}f}"
        return float(self.formatted_string)

class TemperatureProcessor:
    def __init__(self):
        self.converter = TemperatureConverter()
        self.formatter = TemperatureFormatter()

    def celsius_to_fahrenheit(self, celsius):
        self.celsius_input = celsius
        self.fahrenheit_raw = self.converter.to_fahrenheit(self.celsius_input)
        self.fahrenheit_formatted = self.formatter.format_temperature(self.fahrenheit_raw)
        return self.fahrenheit_formatted

def celsius_to_fahrenheit(celsius):
    processor = TemperatureProcessor()
    return processor.celsius_to_fahrenheit(celsius)

