class BMICalculator:
    def __init__(self, weight, height):
        self.weight_kg = weight
        self.height_m = height

    def _validate_inputs(self):
        if not isinstance(self.weight_kg, (int, float)) or not isinstance(self.height_m, (int, float)):
            raise TypeError("Weight and height must be numeric.")
        if self.weight_kg <= 0 or self.height_m <= 0:
            raise ValueError("Weight and height must be positive.")
        return True

    def calculate_bmi_value(self):
        self._validate_inputs()
        bmi = self.weight_kg / (self.height_m ** 2)
        return bmi

