class QueueSimulator:
    def __init__(self):
        self.queue = []

    def enqueue_item(self, item):
        self.queue.append(item)
        return self.queue

    def dequeue_item(self):
        if self.queue:
            self.queue.pop(0)
        return self.queue

    def get_current_queue(self):
        return self.queue

class OperationHandler:
    def __init__(self, simulator_instance):
        self.simulator = simulator_instance

    def process_operation(self, operation_type, item):
        if operation_type == 'enqueue':
            self.simulator.enqueue_item(item)
        elif operation_type == 'dequeue':
            self.simulator.dequeue_item()
        return self.simulator.get_current_queue()

class QueueManager:
    def __init__(self):
        self.simulator = QueueSimulator()
        self.handler = OperationHandler(self.simulator)

    def run_operations(self, operations_list):
        for op_type, item_value in operations_list:
            self.handler.process_operation(op_type, item_value)
        return self.simulator.get_current_queue()

def simulate_queue(operations):
    manager = QueueManager()
    return manager.run_operations(operations)

