class TimeConverter:
    def __init__(self, total_seconds):
        self.total_seconds = total_seconds
        self.hours = 0
        self.minutes = 0
        self.seconds = 0

    def _calculate_hms(self):
        self.hours = self.total_seconds // 3600
        remaining_seconds = self.total_seconds % 3600
        self.minutes = remaining_seconds // 60
        self.seconds = remaining_seconds % 60

    def get_hms_values(self):
        self._calculate_hms()
        return self.hours, self.minutes, self.seconds

class Formatter:
    def __init__(self):
        pass

    def _pad(self, value):
        return f"{value:02d}"

    def format_time_components(self, hours, minutes, seconds):
        self.formatted_hours = self._pad(hours)
        self.formatted_minutes = self._pad(minutes)
        self.formatted_seconds = self._pad(seconds)
        return f"{self.formatted_hours}:{self.formatted_minutes}:{self.formatted_seconds}"

class HMSRenderer:
    def __init__(self, total_seconds):
        self.converter = TimeConverter(total_seconds)
        self.formatter = Formatter()

    def render(self):
        h, m, s = self.converter.get_hms_values()
        self.hms_string = self.formatter.format_time_components(h, m, s)
        return self.hms_string

def seconds_to_hms(seconds):
    renderer = HMSRenderer(seconds)
    return renderer.render()

