class Validator:
    def __init__(self):
        self.bracket_map = {")": "(", "}": "{", "]": "["}

    def check(self, s):
        stack_manager = StackManager()
        for char in s:
            if char in self.bracket_map.values():
                stack_manager.push(char)
            elif char in self.bracket_map:
                if not stack_manager.peek() or stack_manager.pop() != self.bracket_map[char]:
                    return False
            else:
                return False
        return not stack_manager.peek()

class StackManager:
    def __init__(self):
        self.stack = []

    def push(self, item):
        self.stack.append(item)
        return self.stack

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        return None

    def peek(self):
        if not self.is_empty():
            return self.stack[-1]
        return None

    def is_empty(self):
        return len(self.stack) == 0

class Solution:
    def is_valid_parentheses(self, s: str) -> bool:
        validator = Validator()
        return validator.check(s)

def is_valid_parentheses(s: str) -> bool:
    solution = Solution()
    return solution.is_valid_parentheses(s)

