        self.normalized_s2 = self.processor._normalize(s2)

        if len(self.normalized_s1) != len(self.normalized_s2):
            return False

        self.counts1 = self.counter._count_characters(self.normalized_s1)
        self.counts2 = self.counter._count_characters(self.normalized_s2)

        return self.counts1 == self.counts2

def is_anagram(s1, s2):
    checker = AnagramChecker()
    return checker.is_anagram(s1, s2)

