class ListComparator:
    def __init__(self, primary_list):
        self.primary_list = primary_list
        self.result = []

    def find_difference(self, secondary_list):
        for item in self.primary_list:
            if not self._is_in_secondary(item, secondary_list):
                self.result.append(item)
        return self.result

    def _is_in_secondary(self, item, secondary_list):
