class FibonacciCalculator:
    def __init__(self):
        self.memo = {}

    def calculate_fibonacci(self, n):
        if n in self.memo:
            return self.memo[n]
        if n <= 1:
            self.memo[n] = n
            return self.memo[n]

        fib_n_minus_1 = self.calculate_fibonacci(n - 1)
        fib_n_minus_2 = self.calculate_fibonacci(n - 2)
        result = fib_n_minus_1 + fib_n_minus_2
        self.memo[n] = result
        return self.memo[n]

class FibonacciSequenceManager:
    def __init__(self):
        self.calculator = FibonacciCalculator()

    def get_nth_fibonacci_number(self, n):
        return self.calculator.calculate_fibonacci(n)

class Solution:
    def __init__(self):
        self.manager = FibonacciSequenceManager()

    def nth_fibonacci(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("Input must be a non-negative integer.")
        return self.manager.get_nth_fibonacci_number(n)

