class SchemeChecker:
    def __init__(self):
        self.valid_schemes = ['http://', 'https://']

    def check_scheme(self, url):
        for scheme in self.valid_schemes:
            if url.startswith(scheme):
                self.found_scheme = scheme
                return True
        self.found_scheme = None
        return False

class DomainValidator:
    def __init__(self):
        self.min_dots = 1

    def validate_domain_part(self, url_after_scheme):
        if '.' in url_after_scheme:
            self.dot_present = True
            return True
        self.dot_present = False
        return False

class URLValidator:
    def __init__(self):
        self.scheme_checker = SchemeChecker()
        self.domain_validator = DomainValidator()
        self.is_valid = False

    def is_valid_url(self, url):
        if not isinstance(url, str):
            self.is_valid = False
            return self.is_valid

        if not self.scheme_checker.check_scheme(url):
            self.is_valid = False
            return self.is_valid

        scheme_length = len(self.scheme_checker.found_scheme)
        url_after_scheme = url[scheme_length:]

        if not self.domain_validator.validate_domain_part(url_after_scheme):
            self.is_valid = False
            return self.is_valid

        self.is_valid = True
        return self.is_valid

def is_valid_url(url):
    validator = URLValidator()
    return validator.is_valid_url(url)

