        self.stack = list(initial_stack)

    def get_stack(self):
        return self.stack

class StackOperations:
    def __init__(self, manager):
        self.manager = manager

    def perform_push(self, item):
        self.manager.stack.append(item)
        return self.manager.get_stack()

    def perform_pop(self):
        if not self.manager.stack:
            return None
        return self.manager.stack.pop()

class StackSimulator:
    def simulate_stack(self, stack_list, operation, item=None):
        manager = StackManager(stack_list)
        ops = StackOperations(manager)

        if operation == 'push':
            return ops.perform_push(item)
        elif operation == 'pop':
            return ops.perform_pop()
        else:
            raise ValueError(f"Unknown operation: {operation}")

_simulator = StackSimulator()
simulate_stack = _simulator.simulate_stack

