class LogEntry:
    def __init__(self, timestamp, level, message):
        self.timestamp = timestamp
        self.level = level
        self.message = message

    def to_dict(self):
        return {'timestamp': self.timestamp, 'level': self.level, 'message': self.message}

class LogParser:
    def __init__(self, delimiter=' - '):
        self.delimiter = delimiter

    def _split_line(self, log_line):
        parts = log_line.split(self.delimiter, 2)
        return parts

class LogProcessor:
    def __init__(self):
        self.parser = LogParser()

    def process_line(self, log_line):
        parts = self.parser._split_line(log_line)
        if len(parts) == 3:
            timestamp = parts[0]
            level = parts[1]
            message = parts[2]
            entry = LogEntry(timestamp, level, message)
            return entry.to_dict()
        else:
            return {}

def parse_log_line(log_line):
    processor = LogProcessor()
    parsed_log = processor.process_line(log_line)
    return parsed_log

