class FrequencyCounter:
    def __init__(self, text):
        self.text = text
        self.char_counts = {}

    def count_frequencies(self):
        for char in self.text:
            self.char_counts[char] = self.char_counts.get(char, 0) + 1
        return self.char_counts

class CharacterFinder:
    def __init__(self, text, char_counts):
        self.text = text
        self.char_counts = char_counts
        self.min_frequency = float('inf')
        self.least_frequent_char_result = None

    def find_least_frequent(self):
        for char in self.text:
            current_frequency = self.char_counts[char]
            if current_frequency < self.min_frequency:
                self.min_frequency = current_frequency
                self.least_frequent_char_result = char
        return self.least_frequent_char_result

class Solution:
    def __init__(self):
        self.input_text = ""

    def least_frequent_char(self, text):
        self.input_text = text
        counter = FrequencyCounter(self.input_text)
        counts = counter.count_frequencies()
        finder = CharacterFinder(self.input_text, counts)
        return finder.find_least_frequent()

def least_frequent_char(text):
    solver = Solution()
    return solver.least_frequent_char(text)

