class MatrixRow:
    def __init__(self, elements):
        self.elements = elements

    def subtract_row(self, other_row):
        result_elements = []
        for i in range(len(self.elements)):
            result_elements.append(self.elements[i] - other_row.elements[i])
        return MatrixRow(result_elements)

    def to_list(self):
        return self.elements

class Matrix:
    def __init__(self, data):
        self.rows = [MatrixRow(row_data) for row_data in data]

    def subtract(self, other_matrix):
        result_rows = []
        for i in range(len(self.rows)):
            current_row = self.rows[i]
            other_row = other_matrix.rows[i]
            subtracted_row = current_row.subtract_row(other_row)
            result_rows.append(subtracted_row.to_list())
        return Matrix(result_rows)

    def to_list(self):
        return [row.to_list() for row in self.rows]

class MatrixOperations:
    def __init__(self):
        self.description = "Performs matrix operations."

    def subtract_matrices(self, matrix1_data, matrix2_data):
        matrix1_obj = Matrix(matrix1_data)
        matrix2_obj = Matrix(matrix2_data)
        result_matrix_obj = matrix1_obj.subtract(matrix2_obj)
        self.last_operation_result = result_matrix_obj.to_list()
        return self.last_operation_result

def matrix_subtract(matrix1, matrix2):
    operator = MatrixOperations()
    return operator.subtract_matrices(matrix1, matrix2)

