class DictFlattener:
    def __init__(self, separator):
        self.separator = separator
        self.flat_data = {}

    def _process_item(self, key, value, prefix=""):
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                self._process_nested_dict(key, sub_key, sub_value, prefix)
        else:
            self._add_to_flat_data(key, value, prefix)

    def _process_nested_dict(self, parent_key, sub_key, sub_value, prefix):
        new_prefix = self.separator.join(filter(None, [prefix, parent_key]))
        self._process_item(sub_key, sub_value, new_prefix)

    def _add_to_flat_data(self, key, value, prefix):
        final_key = self.separator.join(filter(None, [prefix, key]))
        self.flat_data[final_key] = value

    def flatten(self, nested_dict):
        self.flat_data = {}
        for key, value in nested_dict.items():
            self._process_item(key, value)
        return self.flat_data

class Helper:
    def __init__(self):
        pass

    def get_flattener(self, separator):
        self.flattener = DictFlattener(separator)
        return self.flattener

def flatten_dict(nested_dict, separator):
    helper = Helper()
    flattener = helper.get_flattener(separator)
