class DictFlattener:
    def __init__(this, separator):
        this.separator = separator
        this.flat_data = {}

    def _process_item(this, key, value, prefix=""):
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                this._process_nested_dict(key, sub_key, sub_value, prefix)
        else:
            this._add_to_flat_data(key, value, prefix)

    def _process_nested_dict(this, parent_key, sub_key, sub_value, prefix):
        new_prefix = this.separator.join(filter(None, [prefix, parent_key]))
        this._process_item(sub_key, sub_value, new_prefix)

    def _add_to_flat_data(this, key, value, prefix):
        final_key = this.separator.join(filter(None, [prefix, key]))
        this.flat_data[final_key] = value

    def flatten(this, nested_dict):
        this.flat_data = {}
        for key, value in nested_dict.items():
            this._process_item(key, value)
        return this.flat_data

class Helper:
    def __init__(this):
        pass

    def get_flattener(this, separator):
        this.flattener = DictFlattener(separator)
        return this.flattener

def flatten_dict(nested_dict, separator):
    helper = Helper()
    flattener = helper.get_flattener(separator)
    return flattener.flatten(nested_dict)

