class NumberProcessor:
    def __init__(self, numbers):
        self.raw_numbers = numbers
        self.distinct_numbers = []

    def process_distinct(self):
        seen = set()
        for num in self.raw_numbers:
            if num not in seen:
                self.distinct_numbers.append(num)
                seen.add(num)
        self.distinct_numbers.sort(reverse=True)
        return self.distinct_numbers

class ThirdLargestFinder:
    def __init__(self, processed_numbers):
        self.processed_numbers = processed_numbers

    def find(self):
        if len(self.processed_numbers) < 3:
            return self.processed_numbers[0] if self.processed_numbers else None
        return self.processed_numbers[2]

class Solution:
    def find_third_largest(self, numbers):
        processor = NumberProcessor(numbers)
        distinct = processor.process_distinct()
        finder = ThirdLargestFinder(distinct)
        result = finder.find()
        return result

def find_third_largest(numbers):
    solution = Solution()
    return solution.find_third_largest(numbers)

