class DecimalToHexConverter:
    def __init__(self):
        self.converter = HexConverter()
        self.builder = HexBuilder()

    def convert(self, decimal_num):
        if decimal_num == 0:
            return "0"
        temp_num = decimal_num
        while temp_num > 0:
            remainder = temp_num % 16
            hex_digit = self.converter.convert_digit(remainder)
            self.builder.append_part(hex_digit)
            temp_num //= 16
        return self.builder.build()[::-1]

def decimal_to_hex(decimal_num):
    converter_instance = DecimalToHexConverter()
    return converter_instance.convert(decimal_num)

