    def __init__(self, bl_x, bl_y, tr_x, tr_y):
        self.bottom_left = Point(bl_x, bl_y)
        self.top_right = Point(tr_x, tr_y)

    def contains_point(self, point_obj):
        x_in_range = self.bottom_left.get_x() <= point_obj.get_x() <= self.top_right.get_x()
        y_in_range = self.bottom_left.get_y() <= point_obj.get_y() <= self.top_right.get_y()
        return x_in_range and y_in_range

class GeometryChecker:
