        self.target_point = Point(px, py)
        self.rectangle_obj = Rectangle(x1, y1, x2, y2)
        return self.rectangle_obj.contains_point(self.target_point)

def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    checker = GeometryChecker()
    return checker.is_point_in_rectangle(px, py, x1, y1, x2, y2)

