class NumberProcessor:
    def __init__(self, numbers):
        self.numbers = numbers
        self.sorted_numbers = []

    def sort_unique(self):
        unique_numbers = sorted(list(set(self.numbers)))
        self.sorted_numbers = unique_numbers
        return self.sorted_numbers

class SecondSmallestFinder:
    def __init__(self, processed_numbers):
        self.processed_numbers = processed_numbers
        self.second_smallest_value = None

    def calculate_second_smallest(self):
        if len(self.processed_numbers) < 2:
            raise ValueError("List must contain at least two distinct numbers.")
        self.second_smallest_value = self.processed_numbers[1]
        return self.second_smallest_value

class Solution:
    def __init__(self):
        self.result = None

    def find_second_smallest(self, numbers):
        processor = NumberProcessor(numbers)
        sorted_unique = processor.sort_unique()

        finder = SecondSmallestFinder(sorted_unique)
        self.result = finder.calculate_second_smallest()
        return self.result

def find_second_smallest(numbers):
    solver = Solution()
    return solver.find_second_smallest(numbers)

