class DigitTransformer:
    def __init__(self):
        pass

    def double_and_subtract_nine(self, digit):
        doubled = int(digit) * 2
        return doubled - 9 if doubled > 9 else doubled

class LuhnProcessor:
    def __init__(self, transformer):
        self.transformer = transformer

    def process_digits(self, digits):
        processed = []
        for i, digit in enumerate(digits):
            if (len(digits) - 1 - i) % 2 == 1:
                processed.append(self.transformer.double_and_subtract_nine(digit))
            else:
                processed.append(int(digit))
        return processed

class LuhnValidator:
    def __init__(self, processor):
        self.processor = processor

    def is_valid_luhn(self, card_number_str):
        digits = list(card_number_str)
        processed_digits = self.processor.process_digits(digits)
        total_sum = sum(processed_digits)
        return total_sum % 10 == 0

def is_valid_luhn(card_number):
    transformer_instance = DigitTransformer()
    processor_instance = LuhnProcessor(transformer_instance)
    validator_instance = LuhnValidator(processor_instance)
    return validator_instance.is_valid_luhn(card_number)

