class QueueNode:
    def __init__(self, value):
        self.value = value
        self.next = None

class QueueList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def append(self, item):
        new_node = QueueNode(item)
        if self.tail is None:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            self.tail = new_node
        self.size += 1

    def pop_front(self):
        if self.head is None:
            return None
        value = self.head.value
        self.head = self.head.next
        if self.head is None:
            self.tail = None
        self.size -= 1
        return value

    def is_empty(self):
        return self.size == 0

class Queue:
    def __init__(self):
        self.internal_list = QueueList()

    def enqueue(self, item):
        self.internal_list.append(item)
        self.current_size = self.internal_list.size

    def dequeue(self):
        if self.internal_list.is_empty():
            return None
        removed_item = self.internal_list.pop_front()
        self.current_size = self.internal_list.size
        return removed_item

