class FibonacciGenerator:
    def __init__(self, limit):
        self.limit = limit
        self.current_sequence = []

    def _initialize_sequence(self):
        if self.limit > 0:
            self.current_sequence.append(0)
            if self.limit > 1:
                self.current_sequence.append(1)

    def generate(self):
        self._initialize_sequence()
        while True:
            if len(self.current_sequence) < 2:
                break
            next_fib = self.current_sequence[-1] + self.current_sequence[-2]
            if next_fib >= self.limit:
                break
            self.current_sequence.append(next_fib)
        return self.current_sequence

class SequenceFormatter:
    def __init__(self, raw_sequence):
        self.raw_sequence = raw_sequence
        self.formatted_result = []

    def _process_elements(self):
        for element in self.raw_sequence:
            self.formatted_result.append(element)

    def get_formatted_sequence(self):
        self._process_elements()
        return self.formatted_result

class FibonacciManager:
    def __init__(self, n_value):
        self.n_value = n_value
        self.generator = FibonacciGenerator(self.n_value)
        self.formatter = None

    def execute_generation(self):
        generated_list = self.generator.generate()
        self.formatter = SequenceFormatter(generated_list)
        return self.formatter.get_formatted_sequence()

def fibonacci_sequence(n):
    manager = FibonacciManager(n)
    return manager.execute_generation()

