class TemperatureConverter:
    def __init__(self):
        self.conversion_factor = 9/5
        self.offset = 32

    def _apply_conversion_factor(self, celsius_value):
        self.intermediate_result = celsius_value * self.conversion_factor
        return self.intermediate_result

    def _apply_offset(self, intermediate_value):
        self.final_result = intermediate_value + self.offset
        return self.final_result

    def convert(self, celsius):
        self.celsius_input = float(celsius)
        self._apply_conversion_factor(self.celsius_input)
        self._apply_offset(self.intermediate_result)
        return self.final_result

