class Alphabet:
    def __init__(self):
        self.alphabet_lower = "abcdefghijklmnopqrstuvwxyz"
        self.alphabet_upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        self.alphabet_len = 26

    def is_lower(self, char):
        return char in self.alphabet_lower

    def is_upper(self, char):
        return char in self.alphabet_upper

    def get_shifted_char(self, char, shift):
        if self.is_lower(char):
            idx = self.alphabet_lower.find(char)
            shifted_idx = (idx + shift) % self.alphabet_len
            return self.alphabet_lower[shifted_idx]
        elif self.is_upper(char):
            idx = self.alphabet_upper.find(char)
            shifted_idx = (idx + shift) % self.alphabet_len
            return self.alphabet_upper[shifted_idx]
        return char

class CipherEngine:
    def __init__(self):
        self.alphabet_helper = Alphabet()

    def encrypt_char(self, char, shift):
        return self.alphabet_helper.get_shifted_char(char, shift)

class Encryptor:
    def __init__(self):
        self.cipher_engine = CipherEngine()

    def encrypt_string(self, text, shift):
        encrypted_chars = []
        for char in text:
            encrypted_chars.append(self.cipher_engine.encrypt_char(char, shift))
        return "".join(encrypted_chars)

def encrypt_shift(text, shift):
    my_encryptor = Encryptor()
    return my_encryptor.encrypt_string(text, shift)

