class QueryParser:
    def __init__(self, query_string):
        self.query_string = query_string
        self.params = {}

    def parse(self):
        pairs = self.query_string.split('&')
        for pair_str in pairs:
            self.process_pair(pair_str)
        return self.params

    def process_pair(self, pair_str):
        parts = pair_str.split('=', 1)
        if len(parts) == 2:
            key_processor = KeyProcessor(parts[0])
            value_processor = ValueProcessor(parts[1])
            self.params[key_processor.get_key()] = value_processor.get_value()

class KeyProcessor:
    def __init__(self, raw_key):
        self.raw_key = raw_key

    def get_key(self):
        return self.raw_key.strip()

class ValueProcessor:
    def __init__(self, raw_value):
        self.raw_value = raw_value

    def get_value(self):
        return self.raw_value.strip()

def parse_url_params(query_string):
    parser = QueryParser(query_string)
    return parser.parse()

