class PrefixFinder:
    def __init__(self, strings):
        self.strings = strings

    def find_longest(self):
        if not self.strings:
            return ""

        first_string = self.strings[0]

        for i, char in enumerate(first_string):
            for other_string in self.strings[1:]:
                if i >= len(other_string) or other_string[i] != char:
                    return first_string[:i]
        return first_string

class StringListProcessor:
    def __init__(self, string_list):
        self.string_list = string_list

    def get_first(self):
        if not self.string_list:
            return ""
        return self.string_list[0]

    def get_remaining(self):
        return self.string_list[1:]

class CommonPrefixCalculator:
    def __init__(self):
        self.current_prefix = ""

    def calculate(self, strings):
        processor = StringListProcessor(strings)
        first_str = processor.get_first()
        if not first_str:
            return ""
        self.current_prefix = first_str

        for other_str in processor.get_remaining():
            while other_str.find(self.current_prefix) != 0:
                self.current_prefix = self.current_prefix[:-1]
                if not self.current_prefix:
                    return ""
        return self.current_prefix

def longest_common_prefix(strings):
    finder = PrefixFinder(strings)
    LCP_result = finder.find_longest()
    return LCP_result

