class OctetValidator:
    def __init__(self):
        self.min_value = 0
        self.max_value = 255

    def validate(self, octet_str):
        try:
            self.octet_int = int(octet_str)
            return self.min_value <= self.octet_int <= self.max_value
        except ValueError:
            return False

class IpAddressParser:
    def __init__(self, ip_address_str):
        self.ip_address_str = ip_address_str
        self.parts = self.ip_address_str.split('.')

    def get_octets(self):
        return self.parts

    def has_correct_part_count(self):
        return len(self.parts) == 4

class IpAddressValidator:
    def __init__(self):
        self.octet_validator = OctetValidator()

    def is_valid(self, ip_address_str):
        self.parser = IpAddressParser(ip_address_str)
        if not self.parser.has_correct_part_count():
            return False
        for self.octet in self.parser.get_octets():
            if not self.octet_validator.validate(self.octet):
                return False
        return True

def is_valid_ipv4(ip_address):
    validator = IpAddressValidator()
    return validator.is_valid(ip_address)

