class PowerCalculator:
    def __init__(self, base, exponent):
        self.base = base
        self.exponent = exponent
        self.result = None

    def _calculate_positive_power(self):
        self.result = 1
        for _ in range(self.exponent):
            self.result *= self.base
        return self.result

    def calculate(self):
        if self.exponent == 0:
            self.result = 1
        elif self.exponent > 0:
            self.result = self._calculate_positive_power()
        else:
            raise ValueError("Exponent must be non-negative for this implementation.")
        return self.result

