class FileWriter:
    def __init__(self):
        self.last_status = None

    def write_content(self, filepath, content):
        try:
            with open(filepath, 'a') as self.file_handle:
                self.file_handle.write(content)
            self.last_status = True
            return True
        except IOError:
            self.last_status = False
            return False

class FileStatusTracker:
    def __init__(self):
        self.history = []

    def record_status(self, filepath, success):
        self.history.append({'filepath': filepath, 'success': success})
        self.last_recorded_success = success
        return self.last_recorded_success

    def get_last_status(self):
        return self.last_recorded_success

class FileAppender:
    def __init__(self):
        self.writer = FileWriter()
        self.tracker = FileStatusTracker()
        self.operation_count = 0

    def append(self, filepath, content):
        self.operation_count += 1
        success = self.writer.write_content(filepath, content)
        self.tracker.record_status(filepath, success)
        self.last_operation_successful = success
        return success

def append_to_file(filepath, content):
    appender_instance = FileAppender()
    result = appender_instance.append(filepath, content)
    return result

