import math

class Point3D:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z

    def get_coordinates(self):
        return (self.x, self.y, self.z)

    def subtract(self, other_point):
        dx = self.x - other_point.x
        dy = self.y - other_point.y
        dz = self.z - other_point.z
        return Vector3D(dx, dy, dz)

class Vector3D:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z

    def square_magnitude(self):
        return self.x**2 + self.y**2 + self.z**2

    def magnitude(self):
        return math.sqrt(self.square_magnitude())

class DistanceCalculator:
    def calculate(self, p1_tuple, p2_tuple):
        self.p1 = Point3D(p1_tuple[0], p1_tuple[1], p1_tuple[2])
        self.p2 = Point3D(p2_tuple[0], p2_tuple[1], p2_tuple[2])
        self.diff_vector = self.p1.subtract(self.p2)
        return self.diff_vector.magnitude()

def distance_3d(p1, p2):
    calculator = DistanceCalculator()
    return calculator.calculate(p1, p2)

