class EmailValidator:
    def __init__(self):
        self.at_char = '@'
        self.dot_char = '.'
        self.min_length_after_at = 2

    def _check_at_count(self, email_string):
        self.count = email_string.count(self.at_char)
        if self.count != 1:
            return False
        return True

    def _get_parts(self, email_string):
        self.parts = email_string.split(self.at_char)
        return self.parts

    def _check_dot_after_at(self, domain_part):
        self.dot_index = domain_part.find(self.dot_char)
        if self.dot_index == -1:
            return False
        return True

class EmailFormatChecker:
    def __init__(self, validator_instance):
        self.validator = validator_instance
        self.valid_domain_chars = "abcdefghijklmnopqrstuvwxyz0123456789-"

    def _check_domain_length(self, domain_part):
        self.domain_part_length = len(domain_part)
        if self.domain_part_length < self.validator.min_length_after_at:
            return False
        return True

    def _check_domain_characters(self, domain_part):
        for self.char in domain_part:
            if self.char not in self.valid_domain_chars and self.char != self.validator.dot_char:
                return False
        return True

class EmailVerifier:
    def __init__(self):
        self.validator = EmailValidator()
        self.checker = EmailFormatChecker(self.validator)

    def is_valid_email(self, email_string):
        if not self.validator._check_at_count(email_string):
            return False

        self.parts = self.validator._get_parts(email_string)
        self.local_part, self.domain_part = self.parts[0], self.parts[1]

        if not self.checker._check_domain_length(self.domain_part):
            return False

        if not self.validator._check_dot_after_at(self.domain_part):
            return False

        if not self.checker._check_domain_characters(self.domain_part):
            return False
        return True

def is_valid_email(email_string):
    verifier = EmailVerifier()
    return verifier.is_valid_email(email_string)

