class DigitConverter:
    def __init__(self):
        self.digits = "0123456789ABCDEF"

    def get_digit(self, value):
        return self.digits[value]

class BaseConverter:
    def __init__(self, digit_converter):
        self.digit_converter = digit_converter
        self.result = []

    def convert_single_step(self, number, base):
        remainder = number % base
        self.result.append(self.digit_converter.get_digit(remainder))
        return number // base

class NumberConverter:
    def __init__(self):
        self.digit_converter = DigitConverter()
        self.base_converter = BaseConverter(self.digit_converter)

    def convert_base(self, number, base):
        if number == 0:
            return "0"
        self.base_converter.result = []
        current_number = number
        while current_number > 0:
            current_number = self.base_converter.convert_single_step(current_number, base)
        return "".join(reversed(self.base_converter.result))

def convert_base(number, base):
    converter = NumberConverter()
    return converter.convert_base(number, base)

