class Cipher:
    def __init__(self, key_char):
        self.key_char = key_char
        self.key_val = ord(self.key_char)

    def _xor_char(self, char_to_xor):
        return chr(ord(char_to_xor) ^ self.key_val)

    def process_text(self, text_to_process):
        return "".join([self._xor_char(char) for char in text_to_process])

class TextProcessor:
    def __init__(self, text):
        self.original_text = text

    def get_text(self):
        return self.original_text

    def set_text(self, new_text):
        self.original_text = new_text

class XORCipherMachine:
    def __init__(self):
        self.current_cipher = None

    def set_cipher_key(self, key_char):
        self.current_cipher = Cipher(key_char)

    def encrypt_decrypt(self, text):
        if not self.current_cipher:
            raise ValueError("Key not set for cipher machine.")
        text_obj = TextProcessor(text)
        processed_text = self.current_cipher.process_text(text_obj.get_text())
        text_obj.set_text(processed_text)
        return text_obj.get_text()

def xor_cipher(text, key_char):
    machine = XORCipherMachine()
    machine.set_cipher_key(key_char)
    return machine.encrypt_decrypt(text)

