    def encrypt_decrypt(this, text):
        if not this.current_cipher:
            raise ValueError("Key not set for cipher machine.")
        text_obj = TextProcessor(text)
        processed_text = this.current_cipher.process_text(text_obj.get_text())
        text_obj.set_text(processed_text)
        return text_obj.get_text()

def xor_cipher(text, key_char):
    machine = XORCipherMachine()
