class Converter:
    def __init__(self):
        self.c_to_k_offset = 273.15
        self.f_to_c_factor = 5/9
        self.c_to_f_factor = 9/5
        self.f_to_c_offset = 32
        self.c_to_f_offset = 32

    def to_celsius(self, value, unit_from):
        if unit_from == 'C':
            self_c_value = value
            return self_c_value
        elif unit_from == 'F':
            self_f_to_c = (value - self.f_to_c_offset) * self.f_to_c_factor
            return self_f_to_c
        elif unit_from == 'K':
            self_k_to_c = value - self.c_to_k_offset
            return self_k_to_c

class TemperatureConverter:
    def __init__(self):
        self.converter_utility = Converter()

    def convert(self, value, unit_from, unit_to):
        self.celsius_value = self.converter_utility.to_celsius(value, unit_from)
        self.final_value = self.to_target_unit(self.celsius_value, unit_to)
        return self.final_value

    def to_target_unit(self, celsius_value, unit_to):
        if unit_to == 'C':
            self_c_result = celsius_value
            return self_c_result
        elif unit_to == 'F':
            self_f_result = celsius_value * self.converter_utility.c_to_f_factor + self.converter_utility.c_to_f_offset
            return self_f_result
        elif unit_to == 'K':
            self_k_result = celsius_value + self.converter_utility.c_to_k_offset
            return self_k_result

