    def __init__(self):
        self.prefix = '#'

    def starts_with_prefix(self, code):
        self.code = code
        return self.code.startswith(self.prefix)

class HexDigitChecker:
    def __init__(self):
        self.hex_chars = "0123456789abcdefABCDEF"

    def contains_only_hex_digits(self, s):
        self.s = s
        for char in self.s:
            if char not in self.hex_chars:
                return False
        return True

class LengthChecker:
    def __init__(self):
        self.valid_lengths = [3, 6]

    def has_valid_length(self, s):
        self.s = s
        self.length = len(self.s)
        return self.length in self.valid_lengths

def is_valid_hex_color(code):
    validator = ColorValidator()
    if not validator.starts_with_prefix(code):
        return False

    hex_part = code[1:]

    digit_checker = HexDigitChecker()
    if not digit_checker.contains_only_hex_digits(hex_part):
        return False

    length_checker = LengthChecker()
    if not length_checker.has_valid_length(hex_part):
        return False

    return True

