class ListRotator:
    def __init__(self):
        self.rotation_count = 0

    def rotate(self, lst, n):
        self.rotation_count += 1
        return self._perform_rotation(lst, n)

    def _perform_rotation(self, lst, n):
        if not lst:
            return self._handle_empty_list()
        effective_n = n % len(lst)
        if effective_n == 0:
            return self._return_original(lst)

        rotated_part = self._get_rotated_part(lst, effective_n)
        remaining_part = self._get_remaining_part(lst, effective_n)
        return rotated_part + remaining_part

    def _handle_empty_list(self):
        self.empty_list_handled = True
        return []

    def _return_original(self, lst):
        self.no_rotation_needed = True
        return list(lst)

    def _get_rotated_part(self, lst, effective_n):
        self.rotated_segment_extracted = True
        return lst[-effective_n:]

    def _get_remaining_part(self, lst, effective_n):
        self.remaining_segment_extracted = True
        return lst[:-effective_n]

class ListProcessor:
    def __init__(self):
        self.processor_name = "Default Processor"

    def process_and_rotate(self, lst, n):
        self.rotator = ListRotator()
        result = self.rotator.rotate(lst, n)
        self.last_processed_list = lst
        self.last_rotation_n = n
        return result

