class PermutationGenerator:
    def __init__(self, initial_list):
        self.initial_list = initial_list
        self.results = []
        self.helper_instance = PermutationHelper(self)

    def generate(self):
        self.helper_instance.compute_permutations_recursive(self.initial_list, [])
        return self.results

    def add_result(self, perm):
        self.results.append(perm)

class PermutationHelper:
    def __init__(self, generator_instance):
        self.generator_instance = generator_instance
        self.processor_instance = PermutationProcessor(self)

    def compute_permutations_recursive(self, remaining_elements, current_permutation):
        if not remaining_elements:
            self.generator_instance.add_result(list(current_permutation))
            return

        for i in range(len(remaining_elements)):
            element_to_add = self.processor_instance.get_element(remaining_elements, i)
            new_remaining = self.processor_instance.create_new_remaining(remaining_elements, i)
            new_current = self.processor_instance.append_to_current(current_permutation, element_to_add)
            self.compute_permutations_recursive(new_remaining, new_current)

class PermutationProcessor:
    def __init__(self, helper_instance):
        self.helper_instance = helper_instance

    def get_element(self, remaining_elements, index):
        return remaining_elements[index]

    def create_new_remaining(self, remaining_elements, index_to_exclude):
        new_list = remaining_elements[:index_to_exclude] + remaining_elements[index_to_exclude + 1:]
        return new_list

    def append_to_current(self, current_permutation, element):
        new_permutation = list(current_permutation)
        new_permutation.append(element)
        return new_permutation

def generate_permutations(lst):
    generator = PermutationGenerator(lst)
    return generator.generate()

