class PatternFinder:
    def __init__(self, text):
        self.text = text
        self.occurrences = []

    def find_pattern(self, pattern):
        self.pattern = pattern
        self.text_length = len(self.text)
        self.pattern_length = len(self.pattern)
        for i in range(self.text_length - self.pattern_length + 1):
            if self.text[i : i + self.pattern_length] == self.pattern:
                self.occurrences.append(i)
        return self.occurrences

class SearchEngine:
    def __init__(self):
        self.results = []

    def search(self, text_content, search_pattern):
        self.finder = PatternFinder(text_content)
        self.current_results = self.finder.find_pattern(search_pattern)
        self.results.extend(self.current_results)
        return self.current_results

class OccurrenceCollector:
    def __init__(self):
        self.all_found_indices = []
        self.engine = SearchEngine()

    def collect_from_text(self, target_text, search_term):
        self.found_indices = self.engine.search(target_text, search_term)
        self.all_found_indices.extend(self.found_indices)
        return self.found_indices

def find_all_occurrences(text, pattern):
    collector = OccurrenceCollector()
    return collector.collect_from_text(text, pattern)

