        match = self.punctuation_pattern.search(word_with_punct)
        if match:
            self.punctuation = match.group(1)
            self.word = word_with_punct[:match.start()]
        else:
            self.punctuation = ""
            self.word = word_with_punct
        return self.word, self.punctuation

