class ItemGrouper:
    def __init__(this):
        this.grouped_data = {}

    def add_item(this, item):
        type_name = this._get_type_name(item)
        if type_name not in this.grouped_data:
            this.grouped_data[type_name] = []
        this.grouped_data[type_name].append(item)

    def _get_type_name(this, item):
        return type(item).__name__

    def get_groups(this):
        return this.grouped_data

class TypeClassifier:
    def classify(this, item):
        return type(item).__name__

class GroupingProcessor:
    def __init__(this):
