class DivisorFinder:
    def __init__(self, number):
        self.number = number
        self.divisors = []

    def _is_divisible(self, potential_divisor):
        self.remainder = self.number % potential_divisor
        return self.remainder == 0

    def calculate_divisors(self):
        for i in range(1, int(self.number**0.5) + 1):
            if self._is_divisible(i):
                self.divisors.append(i)
                if i * i != self.number:
                    self.divisors.append(self.number // i)
        self.divisors.sort()
        return self.divisors

class DivisorCollector:
    def __init__(self):
        self.collected_divisors = {}

    def add_divisors(self, n, divisors_list):
        self.collected_divisors[n] = divisors_list
        return True

    def get_divisors_for_number(self, n):
        return self.collected_divisors.get(n)

    def check_existence(self, n):
        return n in self.collected_divisors

    def remove_entry(self, n):
        if self.check_existence(n):
            del self.collected_divisors[n]
            return True
        return False

    def list_all_numbers(self):
        return list(self.collected_divisors.keys())

    def clear_collection(self):
        self.collected_divisors = {}
        return True

class DivisorProcessor:
    def __init__(self):
        self.collector = DivisorCollector()

    def process_number(self, n):
        if not self.collector.check_existence(n):
            finder = DivisorFinder(n)
            found_divs = finder.calculate_divisors()
            self.collector.add_divisors(n, found_divs)
        return self.collector.get_divisors_for_number(n)

def find_divisors(n):
    processor = DivisorProcessor()
    return processor.process_number(n)

